window.NOTIONS = [{"id": 1, "title": "Fonctions", "category": "Analyse", "formulas": ["f : A → B", "f(x + h) - f(x)", "Composition : (f ∘ g)(x) = f(g(x))"], "details": "Notion centrale : une fonction associe à chaque élément d’un ensemble un unique élément d’un autre ensemble.", "images": ["fonctions.png"], "correspondances": [{"id": 2, "title": "Limites"}, {"id": 3, "title": "Continuité"}], "tags": ["analyse", "fonctions", "continuite"], "niveau": "lycee", "definition": "Une fonction associe à chaque élément d'un ensemble de départ (A) au plus un élément d'un ensemble d'arrivée (B). C'est l'outil de base pour décrire comment une quantité dépend d'une autre.", "explication_formules": "f(x+h)-f(x) mesure la variation de f entre x et x+h : c'est la brique de base de la dérivée. La composition (f∘g)(x)=f(g(x)) enchaîne deux transformations : on applique d'abord g, puis f au résultat.", "approfondissements": [{"label": "Fonctions réciproques", "link": {"type": "theme", "slug": "fonctions-reciproques"}}, {"label": "Fonctions périodiques", "link": {"type": "theme", "slug": "fonctions-periodiques"}}, {"label": "Fonctions à plusieurs variables", "link": {"type": "theme", "slug": "fonctions-a-plusieurs-variables"}}, {"label": "Fonctions génératrices", "link": {"type": "theme", "slug": "fonctions-generatrices"}}, {"label": "Composition et itération de fonctions", "link": {"type": "theme", "slug": "composition-et-iteration-de-fonctions"}}], "sous_points": [{"terme": "Fonctions injectives", "definition": "Une fonction est injective si deux entrées différentes donnent toujours deux sorties différentes : jamais deux x distincts n'ont la même image."}, {"terme": "Fonctions surjectives", "definition": "Une fonction est surjective si tout élément de l'ensemble d'arrivée est atteint par au moins un élément de départ."}, {"terme": "Fonctions bijectives", "definition": "Une fonction est bijective si elle est à la fois injective et surjective : chaque élément d'arrivée correspond à exactement un élément de départ."}, {"terme": "Fonctions monotones", "definition": "Une fonction est monotone si elle est soit toujours croissante, soit toujours décroissante sur l'intervalle considéré."}, {"terme": "Fonctions continues", "definition": "Une fonction est continue si sa courbe ne présente aucun saut : on peut la tracer sans lever le crayon."}], "applications_list": [{"text": "Modéliser un prix en fonction d'une quantité vendue.", "icon": "finance"}, {"text": "Décrire une trajectoire en fonction du temps.", "icon": "physics"}, {"text": "Représenter un signal audio en fonction de la fréquence.", "icon": "audio"}]}, {"id": 2, "title": "Limites", "category": "Analyse", "formulas": ["lim_{x→a} f(x) = L", "lim_{x→∞} f(x)", "lim_{x→0} sin(x)/x = 1"], "details": "La limite décrit le comportement d’une fonction lorsqu’on approche un point.", "images": ["limites.png"], "correspondances": [{"id": 3, "title": "Continuité"}, {"id": 4, "title": "Dérivation"}], "tags": ["analyse", "limites"], "niveau": "lycee", "definition": "La limite décrit la valeur vers laquelle une fonction (ou une suite) se rapproche indéfiniment lorsque la variable s'approche d'un point donné, sans forcément l'atteindre.", "explication_formules": "lim f(x)=L en x=a signifie qu'on peut rendre f(x) aussi proche de L qu'on veut en prenant x assez proche de a. lim sin(x)/x=1 en 0 est une limite remarquable qui sert de brique pour dériver sin et cos.", "approfondissements": [{"label": "Limites à l'infini et asymptotes", "link": {"type": "theme", "slug": "limites-a-l-infini-et-asymptotes"}}, {"label": "Formes indéterminées et règle de l'Hôpital", "link": {"type": "theme", "slug": "formes-indeterminees-et-regle-de-l-hopital"}}, {"label": "Limites de suites récurrentes", "link": {"type": "theme", "slug": "limites-de-suites-recurrentes"}}, {"label": "Continuité uniforme", "link": {"type": "theme", "slug": "continuite-uniforme"}}, {"label": "Ordres de grandeur et équivalents", "link": {"type": "theme", "slug": "ordres-de-grandeur-et-equivalents"}}], "sous_points": [{"terme": "Limites infinies", "definition": "Une limite infinie décrit une fonction dont les valeurs deviennent arbitrairement grandes (vers +∞ ou -∞) quand x s'approche d'un point ou de l'infini."}, {"terme": "Limites en un point", "definition": "La limite d'une fonction en un point a est la valeur vers laquelle elle se rapproche quand x tend vers a, sans nécessairement l'atteindre."}, {"terme": "Limites de suites", "definition": "La limite d'une suite est la valeur vers laquelle ses termes se rapprochent indéfiniment lorsque l'indice n tend vers l'infini."}], "applications_list": [{"text": "Calculer une vitesse instantanée à partir d'une vitesse moyenne.", "icon": "transport"}, {"text": "Estimer le comportement à long terme d'une population.", "icon": "biology"}, {"text": "Déterminer si un algorithme converge vers une solution stable.", "icon": "computer"}]}, {"id": 3, "title": "Continuité", "category": "Analyse", "formulas": ["f continue en a ⇔ lim_{x→a} f(x) = f(a)", "Théorème des valeurs intermédiaires"], "details": "Une fonction est continue si elle ne présente pas de saut.", "images": ["continuite.png"], "correspondances": [{"id": 2, "title": "Limites"}, {"id": 5, "title": "Intégration"}], "tags": ["analyse", "continuite"], "niveau": "lycee", "definition": "Une fonction est continue en un point si sa courbe ne présente pas de saut à cet endroit : la limite de la fonction y coïncide avec sa valeur réelle.", "explication_formules": "f continue en a ⇔ lim_{x→a} f(x) = f(a) formalise l'absence de saut. Le théorème des valeurs intermédiaires dit que si f est continue entre a et b, elle prend toutes les valeurs intermédiaires entre f(a) et f(b).", "approfondissements": [{"label": "Continuité uniforme vs simple", "link": {"type": "theme", "slug": "continuite-uniforme-vs-simple"}}, {"label": "Théorème de Heine", "link": {"type": "theme", "slug": "theoreme-de-heine"}}, {"label": "Prolongement par continuité", "link": {"type": "theme", "slug": "prolongement-par-continuite"}}, {"label": "Fonctions lipschitziennes", "link": {"type": "theme", "slug": "fonctions-lipschitziennes"}}, {"label": "Continuité en dimension supérieure", "link": {"type": "theme", "slug": "continuite-en-dimension-superieure"}}], "sous_points": [{"terme": "Continuité uniforme", "definition": "Une fonction est uniformément continue si le contrôle de sa variation ne dépend pas du point considéré, mais seulement de l'écart entre les deux points."}, {"terme": "Continuité sur un intervalle fermé", "definition": "Sur un intervalle fermé borné, une fonction continue atteint toujours ses bornes (un maximum et un minimum), contrairement à un intervalle ouvert."}], "applications_list": [{"text": "Garantir qu'un pont conçu par un modèle mathématique ne se rompt pas brutalement.", "icon": "construction"}, {"text": "Prouver l'existence d'une solution à une équation sans la calculer explicitement.", "icon": "research"}]}, {"id": 4, "title": "Dérivation", "category": "Analyse", "formulas": ["f'(x) = lim_{h→0} (f(x+h)-f(x))/h", "(fg)' = f'g + fg'", "(f/g)' = (f'g - fg')/g²"], "details": "La dérivée mesure la variation instantanée d’une fonction.", "images": ["derivation.png"], "correspondances": [{"id": 5, "title": "Intégration"}, {"id": 6, "title": "Équations différentielles"}], "tags": ["analyse", "derivation"], "niveau": "lycee", "definition": "La dérivée mesure la vitesse instantanée de variation d'une fonction : c'est la pente de la tangente à la courbe en un point.", "explication_formules": "f'(x) est la limite du taux d'accroissement (f(x+h)-f(x))/h quand h tend vers 0. La règle du produit (fg)'=f'g+fg' et celle du quotient permettent de dériver des fonctions composées à partir de règles simples.", "approfondissements": [{"label": "Dérivées partielles et gradient", "link": {"type": "theme", "slug": "derivees-partielles-et-gradient"}}, {"label": "Dérivation implicite", "link": {"type": "theme", "slug": "derivation-implicite"}}, {"label": "Théorème des accroissements finis", "link": {"type": "theme", "slug": "theoreme-des-accroissements-finis"}}, {"label": "Dérivées d'ordre supérieur et convexité", "link": {"type": "theme", "slug": "derivees-d-ordre-superieur-et-convexite"}}, {"label": "Différentielle et approximation linéaire", "link": {"type": "theme", "slug": "differentielle-et-approximation-lineaire"}}], "sous_points": [{"terme": "Dérivées successives", "definition": "La dérivée seconde, troisième, etc. s'obtiennent en dérivant plusieurs fois de suite une fonction, révélant des informations de plus en plus fines sur sa courbe."}, {"terme": "Convexité", "definition": "Une fonction est convexe si sa courbe reste toujours au-dessus de ses tangentes, ce qui se traduit par une dérivée seconde positive."}, {"terme": "Points critiques", "definition": "Un point critique est un point où la dérivée s'annule : c'est là que se trouvent les extrema locaux possibles d'une fonction."}], "applications_list": [{"text": "Calculer la vitesse d'une voiture à partir de sa position.", "icon": "transport"}, {"text": "Optimiser un profit en cherchant où la dérivée s'annule.", "icon": "finance"}, {"text": "Entraîner un algorithme d'apprentissage automatique par rétropropagation du gradient.", "icon": "computer"}]}, {"id": 5, "title": "Intégration", "category": "Analyse", "formulas": ["∫_a^b f(x) dx = F(b) - F(a)", "∫ x dx = x²/2", "Changement de variable : ∫ f(g(t)) g'(t) dt"], "details": "Somme continue, aire, accumulation.", "images": ["integration.png"], "correspondances": [{"id": 4, "title": "Dérivation"}, {"id": 7, "title": "Séries de Fourier"}], "tags": ["analyse", "integration"], "niveau": "lycee", "definition": "L'intégrale calcule l'aire sous une courbe, ou de façon plus générale accumule une infinité de contributions infinitésimales pour obtenir une grandeur globale.", "explication_formules": "∫ₐᵇ f(x)dx = F(b)-F(a) est le théorème fondamental : intégrer revient à trouver une primitive F puis évaluer sa variation entre a et b. Le changement de variable transforme une intégrale compliquée en une plus simple en changeant de variable d'intégration.", "approfondissements": [{"label": "Intégrales généralisées (bornes infinies)", "link": {"type": "theme", "slug": "integrales-generalisees-bornes-infinies"}}, {"label": "Intégration par parties", "link": {"type": "theme", "slug": "integration-par-parties"}}, {"label": "Intégrale de Lebesgue", "link": {"type": "theme", "slug": "integrale-de-lebesgue"}}, {"label": "Calcul de volumes par intégration", "link": {"type": "theme", "slug": "calcul-de-volumes-par-integration"}}, {"label": "Intégrales multiples", "link": {"type": "theme", "slug": "integrales-multiples"}}], "sous_points": [{"terme": "Intégrale de Riemann", "definition": "Cette intégrale calcule une aire en découpant l'intervalle en petits rectangles dont on fait tendre la largeur vers zéro."}, {"terme": "Intégrale de Lebesgue", "definition": "Cette intégrale généralise celle de Riemann en découpant selon les valeurs de la fonction plutôt que selon son domaine, ce qui permet d'intégrer des fonctions plus irrégulières."}, {"terme": "Intégrales généralisées", "definition": "Une intégrale généralisée porte sur un intervalle infini ou une fonction non bornée ; elle se définit comme une limite d'intégrales sur des intervalles finis."}], "applications_list": [{"text": "Calculer la distance parcourue à partir de la vitesse.", "icon": "transport"}, {"text": "Calculer la quantité totale d'eau écoulée à partir d'un débit.", "icon": "environment"}, {"text": "Calculer l'aire d'un terrain de forme irrégulière.", "icon": "construction"}]}, {"id": 6, "title": "Équations différentielles", "category": "Analyse", "formulas": ["y' = ay", "y' + ay = f(x)", "Solution homogène + solution particulière"], "details": "Décrivent l’évolution d’un système.", "images": ["ed.png"], "correspondances": [{"id": 4, "title": "Dérivation"}, {"id": 5, "title": "Intégration"}], "tags": ["analyse", "equations-differentielles"], "niveau": "lycee", "definition": "Une équation différentielle relie une fonction inconnue à ses dérivées : elle décrit comment une quantité évolue dans le temps ou l'espace plutôt que sa valeur directement.", "explication_formules": "y'=ay décrit une croissance ou décroissance exponentielle (populations, radioactivité). y'+ay=f(x) se résout en additionnant une solution de l'équation homogène (sans second membre) et une solution particulière liée à f.", "approfondissements": [{"label": "Équations du second ordre", "link": {"type": "theme", "slug": "equations-du-second-ordre"}}, {"label": "Systèmes différentiels couplés", "link": {"type": "theme", "slug": "systemes-differentiels-couples"}}, {"label": "Résolution par transformée de Laplace", "link": {"type": "theme", "slug": "resolution-par-transformee-de-laplace"}}, {"label": "Stabilité des points d'équilibre", "link": {"type": "theme", "slug": "stabilite-des-points-d-equilibre"}}, {"label": "Équations différentielles stochastiques", "link": {"type": "notion", "id": 6}}], "sous_points": [{"terme": "Équations différentielles linéaires", "definition": "Une ED linéaire relie une fonction inconnue et ses dérivées de façon linéaire, sans produit entre elles, ce qui permet de la résoudre systématiquement."}, {"terme": "Équations différentielles non linéaires", "definition": "Une ED non linéaire contient des produits ou des puissances de la fonction inconnue et de ses dérivées, ce qui la rend souvent bien plus difficile à résoudre."}, {"terme": "Systèmes", "definition": "Un système d'équations différentielles regroupe plusieurs équations couplées, où l'évolution de chaque fonction dépend aussi des autres."}], "applications_list": [{"text": "Modéliser la décroissance radioactive.", "icon": "physics"}, {"text": "Modéliser la propagation d'une épidémie.", "icon": "medicine"}, {"text": "Modéliser la charge d'un condensateur électrique.", "icon": "electronics"}]}, {"id": 7, "title": "Séries de Fourier", "category": "Analyse", "formulas": ["f(x) = a0 + Σ (an cos(nx) + bn sin(nx))", "an = ∫ f(x) cos(nx) dx", "bn = ∫ f(x) sin(nx) dx"], "details": "Décomposition d’une fonction en fréquences.", "images": ["fourier.svg"], "correspondances": [{"id": 5, "title": "Intégration"}, {"id": 8, "title": "Analyse complexe"}, {"key": "sup:1411", "title": "Caractères des représentations et relations d'orthogonalité", "raison": "Pour un groupe fini abélien, les caractères forment une base orthonormée des fonctions sur le groupe : la transformée de Fourier discrète est le cas du groupe ℤ/nℤ."}, {"key": "sup:573", "title": "Géodésiques et spectre du Laplacien", "raison": "Sur une variété compacte, les fonctions propres du laplacien généralisent les exponentielles e^(inθ) (fonctions propres du laplacien du cercle) : le spectre du laplacien encode la géométrie."}, {"key": "sup:339", "title": "Fonction caractéristique", "raison": "La fonction caractéristique φ(t)=E[e^(itX)] est la transformée de Fourier de la loi de X : elle caractérise la loi et change la somme de variables indépendantes en produit."}, {"key": "sup:527", "title": "Transformée de Fourier rapide (FFT)", "raison": "La FFT calcule la transformée de Fourier discrète de n points en O(n log n) opérations au lieu de O(n²), ce qui rend praticables le filtrage et la convolution de signaux."}], "tags": ["analyse", "fourier"], "niveau": "grandes-ecoles", "definition": "Une série de Fourier décompose une fonction périodique en une somme infinie de sinus et cosinus de fréquences croissantes — une véritable analyse spectrale de la fonction.", "explication_formules": "f(x)=a0+Σ(an cos(nx)+bn sin(nx)) exprime f comme une somme de vibrations élémentaires. Les coefficients an et bn se calculent par une intégrale qui mesure la 'quantité' de chaque fréquence présente dans f.", "approfondissements": [{"label": "Transformée de Fourier (cas non périodique)", "link": {"type": "theme", "slug": "transformee-de-fourier-cas-non-periodique"}}, {"label": "FFT et traitement numérique du signal", "link": {"type": "theme", "slug": "fft-et-traitement-numerique-du-signal"}}, {"label": "Séries de Fourier et EDP", "link": {"type": "notion", "id": 7}}, {"label": "Analyse spectrale sur variétés", "link": {"type": "theme", "slug": "analyse-spectrale-sur-varietes"}}, {"label": "Ondelettes et analyse multi-résolution", "link": {"type": "theme", "slug": "ondelettes-et-analyse-multi-resolution"}}], "sous_points": [{"terme": "Orthogonalité", "definition": "Deux fonctions sinus/cosinus de fréquences différentes ont une intégrale de produit nulle sur une période : cette propriété permet de calculer isolément chaque coefficient de Fourier."}, {"terme": "Convergence", "definition": "La convergence d'une série de Fourier désigne le fait que la somme des termes se rapproche de plus en plus de la fonction d'origine."}, {"terme": "Transformée de Fourier", "definition": "Cette transformée généralise les séries de Fourier aux fonctions non périodiques, donnant un spectre continu de fréquences plutôt qu'une somme discrète."}], "applications_list": [{"text": "Compresser l'audio (MP3) et l'image (JPEG).", "icon": "audio"}, {"text": "Analyser le son en musique avec un égaliseur.", "icon": "audio"}, {"text": "Traiter le signal en télécommunications.", "icon": "communication"}]}, {"id": 8, "title": "Analyse complexe", "category": "Analyse", "formulas": ["z = x + iy", "e^{iθ} = cos θ + i sin θ", "∮ f(z) dz"], "details": "Étude des fonctions d’une variable complexe.", "images": ["complexe.png"], "correspondances": [{"id": 7, "title": "Séries de Fourier"}, {"id": 9, "title": "Séries entières"}, {"key": "sup:92", "title": "Théorème de d'Alembert-Gauss", "raison": "Tout polynôme non constant de ℂ[X] admet une racine dans ℂ : la démonstration classique utilise le théorème de Liouville (une fonction entière bornée est constante)."}, {"key": "sup:549", "title": "Variétés complexes", "raison": "Une variété complexe est un espace localement isomorphe à ℂ^n dont les changements de cartes sont holomorphes ; en dimension 1, ce sont les surfaces de Riemann."}, {"key": "sup:339", "title": "Fonction caractéristique", "raison": "La fonction caractéristique φ(t) = E[e^(itX)] est à valeurs complexes et caractérise la loi ; si X a des moments exponentiels, φ se prolonge en une fonction analytique dans une bande du plan complexe."}, {"key": "sup:1766", "title": "Ensemble de Mandelbrot et de Julia (introduction culturelle)", "raison": "Les ensembles de Julia et de Mandelbrot étudient l'itération z ↦ z² + c : c'est la dynamique holomorphe, où l'analyse complexe décrit la stabilité des orbites."}], "tags": ["analyse", "complexe"], "niveau": "prepa", "definition": "L'analyse complexe étudie les fonctions dont la variable et les valeurs sont des nombres complexes, avec des propriétés bien plus rigides et puissantes que dans le cas réel.", "explication_formules": "Un nombre complexe z=x+iy combine partie réelle et imaginaire. La formule d'Euler e^{iθ}=cos θ+i sin θ relie exponentielle et trigonométrie. L'intégrale sur un contour fermé ∮f(z)dz permet de calculer des quantités globales à partir du comportement local de f.", "approfondissements": [{"label": "Théorème des résidus", "link": {"type": "theme", "slug": "theoreme-des-residus"}}, {"label": "Séries de Laurent", "link": {"type": "theme", "slug": "series-de-laurent"}}, {"label": "Transformations conformes", "link": {"type": "notion", "id": 706}}, {"label": "Fonctions holomorphes et harmoniques", "link": {"type": "theme", "slug": "fonctions-holomorphes-et-harmoniques"}}, {"label": "Prolongement analytique", "link": {"type": "theme", "slug": "prolongement-analytique"}}], "sous_points": [{"terme": "Holomorphie", "definition": "Une fonction complexe est holomorphe si elle est dérivable au sens complexe en tout point, une condition bien plus forte que la dérivabilité réelle."}, {"terme": "Résidus", "definition": "Le résidu d'une fonction en un pôle est un coefficient qui résume son comportement local ; sommer les résidus permet de calculer des intégrales de contour."}, {"terme": "Intégrales complexes", "definition": "Une intégrale complexe se calcule le long d'un chemin dans le plan complexe, et ne dépend souvent que des singularités entourées par ce chemin."}], "applications_list": [{"text": "Analyser les circuits électriques en régime alternatif (impédance complexe).", "icon": "electronics"}, {"text": "Traiter le signal en télécommunications.", "icon": "communication"}, {"text": "Étudier la mécanique des fluides (écoulements potentiels).", "icon": "physics"}]}, {"id": 9, "title": "Séries entières", "category": "Analyse", "formulas": ["Σ a_n x^n", "Rayon de convergence R", "Test de Cauchy"], "details": "Développement d’une fonction en série de puissances.", "images": ["series.png"], "correspondances": [{"id": 8, "title": "Analyse complexe"}, {"id": 10, "title": "Développements limités"}], "tags": ["analyse", "series"], "niveau": "prepa", "definition": "Une série entière est une somme infinie de puissances de x (Σ aₙxⁿ) qui généralise les polynômes en autorisant un nombre infini de termes, sous réserve de convergence.", "explication_formules": "Le rayon de convergence R délimite la zone où la somme a un sens : la série converge si |x|<R et diverge si |x|>R. Le test de Cauchy (racine n-ième des coefficients) permet de calculer R explicitement.", "approfondissements": [{"label": "Développements limités", "link": {"type": "theme", "slug": "developpements-limites"}}, {"label": "Fonctions analytiques", "link": {"type": "theme", "slug": "fonctions-analytiques"}}, {"label": "Séries de Laurent (puissances négatives)", "link": {"type": "theme", "slug": "series-de-laurent-puissances-negatives"}}, {"label": "Rayon de convergence et critère de Cauchy-Hadamard", "link": {"type": "theme", "slug": "rayon-de-convergence-et-critere-de-cauchy-hadamard"}}, {"label": "Séries entières à plusieurs variables", "link": {"type": "notion", "id": 9}}], "sous_points": [{"terme": "Convergence", "definition": "Une série entière converge à l'intérieur de son rayon de convergence R, c'est-à-dire pour tout x tel que |x|<R."}, {"terme": "Dérivation terme à terme", "definition": "À l'intérieur du rayon de convergence, on peut dériver une série entière en dérivant chaque terme séparément, sans changer le rayon de convergence."}], "applications_list": [{"text": "Approcher numériquement les fonctions usuelles sur une calculatrice.", "icon": "computer"}, {"text": "Résoudre des équations différentielles par développement en série.", "icon": "research"}, {"text": "Définir rigoureusement des fonctions complexes.", "icon": "research"}]}, {"id": 10, "title": "Développements limités", "category": "Analyse", "formulas": ["sin x = x - x³/6 + ...", "e^x = 1 + x + x²/2 + ...", "ln(1+x) = x - x²/2 + ..."], "details": "Approximation locale d’une fonction.", "images": ["dl.png"], "correspondances": [{"id": 2, "title": "Limites"}, {"id": 4, "title": "Dérivation"}], "tags": ["analyse", "dl"], "niveau": "prepa", "definition": "Un développement limité approxime une fonction compliquée au voisinage d'un point par un polynôme, avec un contrôle précis de l'erreur commise.", "explication_formules": "sin x ≈ x - x³/6 pour x proche de 0 : plus on ajoute de termes, plus l'approximation est précise. Ces développements viennent de la formule de Taylor, qui utilise les dérivées successives de la fonction au point considéré.", "approfondissements": [{"label": "Formule de Taylor avec reste", "link": {"type": "theme", "slug": "formule-de-taylor-avec-reste"}}, {"label": "Développements asymptotiques", "link": {"type": "theme", "slug": "developpements-asymptotiques"}}, {"label": "Règle de l'Hôpital via DL", "link": {"type": "theme", "slug": "regle-de-l-hopital-via-dl"}}, {"label": "DL à plusieurs variables", "link": {"type": "theme", "slug": "dl-a-plusieurs-variables"}}, {"label": "Séries entières et rayon de convergence", "link": {"type": "notion", "id": 9}}], "sous_points": [{"terme": "DL d'ordre n", "definition": "Le développement limité d'ordre n approxime une fonction par un polynôme de degré n, avec une erreur qui devient négligeable devant xⁿ."}, {"terme": "Équivalents", "definition": "Deux fonctions sont équivalentes en un point si leur rapport tend vers 1, ce qui permet de simplifier des calculs de limites en ne gardant que le terme dominant."}], "applications_list": [{"text": "Simplifier des calculs de physique aux petites oscillations et petits angles.", "icon": "physics"}, {"text": "Accélérer des calculs numériques.", "icon": "computer"}, {"text": "Estimer des erreurs d'approximation dans des simulations.", "icon": "research"}]}, {"id": 100, "title": "Nombres réels", "category": "Algèbre", "formulas": ["ℝ = ensemble des nombres réels", "Propriétés : ordre total, densité, complétude"], "details": "Les réels forment la base de l’analyse et de l’algèbre élémentaire.", "images": ["reels.png"], "correspondances": [{"id": 101, "title": "Nombres complexes"}, {"id": 102, "title": "Polynômes"}], "tags": ["algebre", "reels"], "niveau": "lycee", "definition": "L'ensemble des nombres réels regroupe tous les nombres qu'on peut placer sur une droite graduée : entiers, fractions, et nombres irrationnels comme π ou √2.", "explication_formules": "ℝ est ordonné (on peut toujours comparer deux réels), dense (entre deux réels il y en a toujours un autre) et complet (pas de 'trou' : toute suite qui devrait converger converge effectivement).", "approfondissements": [{"label": "Densité de ℚ dans ℝ", "link": {"type": "theme", "slug": "densite-de-dans"}}, {"label": "Borne supérieure et axiome de complétude", "link": {"type": "theme", "slug": "borne-superieure-et-axiome-de-completude"}}, {"label": "Nombres irrationnels et transcendants", "link": {"type": "theme", "slug": "nombres-irrationnels-et-transcendants"}}, {"label": "Construction de ℝ (coupures de Dedekind)", "link": {"type": "theme", "slug": "construction-de-coupures-de-dedekind"}}, {"label": "Suites de Cauchy et complétude", "link": {"type": "theme", "slug": "suites-de-cauchy-et-completude"}}], "sous_points": [{"terme": "Intervalles", "definition": "Un intervalle est un sous-ensemble de ℝ qui contient tous les nombres compris entre deux bornes données, comme [a,b] ou ]a,b[."}, {"terme": "Bornes", "definition": "Un majorant est un nombre supérieur ou égal à tous les éléments d'un ensemble ; la borne supérieure est le plus petit de ces majorants."}, {"terme": "Complétude", "definition": "ℝ est complet : toute suite dont les termes se rapprochent indéfiniment (suite de Cauchy) converge effectivement vers un réel, sans « trou »."}, {"terme": "Axiome de l'ordre", "definition": "Cet axiome garantit qu'on peut toujours comparer deux nombres réels distincts : l'un est strictement plus petit que l'autre."}], "applications_list": [{"text": "Mesurer une longueur, une température ou un temps.", "icon": "research"}, {"text": "Modéliser toute grandeur physique continue.", "icon": "physics"}]}, {"id": 101, "title": "Nombres complexes", "category": "Algèbre", "formulas": ["z = x + iy", "i² = -1", "|z| = √(x² + y²)", "e^{iθ} = cos θ + i sin θ"], "details": "Extension algébrique des réels permettant de résoudre toutes les équations polynomiales.", "images": ["complexes.png"], "correspondances": [{"id": 102, "title": "Polynômes"}, {"id": 103, "title": "Matrices"}, {"key": "sup:1101", "title": "Transformations géométriques via les nombres complexes", "raison": "Le module mesure les longueurs, l'argument les angles : multiplier par e^(iθ) est une rotation, et les similitudes directes du plan s'écrivent z ↦ az+b."}, {"key": "sup:441", "title": "Fonctions holomorphes : définition", "raison": "Dériver au sens complexe est si exigeant qu'une fonction holomorphe est automatiquement développable en série entière ; les intégrales se calculent alors par résidus."}, {"key": "sup:339", "title": "Fonction caractéristique", "raison": "La fonction caractéristique φ(t)=E[e^(itX)], à valeurs complexes, caractérise la loi de X et sert à démontrer le théorème central limite."}, {"id": 406, "title": "Oscillations", "raison": "Une oscillation A cos(ωt+φ) est la partie réelle de A e^(i(ωt+φ)) : dériver revient à multiplier par iω, et l'amplitude complexe code amplitude et phase."}, {"key": "sup:527", "title": "Transformée de Fourier rapide (FFT)", "raison": "La transformée de Fourier discrète évalue un polynôme aux racines n-ièmes de l'unité e^(2iπk/n) ; la FFT exploite leur structure pour passer de O(n²) à O(n log n)."}, {"key": "sup:1497", "title": "Quaternions (introduction)", "raison": "ℍ contient ℂ comme sous-corps (a+bi ↔ a+bi+0j+0k) : un quaternion se voit comme une paire de nombres complexes, et sa norme |q|² = a²+b²+c²+d² généralise le module complexe."}], "tags": ["algebre", "complexes"], "niveau": "lycee", "definition": "Les nombres complexes étendent les nombres réels en ajoutant un nombre i tel que i²=-1, ce qui permet de résoudre toute équation polynomiale, même celles sans solution réelle.", "explication_formules": "z=x+iy combine une partie réelle x et une partie imaginaire y. Le module |z|=√(x²+y²) mesure la 'longueur' de z, interprété comme distance à l'origine dans le plan complexe.", "approfondissements": [{"label": "Forme trigonométrique et exponentielle", "link": {"type": "theme", "slug": "forme-trigonometrique-et-exponentielle"}}, {"label": "Formule de Moivre et racines n-ièmes", "link": {"type": "theme", "slug": "formule-de-moivre-et-racines-n-iemes"}}, {"label": "Nombres complexes et transformations géométriques", "link": {"type": "notion", "id": 101}}, {"label": "Analyse complexe (fonctions holomorphes)", "link": {"type": "notion", "id": 8}}, {"label": "Applications en électronique (impédance)", "link": {"type": "theme", "slug": "applications-en-electronique-impedance"}}], "sous_points": [{"terme": "Plan complexe", "definition": "Le plan complexe représente chaque nombre complexe z=x+iy comme un point de coordonnées (x,y), reliant algèbre et géométrie."}, {"terme": "Module", "definition": "Le module |z|=√(x²+y²) mesure la distance entre le point z et l'origine du plan complexe."}, {"terme": "Argument", "definition": "L'argument d'un nombre complexe est l'angle que fait le segment reliant l'origine à ce point avec l'axe des réels positifs."}, {"terme": "Forme trigonométrique", "definition": "Cette écriture z=r(cos θ+i sin θ) exprime un nombre complexe à partir de son module r et de son argument θ."}], "applications_list": [{"text": "Analyser les circuits électriques en courant alternatif.", "icon": "electronics"}, {"text": "Décrire les rotations et ondes en physique.", "icon": "physics"}, {"text": "Fonder le traitement du signal (transformée de Fourier).", "icon": "communication"}]}, {"id": 102, "title": "Polynômes", "category": "Algèbre", "formulas": ["P(x) = a_n x^n + ... + a_0", "P'(x) = Σ k a_k x^{k-1}", "Racines : P(x)=0"], "details": "Objets fondamentaux de l’algèbre, de l’analyse et de la géométrie.", "images": ["polynomes.svg"], "correspondances": [{"id": 101, "title": "Nombres complexes"}, {"id": 104, "title": "Espaces vectoriels"}, {"key": "sup:670", "title": "Indécidabilité", "raison": "Dixième problème de Hilbert : il n'existe pas d'algorithme qui décide si une équation polynomiale à coefficients entiers a une solution entière (théorème de Matiyasevich)."}, {"key": "sup:1174", "title": "Équations différentielles linéaires d'ordre 2 à coefficients constants", "raison": "Les solutions de y'' + ay' + by = 0 sont gouvernées par les racines de l'équation caractéristique r² + ar + b = 0 : leur nature (réelles, complexes conjuguées) décide du comportement."}, {"key": "sup:547", "title": "Courbes algébriques (introduction)", "raison": "Les zéros d'un polynôme à deux variables définissent une courbe algébrique : l'étude de ces courbes (degré, genre, intersections) relève de la géométrie algébrique."}, {"key": "sup:155", "title": "Fonction génératrice", "raison": "La fonction génératrice G(s) = E[s^X] d'une variable à valeurs entières est un polynôme (ou une série) : pour la loi binomiale, G(s) = (1−p+ps)^n, et ses dérivées en 1 donnent espérance et variance."}, {"key": "sup:1244", "title": "Interpolation polynomiale de Lagrange", "raison": "Par n+1 points d'abscisses distinctes passe un unique polynôme de degré ≤ n : l'interpolation approche une fonction par un polynôme, avec une erreur contrôlée par la dérivée d'ordre n+1."}], "tags": ["algebre", "polynomes"], "niveau": "lycee", "definition": "Un polynôme est une expression construite uniquement à partir de puissances entières d'une variable et de sommes/produits par des constantes — l'objet algébrique le plus simple et le plus manipulable.", "explication_formules": "P(x)=aₙxⁿ+...+a0 : le degré n détermine le nombre maximal de racines. P'(x) se calcule terme à terme et sert à étudier les variations de P. Trouver les racines revient à résoudre P(x)=0.", "approfondissements": [{"label": "Factorisation et relations de Viète", "link": {"type": "theme", "slug": "factorisation-et-relations-de-viete"}}, {"label": "Théorème de d'Alembert-Gauss", "link": {"type": "theme", "slug": "theoreme-de-d-alembert-gauss"}}, {"label": "Polynômes irréductibles et critère d'Eisenstein", "link": {"type": "theme", "slug": "polynomes-irreductibles-et-critere-d-eisenstein"}}, {"label": "Interpolation polynomiale (Lagrange)", "link": {"type": "theme", "slug": "interpolation-polynomiale-lagrange"}}, {"label": "Polynômes sur les corps finis (cryptographie)", "link": {"type": "theme", "slug": "polynomes-sur-les-corps-finis-cryptographie"}}], "sous_points": [{"terme": "Racines", "definition": "Une racine d'un polynôme P est une valeur x telle que P(x)=0 ; le nombre de racines (comptées avec multiplicité) égale le degré sur ℂ."}, {"terme": "Factorisation", "definition": "Factoriser un polynôme, c'est l'écrire comme produit de facteurs plus simples (souvent liés à ses racines), ce qui facilite l'étude de son signe."}, {"terme": "Théorème de d'Alembert-Gauss", "definition": "Ce théorème garantit que ℂ est algébriquement clos : tout polynôme non constant à coefficients complexes possède au moins une racine complexe."}], "applications_list": [{"text": "Modéliser une trajectoire en forme de parabole.", "icon": "physics"}, {"text": "Ajuster une courbe à des données expérimentales.", "icon": "data"}, {"text": "Concevoir des codes correcteurs d'erreurs en informatique.", "icon": "computer"}]}, {"id": 103, "title": "Matrices", "category": "Algèbre", "formulas": ["A ∈ M_{n×n}(ℝ)", "det(A)", "A^{-1} si det(A) ≠ 0"], "details": "Représentation des applications linéaires.", "images": ["matrices.svg"], "correspondances": [{"id": 104, "title": "Espaces vectoriels"}, {"id": 105, "title": "Déterminant"}, {"key": "sup:1489", "title": "Théorie élémentaire des catégories : objets et morphismes (introduction culturelle)", "raison": "Les matrices sont les morphismes de la catégorie dont les objets sont les espaces ℝ^n : le produit matriciel est la composition, et la matrice unité est l'identité."}, {"key": "sup:290", "title": "Exponentielle de matrice X(t)=exp(tA)X₀", "raison": "Le système X' = AX se résout explicitement par X(t) = e^(tA)X₀ ; de plus det(e^(tA)) = e^(t·tr A) : la trace de A gouverne la dilatation des volumes le long du flot (formule de Liouville)."}, {"key": "sup:125", "title": "Matrices de rotation", "raison": "Une rotation du plan d'angle θ a pour matrice [[cos θ, −sin θ], [sin θ, cos θ]] ; plus généralement les matrices orthogonales (A^T A = I) représentent les isométries vectorielles."}, {"key": "sup:344", "title": "Chaînes de Markov : matrice de transition", "raison": "La loi de X_n est μP^n, où P est la matrice de transition (lignes de somme 1) : les puissances de matrices décrivent l'évolution d'une chaîne."}, {"key": "sup:1643", "title": "Décomposition en valeurs singulières (SVD) : calcul et applications", "raison": "Toute matrice s'écrit A = UΣV^T (décomposition en valeurs singulières) : c'est l'outil de base de la compression, de la pseudo-inverse et de l'analyse en composantes principales."}], "tags": ["algebre", "matrices"], "niveau": "prepa", "definition": "Une matrice est un tableau de nombres qui représente une transformation linéaire : elle prend un vecteur en entrée et produit un autre vecteur en sortie, de façon proportionnelle et additive.", "explication_formules": "Le déterminant det(A) mesure comment la matrice dilate ou contracte les volumes ; il est nul exactement quand la transformation 'écrase' l'espace (perte d'information). A⁻¹ existe et 'annule' l'effet de A seulement si det(A)≠0.", "approfondissements": [{"label": "Valeurs propres et diagonalisation", "link": {"type": "notion", "id": 107}}, {"label": "Décomposition en valeurs singulières (SVD)", "link": {"type": "theme", "slug": "decomposition-en-valeurs-singulieres-svd"}}, {"label": "Matrices orthogonales et rotations", "link": {"type": "theme", "slug": "matrices-orthogonales-et-rotations"}}, {"label": "Exponentielle de matrice", "link": {"type": "theme", "slug": "exponentielle-de-matrice"}}, {"label": "Matrices stochastiques et chaînes de Markov", "link": {"type": "theme", "slug": "matrices-stochastiques-et-chaines-de-markov"}}], "sous_points": [{"terme": "Rang", "definition": "Le rang d'une matrice est le nombre maximal de lignes (ou colonnes) linéairement indépendantes, mesurant combien de dimensions elle « atteint »."}, {"terme": "Noyau", "definition": "Le noyau d'une matrice regroupe tous les vecteurs qu'elle transforme en zéro : il mesure ce que la transformation « écrase »."}, {"terme": "Image", "definition": "L'image d'une matrice regroupe tous les vecteurs qu'elle peut effectivement produire, c'est-à-dire l'ensemble des sorties possibles."}, {"terme": "Opérations matricielles", "definition": "L'addition, la multiplication et l'inversion des matrices permettent de combiner et d'analyser les transformations linéaires qu'elles représentent."}], "applications_list": [{"text": "Faire pivoter ou redimensionner une image numérique.", "icon": "art"}, {"text": "Résoudre des systèmes d'équations en ingénierie.", "icon": "industry"}, {"text": "Effectuer les calculs des réseaux de neurones.", "icon": "computer"}]}, {"id": 104, "title": "Espaces vectoriels", "category": "Algèbre", "formulas": ["E espace vectoriel sur K", "Base : (e1,...,en)", "Dimension : dim(E)"], "details": "Structure fondamentale de l’algèbre linéaire.", "images": ["espaces_vectoriels.svg"], "correspondances": [{"id": 103, "title": "Matrices"}, {"id": 106, "title": "Applications linéaires"}, {"key": "sup:1952", "title": "Théorème de Zermelo (bon ordre)", "raison": "Tout espace vectoriel admet une base, mais en dimension infinie cela repose sur l'axiome du choix : l'existence de bases pour tous les espaces vectoriels lui est équivalente."}, {"key": "sup:429", "title": "Espaces normés, Banach", "raison": "Munir un espace vectoriel d'une norme complète en fait un espace de Banach ; en dimension finie toutes les normes sont équivalentes, ce qui cesse d'être vrai en dimension infinie (théorème de Riesz)."}, {"key": "sup:1212", "title": "Espaces affines et applications affines", "raison": "Un espace affine est un espace vectoriel « sans origine » : ses translations forment un espace vectoriel (sa direction), et une application affine est linéaire à une translation près."}, {"key": "sup:1240", "title": "Vecteurs aléatoires et matrice de covariance", "raison": "Un vecteur aléatoire de ℝ^n de carré intégrable est résumé par son vecteur moyenne et sa matrice de covariance, symétrique positive : l'algèbre linéaire décrit sa dispersion."}, {"key": "sup:1250", "title": "Approximation au sens des moindres carrés", "raison": "Ajuster des données par moindres carrés revient à projeter orthogonalement le vecteur des observations sur le sous-espace engendré par les colonnes du modèle."}], "tags": ["algebre", "espaces-vectoriels"], "niveau": "prepa", "definition": "Un espace vectoriel est un ensemble d'objets (vecteurs) qu'on peut additionner entre eux et multiplier par un nombre, en respectant des règles simples de cohérence — le cadre abstrait de toute l'algèbre linéaire.", "explication_formules": "Une base (e1,...,en) est un ensemble minimal de vecteurs permettant de reconstruire tous les autres par combinaison linéaire. La dimension dim(E) est le nombre de vecteurs dans une base, une quantité toujours bien définie.", "approfondissements": [{"label": "Sous-espaces et somme directe", "link": {"type": "theme", "slug": "sous-espaces-et-somme-directe"}}, {"label": "Théorème de la base incomplète", "link": {"type": "theme", "slug": "theoreme-de-la-base-incomplete"}}, {"label": "Espaces de fonctions (dimension infinie)", "link": {"type": "theme", "slug": "espaces-de-fonctions-dimension-infinie"}}, {"label": "Applications linéaires et théorème du rang", "link": {"type": "notion", "id": 106}}, {"label": "Espaces euclidiens et produit scalaire", "link": {"type": "notion", "id": 203}}], "sous_points": [{"terme": "Familles libres", "definition": "Une famille de vecteurs est libre si aucun d'entre eux ne peut s'écrire comme combinaison des autres : il n'y a aucune redondance."}, {"terme": "Familles génératrices", "definition": "Une famille génératrice permet de reconstruire tout vecteur de l'espace comme combinaison linéaire de ses éléments."}, {"terme": "Bases", "definition": "Une base est une famille à la fois libre et génératrice : le nombre minimal de vecteurs nécessaires pour engendrer tout l'espace."}, {"terme": "Dimension", "definition": "La dimension d'un espace vectoriel est le nombre de vecteurs dans n'importe laquelle de ses bases, une quantité toujours bien définie."}], "applications_list": [{"text": "Représenter des données à haute dimension en apprentissage automatique.", "icon": "computer"}, {"text": "Décrire l'espace des états en mécanique quantique.", "icon": "physics"}, {"text": "Modéliser des signaux comme fonctions dans un espace vectoriel.", "icon": "communication"}]}, {"id": 105, "title": "Déterminant", "category": "Algèbre", "formulas": ["det(A)", "det(AB) = det(A) det(B)", "A inversible ⇔ det(A) ≠ 0"], "details": "Mesure du volume orienté et de l’inversibilité.", "images": ["determinant.png"], "correspondances": [{"id": 103, "title": "Matrices"}, {"id": 107, "title": "Valeurs propres"}, {"key": "sup:1052", "title": "Produit vectoriel et produit mixte", "raison": "Dans le plan, det(u,v) est l'aire signée du parallélogramme construit sur u et v (volume signé en dimension 3) ; det(u,v)=0 exprime la colinéarité."}, {"key": "sup:264", "title": "Changement de variables (jacobien)", "raison": "Le déterminant de la matrice jacobienne est le facteur de dilatation locale des volumes : dx dy = |det J| du dv dans un changement de variables d'une intégrale multiple."}, {"key": "sup:290", "title": "Exponentielle de matrice X(t)=exp(tA)X₀", "raison": "Pour X' = AX, X(t) = e^(tA)X₀ ; le wronskien W = det X vérifie W' = tr(A)·W (formule de Liouville), donc det(e^(tA)) = e^(t·tr A) : le déterminant change l'exponentielle de matrice en exponentielle de la trace."}, {"key": "sup:1690", "title": "Exponentielle sur un groupe de Lie", "raison": "L'application det : GL_n(ℝ) → ℝ* est un morphisme de groupes de Lie dont la différentielle en I est la trace ; via l'exponentielle, det(e^X) = e^(tr X), d'où SL_n(ℝ) = {det = 1} d'algèbre de Lie {tr = 0}."}, {"key": "sup:1426", "title": "Vecteurs gaussiens", "raison": "La densité d'un vecteur gaussien de covariance Σ contient le facteur (det Σ)^(-1/2) : √(det Σ) est proportionnel au volume de l'ellipsoïde de dispersion."}, {"key": "sup:1343", "title": "Décomposition LU d'une matrice", "raison": "La formule de Leibniz demande n! termes ; l'élimination de Gauss calcule le même déterminant en O(n³) opérations."}], "tags": ["algebre", "determinant"], "niveau": "prepa", "definition": "Le déterminant est un nombre associé à une matrice carrée qui mesure le facteur d'échelle (avec signe) qu'applique la transformation correspondante sur les volumes.", "explication_formules": "det(AB)=det(A)det(B) montre que composer deux transformations multiplie leurs facteurs d'échelle. A est inversible exactement quand det(A)≠0, c'est-à-dire quand la transformation ne réduit aucune dimension à zéro.", "approfondissements": [{"label": "Développement selon une ligne/colonne", "link": {"type": "theme", "slug": "developpement-selon-une-ligne-colonne"}}, {"label": "Déterminant et changement de base", "link": {"type": "theme", "slug": "determinant-et-changement-de-base"}}, {"label": "Comatrice et formule de Cramer", "link": {"type": "theme", "slug": "comatrice-et-formule-de-cramer"}}, {"label": "Déterminant comme forme multilinéaire alternée", "link": {"type": "theme", "slug": "determinant-comme-forme-multilineaire-alternee"}}, {"label": "Wronskien (déterminant de fonctions)", "link": {"type": "theme", "slug": "wronskien-determinant-de-fonctions"}}], "sous_points": [{"terme": "Développement par rapport à une ligne", "definition": "Le déterminant d'une matrice peut se calculer récursivement en le développant selon n'importe quelle ligne ou colonne, une méthode pratique pour les petites matrices."}, {"terme": "Propriétés", "definition": "Le déterminant vérifie des propriétés utiles : il change de signe si on échange deux lignes, et devient nul si deux lignes sont identiques."}], "applications_list": [{"text": "Vérifier si un système d'équations linéaires a une solution unique.", "icon": "research"}, {"text": "Calculer une aire ou un volume orienté.", "icon": "construction"}, {"text": "Détecter si des vecteurs sont colinéaires ou coplanaires.", "icon": "research"}]}, {"id": 106, "title": "Applications linéaires", "category": "Algèbre", "formulas": ["f(u+v)=f(u)+f(v)", "f(λu)=λf(u)", "Mat(f) dépend de la base"], "details": "Fonctions préservant la structure vectorielle.", "images": ["applications_lineaires.png"], "correspondances": [{"id": 104, "title": "Espaces vectoriels"}, {"id": 103, "title": "Matrices"}], "tags": ["algebre", "applications-lineaires"], "niveau": "prepa", "definition": "Une application linéaire est une transformation entre espaces vectoriels qui respecte l'addition et la multiplication par un scalaire : elle 'ne déforme pas' les combinaisons linéaires.", "explication_formules": "f(u+v)=f(u)+f(v) et f(λu)=λf(u) sont les deux conditions qui définissent la linéarité. Une fois une base choisie, toute application linéaire se représente par une matrice, ce qui permet de la calculer concrètement.", "approfondissements": [{"label": "Noyau et image (théorème du rang)", "link": {"type": "theme", "slug": "noyau-et-image-theoreme-du-rang"}}, {"label": "Changement de base et matrices de passage", "link": {"type": "theme", "slug": "changement-de-base-et-matrices-de-passage"}}, {"label": "Applications linéaires continues (dimension infinie)", "link": {"type": "notion", "id": 106}}, {"label": "Dualité et formes linéaires", "link": {"type": "theme", "slug": "dualite-et-formes-lineaires"}}, {"label": "Composition et inversibilité", "link": {"type": "theme", "slug": "composition-et-inversibilite"}}], "sous_points": [{"terme": "Noyau", "definition": "Le noyau d'une application linéaire regroupe tous les vecteurs qu'elle envoie sur zéro."}, {"terme": "Image", "definition": "L'image regroupe tous les vecteurs effectivement atteints par l'application linéaire."}, {"terme": "Rang", "definition": "Le rang d'une application linéaire est la dimension de son image, mesurant combien de dimensions elle préserve."}, {"terme": "Théorème du rang", "definition": "Ce théorème relie les dimensions du noyau et de l'image à celle de l'espace de départ : dim(noyau)+dim(image)=dim(espace de départ)."}], "applications_list": [{"text": "Modéliser des transformations géométriques (rotation, projection).", "icon": "art"}, {"text": "Effectuer un changement d'unités ou de repère en physique.", "icon": "physics"}, {"text": "Décrire les couches d'un réseau de neurones.", "icon": "computer"}]}, {"id": 107, "title": "Valeurs propres", "category": "Algèbre", "formulas": ["A v = λ v", "det(A - λI) = 0"], "details": "Analyse spectrale des matrices.", "images": ["valeurs_propres.png"], "correspondances": [{"id": 103, "title": "Matrices"}, {"id": 108, "title": "Diagonalisation"}], "tags": ["algebre", "valeurs-propres"], "niveau": "prepa", "definition": "Une valeur propre est un facteur d'échelle particulier associé à une matrice : certains vecteurs (les vecteurs propres) gardent exactement leur direction sous la transformation, seule leur longueur change.", "explication_formules": "Av=λv signifie que le vecteur v n'est pas dévié par A, juste multiplié par λ. Les valeurs propres sont les solutions de l'équation det(A-λI)=0, appelée équation caractéristique.", "approfondissements": [{"label": "Diagonalisation et polynôme minimal", "link": {"type": "theme", "slug": "diagonalisation-et-polynome-minimal"}}, {"label": "Théorème spectral (matrices symétriques)", "link": {"type": "theme", "slug": "theoreme-spectral-matrices-symetriques"}}, {"label": "Multiplicité algébrique vs géométrique", "link": {"type": "theme", "slug": "multiplicite-algebrique-vs-geometrique"}}, {"label": "Décomposition en valeurs singulières", "link": {"type": "theme", "slug": "decomposition-en-valeurs-singulieres"}}, {"label": "Rayon spectral et convergence d'algorithmes", "link": {"type": "theme", "slug": "rayon-spectral-et-convergence-d-algorithmes"}}], "sous_points": [{"terme": "Polynôme caractéristique", "definition": "Ce polynôme χ_A(λ)=det(A-λI) a pour racines exactement les valeurs propres de la matrice A."}, {"terme": "Multiplicité", "definition": "La multiplicité d'une valeur propre est le nombre de fois qu'elle apparaît comme racine du polynôme caractéristique."}], "applications_list": [{"text": "Identifier les axes principaux de déformation en mécanique.", "icon": "industry"}, {"text": "Analyser la stabilité d'un système dynamique.", "icon": "physics"}, {"text": "Réduire la dimension de données (analyse en composantes principales).", "icon": "data"}]}, {"id": 108, "title": "Diagonalisation", "category": "Algèbre", "formulas": ["A = PDP^{-1}", "D diag(λ1,...,λn)"], "details": "Simplification des matrices via changement de base.", "images": ["diagonalisation.png"], "correspondances": [{"id": 107, "title": "Valeurs propres"}, {"id": 109, "title": "Formes quadratiques"}], "tags": ["algebre", "diagonalisation"], "niveau": "prepa", "definition": "Diagonaliser une matrice, c'est la réécrire dans une base de vecteurs propres où elle devient une simple matrice diagonale — ce qui simplifie énormément tous les calculs qui l'impliquent.", "explication_formules": "A=PDP⁻¹ où D est diagonale (contenant les valeurs propres) et P contient les vecteurs propres en colonnes. Cette forme rend le calcul de puissances de A (Aⁿ=PDⁿP⁻¹) et de l'exponentielle de matrice immédiat.", "approfondissements": [{"label": "Critère de diagonalisabilité", "link": {"type": "theme", "slug": "critere-de-diagonalisabilite"}}, {"label": "Réduction de Jordan (cas non diagonalisable)", "link": {"type": "theme", "slug": "reduction-de-jordan-cas-non-diagonalisable"}}, {"label": "Diagonalisation simultanée", "link": {"type": "theme", "slug": "diagonalisation-simultanee"}}, {"label": "Applications aux chaînes de Markov", "link": {"type": "notion", "id": 314}}, {"label": "Décomposition spectrale des opérateurs", "link": {"type": "theme", "slug": "decomposition-spectrale-des-operateurs"}}], "sous_points": [{"terme": "Matrices diagonalisables", "definition": "Une matrice est diagonalisable si elle peut être réécrite, dans une base de vecteurs propres bien choisie, sous forme diagonale."}, {"terme": "Critères", "definition": "Une matrice est diagonalisable si et seulement si la somme des dimensions de ses sous-espaces propres égale la dimension totale de l'espace."}], "applications_list": [{"text": "Résoudre efficacement des systèmes d'équations différentielles linéaires.", "icon": "research"}, {"text": "Calculer rapidement de grandes puissances de matrices (PageRank de Google).", "icon": "computer"}, {"text": "Simplifier l'étude des systèmes dynamiques.", "icon": "physics"}]}, {"id": 109, "title": "Formes quadratiques", "category": "Algèbre", "formulas": ["Q(x)=xᵀAx", "Signature de Sylvester"], "details": "Objets reliant algèbre, géométrie et analyse.", "images": ["formes_quadratiques.svg"], "correspondances": [{"id": 108, "title": "Diagonalisation"}, {"id": 110, "title": "Groupes"}, {"key": "sup:251", "title": "Matrice hessienne", "raison": "En un point critique, la hessienne (la forme quadratique du développement de Taylor à l'ordre 2) décide de la nature du point : minimum si elle est définie positive, maximum si définie négative, col si indéfinie."}, {"key": "sup:1224", "title": "Quadriques : classification", "raison": "La signature d'une forme quadratique classe les coniques et quadriques : x²/a² + y²/b² = 1 est une ellipse (signature (2,0)), x²/a² − y²/b² = 1 une hyperbole (signature (1,1))."}, {"key": "sup:1426", "title": "Vecteurs gaussiens", "raison": "La matrice de covariance d'un vecteur gaussien est symétrique définie positive ; la densité contient la forme quadratique x^T Σ^(-1) x, dont les lignes de niveau sont des ellipsoïdes."}, {"key": "sup:1725", "title": "Programmation quadratique (introduction)", "raison": "Minimiser une forme quadratique convexe sous contraintes linéaires est un problème de programmation quadratique : la convexité, équivalente à la positivité de la forme, garantit un minimum global."}], "tags": ["algebre", "formes-quadratiques"], "niveau": "prepa", "definition": "Une forme quadratique est une expression du type Q(x)=xᵀAx qui généralise le carré d'un nombre à un vecteur : elle mesure une sorte d''énergie' ou de 'distance déformée' associée à x.", "explication_formules": "La signature de Sylvester compte combien de directions rendent Q positive, négative ou nulle après diagonalisation ; cette signature est un invariant qui ne dépend pas de la base choisie, contrairement aux coefficients de Q eux-mêmes.", "approfondissements": [{"label": "Loi d'inertie de Sylvester", "link": {"type": "theme", "slug": "loi-d-inertie-de-sylvester"}}, {"label": "Réduction de Gauss", "link": {"type": "theme", "slug": "reduction-de-gauss"}}, {"label": "Formes quadratiques et convexité (Hessienne)", "link": {"type": "notion", "id": 109}}, {"label": "Coniques et surfaces quadratiques", "link": {"type": "theme", "slug": "coniques-et-surfaces-quadratiques"}}, {"label": "Applications aux statistiques multivariées (covariance)", "link": {"type": "theme", "slug": "applications-aux-statistiques-multivariees-covariance"}}], "sous_points": [{"terme": "Diagonalisation", "definition": "Diagonaliser une forme quadratique consiste à l'écrire comme une simple somme de carrés pondérés, en changeant de base."}, {"terme": "Réduction", "definition": "La réduction d'une forme quadratique révèle sa signature (nombre de coefficients positifs, négatifs, nuls), un invariant indépendant de la méthode utilisée."}], "applications_list": [{"text": "Étudier la stabilité d'un point d'équilibre en mécanique.", "icon": "physics"}, {"text": "Déterminer si un point critique est un minimum ou un maximum.", "icon": "research"}, {"text": "Modéliser la covariance en statistique.", "icon": "data"}]}, {"id": 110, "title": "Groupes", "category": "Algèbre", "formulas": ["G ensemble + opération", "Identité, inverse", "Associativité"], "details": "Structure fondamentale de symétrie.", "images": ["groupes.svg"], "correspondances": [{"id": 111, "title": "Anneaux"}, {"id": 112, "title": "Corps"}, {"key": "sup:641", "title": "Catégories : définition", "raison": "Un groupe est une catégorie à un seul objet dont tous les morphismes sont inversibles ; les morphismes de groupes sont les foncteurs entre ces catégories."}, {"key": "sup:534", "title": "Analyse harmonique sur les groupes", "raison": "Sur un groupe abélien localement compact, la transformée de Fourier décompose selon les caractères du groupe : séries de Fourier (le cercle), transformée de Fourier (ℝ), transformée discrète (ℤ/nℤ)."}, {"key": "sup:1617", "title": "Groupes de Lie : définition et exemples", "raison": "Un groupe de Lie est à la fois un groupe et une variété différentielle : les rotations SO(n) ou les matrices inversibles GL_n(ℝ) sont des groupes sur lesquels on peut faire du calcul différentiel."}, {"key": "sup:1510", "title": "Marche aléatoire simple", "raison": "Une marche aléatoire simple est la somme de pas indépendants dans le groupe (ℤ,+) : sa loi après n pas est la n-ième puissance de convolution de la loi d'un pas."}, {"key": "sup:1890", "title": "Problème du logarithme discret sur courbes elliptiques (approfondissement cryptographique)", "raison": "Le logarithme discret dans le groupe des points d'une courbe elliptique fonde la cryptographie elliptique : calculer g^x est facile, retrouver x à partir de g^x ne l'est pas."}], "tags": ["algebre", "groupes"], "niveau": "prepa", "definition": "Un groupe est un ensemble muni d'une opération qui combine deux éléments en un troisième, avec un élément neutre et un inverse pour chaque élément — la structure la plus simple pour décrire des symétries.", "explication_formules": "Les quatre propriétés (fermeture, associativité, élément neutre, inverse) suffisent à générer une théorie extrêmement riche. Le théorème de Lagrange dit que l'ordre (taille) d'un sous-groupe divise toujours l'ordre du groupe entier.", "approfondissements": [{"label": "Sous-groupes et groupes quotients", "link": {"type": "theme", "slug": "sous-groupes-et-groupes-quotients"}}, {"label": "Groupes symétriques et permutations", "link": {"type": "theme", "slug": "groupes-symetriques-et-permutations"}}, {"label": "Action de groupe et formule des classes", "link": {"type": "theme", "slug": "action-de-groupe-et-formule-des-classes"}}, {"label": "Théorie de Galois", "link": {"type": "notion", "id": 125}}, {"label": "Groupes de Lie et symétries continues", "link": {"type": "theme", "slug": "groupes-de-lie-et-symetries-continues"}}], "sous_points": [{"terme": "Groupes finis", "definition": "Un groupe fini ne contient qu'un nombre fini d'éléments ; le théorème de Lagrange dit que l'ordre de tout sous-groupe divise l'ordre du groupe entier."}, {"terme": "Groupes abéliens", "definition": "Un groupe est abélien (ou commutatif) si l'ordre dans lequel on combine deux éléments n'a pas d'importance : a*b=b*a."}], "applications_list": [{"text": "Décrire les symétries d'une molécule en chimie.", "icon": "chemistry"}, {"text": "Sécuriser des communications avec la cryptographie RSA et les courbes elliptiques.", "icon": "security"}, {"text": "Classer les mouvements possibles d'un Rubik's Cube.", "icon": "games"}]}, {"id": 111, "title": "Anneaux", "category": "Algèbre", "formulas": ["(A,+,×)", "Distributivité"], "details": "Structure algébrique avec addition et multiplication.", "images": ["anneaux.png"], "correspondances": [{"id": 110, "title": "Groupes"}, {"id": 112, "title": "Corps"}], "tags": ["algebre", "anneaux"], "niveau": "prepa", "definition": "Un anneau est un ensemble muni de deux opérations (addition et multiplication) compatibles entre elles, comme les entiers relatifs ℤ — mais où la division n'est pas toujours possible.", "explication_formules": "La distributivité a(b+c)=ab+ac relie les deux opérations et est la propriété clé qui distingue un anneau d'un simple groupe additif muni d'une multiplication indépendante.", "approfondissements": [{"label": "Idéaux et anneaux quotients", "link": {"type": "theme", "slug": "ideaux-et-anneaux-quotients"}}, {"label": "Anneaux intègres et corps de fractions", "link": {"type": "theme", "slug": "anneaux-integres-et-corps-de-fractions"}}, {"label": "Anneaux principaux et factoriels", "link": {"type": "theme", "slug": "anneaux-principaux-et-factoriels"}}, {"label": "Anneaux de polynômes", "link": {"type": "theme", "slug": "anneaux-de-polynomes"}}, {"label": "Applications en cryptographie et codage", "link": {"type": "theme", "slug": "applications-en-cryptographie-et-codage"}}], "sous_points": [{"terme": "Anneaux commutatifs", "definition": "Un anneau est commutatif si sa multiplication vérifie ab=ba pour tous ses éléments, comme c'est le cas pour ℤ."}, {"terme": "Idéaux", "definition": "Un idéal est un sous-ensemble d'un anneau stable par absorption : le multiplier par n'importe quel élément de l'anneau reste dans l'idéal."}], "applications_list": [{"text": "Fonder l'arithmétique modulaire utilisée en cryptographie.", "icon": "security"}, {"text": "Structurer les polynômes pour les codes correcteurs d'erreurs.", "icon": "computer"}, {"text": "Modéliser les calculs en précision finie des ordinateurs.", "icon": "computer"}]}, {"id": 112, "title": "Corps", "category": "Algèbre", "formulas": ["K corps", "ℚ, ℝ, ℂ"], "details": "Structure algébrique où tout élément non nul est inversible.", "images": ["corps.png"], "correspondances": [{"id": 111, "title": "Anneaux"}, {"id": 113, "title": "Arithmétique modulaire"}], "tags": ["algebre", "corps"], "niveau": "prepa", "definition": "Un corps est un anneau où, en plus, tout élément non nul possède un inverse pour la multiplication : on peut donc toujours diviser (sauf par zéro), comme dans ℚ, ℝ ou ℂ.", "explication_formules": "ℚ, ℝ, ℂ sont les corps usuels, chacun contenant le précédent avec des propriétés supplémentaires (ℝ est complet, ℂ est algébriquement clos). Un corps fini 𝔽_q existe pour toute puissance de nombre premier q.", "approfondissements": [{"label": "Extensions de corps et degré", "link": {"type": "theme", "slug": "extensions-de-corps-et-degre"}}, {"label": "Corps finis et théorie de Galois", "link": {"type": "theme", "slug": "corps-finis-et-theorie-de-galois"}}, {"label": "Corps de rupture et de décomposition", "link": {"type": "theme", "slug": "corps-de-rupture-et-de-decomposition"}}, {"label": "Corps algébriquement clos", "link": {"type": "theme", "slug": "corps-algebriquement-clos"}}, {"label": "Applications aux codes correcteurs", "link": {"type": "theme", "slug": "applications-aux-codes-correcteurs"}}], "sous_points": [{"terme": "Extensions de corps", "definition": "Une extension de corps L/K est un corps L qui contient un plus petit corps K, permettant par exemple d'y ajouter des racines manquantes."}, {"terme": "Polynômes irréductibles", "definition": "Un polynôme irréductible ne peut pas être factorisé en polynômes de degré strictement plus petit sur le corps considéré."}], "applications_list": [{"text": "Résoudre des systèmes d'équations linéaires (l'algèbre linéaire nécessite un corps).", "icon": "research"}, {"text": "Construire des codes correcteurs d'erreurs sur des corps finis.", "icon": "computer"}, {"text": "Fonder la cryptographie sur courbes elliptiques.", "icon": "security"}]}, {"id": 113, "title": "Arithmétique modulaire", "category": "Algèbre", "formulas": ["a ≡ b (mod n)", "ℤ/nℤ"], "details": "Base de la cryptographie moderne.", "images": ["modulaire.png"], "correspondances": [{"id": 112, "title": "Corps"}, {"id": 114, "title": "Cryptographie"}], "tags": ["algebre", "modulaire"], "niveau": "lycee", "definition": "L'arithmétique modulaire étudie les nombres 'en cycle' : deux nombres sont considérés équivalents (congrus) s'ils ont le même reste dans une division par un nombre fixé n.", "explication_formules": "a≡b (mod n) signifie que a-b est un multiple de n. L'ensemble ℤ/nℤ regroupe les n restes possibles (0 à n-1) et permet de faire des calculs 'cycliques', comme les heures sur une horloge (modulo 12 ou 24).", "approfondissements": [{"label": "Théorème chinois des restes", "link": {"type": "theme", "slug": "theoreme-chinois-des-restes"}}, {"label": "Petit théorème de Fermat", "link": {"type": "theme", "slug": "petit-theoreme-de-fermat"}}, {"label": "Inversibilité modulo n", "link": {"type": "theme", "slug": "inversibilite-modulo-n"}}, {"label": "Applications à la cryptographie RSA", "link": {"type": "theme", "slug": "applications-a-la-cryptographie-rsa"}}, {"label": "Résidus quadratiques", "link": {"type": "theme", "slug": "residus-quadratiques"}}], "sous_points": [{"terme": "Inverses mod n", "definition": "Un nombre a possède un inverse modulo n (un nombre b tel que ab≡1) si et seulement si a et n sont premiers entre eux."}, {"terme": "Théorème de Fermat", "definition": "Le petit théorème de Fermat dit que si p est premier et a n'est pas multiple de p, alors a^(p-1)≡1 (mod p)."}], "applications_list": [{"text": "Lire l'heure sur une horloge (modulo 12/24).", "icon": "navigation"}, {"text": "Vérifier une clé de contrôle (carte bancaire, ISBN).", "icon": "finance"}, {"text": "Fonder la cryptographie moderne (RSA).", "icon": "security"}]}, {"id": 114, "title": "Cryptographie", "category": "Algèbre", "formulas": ["RSA : c ≡ m^e (mod n)", "Diffie-Hellman"], "details": "Sécurité basée sur l’algèbre.", "images": ["crypto.png"], "correspondances": [{"id": 113, "title": "Arithmétique modulaire"}, {"id": 103, "title": "Matrices"}], "tags": ["algebre", "crypto"], "niveau": "lycee", "definition": "La cryptographie utilise des propriétés mathématiques (souvent arithmétiques) difficiles à inverser sans une information secrète, pour sécuriser la transmission d'informations.", "explication_formules": "RSA : c≡mᵉ (mod n) chiffre un message m ; le déchiffrement nécessite de connaître la factorisation de n, calcul extrêmement difficile pour de grands nombres. Diffie-Hellman permet à deux personnes de créer une clé secrète commune sans jamais l'échanger directement.", "approfondissements": [{"label": "Logarithme discret et Diffie-Hellman", "link": {"type": "theme", "slug": "logarithme-discret-et-diffie-hellman"}}, {"label": "Cryptographie sur courbes elliptiques", "link": {"type": "theme", "slug": "cryptographie-sur-courbes-elliptiques"}}, {"label": "Fonctions de hachage cryptographiques", "link": {"type": "theme", "slug": "fonctions-de-hachage-cryptographiques"}}, {"label": "Cryptographie post-quantique", "link": {"type": "theme", "slug": "cryptographie-post-quantique"}}, {"label": "Preuves à divulgation nulle de connaissance", "link": {"type": "theme", "slug": "preuves-a-divulgation-nulle-de-connaissance"}}], "sous_points": [{"terme": "Exponentiation modulaire", "definition": "Cette opération calcule aᵏ mod n efficacement, sans jamais manipuler de nombres immenses, brique de base des calculs cryptographiques comme RSA."}, {"terme": "Factorisation", "definition": "Factoriser un grand nombre en ses facteurs premiers est un problème extrêmement difficile, sur lequel repose la sécurité de RSA."}], "applications_list": [{"text": "Sécuriser les connexions bancaires en ligne (HTTPS).", "icon": "finance"}, {"text": "Protéger les communications par messagerie chiffrée.", "icon": "security"}, {"text": "Authentifier les transactions en cryptomonnaie.", "icon": "finance"}]}, {"id": 200, "title": "Points, droites et plans", "category": "Géométrie", "formulas": ["Droite (plan) : ax + by + c = 0", "Plan (espace) : ax + by + cz + d = 0", "Distance point–droite : |ax0 + by0 + c| / √(a² + b²)"], "details": "Les points, droites et plans sont les objets de base de la géométrie euclidienne en dimension 2 et 3.", "images": ["points_droites_plans.png"], "correspondances": [{"id": 201, "title": "Vecteurs"}, {"id": 216, "title": "Géométrie vectorielle"}], "tags": ["geometrie", "droites", "plans"], "niveau": "college", "definition": "Points, droites et plans sont les objets géométriques les plus élémentaires, à partir desquels toutes les figures et tous les solides se construisent.", "explication_formules": "ax+by+c=0 décrit toutes les droites du plan via une équation linéaire. La distance point-droite |ax0+by0+c|/√(a²+b²) mesure directement l'écart perpendiculaire entre un point et une droite sans avoir à chercher le point le plus proche.", "approfondissements": [{"label": "Équations paramétriques de droites et plans", "link": {"type": "theme", "slug": "equations-parametriques-de-droites-et-plans"}}, {"label": "Positions relatives (parallélisme, intersection)", "link": {"type": "theme", "slug": "positions-relatives-parallelisme-intersection"}}, {"label": "Géométrie analytique dans l'espace", "link": {"type": "notion", "id": 217}}, {"label": "Distance entre deux droites", "link": {"type": "theme", "slug": "distance-entre-deux-droites"}}, {"label": "Faisceaux de droites et de plans", "link": {"type": "theme", "slug": "faisceaux-de-droites-et-de-plans"}}], "sous_points": [{"terme": "Incidence (appartenance)", "definition": "L'incidence décrit si un point appartient à une droite ou un plan, la relation la plus élémentaire de la géométrie."}, {"terme": "Parallélisme", "definition": "Deux droites (ou plans) sont parallèles si elles ne se rencontrent jamais, quelle que soit la distance sur laquelle on les prolonge."}, {"terme": "Orthogonalité", "definition": "Deux droites sont orthogonales si elles se coupent en formant un angle droit (90°)."}, {"terme": "Représentation par équations", "definition": "Une droite ou un plan peut se décrire par une équation cartésienne (contrainte à vérifier) ou paramétrique (point + direction)."}], "applications_list": [{"text": "Concevoir des plans d'architecture.", "icon": "construction"}, {"text": "Programmer les déplacements d'un robot ou d'un GPS.", "icon": "robotics"}, {"text": "Détecter des collisions dans un jeu vidéo.", "icon": "games"}]}, {"id": 201, "title": "Vecteurs", "category": "Géométrie", "formulas": ["→AB = (xB - xA, yB - yA)", "Norme : ||u|| = √(x² + y²)", "u·v = x1x2 + y1y2"], "details": "Les vecteurs décrivent des déplacements, des directions et des intensités dans le plan ou l’espace.", "images": ["vecteurs.png"], "correspondances": [{"id": 200, "title": "Points, droites et plans"}, {"id": 203, "title": "Produit scalaire"}], "tags": ["geometrie", "vecteurs"], "niveau": "lycee", "definition": "Un vecteur représente un déplacement : il a une direction, un sens et une longueur, mais pas de position fixe dans l'espace — seul le trajet 'de A vers B' compte.", "explication_formules": "→AB=(xB-xA, yB-yA) donne les coordonnées du déplacement de A vers B. Le produit scalaire u·v=x1x2+y1y2 mesure à la fois l'alignement de deux vecteurs et permet de calculer angles et projections.", "approfondissements": [{"label": "Produit vectoriel (dimension 3)", "link": {"type": "theme", "slug": "produit-vectoriel-dimension-3"}}, {"label": "Combinaisons linéaires et colinéarité", "link": {"type": "theme", "slug": "combinaisons-lineaires-et-colinearite"}}, {"label": "Vecteurs et translations", "link": {"type": "theme", "slug": "vecteurs-et-translations"}}, {"label": "Espaces vectoriels abstraits", "link": {"type": "notion", "id": 104}}, {"label": "Vecteurs aléatoires en probabilité", "link": {"type": "theme", "slug": "vecteurs-aleatoires-en-probabilite"}}], "sous_points": [{"terme": "Somme de vecteurs", "definition": "La somme de deux vecteurs s'obtient en mettant bout à bout leurs déplacements : c'est la règle du parallélogramme."}, {"terme": "Multiplication par un scalaire", "definition": "Multiplier un vecteur par un nombre k change sa longueur (et son sens si k est négatif) sans changer sa direction."}, {"terme": "Colinéarité", "definition": "Deux vecteurs sont colinéaires si l'un est un multiple de l'autre, c'est-à-dire s'ils pointent dans la même direction (ou la direction opposée)."}, {"terme": "Orthogonalité", "definition": "Deux vecteurs sont orthogonaux si leur produit scalaire est nul, ce qui correspond géométriquement à un angle droit entre eux."}], "applications_list": [{"text": "Décrire une force ou une vitesse en physique.", "icon": "physics"}, {"text": "Programmer les déplacements dans un jeu vidéo.", "icon": "games"}, {"text": "Calculer des trajectoires en navigation GPS.", "icon": "navigation"}]}, {"id": 202, "title": "Distances et milieux", "category": "Géométrie", "formulas": ["Distance : d(A,B) = √((xB-xA)² + (yB-yA)²)", "Milieu : M = ((xA+xB)/2, (yA+yB)/2)"], "details": "La distance mesure la longueur d’un segment, le milieu est un point remarquable de ce segment.", "images": ["distance_milieu.png"], "correspondances": [{"id": 201, "title": "Vecteurs"}, {"id": 204, "title": "Cercles"}], "tags": ["geometrie", "distance", "milieu"], "niveau": "college", "definition": "La distance et le milieu sont deux mesures géométriques fondamentales : l'une quantifie l'écart entre deux points, l'autre localise le point exactement à équidistance des deux.", "explication_formules": "d(A,B)=√((xB-xA)²+(yB-yA)²) vient directement du théorème de Pythagore appliqué aux différences de coordonnées. Le milieu M=((xA+xB)/2,(yA+yB)/2) est simplement la moyenne des coordonnées.", "approfondissements": [{"label": "Distance dans l'espace (3D)", "link": {"type": "theme", "slug": "distance-dans-l-espace-3d"}}, {"label": "Médiatrice d'un segment", "link": {"type": "theme", "slug": "mediatrice-d-un-segment"}}, {"label": "Distance euclidienne vs autres normes", "link": {"type": "theme", "slug": "distance-euclidienne-vs-autres-normes"}}, {"label": "Barycentres pondérés", "link": {"type": "theme", "slug": "barycentres-ponderes"}}, {"label": "Distances dans des espaces abstraits", "link": {"type": "theme", "slug": "distances-dans-des-espaces-abstraits"}}], "sous_points": [{"terme": "Segments", "definition": "Un segment est la portion de droite reliant deux points précis, de longueur finie."}, {"terme": "Médiatrices", "definition": "La médiatrice d'un segment regroupe tous les points équidistants de ses deux extrémités."}, {"terme": "Cercles de centre et rayon donnés", "definition": "Un cercle est entièrement déterminé par son centre (un point) et son rayon (une distance) : l'ensemble des points à cette distance du centre."}], "applications_list": [{"text": "Calculer une distance à vol d'oiseau sur une carte.", "icon": "navigation"}, {"text": "Trouver le point de rencontre idéal entre deux lieux.", "icon": "navigation"}, {"text": "Positionner le centre de gravité d'une figure simple.", "icon": "construction"}]}, {"id": 203, "title": "Produit scalaire", "category": "Géométrie", "formulas": ["u·v = ||u|| ||v|| cos θ", "u·v = x1x2 + y1y2 (plan)", "Orthogonalité : u·v = 0"], "details": "Le produit scalaire relie vecteurs, angles et longueurs, et permet de définir la notion d’orthogonalité.", "images": ["produit_scalaire.png"], "correspondances": [{"id": 201, "title": "Vecteurs"}, {"id": 205, "title": "Angles"}, {"key": "sup:201", "title": "Espaces euclidiens : produit scalaire, orthogonalité", "raison": "En dimension quelconque, un produit scalaire redonne longueurs, angles et orthogonalité ; l'inégalité de Cauchy–Schwarz |(u|v)| ≤ ‖u‖‖v‖ y reste vraie."}, {"key": "sup:241", "title": "Séries de Fourier : coefficients", "raison": "Avec (f|g) = (1/2π) ∫_0^(2π) f·conj(g), les e^(inθ) sont orthonormées : les coefficients de Fourier sont des projections orthogonales, et la formule de Parseval est le théorème de Pythagore."}, {"key": "sup:336", "title": "Covariance et corrélation", "raison": "La covariance est un produit scalaire sur les variables centrées de carré intégrable ; le coefficient de corrélation est le cosinus de l'angle entre elles, d'où |ρ| ≤ 1."}, {"key": "sup:1640", "title": "Méthode du gradient conjugué", "raison": "Le gradient conjugué construit des directions orthogonales pour le produit scalaire (x|Ay) d'une matrice A symétrique définie positive : il résout Ax = b en au plus n itérations en arithmétique exacte."}, {"id": 404, "title": "Travail et puissance", "raison": "Le travail d'une force constante est le produit scalaire W = F·d : seule la composante de la force dans la direction du déplacement travaille."}], "tags": ["geometrie", "produit-scalaire"], "niveau": "lycee", "definition": "Le produit scalaire combine deux vecteurs pour produire un nombre qui mesure à la fois leur longueur et leur alignement angulaire — un outil central de toute la géométrie euclidienne.", "explication_formules": "u·v=‖u‖‖v‖cos θ relie directement le produit scalaire à l'angle θ entre les vecteurs. Quand u·v=0, les vecteurs sont perpendiculaires (orthogonaux) : c'est le test d'orthogonalité le plus utilisé en géométrie.", "approfondissements": [{"label": "Produit vectoriel et produit mixte", "link": {"type": "theme", "slug": "produit-vectoriel-et-produit-mixte"}}, {"label": "Projections orthogonales", "link": {"type": "theme", "slug": "projections-orthogonales"}}, {"label": "Produit scalaire dans un espace euclidien général", "link": {"type": "notion", "id": 203}}, {"label": "Angle entre deux vecteurs en haute dimension", "link": {"type": "theme", "slug": "angle-entre-deux-vecteurs-en-haute-dimension"}}, {"label": "Similarité cosinus en IA", "link": {"type": "theme", "slug": "similarite-cosinus-en-ia"}}], "sous_points": [{"terme": "Norme", "definition": "La norme d'un vecteur mesure sa longueur ; elle se calcule à partir du produit scalaire du vecteur avec lui-même."}, {"terme": "Projection orthogonale", "definition": "La projection orthogonale d'un vecteur sur un autre en donne la composante alignée avec ce dernier."}, {"terme": "Angle entre deux vecteurs", "definition": "L'angle entre deux vecteurs se retrouve à partir du produit scalaire via la formule cos θ=u·v/(‖u‖‖v‖)."}, {"terme": "Inégalité de Cauchy-Schwarz", "definition": "Cette inégalité dit que le produit scalaire de deux vecteurs est toujours borné par le produit de leurs normes."}], "applications_list": [{"text": "Calculer le travail d'une force non alignée avec le déplacement.", "icon": "physics"}, {"text": "Détecter si deux directions sont perpendiculaires en CAO.", "icon": "construction"}, {"text": "Mesurer la similarité entre deux vecteurs en apprentissage automatique.", "icon": "computer"}]}, {"id": 204, "title": "Cercles", "category": "Géométrie", "formulas": ["(x - a)² + (y - b)² = r²", "Longueur : 2πr", "Aire : πr²"], "details": "Le cercle est l’ensemble des points à distance constante d’un centre donné.", "images": ["cercles.png"], "correspondances": [{"id": 202, "title": "Distances et milieux"}, {"id": 206, "title": "Triangles"}], "tags": ["geometrie", "cercles"], "niveau": "college", "definition": "Un cercle est l'ensemble de tous les points situés à une distance fixe (le rayon) d'un point central — la figure la plus symétrique du plan.", "explication_formules": "(x-a)²+(y-b)²=r² décrit tous les cercles via le théorème de Pythagore : la distance au centre (a,b) doit toujours valoir r. Le périmètre 2πr et l'aire πr² dépendent uniquement du rayon.", "approfondissements": [{"label": "Équation générale du cercle", "link": {"type": "theme", "slug": "equation-generale-du-cercle"}}, {"label": "Cercle circonscrit et inscrit d'un triangle", "link": {"type": "notion", "id": 212}}, {"label": "Puissance d'un point par rapport à un cercle", "link": {"type": "theme", "slug": "puissance-d-un-point-par-rapport-a-un-cercle"}}, {"label": "Coniques (généralisation du cercle)", "link": {"type": "theme", "slug": "coniques-generalisation-du-cercle"}}, {"label": "Sphères (cercle en 3 dimensions)", "link": {"type": "theme", "slug": "spheres-cercle-en-3-dimensions"}}], "sous_points": [{"terme": "Tangentes", "definition": "Une tangente à un cercle est une droite qui le touche en un seul point, perpendiculaire au rayon en ce point."}, {"terme": "Arcs", "definition": "Un arc de cercle est une portion du cercle délimitée par deux points sur celui-ci."}, {"terme": "Angles au centre et angles inscrits", "definition": "L'angle au centre a pour sommet le centre du cercle ; l'angle inscrit a son sommet sur le cercle. L'angle inscrit vaut toujours la moitié de l'angle au centre qui intercepte le même arc."}, {"terme": "Puissance d'un point", "definition": "La puissance d'un point par rapport à un cercle est une quantité constante qui relie les distances aux points d'intersection de toute droite passant par ce point."}], "applications_list": [{"text": "Concevoir des roues et engrenages en mécanique.", "icon": "industry"}, {"text": "Calculer la couverture d'une antenne radio.", "icon": "communication"}, {"text": "Modéliser des orbites simplifiées en astronomie.", "icon": "space"}]}, {"id": 205, "title": "Angles", "category": "Géométrie", "formulas": ["cos θ = u·v / (||u|| ||v||)", "Somme des angles d’un triangle : 180°"], "details": "Les angles mesurent l’ouverture entre deux segments ou vecteurs.", "images": ["angles.png"], "correspondances": [{"id": 203, "title": "Produit scalaire"}, {"id": 207, "title": "Trigonométrie"}], "tags": ["geometrie", "angles"], "niveau": "college", "definition": "Un angle mesure l'écart de direction entre deux droites ou deux vecteurs partageant une origine commune — le fondement de toute la trigonométrie.", "explication_formules": "cos θ=u·v/(‖u‖‖v‖) permet de calculer un angle à partir de coordonnées, sans avoir besoin de rapporteur. La somme des angles d'un triangle vaut toujours 180°, une propriété fondamentale de la géométrie euclidienne plane.", "approfondissements": [{"label": "Angles orientés", "link": {"type": "theme", "slug": "angles-orientes"}}, {"label": "Angle inscrit et angle au centre", "link": {"type": "theme", "slug": "angle-inscrit-et-angle-au-centre"}}, {"label": "Trigonométrie et cercle unité", "link": {"type": "theme", "slug": "trigonometrie-et-cercle-unite"}}, {"label": "Angles en géométrie sphérique", "link": {"type": "theme", "slug": "angles-en-geometrie-spherique"}}, {"label": "Angles dièdres en 3D", "link": {"type": "theme", "slug": "angles-diedres-en-3d"}}], "sous_points": [{"terme": "Angles orientés", "definition": "Un angle orienté tient compte du sens de rotation (horaire ou antihoraire), contrairement à la simple mesure d'angle."}, {"terme": "Angles complémentaires", "definition": "Deux angles sont complémentaires si leur somme vaut 90°."}, {"terme": "Angles supplémentaires", "definition": "Deux angles sont supplémentaires si leur somme vaut 180°."}, {"terme": "Trigonométrie", "definition": "La trigonométrie relie les angles d'un triangle rectangle aux longueurs de ses côtés via sinus, cosinus et tangente."}], "applications_list": [{"text": "Trianguler une position en navigation.", "icon": "navigation"}, {"text": "Orienter des panneaux solaires selon l'angle du soleil.", "icon": "environment"}, {"text": "Calculer des trajectoires balistiques.", "icon": "physics"}]}, {"id": 206, "title": "Triangles", "category": "Géométrie", "formulas": ["Pythagore : a² + b² = c² (triangle rectangle)", "Aire : (base × hauteur)/2", "Formule de Héron : A = √(p(p-a)(p-b)(p-c))"], "details": "Les triangles sont les figures fondamentales de la géométrie plane.", "images": ["triangles.png"], "correspondances": [{"id": 205, "title": "Angles"}, {"id": 210, "title": "Polygones"}], "tags": ["geometrie", "triangles"], "niveau": "college", "definition": "Le triangle est la figure polygonale la plus simple et la plus rigide (trois côtés déterminent sa forme de façon unique), servant de brique de base à toute la géométrie.", "explication_formules": "Le théorème de Pythagore a²+b²=c² caractérise exactement les triangles rectangles. La formule de Héron calcule l'aire d'un triangle à partir de ses trois côtés seulement, sans connaître sa hauteur.", "approfondissements": [{"label": "Théorème d'Al-Kashi (loi des cosinus)", "link": {"type": "theme", "slug": "theoreme-d-al-kashi-loi-des-cosinus"}}, {"label": "Théorème de Thalès", "link": {"type": "theme", "slug": "theoreme-de-thales"}}, {"label": "Points remarquables (centre de gravité, orthocentre)", "link": {"type": "theme", "slug": "points-remarquables-centre-de-gravite-orthocentre"}}, {"label": "Triangles semblables", "link": {"type": "theme", "slug": "triangles-semblables"}}, {"label": "Triangulation en topographie et infographie", "link": {"type": "theme", "slug": "triangulation-en-topographie-et-infographie"}}], "sous_points": [{"terme": "Triangles rectangles", "definition": "Un triangle rectangle possède un angle droit ; le théorème de Pythagore s'y applique directement."}, {"terme": "Triangles isocèles", "definition": "Un triangle isocèle a deux côtés de même longueur, et donc deux angles égaux."}, {"terme": "Triangles équilatéraux", "definition": "Un triangle équilatéral a ses trois côtés égaux, et donc ses trois angles égaux à 60°."}, {"terme": "Médianes, hauteurs, bissectrices", "definition": "Une médiane relie un sommet au milieu du côté opposé ; une hauteur est perpendiculaire au côté opposé ; une bissectrice partage un angle en deux parties égales."}], "applications_list": [{"text": "Trianguler des positions en topographie et GPS.", "icon": "navigation"}, {"text": "Calculer des distances inaccessibles (hauteur d'une montagne).", "icon": "navigation"}, {"text": "Garantir la rigidité de structures en architecture.", "icon": "construction"}]}, {"id": 207, "title": "Trigonométrie", "category": "Géométrie", "formulas": ["sin² x + cos² x = 1", "tan x = sin x / cos x", "cos(a+b) = cos a cos b - sin a sin b"], "details": "La trigonométrie relie angles et longueurs dans les triangles et sur le cercle trigonométrique.", "images": ["trigo.png"], "correspondances": [{"id": 205, "title": "Angles"}, {"id": 209, "title": "Nombres complexes en géométrie"}], "tags": ["geometrie", "trigo"], "niveau": "college", "definition": "La trigonométrie relie les angles d'un triangle rectangle aux longueurs de ses côtés, via les fonctions sinus, cosinus et tangente — l'outil qui connecte géométrie et calcul.", "explication_formules": "sin²x+cos²x=1 exprime que le point (cos x, sin x) est toujours sur le cercle de rayon 1. Les formules d'addition comme cos(a+b) permettent de calculer un angle composé à partir d'angles connus.", "approfondissements": [{"label": "Formules de duplication et linéarisation", "link": {"type": "theme", "slug": "formules-de-duplication-et-linearisation"}}, {"label": "Fonctions trigonométriques réciproques", "link": {"type": "theme", "slug": "fonctions-trigonometriques-reciproques"}}, {"label": "Trigonométrie sphérique", "link": {"type": "theme", "slug": "trigonometrie-spherique"}}, {"label": "Fonctions hyperboliques", "link": {"type": "theme", "slug": "fonctions-hyperboliques"}}, {"label": "Séries de Fourier (décomposition en sinus/cosinus)", "link": {"type": "notion", "id": 7}}], "sous_points": [{"terme": "Identités trigonométriques", "definition": "Ces relations, comme sin²x+cos²x=1, relient entre elles les fonctions trigonométriques et permettent de simplifier des expressions."}, {"terme": "Cercle trigonométrique", "definition": "Ce cercle de rayon 1 centré à l'origine sert de référence : les coordonnées d'un point sur ce cercle sont (cos θ, sin θ)."}, {"terme": "Angles remarquables", "definition": "Certains angles (0, π/6, π/4, π/3, π/2) ont des valeurs de sinus et cosinus simples et à connaître par cœur."}], "applications_list": [{"text": "Calculer la hauteur d'un bâtiment à partir d'un angle de visée.", "icon": "construction"}, {"text": "Modéliser des phénomènes périodiques (marées, sons, courant alternatif).", "icon": "audio"}, {"text": "Programmer des rotations en infographie.", "icon": "art"}]}, {"id": 208, "title": "Quadrilatères", "category": "Géométrie", "formulas": ["Aire rectangle : L × l", "Aire parallélogramme : base × hauteur"], "details": "Les quadrilatères sont des polygones à quatre côtés, avec des propriétés variées selon les types.", "images": ["quadrilateres.png"], "correspondances": [{"id": 206, "title": "Triangles"}, {"id": 210, "title": "Polygones"}], "tags": ["geometrie", "quadrilateres"], "niveau": "college", "definition": "Un quadrilatère est un polygone à quatre côtés (rectangle, carré, losange, trapèze...) dont les propriétés varient selon les contraintes imposées sur les côtés et les angles.", "explication_formules": "L'aire d'un rectangle L×l vient directement du découpage en unités carrées. L'aire d'un parallélogramme (base×hauteur) généralise cette idée même quand les angles ne sont plus droits.", "approfondissements": [{"label": "Losanges, trapèzes et propriétés spécifiques", "link": {"type": "theme", "slug": "losanges-trapezes-et-proprietes-specifiques"}}, {"label": "Quadrilatères inscriptibles", "link": {"type": "theme", "slug": "quadrilateres-inscriptibles"}}, {"label": "Théorème de Varignon", "link": {"type": "theme", "slug": "theoreme-de-varignon"}}, {"label": "Quadrilatères en 3D (parallélépipèdes)", "link": {"type": "theme", "slug": "quadrilateres-en-3d-parallelepipedes"}}, {"label": "Pavages par quadrilatères", "link": {"type": "theme", "slug": "pavages-par-quadrilateres"}}], "sous_points": [{"terme": "Rectangles", "definition": "Un rectangle a quatre angles droits ; ses côtés opposés sont parallèles et de même longueur."}, {"terme": "Carrés", "definition": "Un carré est un rectangle dont les quatre côtés sont égaux : le quadrilatère le plus symétrique."}, {"terme": "Losanges", "definition": "Un losange a ses quatre côtés égaux et ses diagonales perpendiculaires."}, {"terme": "Parallélogrammes", "definition": "Un parallélogramme a ses côtés opposés parallèles et égaux deux à deux."}, {"terme": "Trapèzes", "definition": "Un trapèze a seulement deux côtés parallèles (les bases), les deux autres pouvant être quelconques."}], "applications_list": [{"text": "Calculer la surface d'une pièce ou d'un terrain.", "icon": "construction"}, {"text": "Dimensionner des matériaux de construction.", "icon": "construction"}, {"text": "Concevoir des mises en page en design graphique.", "icon": "art"}]}, {"id": 209, "title": "Nombres complexes en géométrie", "category": "Géométrie", "formulas": ["z = x + iy", "Rotation : z' = e^{iθ} z", "Translation : z' = z + a"], "details": "Les nombres complexes permettent de décrire les transformations du plan de manière élégante.", "images": ["complexes_geo.png"], "correspondances": [{"id": 207, "title": "Trigonométrie"}, {"id": 211, "title": "Transformations géométriques"}], "tags": ["geometrie", "complexes"], "niveau": "lycee", "definition": "Cette notion utilise les nombres complexes comme un outil géométrique puissant : chaque point du plan devient un nombre, et les transformations géométriques deviennent de simples opérations algébriques.", "explication_formules": "z=x+iy identifie un point à un nombre complexe. La rotation d'angle θ autour de l'origine s'écrit simplement z'=e^{iθ}z, bien plus simple que la matrice de rotation équivalente.", "approfondissements": [{"label": "Affixe d'un vecteur et d'un point", "link": {"type": "theme", "slug": "affixe-d-un-vecteur-et-d-un-point"}}, {"label": "Similitudes directes et indirectes", "link": {"type": "theme", "slug": "similitudes-directes-et-indirectes"}}, {"label": "Racines n-ièmes de l'unité et polygones réguliers", "link": {"type": "theme", "slug": "racines-n-iemes-de-l-unite-et-polygones-reguliers"}}, {"label": "Transformations conformes", "link": {"type": "notion", "id": 706}}, {"label": "Géométrie olympique via les complexes", "link": {"type": "notion", "id": 610}}], "sous_points": [{"terme": "Rotations", "definition": "Une rotation d'angle θ s'écrit z'=e^{iθ}z en nombres complexes, tournant chaque point autour de l'origine."}, {"terme": "Homothéties", "definition": "Une homothétie de rapport k s'écrit z'=kz, agrandissant ou réduisant la figure depuis l'origine."}, {"terme": "Translations", "definition": "Une translation par un vecteur d'affixe a s'écrit simplement z'=z+a."}, {"terme": "Similitudes", "definition": "Une similitude combine rotation et homothétie en une seule transformation z'=az+b, préservant les angles et multipliant les longueurs."}], "applications_list": [{"text": "Simplifier les calculs de rotations et symétries en infographie.", "icon": "art"}, {"text": "Résoudre élégamment des problèmes de géométrie olympique.", "icon": "education"}, {"text": "Analyser des figures ayant des symétries complexes.", "icon": "art"}]}, {"id": 210, "title": "Polygones", "category": "Géométrie", "formulas": ["Somme des angles intérieurs : (n-2) × 180°", "Aire polygone régulier : (n × côté²) / (4 tan(π/n))"], "details": "Les polygones sont des figures formées par plusieurs segments reliés bout à bout.", "images": ["polygones.png"], "correspondances": [{"id": 208, "title": "Quadrilatères"}, {"id": 212, "title": "Cercle circonscrit"}], "tags": ["geometrie", "polygones"], "niveau": "college", "definition": "Un polygone est une figure plane fermée formée de segments de droite reliés bout à bout — le cas général dont le triangle et le quadrilatère sont des exemples particuliers.", "explication_formules": "La somme des angles intérieurs (n-2)×180° augmente avec le nombre de côtés n. L'aire d'un polygone régulier dépend uniquement du nombre de côtés et de la longueur d'un côté.", "approfondissements": [{"label": "Polygones réguliers et construction", "link": {"type": "theme", "slug": "polygones-reguliers-et-construction"}}, {"label": "Triangulation de polygones", "link": {"type": "theme", "slug": "triangulation-de-polygones"}}, {"label": "Polygones convexes vs non convexes", "link": {"type": "theme", "slug": "polygones-convexes-vs-non-convexes"}}, {"label": "Théorème de Pick (aire sur grille)", "link": {"type": "theme", "slug": "theoreme-de-pick-aire-sur-grille"}}, {"label": "Polyèdres (polygones en 3D)", "link": {"type": "theme", "slug": "polyedres-polygones-en-3d"}}], "sous_points": [{"terme": "Polygones convexes", "definition": "Un polygone convexe ne « rentre » jamais vers l'intérieur : tout segment reliant deux de ses points reste à l'intérieur."}, {"terme": "Polygones réguliers", "definition": "Un polygone régulier a tous ses côtés et tous ses angles égaux, comme le carré ou l'hexagone régulier."}, {"terme": "Polygones inscriptibles", "definition": "Un polygone est inscriptible s'il existe un cercle unique passant par tous ses sommets."}], "applications_list": [{"text": "Concevoir des pavages et mosaïques en architecture.", "icon": "construction"}, {"text": "Modéliser des formes en infographie 3D.", "icon": "art"}, {"text": "Calculer des surfaces de terrains irréguliers.", "icon": "construction"}]}, {"id": 211, "title": "Transformations géométriques", "category": "Géométrie", "formulas": ["Translation : z' = z + a", "Rotation : z' = e^{iθ} z", "Homothétie : z' = k z"], "details": "Les transformations géométriques décrivent les déplacements et déformations du plan.", "images": ["transformations.png"], "correspondances": [{"id": 209, "title": "Nombres complexes en géométrie"}, {"id": 213, "title": "Symétries"}, {"key": "sup:80", "title": "Groupes : définitions", "raison": "Les isométries du plan (translations, rotations, symétries) forment un groupe pour la composition ; classer les géométries revient à classer les groupes de transformations qui préservent leurs propriétés (programme d'Erlangen)."}, {"key": "sup:1200", "title": "Matrices orthogonales et isométries vectorielles", "raison": "Une isométrie vectorielle est représentée par une matrice orthogonale (A^T A = I) : det A = 1 pour une rotation, −1 pour une réflexion."}, {"key": "sup:450", "title": "Applications conformes", "raison": "Une fonction holomorphe de dérivée non nulle conserve les angles orientés : c'est une transformation conforme, comme les homographies z ↦ (az+b)/(cz+d)."}, {"id": 421, "title": "Relativité restreinte", "raison": "Le passage d'un référentiel inertiel à un autre est une transformation de Lorentz, qui conserve l'intervalle c²t²−x²−y²−z² ; ces transformations forment un groupe."}], "tags": ["geometrie", "transformations"], "niveau": "lycee", "definition": "Les transformations géométriques (translation, rotation, homothétie...) déplacent ou déforment une figure selon des règles précises, tout en préservant certaines propriétés (comme les distances ou les angles).", "explication_formules": "z'=z+a décrit une translation par le vecteur d'affixe a. z'=e^{iθ}z décrit une rotation d'angle θ. z'=kz décrit une homothétie de rapport k, qui agrandit ou réduit la figure.", "approfondissements": [{"label": "Composition de transformations", "link": {"type": "theme", "slug": "composition-de-transformations"}}, {"label": "Isométries et groupe des isométries du plan", "link": {"type": "theme", "slug": "isometries-et-groupe-des-isometries-du-plan"}}, {"label": "Similitudes", "link": {"type": "theme", "slug": "similitudes"}}, {"label": "Transformations en 3D (matrices homogènes)", "link": {"type": "theme", "slug": "transformations-en-3d-matrices-homogenes"}}, {"label": "Groupes de symétrie et pavages", "link": {"type": "theme", "slug": "groupes-de-symetrie-et-pavages"}}], "sous_points": [{"terme": "Isométries", "definition": "Une isométrie (translation, rotation, symétrie) préserve exactement toutes les distances entre les points."}, {"terme": "Similitudes", "definition": "Une similitude préserve les angles et multiplie toutes les longueurs par un même rapport."}, {"terme": "Affinités", "definition": "Une affinité préserve le parallélisme des droites mais peut déformer différemment les longueurs selon la direction."}], "applications_list": [{"text": "Animer des personnages en infographie et jeux vidéo.", "icon": "games"}, {"text": "Concevoir des motifs répétitifs en design textile.", "icon": "art"}, {"text": "Modéliser les mouvements de pièces mécaniques en robotique.", "icon": "robotics"}]}, {"id": 212, "title": "Cercle circonscrit", "category": "Géométrie", "formulas": ["Centre : intersection des médiatrices", "Rayon dans un triangle : R = a / (2 sin A)"], "details": "Le cercle circonscrit passe par tous les sommets d’un polygone (souvent un triangle).", "images": ["cercle_circonscrit.png"], "correspondances": [{"id": 210, "title": "Polygones"}, {"id": 206, "title": "Triangles"}], "tags": ["geometrie", "cercle-circonscrit"], "niveau": "lycee", "definition": "Le cercle circonscrit à un triangle est l'unique cercle passant par ses trois sommets — un objet remarquable qui relie géométrie du triangle et propriétés du cercle.", "explication_formules": "Le centre du cercle circonscrit se trouve à l'intersection des trois médiatrices des côtés (chacune équidistante de deux sommets). Le rayon R=a/(2 sin A) relie la taille du triangle à ses angles via la loi des sinus.", "approfondissements": [{"label": "Cercle inscrit et exinscrit", "link": {"type": "theme", "slug": "cercle-inscrit-et-exinscrit"}}, {"label": "Droite d'Euler", "link": {"type": "theme", "slug": "droite-d-euler"}}, {"label": "Cercle des neuf points", "link": {"type": "theme", "slug": "cercle-des-neuf-points"}}, {"label": "Puissance d'un point", "link": {"type": "theme", "slug": "puissance-d-un-point"}}, {"label": "Théorème de l'angle inscrit", "link": {"type": "theme", "slug": "theoreme-de-l-angle-inscrit"}}], "sous_points": [{"terme": "Triangles", "definition": "Tout triangle possède un unique cercle circonscrit, passant par ses trois sommets, dont le centre est à l'intersection des médiatrices."}, {"terme": "Polygones réguliers", "definition": "Un polygone régulier possède aussi un cercle circonscrit unique, passant par tous ses sommets."}, {"terme": "Liens avec les angles et longueurs", "definition": "Le rayon du cercle circonscrit se calcule à partir des côtés et des angles du triangle via la loi des sinus R=a/(2 sin A)."}], "applications_list": [{"text": "Positionner une antenne équidistante de trois points fixes.", "icon": "communication"}, {"text": "Résoudre des problèmes de triangulation en topographie.", "icon": "navigation"}]}, {"id": 213, "title": "Symétries", "category": "Géométrie", "formulas": ["Symétrie axiale : réflexion par rapport à une droite", "Symétrie centrale : réflexion par rapport à un point"], "details": "Les symétries sont des isométries qui préservent les distances et les angles.", "images": ["symetries.png"], "correspondances": [{"id": 211, "title": "Transformations géométriques"}, {"id": 214, "title": "Homothéties"}], "tags": ["geometrie", "symetries"], "niveau": "college", "definition": "Une symétrie transforme une figure en son image miroir, soit par rapport à une droite (symétrie axiale), soit par rapport à un point (symétrie centrale).", "explication_formules": "La symétrie axiale réfléchit chaque point perpendiculairement à travers une droite fixée. La symétrie centrale renvoie chaque point à la même distance de l'autre côté d'un point fixe — équivalente à une rotation de 180°.", "approfondissements": [{"label": "Groupe des symétries d'une figure", "link": {"type": "theme", "slug": "groupe-des-symetries-d-une-figure"}}, {"label": "Symétries en cristallographie", "link": {"type": "theme", "slug": "symetries-en-cristallographie"}}, {"label": "Symétries et invariance en physique", "link": {"type": "theme", "slug": "symetries-et-invariance-en-physique"}}, {"label": "Symétrie et pavages du plan", "link": {"type": "theme", "slug": "symetrie-et-pavages-du-plan"}}, {"label": "Symétrie axiale en 3D (plans de symétrie)", "link": {"type": "theme", "slug": "symetrie-axiale-en-3d-plans-de-symetrie"}}], "sous_points": [{"terme": "Axes", "definition": "Une symétrie axiale réfléchit chaque point perpendiculairement à travers une droite fixée, l'axe de symétrie."}, {"terme": "Centres", "definition": "Une symétrie centrale renvoie chaque point à la même distance de l'autre côté d'un point fixe, équivalente à une rotation de 180°."}, {"terme": "Invariants", "definition": "Un invariant de symétrie est un point ou une figure qui reste inchangé par la transformation, comme l'axe lui-même pour une symétrie axiale."}, {"terme": "Compositions de symétries", "definition": "Composer deux symétries produit une nouvelle transformation : deux symétries axiales donnent une rotation ou une translation selon leurs axes."}], "applications_list": [{"text": "Concevoir des motifs décoratifs et des logos symétriques.", "icon": "art"}, {"text": "Analyser les symétries moléculaires en chimie.", "icon": "chemistry"}, {"text": "Détecter des défauts de fabrication par comparaison miroir.", "icon": "industry"}]}, {"id": 214, "title": "Homothéties", "category": "Géométrie", "formulas": ["z' = k z (centre à l’origine)", "Aire multipliée par k²"], "details": "Les homothéties sont des transformations qui agrandissent ou réduisent les figures en conservant les angles.", "images": ["homotheties.png"], "correspondances": [{"id": 213, "title": "Symétries"}, {"id": 215, "title": "Affinités"}], "tags": ["geometrie", "homotheties"], "niveau": "college", "definition": "Une homothétie agrandit ou réduit une figure depuis un point fixe (le centre), en multipliant toutes les distances à ce centre par un même facteur.", "explication_formules": "z'=kz (centre à l'origine) multiplie chaque coordonnée par le rapport k. L'aire de la figure transformée est multipliée par k², car les deux dimensions sont dilatées simultanément.", "approfondissements": [{"label": "Composition d'homothéties", "link": {"type": "theme", "slug": "composition-d-homotheties"}}, {"label": "Homothéties et théorème de Thalès", "link": {"type": "theme", "slug": "homotheties-et-theoreme-de-thales"}}, {"label": "Rapport d'homothétie négatif", "link": {"type": "theme", "slug": "rapport-d-homothetie-negatif"}}, {"label": "Homothéties en 3D", "link": {"type": "theme", "slug": "homotheties-en-3d"}}, {"label": "Fractales et auto-similarité (homothéties répétées)", "link": {"type": "theme", "slug": "fractales-et-auto-similarite-homotheties-repetees"}}], "sous_points": [{"terme": "Rapports de longueurs", "definition": "Une homothétie de rapport k multiplie toutes les distances au centre par k, et donc toutes les longueurs de la figure par |k|."}, {"terme": "Invariants", "definition": "Le centre de l'homothétie est le seul point invariant (fixe) de la transformation."}, {"terme": "Similitudes", "definition": "Une homothétie est un cas particulier de similitude, qui préserve les angles tout en changeant l'échelle."}], "applications_list": [{"text": "Redimensionner une image sans la déformer (zoom).", "icon": "art"}, {"text": "Concevoir des cartes à différentes échelles.", "icon": "navigation"}, {"text": "Modéliser des agrandissements en dessin technique.", "icon": "construction"}]}, {"id": 215, "title": "Affinités", "category": "Géométrie", "formulas": ["Transformation linéaire du plan préservant le parallélisme", "Représentation par matrices 2×2 + translation"], "details": "Les affinités généralisent les homothéties et permettent des déformations plus générales.", "images": ["affinites.png"], "correspondances": [{"id": 214, "title": "Homothéties"}, {"id": 216, "title": "Géométrie vectorielle"}], "tags": ["geometrie", "affinites"], "niveau": "lycee", "definition": "Une affinité est une transformation linéaire du plan qui préserve le parallélisme des droites, mais peut déformer les longueurs et les angles différemment selon la direction.", "explication_formules": "Une affinité se représente par une matrice 2×2 combinée à une translation. Contrairement à une homothétie, elle peut étirer plus dans une direction que dans une autre, créant des déformations anisotropes.", "approfondissements": [{"label": "Affinités et matrices 2×2", "link": {"type": "theme", "slug": "affinites-et-matrices-2-2"}}, {"label": "Cisaillement (shear)", "link": {"type": "theme", "slug": "cisaillement-shear"}}, {"label": "Projections en infographie", "link": {"type": "theme", "slug": "projections-en-infographie"}}, {"label": "Affinités et coniques", "link": {"type": "theme", "slug": "affinites-et-coniques"}}, {"label": "Transformations affines en 3D", "link": {"type": "theme", "slug": "transformations-affines-en-3d"}}], "sous_points": [{"terme": "Conservation du parallélisme", "definition": "Une affinité transforme toujours des droites parallèles en droites parallèles, même si elle déforme les longueurs et les angles."}, {"terme": "Modification des angles", "definition": "Contrairement à une isométrie ou une homothétie, une affinité peut changer les angles d'une figure, l'étirant différemment selon la direction."}, {"terme": "Invariants", "definition": "Les directions propres d'une affinité (ses axes de déformation) restent inchangées, seule leur longueur est modifiée."}], "applications_list": [{"text": "Corriger la perspective d'une photo.", "icon": "art"}, {"text": "Modéliser des déformations mécaniques anisotropes en ingénierie.", "icon": "industry"}, {"text": "Effectuer des projections cartographiques.", "icon": "navigation"}]}, {"id": 216, "title": "Géométrie vectorielle", "category": "Géométrie", "formulas": ["Droite paramétrique : A + t u", "Plan paramétrique : A + s u + t v"], "details": "La géométrie vectorielle décrit les objets géométriques à l’aide de vecteurs et de paramètres.", "images": ["geo_vectorielle.png"], "correspondances": [{"id": 200, "title": "Points, droites et plans"}, {"id": 217, "title": "Géométrie dans l’espace"}], "tags": ["geometrie", "vectorielle"], "niveau": "lycee", "definition": "La géométrie vectorielle décrit droites et plans à l'aide de vecteurs et de paramètres, ce qui permet de manipuler des figures géométriques par le calcul plutôt que par le dessin.", "explication_formules": "Une droite paramétrique A+tu part du point A et se déplace le long de la direction u en faisant varier t. Un plan paramétrique A+su+tv utilise deux directions indépendantes pour balayer toute une surface plane.", "approfondissements": [{"label": "Intersections de droites et de plans", "link": {"type": "theme", "slug": "intersections-de-droites-et-de-plans"}}, {"label": "Équations cartésiennes vs paramétriques", "link": {"type": "theme", "slug": "equations-cartesiennes-vs-parametriques"}}, {"label": "Distance d'un point à une droite/un plan", "link": {"type": "theme", "slug": "distance-d-un-point-a-une-droite-un-plan"}}, {"label": "Produit vectoriel et orientation", "link": {"type": "theme", "slug": "produit-vectoriel-et-orientation"}}, {"label": "Géométrie vectorielle en dimension n", "link": {"type": "notion", "id": 216}}], "sous_points": [{"terme": "Droites", "definition": "En géométrie vectorielle, une droite se décrit par un point et un vecteur directeur, via une équation paramétrique."}, {"terme": "Plans", "definition": "Un plan se décrit par un point et deux vecteurs directeurs indépendants, ou par une équation cartésienne ax+by+cz=d."}, {"terme": "Intersections", "definition": "Étudier l'intersection de droites ou de plans revient à résoudre le système d'équations qui les décrit."}, {"terme": "Parallélisme et orthogonalité", "definition": "Le parallélisme se lit sur les vecteurs directeurs (colinéaires) ; l'orthogonalité se teste avec le produit scalaire (nul)."}], "applications_list": [{"text": "Programmer les trajectoires d'objets en 3D (jeux vidéo, simulation).", "icon": "games"}, {"text": "Calculer des intersections entre objets en CAO.", "icon": "construction"}, {"text": "Modéliser des rayons lumineux en infographie.", "icon": "art"}]}, {"id": 217, "title": "Géométrie dans l’espace", "category": "Géométrie", "formulas": ["Plan : ax + by + cz + d = 0", "Droite : A + t u (u ≠ 0)"], "details": "La géométrie dans l’espace étudie les objets en trois dimensions.", "images": ["espace.png"], "correspondances": [{"id": 216, "title": "Géométrie vectorielle"}, {"id": 218, "title": "Sphères"}], "tags": ["geometrie", "espace"], "niveau": "lycee", "definition": "La géométrie dans l'espace étend les concepts du plan (points, droites, distances) à trois dimensions, où de nouvelles configurations deviennent possibles (droites non sécantes et non parallèles).", "explication_formules": "Un plan de l'espace s'écrit ax+by+cz+d=0, une généralisation directe de l'équation de droite. Une droite de l'espace nécessite un point A et un vecteur directeur u, car une seule équation ne suffit plus à la décrire.", "approfondissements": [{"label": "Positions relatives de droites (gauches, sécantes)", "link": {"type": "theme", "slug": "positions-relatives-de-droites-gauches-secantes"}}, {"label": "Produit vectoriel et produit mixte", "link": {"type": "theme", "slug": "produit-vectoriel-et-produit-mixte"}}, {"label": "Distance entre deux droites de l'espace", "link": {"type": "theme", "slug": "distance-entre-deux-droites-de-l-espace"}}, {"label": "Coordonnées cylindriques et sphériques", "link": {"type": "theme", "slug": "coordonnees-cylindriques-et-spheriques"}}, {"label": "Géométrie projective de l'espace", "link": {"type": "notion", "id": 217}}], "sous_points": [{"terme": "Plans", "definition": "Un plan de l'espace est un ensemble de points vérifiant une équation ax+by+cz+d=0."}, {"terme": "Droites", "definition": "Une droite de l'espace se décrit par un point et un vecteur directeur, car une seule équation ne suffit plus à la caractériser."}, {"terme": "Sphères", "definition": "Une sphère est l'ensemble des points à distance fixe (le rayon) d'un centre, l'équivalent 3D du cercle."}, {"terme": "Intersections, parallélisme, orthogonalité", "definition": "Ces relations entre objets de l'espace se déterminent en résolvant les équations associées ou en comparant leurs vecteurs directeurs/normaux."}], "applications_list": [{"text": "Concevoir des bâtiments et structures en architecture 3D.", "icon": "construction"}, {"text": "Programmer des simulations physiques réalistes.", "icon": "computer"}, {"text": "Modéliser l'espace en robotique et vision par ordinateur.", "icon": "robotics"}]}, {"id": 218, "title": "Sphères", "category": "Géométrie", "formulas": ["(x-a)² + (y-b)² + (z-c)² = r²", "Volume : (4/3) π r³", "Aire : 4π r²"], "details": "Les sphères sont l’analogue tridimensionnel des cercles.", "images": ["sphere.png"], "correspondances": [{"id": 217, "title": "Géométrie dans l’espace"}, {"id": 219, "title": "Cylindres"}], "tags": ["geometrie", "sphere"], "niveau": "college", "definition": "Une sphère est l'ensemble des points de l'espace situés à une distance fixe (le rayon) d'un centre — l'équivalent en trois dimensions du cercle.", "explication_formules": "(x-a)²+(y-b)²+(z-c)²=r² généralise l'équation du cercle avec une coordonnée supplémentaire. Le volume (4/3)πr³ et l'aire 4πr² dépendent uniquement du rayon, comme pour le cercle.", "approfondissements": [{"label": "Coordonnées sphériques", "link": {"type": "theme", "slug": "coordonnees-spheriques"}}, {"label": "Géométrie sphérique (triangles sur une sphère)", "link": {"type": "theme", "slug": "geometrie-spherique-triangles-sur-une-sphere"}}, {"label": "Volume et aire par intégration", "link": {"type": "theme", "slug": "volume-et-aire-par-integration"}}, {"label": "Sphères en dimension n", "link": {"type": "theme", "slug": "spheres-en-dimension-n"}}, {"label": "Géodésiques sur une sphère", "link": {"type": "theme", "slug": "geodesiques-sur-une-sphere"}}], "sous_points": [{"terme": "Sections planes", "definition": "Couper une sphère par un plan produit toujours un cercle (éventuellement réduit à un point si le plan est tangent)."}, {"terme": "Tangentes", "definition": "Un plan tangent à une sphère la touche en un seul point, perpendiculaire au rayon en ce point."}, {"terme": "Géométrie des solides", "definition": "L'étude de la sphère s'inscrit dans la géométrie des solides, qui combine volumes, aires et sections planes."}], "applications_list": [{"text": "Modéliser la Terre et les astres en astronomie.", "icon": "space"}, {"text": "Concevoir des réservoirs et ballons en ingénierie.", "icon": "industry"}, {"text": "Calculer la portée d'un signal radio omnidirectionnel.", "icon": "communication"}]}, {"id": 219, "title": "Cylindres", "category": "Géométrie", "formulas": ["Volume : V = π r² h", "Aire latérale : 2π r h"], "details": "Les cylindres sont des solides de révolution obtenus en extrudant un cercle.", "images": ["cylindre.png"], "correspondances": [{"id": 218, "title": "Sphères"}, {"id": 220, "title": "Cones"}], "tags": ["geometrie", "cylindre"], "niveau": "college", "definition": "Un cylindre est un solide obtenu en faisant translater un cercle le long d'un axe perpendiculaire — une des formes de base les plus utilisées en ingénierie.", "explication_formules": "Le volume V=πr²h multiplie l'aire de la base circulaire (πr²) par la hauteur h. L'aire latérale 2πrh correspond à la surface qu'on obtiendrait en 'déroulant' le cylindre en un rectangle.", "approfondissements": [{"label": "Cylindre oblique", "link": {"type": "theme", "slug": "cylindre-oblique"}}, {"label": "Volume par intégration (méthode des disques)", "link": {"type": "theme", "slug": "volume-par-integration-methode-des-disques"}}, {"label": "Sections coniques d'un cylindre", "link": {"type": "theme", "slug": "sections-coniques-d-un-cylindre"}}, {"label": "Cylindre et coordonnées cylindriques", "link": {"type": "theme", "slug": "cylindre-et-coordonnees-cylindriques"}}, {"label": "Cylindre creux (tube)", "link": {"type": "theme", "slug": "cylindre-creux-tube"}}], "sous_points": [{"terme": "Sections", "definition": "Une section d'un cylindre par un plan peut donner un cercle, une ellipse ou un rectangle selon l'orientation du plan."}, {"terme": "Volumes", "definition": "Le volume d'un cylindre V=πr²h multiplie l'aire de la base circulaire par la hauteur."}, {"terme": "Aires", "definition": "L'aire latérale d'un cylindre 2πrh correspond à la surface qu'on obtiendrait en le « déroulant » en un rectangle."}, {"terme": "Liens avec les intégrales", "definition": "Le volume d'un cylindre s'obtient aussi en intégrant l'aire constante de sa section circulaire le long de sa hauteur."}], "applications_list": [{"text": "Dimensionner des tuyaux, réservoirs et canettes.", "icon": "industry"}, {"text": "Calculer la capacité d'un moteur (cylindrée).", "icon": "transport"}, {"text": "Concevoir des colonnes en architecture.", "icon": "construction"}]}, {"id": 220, "title": "Cones", "category": "Géométrie", "formulas": ["Volume : V = (1/3) π r² h", "Aire latérale : π r l (l : génératrice)"], "details": "Les cones sont des solides de révolution pointus, avec un sommet et une base circulaire.", "images": ["cone.png"], "correspondances": [{"id": 219, "title": "Cylindres"}, {"id": 218, "title": "Sphères"}], "tags": ["geometrie", "cone"], "niveau": "college", "definition": "Un cône est un solide qui se rétrécit progressivement d'une base circulaire vers un sommet unique — une forme fondamentale en géométrie et en ingénierie.", "explication_formules": "Le volume V=(1/3)πr²h contient un facteur 1/3 par rapport au cylindre de même base et hauteur, car le cône se rétrécit continûment vers le sommet. L'aire latérale πrl dépend du rayon et de la génératrice l (la pente du cône).", "approfondissements": [{"label": "Sections coniques (cercle, ellipse, parabole, hyperbole)", "link": {"type": "theme", "slug": "sections-coniques-cercle-ellipse-parabole-hyperbole"}}, {"label": "Cône tronqué", "link": {"type": "theme", "slug": "cone-tronque"}}, {"label": "Volume par intégration", "link": {"type": "theme", "slug": "volume-par-integration"}}, {"label": "Cône et coordonnées coniques", "link": {"type": "theme", "slug": "cone-et-coordonnees-coniques"}}, {"label": "Cônes en optique (cône de lumière)", "link": {"type": "theme", "slug": "cones-en-optique-cone-de-lumiere"}}], "sous_points": [{"terme": "Sections", "definition": "Couper un cône donne un cercle, une ellipse, une parabole ou une hyperbole selon l'angle du plan de coupe (les sections coniques)."}, {"terme": "Génératrices", "definition": "Une génératrice du cône est un segment reliant le sommet à un point du cercle de base."}, {"terme": "Liens avec les pyramides", "definition": "Le cône est l'analogue « rond » de la pyramide : les deux partagent la même formule de volume (1/3 × aire base × hauteur)."}], "applications_list": [{"text": "Concevoir des entonnoirs, haut-parleurs et embouts.", "icon": "industry"}, {"text": "Modéliser des volcans et montagnes en géographie.", "icon": "environment"}, {"text": "Calculer des volumes de tas de matériaux en vrac.", "icon": "industry"}]}, {"id": 300, "title": "Expériences aléatoires", "category": "Probabilités", "formulas": ["Ω : ensemble des issues", "Événement : A ⊂ Ω"], "details": "Une expérience aléatoire est un processus dont le résultat n’est pas déterministe.", "images": ["experience_aleatoire.png"], "correspondances": [{"id": 301, "title": "Probabilité d’un événement"}, {"id": 302, "title": "Variables aléatoires"}], "tags": ["probabilites", "experience"], "niveau": "college", "definition": "Une expérience aléatoire est une expérience dont on ne peut pas prédire le résultat avec certitude à l'avance, mais dont on peut lister tous les résultats possibles.", "explication_formules": "Ω regroupe toutes les issues possibles de l'expérience (l'univers). Un événement A est simplement une partie de Ω : le sous-ensemble des issues qui réalisent la condition qu'on étudie.", "approfondissements": [{"label": "Tribu et événements complexes", "link": {"type": "theme", "slug": "tribu-et-evenements-complexes"}}, {"label": "Univers infini (dénombrable ou continu)", "link": {"type": "theme", "slug": "univers-infini-denombrable-ou-continu"}}, {"label": "Événements incompatibles et complémentaires", "link": {"type": "theme", "slug": "evenements-incompatibles-et-complementaires"}}, {"label": "Modélisation probabiliste d'un phénomène réel", "link": {"type": "theme", "slug": "modelisation-probabiliste-d-un-phenomene-reel"}}, {"label": "Simulation de Monte-Carlo", "link": {"type": "theme", "slug": "simulation-de-monte-carlo"}}], "sous_points": [{"terme": "Issues", "definition": "Une issue est un résultat possible unique d'une expérience aléatoire, comme obtenir « 3 » en lançant un dé."}, {"terme": "Événements", "definition": "Un événement est un ensemble d'issues, correspondant à une condition qu'on étudie (par exemple « obtenir un nombre pair »)."}, {"terme": "Événements élémentaires", "definition": "Un événement élémentaire ne contient qu'une seule issue possible."}, {"terme": "Événements certains et impossibles", "definition": "L'événement certain contient toutes les issues (probabilité 1) ; l'événement impossible n'en contient aucune (probabilité 0)."}], "applications_list": [{"text": "Modéliser un lancer de dé ou de pièce.", "icon": "games"}, {"text": "Prévoir la fiabilité d'un composant électronique.", "icon": "electronics"}, {"text": "Fonder les jeux de hasard et les études statistiques.", "icon": "data"}]}, {"id": 301, "title": "Probabilité d’un événement", "category": "Probabilités", "formulas": ["P(A) = |A| / |Ω| (cas équiprobable)", "0 ≤ P(A) ≤ 1", "P(Ω) = 1"], "details": "La probabilité mesure la chance qu’un événement se produise.", "images": ["proba_evenement.png"], "correspondances": [{"id": 300, "title": "Expériences aléatoires"}, {"id": 303, "title": "Probabilités conditionnelles"}], "tags": ["probabilites", "evenement"], "niveau": "college", "definition": "La probabilité d'un événement quantifie, entre 0 et 1, à quel point il est susceptible de se réaliser lors d'une expérience aléatoire — 0 signifiant impossible, 1 signifiant certain.", "explication_formules": "P(A)=|A|/|Ω| dans le cas équiprobable (toutes les issues ont la même chance) compte simplement le nombre de cas favorables sur le nombre de cas possibles. P(Ω)=1 traduit que l'expérience a forcément un résultat.", "approfondissements": [{"label": "Probabilités conditionnelles", "link": {"type": "notion", "id": 303}}, {"label": "Loi des grands nombres", "link": {"type": "theme", "slug": "loi-des-grands-nombres"}}, {"label": "Dénombrement (combinatoire) pour cas équiprobables", "link": {"type": "theme", "slug": "denombrement-combinatoire-pour-cas-equiprobables"}}, {"label": "Probabilités sur univers infini", "link": {"type": "theme", "slug": "probabilites-sur-univers-infini"}}, {"label": "Interprétation fréquentiste vs bayésienne", "link": {"type": "theme", "slug": "interpretation-frequentiste-vs-bayesienne"}}], "sous_points": [{"terme": "Axiomes de Kolmogorov", "definition": "Ces règles de base (probabilité entre 0 et 1, probabilité totale égale à 1, additivité) fondent rigoureusement toute la théorie des probabilités."}, {"terme": "Additivité", "definition": "La probabilité de l'union de deux événements incompatibles est la somme de leurs probabilités individuelles."}, {"terme": "Complémentaire", "definition": "La probabilité de l'événement contraire (« ne pas A ») vaut toujours 1 moins la probabilité de A."}], "applications_list": [{"text": "Calculer les chances de gagner à un jeu de hasard.", "icon": "games"}, {"text": "Évaluer le risque qu'un produit soit défectueux.", "icon": "industry"}, {"text": "Fonder les décisions dans l'incertitude (assurance, finance, médecine).", "icon": "finance"}]}, {"id": 302, "title": "Variables aléatoires", "category": "Probabilités", "formulas": ["X : Ω → ℝ", "Loi de X : P(X = x_i)"], "details": "Une variable aléatoire associe un nombre réel à chaque issue.", "images": ["variable_aleatoire.png"], "correspondances": [{"id": 304, "title": "Espérance"}, {"id": 305, "title": "Variance et écart-type"}], "tags": ["probabilites", "variable-aleatoire"], "niveau": "lycee", "definition": "Une variable aléatoire associe un nombre à chaque issue possible d'une expérience aléatoire, ce qui permet de faire des calculs (moyenne, variance) sur des phénomènes incertains.", "explication_formules": "X:Ω→ℝ transforme chaque résultat de l'expérience en un nombre. La loi de X, donnée par P(X=xᵢ), indique la probabilité de chaque valeur possible et résume complètement le comportement aléatoire de X.", "approfondissements": [{"label": "Variables discrètes vs continues", "link": {"type": "theme", "slug": "variables-discretes-vs-continues"}}, {"label": "Fonction de répartition", "link": {"type": "theme", "slug": "fonction-de-repartition"}}, {"label": "Lois usuelles (binomiale, Poisson, normale)", "link": {"type": "theme", "slug": "lois-usuelles-binomiale-poisson-normale"}}, {"label": "Fonctions de variables aléatoires", "link": {"type": "theme", "slug": "fonctions-de-variables-aleatoires"}}, {"label": "Vecteurs aléatoires (plusieurs variables liées)", "link": {"type": "theme", "slug": "vecteurs-aleatoires-plusieurs-variables-liees"}}], "sous_points": [{"terme": "Variables discrètes", "definition": "Une variable aléatoire discrète ne prend que des valeurs isolées, souvent des entiers (comme le nombre de faces obtenues)."}, {"terme": "Variables continues", "definition": "Une variable aléatoire continue peut prendre n'importe quelle valeur dans un intervalle, décrite par une densité de probabilité."}, {"terme": "Support", "definition": "Le support d'une variable aléatoire est l'ensemble des valeurs qu'elle peut effectivement prendre."}, {"terme": "Loi", "definition": "La loi d'une variable aléatoire décrit complètement la probabilité de chacune de ses valeurs (ou intervalles) possibles."}], "applications_list": [{"text": "Modéliser un gain à un jeu.", "icon": "games"}, {"text": "Modéliser le nombre de clients arrivant dans un magasin.", "icon": "finance"}, {"text": "Modéliser le temps d'attente à un guichet.", "icon": "data"}]}, {"id": 303, "title": "Probabilités conditionnelles", "category": "Probabilités", "formulas": ["P(A|B) = P(A ∩ B) / P(B)", "P(A ∩ B) = P(A|B) P(B)"], "details": "Probabilité d’un événement sachant qu’un autre est réalisé.", "images": ["proba_conditionnelle.png"], "correspondances": [{"id": 301, "title": "Probabilité d’un événement"}, {"id": 306, "title": "Formule de Bayes"}], "tags": ["probabilites", "conditionnelle"], "niveau": "lycee", "definition": "La probabilité conditionnelle mesure la probabilité qu'un événement se produise sachant qu'un autre événement s'est déjà réalisé — elle actualise nos prévisions avec une information nouvelle.", "explication_formules": "P(A|B)=P(A∩B)/P(B) restreint l'univers à l'ensemble des cas où B s'est produit, puis calcule la proportion de A dans ce sous-univers. Cette formule est le point de départ du théorème de Bayes.", "approfondissements": [{"label": "Formule de Bayes", "link": {"type": "notion", "id": 306}}, {"label": "Indépendance conditionnelle", "link": {"type": "theme", "slug": "independance-conditionnelle"}}, {"label": "Arbres de probabilité", "link": {"type": "theme", "slug": "arbres-de-probabilite"}}, {"label": "Chaînes de Markov (mémoire courte)", "link": {"type": "notion", "id": 314}}, {"label": "Probabilités conditionnelles en apprentissage automatique", "link": {"type": "notion", "id": 303}}], "sous_points": [{"terme": "Indépendance", "definition": "Deux événements sont indépendants si la réalisation de l'un ne change rien à la probabilité de l'autre."}, {"terme": "Conditionnement", "definition": "Conditionner par un événement B revient à restreindre l'univers aux seuls cas où B s'est déjà produit."}, {"terme": "Partitions", "definition": "Une partition découpe l'univers en plusieurs événements qui ne se recoupent pas et qui, réunis, couvrent tous les cas possibles."}], "applications_list": [{"text": "Affiner un diagnostic médical après un test positif.", "icon": "medicine"}, {"text": "Ajuster les prévisions météo au fur et à mesure des observations.", "icon": "environment"}, {"text": "Filtrer les emails indésirables selon des mots-clés.", "icon": "computer"}]}, {"id": 304, "title": "Espérance", "category": "Probabilités", "formulas": ["E(X) = Σ x_i P(X = x_i) (discret)", "E(X) = ∫ x f_X(x) dx (continu)"], "details": "Valeur moyenne théorique d’une variable aléatoire.", "images": ["esperance.png"], "correspondances": [{"id": 302, "title": "Variables aléatoires"}, {"id": 305, "title": "Variance et écart-type"}], "tags": ["probabilites", "esperance"], "niveau": "lycee", "definition": "L'espérance est la valeur moyenne qu'on attend d'une variable aléatoire si on répète l'expérience un très grand nombre de fois — le 'centre de gravité' de sa distribution.", "explication_formules": "E(X)=Σxᵢ P(X=xᵢ) pondère chaque valeur possible par sa probabilité (cas discret). Pour une variable continue, la somme devient une intégrale E(X)=∫xf(x)dx utilisant la densité de probabilité.", "approfondissements": [{"label": "Linéarité de l'espérance", "link": {"type": "theme", "slug": "linearite-de-l-esperance"}}, {"label": "Espérance conditionnelle", "link": {"type": "theme", "slug": "esperance-conditionnelle"}}, {"label": "Théorème de transfert", "link": {"type": "theme", "slug": "theoreme-de-transfert"}}, {"label": "Espérance en dimension infinie", "link": {"type": "theme", "slug": "esperance-en-dimension-infinie"}}, {"label": "Espérance et valeur actuelle en finance", "link": {"type": "theme", "slug": "esperance-et-valeur-actuelle-en-finance"}}], "sous_points": [{"terme": "Linéarité de l'espérance", "definition": "L'espérance d'une somme de variables aléatoires est toujours la somme de leurs espérances, même si les variables ne sont pas indépendantes."}, {"terme": "Espérance d'une somme", "definition": "Cette propriété permet de calculer facilement l'espérance de quantités complexes en les décomposant en sommes de variables plus simples."}], "applications_list": [{"text": "Calculer le gain moyen attendu à un jeu de hasard.", "icon": "games"}, {"text": "Estimer le rendement moyen d'un investissement financier.", "icon": "finance"}, {"text": "Dimensionner des stocks selon la demande moyenne.", "icon": "industry"}]}, {"id": 305, "title": "Variance et écart-type", "category": "Probabilités", "formulas": ["Var(X) = E(X²) - [E(X)]²", "σ(X) = √Var(X)"], "details": "Mesure de la dispersion autour de l’espérance.", "images": ["variance.png"], "correspondances": [{"id": 304, "title": "Espérance"}, {"id": 307, "title": "Lois usuelles discrètes"}], "tags": ["probabilites", "variance"], "niveau": "lycee", "definition": "La variance mesure la dispersion d'une variable aléatoire autour de sa moyenne : plus elle est grande, plus les résultats individuels s'écartent fortement de l'espérance.", "explication_formules": "Var(X)=E(X²)-[E(X)]² (formule de König-Huygens) est souvent plus pratique à calculer que la définition directe. L'écart-type σ(X)=√Var(X) remet le résultat dans la même unité que X, ce qui le rend plus interprétable.", "approfondissements": [{"label": "Covariance et corrélation", "link": {"type": "notion", "id": 310}}, {"label": "Inégalité de Bienaymé-Tchebychev", "link": {"type": "theme", "slug": "inegalite-de-bienayme-tchebychev"}}, {"label": "Variance d'une somme de variables", "link": {"type": "theme", "slug": "variance-d-une-somme-de-variables"}}, {"label": "Loi normale et écart-type", "link": {"type": "theme", "slug": "loi-normale-et-ecart-type"}}, {"label": "Variance en apprentissage automatique (biais-variance)", "link": {"type": "notion", "id": 530}}], "sous_points": [{"terme": "Variance d'une somme", "definition": "La variance d'une somme de variables indépendantes est la somme de leurs variances ; sinon il faut ajouter les termes de covariance."}, {"terme": "Covariance", "definition": "La covariance mesure comment deux variables aléatoires varient ensemble, positive si elles ont tendance à augmenter ensemble."}], "applications_list": [{"text": "Évaluer le risque d'un placement financier (volatilité).", "icon": "finance"}, {"text": "Contrôler la qualité de fabrication (dispersion des mesures).", "icon": "industry"}, {"text": "Quantifier l'incertitude d'une mesure scientifique.", "icon": "research"}]}, {"id": 306, "title": "Formule de Bayes", "category": "Probabilités", "formulas": ["P(A|B) = P(B|A) P(A) / P(B)", "P(B) = Σ P(B|A_i) P(A_i)"], "details": "Permet d’inverser les conditionnements.", "images": ["bayes.png"], "correspondances": [{"id": 303, "title": "Probabilités conditionnelles"}, {"id": 308, "title": "Indépendance"}], "tags": ["probabilites", "bayes"], "niveau": "lycee", "definition": "La formule de Bayes inverse une probabilité conditionnelle : elle permet de calculer P(A|B) à partir de P(B|A), ce qui est essentiel quand on ne connaît que la relation dans l'autre sens.", "explication_formules": "P(A|B)=P(B|A)P(A)/P(B) combine la probabilité a priori P(A) avec la nouvelle information B pour obtenir une probabilité a posteriori mise à jour. P(B) se calcule souvent via la formule des probabilités totales, en sommant sur tous les scénarios possibles.", "approfondissements": [{"label": "Probabilités a priori et a posteriori", "link": {"type": "theme", "slug": "probabilites-a-priori-et-a-posteriori"}}, {"label": "Statistique bayésienne", "link": {"type": "theme", "slug": "statistique-bayesienne"}}, {"label": "Réseaux bayésiens", "link": {"type": "theme", "slug": "reseaux-bayesiens"}}, {"label": "Filtre de Kalman (Bayes en continu)", "link": {"type": "theme", "slug": "filtre-de-kalman-bayes-en-continu"}}, {"label": "Paradoxe du faux positif", "link": {"type": "theme", "slug": "paradoxe-du-faux-positif"}}], "sous_points": [{"terme": "Applications aux tests médicaux", "definition": "La formule de Bayes permet d'interpréter correctement un test médical positif, en tenant compte de la rareté de la maladie recherchée."}, {"terme": "Diagnostic", "definition": "En diagnostic, Bayes met à jour la probabilité qu'un patient soit malade en combinant le résultat du test et la prévalence de la maladie."}, {"terme": "Inférence", "definition": "L'inférence bayésienne actualise progressivement une croyance à mesure que de nouvelles données arrivent, via la formule de Bayes."}], "applications_list": [{"text": "Interpréter correctement un test médical.", "icon": "medicine"}, {"text": "Filtrer les spams par apprentissage bayésien.", "icon": "computer"}, {"text": "Fonder les systèmes de recommandation et l'IA bayésienne.", "icon": "computer"}]}, {"id": 307, "title": "Lois usuelles discrètes", "category": "Probabilités", "formulas": ["Loi de Bernoulli : P(X=1)=p, P(X=0)=1-p", "Loi binomiale : P(X=k)=C(n,k)p^k(1-p)^{n-k}", "Loi géométrique : P(X=k)=(1-p)^{k-1}p"], "details": "Lois discrètes classiques pour modéliser des tirages.", "images": ["lois_discretes.png"], "correspondances": [{"id": 304, "title": "Espérance"}, {"id": 305, "title": "Variance et écart-type"}], "tags": ["probabilites", "lois-discretes"], "niveau": "lycee", "definition": "Les lois usuelles discrètes décrivent des schémas récurrents de phénomènes aléatoires à valeurs entières : succès/échec répétés, nombre d'essais avant un succès, etc.", "explication_formules": "La loi de Bernoulli modélise une seule épreuve à deux issues (succès/échec). La loi binomiale P(X=k)=C(n,k)pᵏ(1-p)ⁿ⁻ᵏ compte le nombre de succès sur n répétitions indépendantes. La loi géométrique donne la probabilité d'attendre k essais avant le premier succès.", "approfondissements": [{"label": "Loi de Poisson (événements rares)", "link": {"type": "theme", "slug": "loi-de-poisson-evenements-rares"}}, {"label": "Approximation de la binomiale par la normale", "link": {"type": "theme", "slug": "approximation-de-la-binomiale-par-la-normale"}}, {"label": "Loi hypergéométrique", "link": {"type": "theme", "slug": "loi-hypergeometrique"}}, {"label": "Fonctions génératrices", "link": {"type": "theme", "slug": "fonctions-generatrices"}}, {"label": "Applications au contrôle qualité", "link": {"type": "theme", "slug": "applications-au-controle-qualite"}}], "sous_points": [{"terme": "Moments", "definition": "Les moments d'une loi (espérance, variance, etc.) résument ses caractéristiques numériques essentielles."}, {"terme": "Espérance", "definition": "L'espérance d'une loi usuelle se calcule directement à partir de ses paramètres (comme np pour la loi binomiale)."}, {"terme": "Variance", "definition": "La variance d'une loi usuelle mesure sa dispersion et se calcule aussi directement à partir de ses paramètres."}, {"terme": "Interprétation", "definition": "Chaque loi usuelle modélise un type précis de phénomène aléatoire répété (succès/échec, événements rares, etc.)."}], "applications_list": [{"text": "Modéliser le nombre de pièces défectueuses sur une chaîne de production.", "icon": "industry"}, {"text": "Modéliser le nombre de succès à un examen à choix multiples.", "icon": "education"}, {"text": "Modéliser le nombre de tentatives avant de gagner à un jeu.", "icon": "games"}]}, {"id": 308, "title": "Indépendance", "category": "Probabilités", "formulas": ["A et B indépendants ⇔ P(A ∩ B) = P(A)P(B)", "X et Y indépendantes ⇔ P(X=x, Y=y) = P(X=x)P(Y=y)"], "details": "Deux événements ou variables sont indépendants si la réalisation de l’un n’influence pas l’autre.", "images": ["independance.png"], "correspondances": [{"id": 303, "title": "Probabilités conditionnelles"}, {"id": 309, "title": "Vecteurs aléatoires"}], "tags": ["probabilites", "independance"], "niveau": "lycee", "definition": "Deux événements ou variables sont indépendants si la réalisation de l'un n'apporte aucune information sur l'autre — leur probabilité conjointe se factorise simplement.", "explication_formules": "A et B indépendants ⇔ P(A∩B)=P(A)P(B) : cette factorisation caractérise complètement l'indépendance. Pour des variables aléatoires, la même idée s'applique à toute paire de valeurs (x,y).", "approfondissements": [{"label": "Indépendance de plusieurs variables", "link": {"type": "theme", "slug": "independance-de-plusieurs-variables"}}, {"label": "Indépendance conditionnelle", "link": {"type": "theme", "slug": "independance-conditionnelle"}}, {"label": "Corrélation vs indépendance (nuance importante)", "link": {"type": "theme", "slug": "correlation-vs-independance-nuance-importante"}}, {"label": "Théorème central limite (variables indépendantes)", "link": {"type": "notion", "id": 313}}, {"label": "Tests d'indépendance statistique (χ²)", "link": {"type": "theme", "slug": "tests-d-independance-statistique"}}], "sous_points": [{"terme": "Indépendance mutuelle", "definition": "Plusieurs variables sont mutuellement indépendantes si la factorisation de leur loi conjointe fonctionne pour tout sous-ensemble d'entre elles, pas seulement deux à deux."}, {"terme": "Indépendance conditionnelle", "definition": "Deux variables peuvent devenir indépendantes une fois qu'on connaît une troisième variable, même si elles ne le sont pas globalement."}], "applications_list": [{"text": "Justifier le calcul de probabilités composées (lancers de dés successifs).", "icon": "games"}, {"text": "Concevoir des systèmes redondants fiables.", "icon": "industry"}, {"text": "Fonder les modèles statistiques qui supposent des observations indépendantes.", "icon": "data"}]}, {"id": 309, "title": "Vecteurs aléatoires", "category": "Probabilités", "formulas": ["X = (X1,...,Xn)", "Loi jointe : P(X1=x1,...,Xn=xn)"], "details": "Généralisation des variables aléatoires à plusieurs dimensions.", "images": ["vecteur_aleatoire.png"], "correspondances": [{"id": 305, "title": "Variance et écart-type"}, {"id": 310, "title": "Covariance et corrélation"}, {"key": "sup:206", "title": "Formes quadratiques et réduction de Gauss", "raison": "Pour un vecteur X de covariance Σ, Var(a^T X) = a^T Σ a : la variance d'une combinaison linéaire est une forme quadratique, positive car une variance l'est."}, {"key": "sup:264", "title": "Changement de variables (jacobien)", "raison": "Pour Y = φ(X), la densité de Y s'obtient par changement de variables : f_Y(y) = f_X(φ^(-1)(y)) · |det Dφ^(-1)(y)|."}, {"key": "sup:1224", "title": "Quadriques : classification", "raison": "Les lignes de niveau de la densité d'un vecteur gaussien sont les quadriques x^T Σ^(-1) x = c : des ellipses en dimension 2, des ellipsoïdes en dimension 3, dont les axes suivent les vecteurs propres de Σ."}, {"key": "sup:1965", "title": "Décomposition de Cholesky", "raison": "Si Σ = LL^T (Cholesky) et Z est un vecteur gaussien standard, alors LZ suit N(0, Σ) : c'est ainsi qu'on simule des gaussiennes corrélées."}, {"id": 425, "title": "Thermodynamique statistique", "raison": "Les trois composantes de la vitesse d'une molécule de gaz parfait sont des gaussiennes indépendantes : c'est un vecteur gaussien de ℝ³ (loi de Maxwell–Boltzmann)."}, {"key": "sup:1900", "title": "Filtrage de Kalman (introduction)", "raison": "Le filtre de Kalman est l'estimateur récursif optimal d'un vecteur aléatoire gaussien dont l'état évolue dans le temps : à chaque étape, il combine une prédiction et une mesure en les pondérant par leurs covariances."}], "tags": ["probabilites", "vecteur-aleatoire"], "niveau": "prepa", "definition": "Un vecteur aléatoire regroupe plusieurs variables aléatoires liées entre elles, comme la taille et le poids d'une même personne, qu'on étudie conjointement plutôt qu'isolément.", "explication_formules": "X=(X1,...,Xn) combine n variables en un seul objet. La loi jointe P(X1=x1,...,Xn=xn) donne la probabilité de toute combinaison simultanée de valeurs, contenant plus d'information que les lois de chaque variable séparément.", "approfondissements": [{"label": "Lois marginales et conditionnelles", "link": {"type": "theme", "slug": "lois-marginales-et-conditionnelles"}}, {"label": "Matrice de covariance", "link": {"type": "theme", "slug": "matrice-de-covariance"}}, {"label": "Vecteurs gaussiens", "link": {"type": "theme", "slug": "vecteurs-gaussiens"}}, {"label": "Indépendance de vecteurs aléatoires", "link": {"type": "theme", "slug": "independance-de-vecteurs-aleatoires"}}, {"label": "Applications à la statistique multivariée", "link": {"type": "theme", "slug": "applications-a-la-statistique-multivariee"}}], "sous_points": [{"terme": "Loi jointe", "definition": "La loi jointe d'un vecteur aléatoire donne la probabilité de toute combinaison simultanée de valeurs de ses composantes."}, {"terme": "Marginales", "definition": "La loi marginale d'une composante s'obtient en « oubliant » les autres variables du vecteur."}, {"terme": "Conditionnelles", "definition": "La loi conditionnelle décrit le comportement d'une composante sachant la valeur des autres."}], "applications_list": [{"text": "Modéliser plusieurs mesures corrélées en statistique multivariée.", "icon": "data"}, {"text": "Analyser des portefeuilles financiers avec plusieurs actifs.", "icon": "finance"}, {"text": "Fonder les modèles d'apprentissage automatique à plusieurs variables.", "icon": "computer"}]}, {"id": 310, "title": "Covariance et corrélation", "category": "Probabilités", "formulas": ["Cov(X,Y) = E(XY) - E(X)E(Y)", "Corr(X,Y) = Cov(X,Y) / (σ(X)σ(Y))"], "details": "Mesure de la dépendance linéaire entre deux variables.", "images": ["covariance.png"], "correspondances": [{"id": 309, "title": "Vecteurs aléatoires"}, {"id": 311, "title": "Lois normales"}], "tags": ["probabilites", "covariance"], "niveau": "prepa", "definition": "La covariance mesure comment deux variables aléatoires varient ensemble ; la corrélation normalise cette mesure pour la rendre comparable entre différentes paires de variables.", "explication_formules": "Cov(X,Y)=E(XY)-E(X)E(Y) est positive quand X et Y ont tendance à augmenter ensemble, négative dans le cas inverse. Corr(X,Y) divise la covariance par les écarts-types pour obtenir un nombre toujours compris entre -1 et 1.", "approfondissements": [{"label": "Matrice de covariance et de corrélation", "link": {"type": "notion", "id": 310}}, {"label": "Régression linéaire", "link": {"type": "theme", "slug": "regression-lineaire"}}, {"label": "Corrélation ne signifie pas causalité", "link": {"type": "theme", "slug": "correlation-ne-signifie-pas-causalite"}}, {"label": "Covariance en analyse en composantes principales", "link": {"type": "theme", "slug": "covariance-en-analyse-en-composantes-principales"}}, {"label": "Copules (dépendance au-delà de la corrélation)", "link": {"type": "theme", "slug": "copules-dependance-au-dela-de-la-correlation"}}], "sous_points": [{"terme": "Covariance nulle", "definition": "Une covariance nulle signifie l'absence de lien linéaire entre deux variables, mais n'implique pas forcément leur indépendance."}, {"terme": "Indépendance", "definition": "Deux variables indépendantes ont toujours une covariance nulle, mais l'inverse n'est pas garanti en général."}, {"terme": "Corrélation ±1", "definition": "Une corrélation de +1 ou -1 signifie que les deux variables sont liées par une relation affine parfaite, croissante ou décroissante."}], "applications_list": [{"text": "Diversifier un portefeuille financier en réduisant le risque.", "icon": "finance"}, {"text": "Analyser la relation entre deux variables en statistique.", "icon": "data"}, {"text": "Détecter des motifs en apprentissage automatique.", "icon": "computer"}]}, {"id": 311, "title": "Lois normales", "category": "Probabilités", "formulas": ["N(m,σ²)", "Densité : (1/(σ√(2π))) exp(-(x-m)²/(2σ²))"], "details": "Lois continues fondamentales en probabilité.", "images": ["normale.png"], "correspondances": [{"id": 304, "title": "Espérance"}, {"id": 305, "title": "Variance et écart-type"}], "tags": ["probabilites", "normale"], "niveau": "lycee", "definition": "La loi normale (courbe en cloche) décrit un très grand nombre de phénomènes naturels et statistiques où les valeurs se répartissent symétriquement autour d'une moyenne.", "explication_formules": "N(m,σ²) est entièrement déterminée par sa moyenne m et son écart-type σ. La densité en forme de cloche est maximale en m et décroît symétriquement de part et d'autre, la largeur de la cloche étant contrôlée par σ.", "approfondissements": [{"label": "Théorème central limite (pourquoi la normale est partout)", "link": {"type": "notion", "id": 313}}, {"label": "Loi normale centrée réduite", "link": {"type": "theme", "slug": "loi-normale-centree-reduite"}}, {"label": "Vecteurs gaussiens multivariés", "link": {"type": "theme", "slug": "vecteurs-gaussiens-multivaries"}}, {"label": "Tests statistiques basés sur la normale", "link": {"type": "theme", "slug": "tests-statistiques-bases-sur-la-normale"}}, {"label": "Approximation normale de la binomiale", "link": {"type": "theme", "slug": "approximation-normale-de-la-binomiale"}}], "sous_points": [{"terme": "Théorème central limite", "definition": "Ce théorème explique pourquoi la loi normale apparaît si souvent : une somme de nombreuses variables indépendantes tend vers une loi normale."}, {"terme": "Normalisation", "definition": "Normaliser une variable gaussienne (soustraire sa moyenne, diviser par son écart-type) la ramène à la loi normale centrée réduite, servant de référence universelle."}], "applications_list": [{"text": "Modéliser les tailles ou les notes dans une population.", "icon": "education"}, {"text": "Quantifier l'incertitude de mesure en sciences expérimentales.", "icon": "research"}, {"text": "Fonder les tests statistiques et intervalles de confiance.", "icon": "data"}]}, {"id": 400, "title": "Grandeurs physiques", "category": "Physique", "formulas": ["Longueur : m", "Temps : s", "Masse : kg", "Intensité : A"], "details": "Les grandeurs physiques sont les quantités mesurables utilisées pour décrire les phénomènes naturels.", "images": ["grandeurs.png"], "correspondances": [{"id": 401, "title": "Cinématique"}, {"id": 410, "title": "Énergie"}], "tags": ["physique", "grandeurs"], "niveau": "college", "definition": "Les grandeurs physiques sont les quantités mesurables qui décrivent le monde (longueur, temps, masse...), chacune associée à une unité de référence internationale.", "explication_formules": "Le mètre (m), la seconde (s) et le kilogramme (kg) forment, avec quatre autres unités, le Système International. Toute grandeur physique complexe (vitesse, force, énergie) se construit par combinaison de ces unités de base.", "approfondissements": [{"label": "Analyse dimensionnelle", "link": {"type": "theme", "slug": "analyse-dimensionnelle"}}, {"label": "Système International d'unités", "link": {"type": "theme", "slug": "systeme-international-d-unites"}}, {"label": "Incertitudes de mesure", "link": {"type": "theme", "slug": "incertitudes-de-mesure"}}, {"label": "Grandeurs vectorielles vs scalaires", "link": {"type": "theme", "slug": "grandeurs-vectorielles-vs-scalaires"}}, {"label": "Constantes physiques fondamentales", "link": {"type": "theme", "slug": "constantes-physiques-fondamentales"}}], "sous_points": [{"terme": "Grandeurs scalaires", "definition": "Une grandeur scalaire (température, masse, temps) se résume à un simple nombre accompagné d'une unité."}, {"terme": "Grandeurs vectorielles", "definition": "Une grandeur vectorielle (force, vitesse) nécessite en plus une direction et un sens pour être complètement définie."}, {"terme": "Unités SI", "definition": "Le Système International définit sept unités de base (mètre, kilogramme, seconde...) à partir desquelles toutes les autres se construisent."}, {"terme": "Conversions", "definition": "Convertir une grandeur d'une unité à une autre nécessite de multiplier par un facteur de conversion précis."}], "applications_list": [{"text": "Garantir que les mesures scientifiques sont comparables partout dans le monde.", "icon": "research"}, {"text": "Concevoir des instruments de mesure fiables.", "icon": "industry"}, {"text": "Vérifier la cohérence dimensionnelle d'une formule physique.", "icon": "research"}]}, {"id": 401, "title": "Cinématique", "category": "Physique", "formulas": ["v = dx/dt", "a = dv/dt", "MRU : x(t) = x0 + vt", "MRUA : x(t) = x0 + v0 t + (1/2) a t²"], "details": "La cinématique décrit le mouvement sans s’intéresser aux causes.", "images": ["cinematique.png"], "correspondances": [{"id": 402, "title": "Dynamique"}, {"id": 403, "title": "Forces"}], "tags": ["physique", "cinematique"], "niveau": "lycee", "definition": "La cinématique décrit le mouvement des objets (position, vitesse, accélération) sans se préoccuper des causes de ce mouvement — c'est la 'géométrie du mouvement'.", "explication_formules": "v=dx/dt définit la vitesse comme la variation instantanée de la position. a=dv/dt définit l'accélération comme la variation de la vitesse. Le mouvement rectiligne uniforme x(t)=x0+vt décrit un déplacement à vitesse constante.", "approfondissements": [{"label": "Mouvement uniformément accéléré", "link": {"type": "theme", "slug": "mouvement-uniformement-accelere"}}, {"label": "Mouvement circulaire", "link": {"type": "notion", "id": 405}}, {"label": "Cinématique relative (changement de référentiel)", "link": {"type": "theme", "slug": "cinematique-relative-changement-de-referentiel"}}, {"label": "Cinématique en coordonnées polaires", "link": {"type": "theme", "slug": "cinematique-en-coordonnees-polaires"}}, {"label": "Trajectoires paramétriques", "link": {"type": "theme", "slug": "trajectoires-parametriques"}}], "sous_points": [{"terme": "Trajectoires", "definition": "La trajectoire d'un objet est la courbe décrite par ses positions successives au cours du temps."}, {"terme": "Vitesses", "definition": "La vitesse est la dérivée de la position par rapport au temps, mesurant la rapidité et la direction du déplacement."}, {"terme": "Accélérations", "definition": "L'accélération est la dérivée de la vitesse par rapport au temps, mesurant à quelle vitesse le mouvement change."}, {"terme": "Mouvements rectilignes et circulaires", "definition": "Un mouvement rectiligne suit une ligne droite ; un mouvement circulaire suit un cercle, chacun avec ses formules spécifiques."}], "applications_list": [{"text": "Calculer le temps de trajet d'un véhicule.", "icon": "transport"}, {"text": "Prévoir la trajectoire d'un projectile.", "icon": "physics"}, {"text": "Concevoir les systèmes de freinage en sécurité automobile.", "icon": "transport"}]}, {"id": 402, "title": "Dynamique", "category": "Physique", "formulas": ["F = m a", "Principe fondamental de la dynamique", "ΣF = m a"], "details": "La dynamique relie les forces appliquées à un corps à son mouvement.", "images": ["dynamique.png"], "correspondances": [{"id": 403, "title": "Forces"}, {"id": 410, "title": "Énergie"}], "tags": ["physique", "dynamique"], "niveau": "lycee", "definition": "La dynamique étudie les causes du mouvement : comment les forces appliquées à un objet déterminent son accélération, fondement de toute la mécanique classique.", "explication_formules": "F=ma (deuxième loi de Newton) relie directement la force totale appliquée à l'accélération produite, via la masse de l'objet qui mesure son inertie (sa résistance au changement de mouvement).", "approfondissements": [{"label": "Troisième loi de Newton (action-réaction)", "link": {"type": "theme", "slug": "troisieme-loi-de-newton-action-reaction"}}, {"label": "Dynamique en référentiel non galiléen", "link": {"type": "theme", "slug": "dynamique-en-referentiel-non-galileen"}}, {"label": "Systèmes de points matériels", "link": {"type": "theme", "slug": "systemes-de-points-materiels"}}, {"label": "Mécanique lagrangienne (formulation alternative)", "link": {"type": "theme", "slug": "mecanique-lagrangienne-formulation-alternative"}}, {"label": "Dynamique relativiste", "link": {"type": "theme", "slug": "dynamique-relativiste"}}], "sous_points": [{"terme": "Lois de Newton", "definition": "Ces trois lois relient force et mouvement : inertie, F=ma, et l'égalité action-réaction."}, {"terme": "Inertie", "definition": "L'inertie est la tendance naturelle d'un objet à conserver son état de mouvement (repos ou vitesse constante) en l'absence de force."}, {"terme": "Référentiels", "definition": "Un référentiel est le repère depuis lequel on observe et mesure un mouvement ; vitesse et position en dépendent."}, {"terme": "Frottements", "definition": "Les frottements sont des forces qui s'opposent au mouvement relatif entre deux surfaces en contact."}], "applications_list": [{"text": "Concevoir des véhicules et structures résistant aux forces subies.", "icon": "transport"}, {"text": "Calculer la poussée nécessaire pour lancer une fusée.", "icon": "space"}, {"text": "Programmer la physique des jeux vidéo.", "icon": "games"}]}, {"id": 403, "title": "Forces", "category": "Physique", "formulas": ["Poids : P = m g", "Frottement : f = μ N", "Force élastique : F = -k x"], "details": "Les forces sont des actions mécaniques capables de modifier le mouvement d’un corps.", "images": ["forces.png"], "correspondances": [{"id": 402, "title": "Dynamique"}, {"id": 404, "title": "Travail et puissance"}], "tags": ["physique", "forces"], "niveau": "college", "definition": "Les forces sont les interactions qui peuvent modifier le mouvement d'un objet — poids, frottement, force élastique — chacune obéissant à des lois spécifiques.", "explication_formules": "Le poids P=mg dépend de la masse et de la gravité locale. Le frottement f=μN dépend du coefficient de frottement et de la force normale (perpendiculaire à la surface). La force élastique F=-kx (loi de Hooke) est proportionnelle à l'étirement et s'y oppose.", "approfondissements": [{"label": "Forces de frottement statique vs dynamique", "link": {"type": "theme", "slug": "forces-de-frottement-statique-vs-dynamique"}}, {"label": "Force élastique et oscillateur harmonique", "link": {"type": "theme", "slug": "force-elastique-et-oscillateur-harmonique"}}, {"label": "Forces fictives (référentiel non inertiel)", "link": {"type": "theme", "slug": "forces-fictives-referentiel-non-inertiel"}}, {"label": "Force de traînée (résistance de l'air)", "link": {"type": "theme", "slug": "force-de-trainee-resistance-de-l-air"}}, {"label": "Champs de force et énergie potentielle", "link": {"type": "theme", "slug": "champs-de-force-et-energie-potentielle"}}], "sous_points": [{"terme": "Forces de contact", "definition": "Une force de contact s'exerce entre deux objets qui se touchent physiquement, comme le frottement ou la réaction d'un support."}, {"terme": "Forces à distance", "definition": "Une force à distance s'exerce sans contact direct, comme la gravité ou la force électromagnétique."}, {"terme": "Diagrammes de forces", "definition": "Un diagramme de forces représente graphiquement toutes les forces agissant sur un objet, essentiel pour appliquer les lois de Newton."}], "applications_list": [{"text": "Dimensionner les freins et pneus d'un véhicule.", "icon": "transport"}, {"text": "Concevoir des amortisseurs et ressorts en ingénierie.", "icon": "industry"}, {"text": "Calculer la portance nécessaire pour faire voler un avion.", "icon": "transport"}]}, {"id": 404, "title": "Travail et puissance", "category": "Physique", "formulas": ["Travail : W = ∫ F·dl", "Puissance : P = dW/dt", "P = F·v"], "details": "Le travail mesure l’énergie transférée par une force.", "images": ["travail_puissance.png"], "correspondances": [{"id": 410, "title": "Énergie"}, {"id": 403, "title": "Forces"}], "tags": ["physique", "travail"], "niveau": "lycee", "definition": "Le travail mesure l'énergie transférée par une force lors d'un déplacement ; la puissance mesure la rapidité avec laquelle ce transfert d'énergie s'effectue.", "explication_formules": "W=∫F·dl intègre la force le long du trajet parcouru, ne comptant que la composante de la force alignée avec le déplacement. La puissance P=dW/dt=F·v relie directement le travail fourni par seconde à la force et à la vitesse instantanées.", "approfondissements": [{"label": "Théorème de l'énergie cinétique", "link": {"type": "theme", "slug": "theoreme-de-l-energie-cinetique"}}, {"label": "Puissance instantanée vs moyenne", "link": {"type": "theme", "slug": "puissance-instantanee-vs-moyenne"}}, {"label": "Rendement énergétique", "link": {"type": "theme", "slug": "rendement-energetique"}}, {"label": "Travail des forces conservatives", "link": {"type": "theme", "slug": "travail-des-forces-conservatives"}}, {"label": "Puissance en électricité (P=UI)", "link": {"type": "theme", "slug": "puissance-en-electricite-p-ui"}}], "sous_points": [{"terme": "Travail d'une force constante", "definition": "Le travail d'une force constante W=F·d ne dépend que de la force et du déplacement dans sa direction."}, {"terme": "Travail d'une force variable", "definition": "Quand la force varie, son travail se calcule par une intégrale le long du trajet parcouru."}, {"terme": "Puissance instantanée", "definition": "La puissance instantanée mesure le taux de transfert d'énergie à un instant précis, P=F·v."}], "applications_list": [{"text": "Dimensionner la puissance d'un moteur nécessaire.", "icon": "industry"}, {"text": "Calculer la consommation énergétique d'un appareil.", "icon": "electronics"}, {"text": "Évaluer l'efficacité d'une machine.", "icon": "industry"}]}, {"id": 405, "title": "Mouvement circulaire", "category": "Physique", "formulas": ["v = ω r", "a_n = v² / r", "a_t = dv/dt"], "details": "Étude des mouvements sur des trajectoires circulaires.", "images": ["mvt_circulaire.png"], "correspondances": [{"id": 401, "title": "Cinématique"}, {"id": 406, "title": "Oscillations"}], "tags": ["physique", "rotation"], "niveau": "lycee", "definition": "Le mouvement circulaire décrit le déplacement d'un objet le long d'un cercle, caractérisé par une vitesse qui change constamment de direction même si sa norme reste constante.", "explication_formules": "v=ωr relie la vitesse linéaire à la vitesse angulaire ω et au rayon r. L'accélération normale a_n=v²/r pointe vers le centre du cercle et est responsable du changement de direction (pas de vitesse) du mouvement.", "approfondissements": [{"label": "Force centripète", "link": {"type": "theme", "slug": "force-centripete"}}, {"label": "Mouvement circulaire non uniforme", "link": {"type": "notion", "id": 405}}, {"label": "Orbites et lois de Kepler", "link": {"type": "theme", "slug": "orbites-et-lois-de-kepler"}}, {"label": "Mouvement circulaire en référentiel tournant", "link": {"type": "notion", "id": 405}}, {"label": "Moment cinétique", "link": {"type": "theme", "slug": "moment-cinetique"}}], "sous_points": [{"terme": "Vitesse angulaire", "definition": "La vitesse angulaire ω mesure la rapidité de rotation, en radians par seconde."}, {"terme": "Accélération normale", "definition": "L'accélération normale, dirigée vers le centre du cercle, est responsable du changement de direction du mouvement circulaire."}, {"terme": "Accélération tangentielle", "definition": "L'accélération tangentielle mesure le changement de la vitesse (sa norme), le long de la trajectoire circulaire."}], "applications_list": [{"text": "Concevoir des manèges et centrifugeuses en toute sécurité.", "icon": "sports"}, {"text": "Calculer les forces subies par les satellites en orbite.", "icon": "space"}, {"text": "Dimensionner des virages routiers en sécurité.", "icon": "transport"}]}, {"id": 406, "title": "Oscillations", "category": "Physique", "formulas": ["Oscillateur harmonique : x'' + ω² x = 0", "Solution : x(t) = A cos(ωt + φ)"], "details": "Les oscillations décrivent des mouvements périodiques autour d’une position d’équilibre.", "images": ["oscillations.png"], "correspondances": [{"id": 405, "title": "Mouvement circulaire"}, {"id": 407, "title": "Ondes"}], "tags": ["physique", "oscillations"], "niveau": "lycee", "definition": "Les oscillations décrivent un mouvement qui se répète périodiquement autour d'une position d'équilibre, comme un pendule ou un ressort qui vibre.", "explication_formules": "x''+ω²x=0 est l'équation de l'oscillateur harmonique, dont la solution x(t)=A cos(ωt+φ) décrit une oscillation sinusoïdale d'amplitude A, de pulsation ω et de phase φ.", "approfondissements": [{"label": "Oscillateur amorti et résonance", "link": {"type": "theme", "slug": "oscillateur-amorti-et-resonance"}}, {"label": "Oscillations couplées", "link": {"type": "theme", "slug": "oscillations-couplees"}}, {"label": "Pendule (petites vs grandes oscillations)", "link": {"type": "theme", "slug": "pendule-petites-vs-grandes-oscillations"}}, {"label": "Oscillations forcées", "link": {"type": "theme", "slug": "oscillations-forcees"}}, {"label": "Analogie avec les circuits électriques (LC)", "link": {"type": "theme", "slug": "analogie-avec-les-circuits-electriques-lc"}}], "sous_points": [{"terme": "Période", "definition": "La période est la durée d'une oscillation complète, mesurée en secondes."}, {"terme": "Fréquence", "definition": "La fréquence est le nombre d'oscillations complètes par seconde, l'inverse de la période."}, {"terme": "Amortissement", "definition": "L'amortissement décrit la perte progressive d'énergie d'un oscillateur par frottement, réduisant peu à peu l'amplitude du mouvement."}, {"terme": "Résonance", "definition": "La résonance se produit quand une force extérieure oscille à la fréquence propre du système, amplifiant fortement le mouvement."}], "applications_list": [{"text": "Concevoir des suspensions de voiture et des amortisseurs.", "icon": "transport"}, {"text": "Régler les horloges à pendule et à quartz.", "icon": "industry"}, {"text": "Modéliser les vibrations mécaniques dans les structures.", "icon": "construction"}]}, {"id": 407, "title": "Ondes", "category": "Physique", "formulas": ["v = λ f", "Équation d’onde : ∂²u/∂t² = c² ∂²u/∂x²"], "details": "Les ondes sont des perturbations qui se propagent dans un milieu.", "images": ["ondes.png"], "correspondances": [{"id": 406, "title": "Oscillations"}, {"id": 408, "title": "Optique géométrique"}], "tags": ["physique", "ondes"], "niveau": "lycee", "definition": "Une onde transporte de l'énergie et de l'information à travers l'espace sans déplacement net de matière, en propageant une perturbation (son, lumière, vague).", "explication_formules": "v=λf relie la vitesse de propagation à la longueur d'onde λ et la fréquence f. L'équation d'onde ∂²u/∂t²=c²∂²u/∂x² décrit mathématiquement comment une perturbation se propage à vitesse constante c.", "approfondissements": [{"label": "Ondes stationnaires", "link": {"type": "theme", "slug": "ondes-stationnaires"}}, {"label": "Interférences et diffraction", "link": {"type": "theme", "slug": "interferences-et-diffraction"}}, {"label": "Effet Doppler", "link": {"type": "theme", "slug": "effet-doppler"}}, {"label": "Ondes électromagnétiques", "link": {"type": "theme", "slug": "ondes-electromagnetiques"}}, {"label": "Ondes en mécanique quantique (fonction d'onde)", "link": {"type": "theme", "slug": "ondes-en-mecanique-quantique-fonction-d-onde"}}], "sous_points": [{"terme": "Ondes mécaniques", "definition": "Une onde mécanique (son, vague) nécessite un support matériel pour se propager."}, {"terme": "Ondes électromagnétiques", "definition": "Une onde électromagnétique (lumière, radio) se propage même dans le vide, résultant de l'oscillation des champs électrique et magnétique."}, {"terme": "Interférences", "definition": "Les interférences résultent de la superposition de plusieurs ondes, qui peuvent se renforcer ou s'annuler selon leur déphasage."}, {"terme": "Diffraction", "definition": "La diffraction est l'étalement d'une onde en rencontrant un obstacle ou une ouverture de taille comparable à sa longueur d'onde."}], "applications_list": [{"text": "Concevoir des systèmes de télécommunication (ondes radio).", "icon": "communication"}, {"text": "Analyser la propagation du son en acoustique.", "icon": "audio"}, {"text": "Étudier les séismes en géophysique.", "icon": "environment"}]}, {"id": 408, "title": "Optique géométrique", "category": "Physique", "formulas": ["Loi de Snell-Descartes : n1 sin i = n2 sin r", "Lentilles : 1/f = 1/p + 1/p'"], "details": "L’optique géométrique étudie la propagation rectiligne de la lumière.", "images": ["optique.png"], "correspondances": [{"id": 407, "title": "Ondes"}, {"id": 409, "title": "Optique physique"}], "tags": ["physique", "optique"], "niveau": "lycee", "definition": "L'optique géométrique décrit la propagation de la lumière en la représentant comme des rayons rectilignes, ce qui suffit à expliquer réflexion, réfraction et formation d'images.", "explication_formules": "La loi de Snell-Descartes n1 sin i=n2 sin r décrit comment un rayon lumineux se courbe en passant d'un milieu à un autre. La formule des lentilles 1/f=1/p+1/p' relie la position de l'objet, de l'image et la distance focale de la lentille.", "approfondissements": [{"label": "Réflexion totale interne", "link": {"type": "theme", "slug": "reflexion-totale-interne"}}, {"label": "Formation d'images (miroirs, lentilles)", "link": {"type": "theme", "slug": "formation-d-images-miroirs-lentilles"}}, {"label": "Aberrations optiques", "link": {"type": "theme", "slug": "aberrations-optiques"}}, {"label": "Fibres optiques", "link": {"type": "theme", "slug": "fibres-optiques"}}, {"label": "Optique instrumentale (télescopes, microscopes)", "link": {"type": "theme", "slug": "optique-instrumentale-telescopes-microscopes"}}], "sous_points": [{"terme": "Réflexion", "definition": "La réflexion est le rebond de la lumière sur une surface, l'angle d'incidence égalant l'angle de réflexion."}, {"terme": "Réfraction", "definition": "La réfraction est le changement de direction de la lumière en passant d'un milieu à un autre, décrit par la loi de Snell-Descartes."}, {"terme": "Lentilles", "definition": "Une lentille dévie les rayons lumineux pour former une image, convergente ou divergente selon sa forme."}, {"terme": "Images", "definition": "Une image se forme là où convergent (ou semblent converger) les rayons lumineux après réflexion ou réfraction."}], "applications_list": [{"text": "Concevoir des lunettes de vue.", "icon": "medicine"}, {"text": "Concevoir des appareils photo et microscopes.", "icon": "research"}, {"text": "Calculer le trajet de la lumière dans les fibres optiques.", "icon": "communication"}]}, {"id": 409, "title": "Optique physique", "category": "Physique", "formulas": ["Diffraction : θ ≈ λ/a", "Interférences : I = I1 + I2 + 2√(I1I2) cos φ"], "details": "L’optique physique étudie les phénomènes ondulatoires de la lumière.", "images": ["optique_physique.png"], "correspondances": [{"id": 407, "title": "Ondes"}, {"id": 408, "title": "Optique géométrique"}], "tags": ["physique", "optique-physique"], "niveau": "lycee", "definition": "L'optique physique étudie la lumière comme une onde, ce qui permet d'expliquer des phénomènes que l'optique géométrique ne peut pas décrire, comme la diffraction et les interférences.", "explication_formules": "La diffraction θ≈λ/a montre qu'une onde s'étale en passant par une ouverture étroite, d'autant plus que sa longueur d'onde λ est grande par rapport à l'ouverture a. Les interférences I=I1+I2+2√(I1I2)cos φ montrent comment deux ondes peuvent se renforcer ou s'annuler selon leur déphasage.", "approfondissements": [{"label": "Expérience des fentes de Young", "link": {"type": "theme", "slug": "experience-des-fentes-de-young"}}, {"label": "Réseaux de diffraction", "link": {"type": "theme", "slug": "reseaux-de-diffraction"}}, {"label": "Polarisation de la lumière", "link": {"type": "theme", "slug": "polarisation-de-la-lumiere"}}, {"label": "Cohérence optique", "link": {"type": "theme", "slug": "coherence-optique"}}, {"label": "Holographie", "link": {"type": "theme", "slug": "holographie"}}], "sous_points": [{"terme": "Diffraction", "definition": "La diffraction étale une onde lumineuse en rencontrant un obstacle, un phénomène impossible à expliquer par l'optique purement géométrique."}, {"terme": "Interférences", "definition": "Les interférences lumineuses produisent des franges alternant zones claires et sombres, preuve de la nature ondulatoire de la lumière."}, {"terme": "Polarisation", "definition": "La polarisation décrit la direction d'oscillation du champ électrique d'une onde lumineuse."}], "applications_list": [{"text": "Concevoir des hologrammes et réseaux de diffraction.", "icon": "art"}, {"text": "Expliquer les couleurs irisées d'une bulle de savon ou d'un CD.", "icon": "physics"}, {"text": "Améliorer la résolution des microscopes et télescopes.", "icon": "research"}]}, {"id": 410, "title": "Énergie", "category": "Physique", "formulas": ["Énergie cinétique : Ec = (1/2) m v²", "Énergie potentielle : Ep = m g h", "Conservation : E_tot = constante"], "details": "L’énergie est la capacité d’un système à produire un travail.", "images": ["energie.png"], "correspondances": [{"id": 404, "title": "Travail et puissance"}, {"id": 411, "title": "Thermodynamique"}], "tags": ["physique", "energie"], "niveau": "lycee", "definition": "L'énergie est une quantité qui se transforme d'une forme à une autre (cinétique, potentielle, thermique...) mais se conserve toujours globalement dans un système isolé.", "explication_formules": "L'énergie cinétique Ec=(1/2)mv² dépend de la masse et de la vitesse. L'énergie potentielle Ep=mgh dépend de la hauteur dans un champ de gravité. La conservation de l'énergie totale garantit que la somme reste constante en l'absence de frottement.", "approfondissements": [{"label": "Énergie potentielle élastique", "link": {"type": "theme", "slug": "energie-potentielle-elastique"}}, {"label": "Théorème de l'énergie mécanique", "link": {"type": "theme", "slug": "theoreme-de-l-energie-mecanique"}}, {"label": "Conservation de l'énergie avec frottement (dissipation)", "link": {"type": "theme", "slug": "conservation-de-l-energie-avec-frottement-dissipation"}}, {"label": "Énergie en relativité (E=mc²)", "link": {"type": "theme", "slug": "energie-en-relativite-e-mc"}}, {"label": "Énergie en mécanique quantique", "link": {"type": "theme", "slug": "energie-en-mecanique-quantique"}}], "sous_points": [{"terme": "Énergies mécaniques", "definition": "L'énergie mécanique combine énergie cinétique (mouvement) et énergie potentielle (position), conservée en l'absence de frottement."}, {"terme": "Énergies thermiques", "definition": "L'énergie thermique correspond à l'agitation microscopique désordonnée des particules d'un système."}, {"terme": "Énergies électriques", "definition": "L'énergie électrique est associée au déplacement de charges électriques sous l'effet d'un champ ou d'une tension."}], "applications_list": [{"text": "Dimensionner des systèmes de stockage d'énergie (batteries, barrages).", "icon": "industry"}, {"text": "Calculer le rendement d'une centrale électrique.", "icon": "industry"}, {"text": "Analyser la sécurité des montagnes russes.", "icon": "sports"}]}, {"id": 411, "title": "Thermodynamique", "category": "Physique", "formulas": ["1er principe : ΔU = Q + W", "PV = nRT", "S ≥ 0 (entropie)"], "details": "La thermodynamique étudie les échanges d’énergie et les transformations de la matière.", "images": ["thermo.png"], "correspondances": [{"id": 410, "title": "Énergie"}, {"id": 412, "title": "Gaz parfaits"}], "tags": ["physique", "thermo"], "niveau": "lycee", "definition": "La thermodynamique étudie les échanges d'énergie sous forme de chaleur et de travail, et les transformations d'un système entre différents états physiques.", "explication_formules": "Le premier principe ΔU=Q+W dit que la variation d'énergie interne d'un système égale la chaleur reçue plus le travail reçu — l'énergie ne se crée ni ne se détruit. L'équation des gaz parfaits PV=nRT relie pression, volume et température. Le second principe impose que l'entropie S d'un système isolé ne peut qu'augmenter.", "approfondissements": [{"label": "Cycles thermodynamiques (Carnot, Otto)", "link": {"type": "theme", "slug": "cycles-thermodynamiques-carnot-otto"}}, {"label": "Entropie et second principe", "link": {"type": "theme", "slug": "entropie-et-second-principe"}}, {"label": "Changements d'état et diagrammes de phase", "link": {"type": "theme", "slug": "changements-d-etat-et-diagrammes-de-phase"}}, {"label": "Thermodynamique statistique (lien microscopique)", "link": {"type": "theme", "slug": "thermodynamique-statistique-lien-microscopique"}}, {"label": "Machines thermiques et rendement", "link": {"type": "theme", "slug": "machines-thermiques-et-rendement"}}], "sous_points": [{"terme": "Systèmes fermés", "definition": "Un système fermé peut échanger de l'énergie avec l'extérieur mais pas de matière."}, {"terme": "Systèmes ouverts", "definition": "Un système ouvert peut échanger à la fois énergie et matière avec l'extérieur."}, {"terme": "Cycles thermodynamiques", "definition": "Un cycle thermodynamique ramène un système à son état initial après une suite de transformations, comme dans un moteur thermique."}], "applications_list": [{"text": "Concevoir des moteurs thermiques et des réfrigérateurs.", "icon": "industry"}, {"text": "Optimiser le rendement des centrales électriques.", "icon": "industry"}, {"text": "Comprendre les limites fondamentales de la conversion d'énergie.", "icon": "research"}]}, {"id": 412, "title": "Gaz parfaits", "category": "Physique", "formulas": ["PV = nRT", "P = ρ R T"], "details": "Modèle simplifié de gaz où les particules n’interagissent pas.", "images": ["gaz_parfaits.png"], "correspondances": [{"id": 411, "title": "Thermodynamique"}, {"id": 413, "title": "Pression"}], "tags": ["physique", "gaz"], "niveau": "lycee", "definition": "Le modèle du gaz parfait décrit un gaz idéalisé où les molécules n'interagissent pas entre elles, ce qui permet des calculs simples reliant pression, volume et température.", "explication_formules": "PV=nRT relie ces trois grandeurs via la constante des gaz parfaits R et la quantité de matière n. Cette loi unifie plusieurs lois empiriques historiques (Boyle-Mariotte, Charles, Gay-Lussac) en une seule équation.", "approfondissements": [{"label": "Théorie cinétique des gaz", "link": {"type": "theme", "slug": "theorie-cinetique-des-gaz"}}, {"label": "Gaz réels et équation de van der Waals", "link": {"type": "theme", "slug": "gaz-reels-et-equation-de-van-der-waals"}}, {"label": "Transformations isotherme, isobare, adiabatique", "link": {"type": "theme", "slug": "transformations-isotherme-isobare-adiabatique"}}, {"label": "Mélanges de gaz (loi de Dalton)", "link": {"type": "theme", "slug": "melanges-de-gaz-loi-de-dalton"}}, {"label": "Applications en météorologie", "link": {"type": "theme", "slug": "applications-en-meteorologie"}}], "sous_points": [{"terme": "Transformations isothermes", "definition": "Une transformation isotherme se produit à température constante."}, {"terme": "Transformations isobares", "definition": "Une transformation isobare se produit à pression constante."}, {"terme": "Transformations adiabatiques", "definition": "Une transformation adiabatique se produit sans échange de chaleur avec l'extérieur."}], "applications_list": [{"text": "Calculer la pression dans une bouteille de gaz comprimé.", "icon": "industry"}, {"text": "Dimensionner des systèmes de climatisation.", "icon": "industry"}, {"text": "Prévoir le comportement de l'atmosphère en météorologie.", "icon": "environment"}]}, {"id": 413, "title": "Pression", "category": "Physique", "formulas": ["P = F / S", "Pression hydrostatique : P = ρ g h"], "details": "La pression est une force exercée par unité de surface.", "images": ["pression.png"], "correspondances": [{"id": 412, "title": "Gaz parfaits"}, {"id": 414, "title": "Fluides"}], "tags": ["physique", "pression"], "niveau": "college", "definition": "La pression mesure la force exercée par unité de surface : elle explique comment une même force peut avoir des effets très différents selon la surface sur laquelle elle s'applique.", "explication_formules": "P=F/S définit la pression comme une force répartie sur une surface. La pression hydrostatique P=ρgh montre que la pression dans un fluide augmente proportionnellement à la profondeur, à cause du poids du fluide au-dessus.", "approfondissements": [{"label": "Principe de Pascal", "link": {"type": "theme", "slug": "principe-de-pascal"}}, {"label": "Poussée d'Archimède", "link": {"type": "theme", "slug": "poussee-d-archimede"}}, {"label": "Pression atmosphérique et altitude", "link": {"type": "theme", "slug": "pression-atmospherique-et-altitude"}}, {"label": "Pression dans les gaz (théorie cinétique)", "link": {"type": "theme", "slug": "pression-dans-les-gaz-theorie-cinetique"}}, {"label": "Applications aux systèmes hydrauliques", "link": {"type": "theme", "slug": "applications-aux-systemes-hydrauliques"}}], "sous_points": [{"terme": "Pression atmosphérique", "definition": "La pression atmosphérique est exercée par le poids de l'air au-dessus d'un point donné, et diminue avec l'altitude."}, {"terme": "Pression hydrostatique", "definition": "La pression hydrostatique dans un fluide augmente avec la profondeur, à cause du poids du fluide au-dessus."}, {"terme": "Manomètres", "definition": "Un manomètre est un instrument qui mesure directement la pression d'un fluide."}], "applications_list": [{"text": "Concevoir des barrages résistant à la pression de l'eau.", "icon": "construction"}, {"text": "Dimensionner des pneus et systèmes hydrauliques.", "icon": "transport"}, {"text": "Comprendre la formation des vents.", "icon": "environment"}]}, {"id": 414, "title": "Fluides", "category": "Physique", "formulas": ["Équation de Bernoulli : P + (1/2)ρv² + ρgh = constante", "Débit : Q = A v"], "details": "Les fluides regroupent les liquides et les gaz.", "images": ["fluides.png"], "correspondances": [{"id": 413, "title": "Pression"}, {"id": 415, "title": "Électricité"}], "tags": ["physique", "fluides"], "niveau": "lycee", "definition": "La mécanique des fluides étudie le comportement des liquides et des gaz en mouvement, un domaine essentiel pour comprendre l'aérodynamique, l'hydraulique et la météorologie.", "explication_formules": "L'équation de Bernoulli P+(1/2)ρv²+ρgh=constante relie pression, vitesse et hauteur le long d'un écoulement, expliquant par exemple pourquoi un fluide accélère quand la pression diminue. Le débit Q=Av relie la vitesse d'écoulement à la section du conduit.", "approfondissements": [{"label": "Équations de Navier-Stokes (fluides visqueux)", "link": {"type": "theme", "slug": "equations-de-navier-stokes-fluides-visqueux"}}, {"label": "Écoulements laminaires et turbulents", "link": {"type": "theme", "slug": "ecoulements-laminaires-et-turbulents"}}, {"label": "Portance et traînée aérodynamique", "link": {"type": "theme", "slug": "portance-et-trainee-aerodynamique"}}, {"label": "Nombre de Reynolds", "link": {"type": "theme", "slug": "nombre-de-reynolds"}}, {"label": "Applications à la météorologie", "link": {"type": "theme", "slug": "applications-a-la-meteorologie"}}], "sous_points": [{"terme": "Hydrostatique", "definition": "L'hydrostatique étudie les fluides au repos, notamment la pression et la poussée d'Archimède."}, {"terme": "Hydrodynamique", "definition": "L'hydrodynamique étudie les fluides en mouvement, notamment via l'équation de Bernoulli."}, {"terme": "Viscosité", "definition": "La viscosité mesure la résistance interne d'un fluide à l'écoulement, plus élevée pour le miel que pour l'eau."}], "applications_list": [{"text": "Concevoir la forme des ailes d'avion et des voitures.", "icon": "transport"}, {"text": "Dimensionner des canalisations et systèmes de ventilation.", "icon": "construction"}, {"text": "Comprendre la formation des tornades et courants océaniques.", "icon": "environment"}]}, {"id": 415, "title": "Électricité", "category": "Physique", "formulas": ["U = R I", "P = U I", "Q = I t"], "details": "L’électricité étudie les charges, les courants et les tensions.", "images": ["electricite.png"], "correspondances": [{"id": 416, "title": "Champ électrique"}, {"id": 417, "title": "Magnétisme"}], "tags": ["physique", "electricite"], "niveau": "college", "definition": "L'électricité étudie le comportement des charges électriques en mouvement (courant) et les circuits qui les guident, fondement de toute la technologie électronique moderne.", "explication_formules": "U=RI (loi d'Ohm) relie la tension, la résistance et l'intensité du courant dans un circuit. P=UI donne la puissance électrique consommée ou fournie. Q=It relie la charge électrique totale transportée au courant et à la durée.", "approfondissements": [{"label": "Circuits en série et en parallèle", "link": {"type": "theme", "slug": "circuits-en-serie-et-en-parallele"}}, {"label": "Lois de Kirchhoff", "link": {"type": "theme", "slug": "lois-de-kirchhoff"}}, {"label": "Circuits RC et RL (régime transitoire)", "link": {"type": "theme", "slug": "circuits-rc-et-rl-regime-transitoire"}}, {"label": "Circuits en courant alternatif", "link": {"type": "theme", "slug": "circuits-en-courant-alternatif"}}, {"label": "Puissance et rendement électrique", "link": {"type": "theme", "slug": "puissance-et-rendement-electrique"}}], "sous_points": [{"terme": "Circuits", "definition": "Un circuit électrique est un chemin fermé permettant au courant électrique de circuler."}, {"terme": "Résistances", "definition": "Une résistance limite le passage du courant électrique, dissipant de l'énergie sous forme de chaleur (loi d'Ohm U=RI)."}, {"terme": "Lois de Kirchhoff", "definition": "Ces deux lois (conservation du courant à un nœud, conservation de la tension sur une boucle) permettent de résoudre tout circuit électrique."}], "applications_list": [{"text": "Concevoir des circuits électroniques et installations domestiques.", "icon": "electronics"}, {"text": "Dimensionner des batteries et systèmes de charge.", "icon": "electronics"}, {"text": "Calculer la consommation énergétique des appareils.", "icon": "electronics"}]}, {"id": 416, "title": "Champ électrique", "category": "Physique", "formulas": ["E = F/q", "E = k q / r²"], "details": "Le champ électrique décrit l’action d’une charge sur une autre.", "images": ["champ_elec.png"], "correspondances": [{"id": 415, "title": "Électricité"}, {"id": 417, "title": "Magnétisme"}], "tags": ["physique", "champ-electrique"], "niveau": "lycee", "definition": "Le champ électrique décrit l'influence qu'exerce une charge électrique sur l'espace qui l'entoure, capable d'exercer une force sur toute autre charge présente à proximité.", "explication_formules": "E=F/q définit le champ comme la force qu'il exercerait sur une charge unitaire. E=kq/r² (loi de Coulomb) montre que le champ créé par une charge ponctuelle décroît avec le carré de la distance, comme la gravité.", "approfondissements": [{"label": "Potentiel électrique", "link": {"type": "theme", "slug": "potentiel-electrique"}}, {"label": "Théorème de Gauss", "link": {"type": "theme", "slug": "theoreme-de-gauss"}}, {"label": "Champ électrique dans un condensateur", "link": {"type": "notion", "id": 416}}, {"label": "Champ électrique et matière (diélectriques)", "link": {"type": "notion", "id": 416}}, {"label": "Lien avec le champ magnétique (électromagnétisme)", "link": {"type": "theme", "slug": "lien-avec-le-champ-magnetique-electromagnetisme"}}], "sous_points": [{"terme": "Lignes de champ", "definition": "Les lignes de champ électrique visualisent la direction de la force qu'exercerait le champ sur une charge positive en chaque point."}, {"terme": "Potentiel électrique", "definition": "Le potentiel électrique est une grandeur scalaire dont dérive le champ électrique, dont la différence entre deux points donne la tension."}], "applications_list": [{"text": "Concevoir des condensateurs pour stocker de l'énergie électrique.", "icon": "electronics"}, {"text": "Comprendre le fonctionnement des écrans tactiles capacitifs.", "icon": "computer"}, {"text": "Analyser la foudre et les phénomènes électrostatiques.", "icon": "environment"}]}, {"id": 417, "title": "Magnétisme", "category": "Physique", "formulas": ["F = q v × B", "B = μ0 I / (2π r)"], "details": "Le magnétisme décrit les effets des courants et des aimants.", "images": ["magnetisme.png"], "correspondances": [{"id": 416, "title": "Champ électrique"}, {"id": 418, "title": "Électromagnétisme"}], "tags": ["physique", "magnetisme"], "niveau": "college", "definition": "Le magnétisme étudie les forces exercées par les aimants et les courants électriques, intimement lié à l'électricité (les deux ne forment qu'un seul phénomène : l'électromagnétisme).", "explication_formules": "F=qv×B donne la force qu'un champ magnétique exerce sur une charge en mouvement (force de Lorentz), perpendiculaire à la fois à la vitesse et au champ. B=μ0I/(2πr) donne le champ magnétique créé par un fil parcouru par un courant.", "approfondissements": [{"label": "Induction électromagnétique (loi de Faraday)", "link": {"type": "theme", "slug": "induction-electromagnetique-loi-de-faraday"}}, {"label": "Moteurs et générateurs électriques", "link": {"type": "theme", "slug": "moteurs-et-generateurs-electriques"}}, {"label": "Champ magnétique terrestre", "link": {"type": "theme", "slug": "champ-magnetique-terrestre"}}, {"label": "Matériaux ferromagnétiques", "link": {"type": "theme", "slug": "materiaux-ferromagnetiques"}}, {"label": "Résonance magnétique nucléaire (IRM)", "link": {"type": "theme", "slug": "resonance-magnetique-nucleaire-irm"}}], "sous_points": [{"terme": "Champ magnétique", "definition": "Le champ magnétique décrit l'influence qu'exerce un aimant ou un courant électrique sur l'espace environnant."}, {"terme": "Force de Lorentz", "definition": "Cette force F=qv×B s'exerce sur une charge en mouvement dans un champ magnétique, perpendiculaire à la fois à la vitesse et au champ."}], "applications_list": [{"text": "Concevoir des moteurs électriques et générateurs.", "icon": "electronics"}, {"text": "Développer l'imagerie médicale par résonance magnétique.", "icon": "medicine"}, {"text": "Fonder le fonctionnement des haut-parleurs et disques durs.", "icon": "audio"}]}, {"id": 418, "title": "Électromagnétisme", "category": "Physique", "formulas": ["Maxwell : ∇·E = ρ/ε0", "∇×B = μ0 J + μ0 ε0 ∂E/∂t"], "details": "L’électromagnétisme unifie électricité et magnétisme.", "images": ["electromagnetisme.png"], "correspondances": [{"id": 417, "title": "Magnétisme"}, {"id": 407, "title": "Ondes"}], "tags": ["physique", "electromagnetisme"], "niveau": "lycee", "definition": "L'électromagnétisme unifie électricité et magnétisme en une seule théorie cohérente, expliquant notamment que la lumière elle-même est une onde électromagnétique.", "explication_formules": "Les équations de Maxwell (∇·E=ρ/ε0, ∇×B=μ0J+μ0ε0∂E/∂t, et deux autres) décrivent complètement comment les champs électriques et magnétiques se créent et interagissent mutuellement, y compris leur propagation sous forme d'ondes.", "approfondissements": [{"label": "Ondes électromagnétiques et spectre", "link": {"type": "theme", "slug": "ondes-electromagnetiques-et-spectre"}}, {"label": "Formulation en formes différentielles", "link": {"type": "theme", "slug": "formulation-en-formes-differentielles"}}, {"label": "Électromagnétisme relativiste", "link": {"type": "theme", "slug": "electromagnetisme-relativiste"}}, {"label": "Rayonnement électromagnétique", "link": {"type": "theme", "slug": "rayonnement-electromagnetique"}}, {"label": "Applications aux télécommunications", "link": {"type": "theme", "slug": "applications-aux-telecommunications"}}], "sous_points": [{"terme": "Ondes EM", "definition": "Les ondes électromagnétiques (lumière, radio) résultent de l'oscillation couplée de champs électrique et magnétique, se propageant même dans le vide."}, {"terme": "Propagation", "definition": "La propagation d'une onde électromagnétique se fait toujours à la vitesse de la lumière dans le vide."}, {"terme": "Polarisation", "definition": "La polarisation décrit la direction d'oscillation du champ électrique de l'onde électromagnétique."}], "applications_list": [{"text": "Fonder toutes les télécommunications sans fil.", "icon": "communication"}, {"text": "Concevoir des antennes et systèmes radar.", "icon": "communication"}, {"text": "Expliquer la nature de la lumière visible et invisible.", "icon": "physics"}]}, {"id": 500, "title": "Algorithmes", "category": "Informatique", "formulas": ["Entrée → Traitement → Sortie", "Complexité : O(f(n))"], "details": "Un algorithme est une suite d’instructions permettant de résoudre un problème de manière systématique.", "images": ["algorithmes.png"], "correspondances": [{"id": 501, "title": "Structures de données"}, {"id": 510, "title": "Complexité algorithmique"}], "tags": ["informatique", "algorithmes"], "niveau": "lycee", "definition": "Un algorithme est une suite finie et précise d'instructions permettant de résoudre un problème ou d'accomplir une tâche, indépendamment du langage de programmation utilisé pour l'implémenter.", "explication_formules": "Le schéma entrée → traitement → sortie décrit la structure de tout algorithme. La complexité O(f(n)) mesure comment le temps de calcul (ou la mémoire utilisée) augmente avec la taille n des données, ce qui permet de comparer l'efficacité de différents algorithmes.", "approfondissements": [{"label": "Complexité temporelle et spatiale", "link": {"type": "theme", "slug": "complexite-temporelle-et-spatiale"}}, {"label": "Algorithmes de tri (rapides, fusion)", "link": {"type": "theme", "slug": "algorithmes-de-tri-rapides-fusion"}}, {"label": "Algorithmes récursifs", "link": {"type": "theme", "slug": "algorithmes-recursifs"}}, {"label": "Analyse du pire cas vs cas moyen", "link": {"type": "theme", "slug": "analyse-du-pire-cas-vs-cas-moyen"}}, {"label": "Algorithmes gloutons et programmation dynamique", "link": {"type": "theme", "slug": "algorithmes-gloutons-et-programmation-dynamique"}}], "sous_points": [{"terme": "Déterminisme", "definition": "Un algorithme déterministe produit toujours le même résultat pour une même entrée donnée."}, {"terme": "Terminaison", "definition": "Un algorithme doit se terminer après un nombre fini d'étapes, sans tourner indéfiniment."}, {"terme": "Correction", "definition": "Un algorithme est correct s'il produit toujours le résultat attendu pour toute entrée valide."}, {"terme": "Complexité", "definition": "La complexité mesure la quantité de ressources (temps, mémoire) qu'un algorithme consomme en fonction de la taille des données."}], "applications_list": [{"text": "Trier des données efficacement dans les moteurs de recherche.", "icon": "computer"}, {"text": "Planifier des trajets optimaux (GPS).", "icon": "navigation"}, {"text": "Fonder toute la programmation informatique moderne.", "icon": "computer"}]}, {"id": 501, "title": "Structures de données", "category": "Informatique", "formulas": ["Tableau : accès O(1)", "Liste chaînée : insertion O(1)", "Pile / File : FIFO / LIFO"], "details": "Les structures de données organisent l’information pour optimiser les opérations.", "images": ["structures.png"], "correspondances": [{"id": 502, "title": "Arbres"}, {"id": 503, "title": "Graphes"}], "tags": ["informatique", "structures"], "niveau": "lycee", "definition": "Une structure de données organise l'information en mémoire d'une façon précise, choisie pour rendre certaines opérations (recherche, insertion) rapides et efficaces.", "explication_formules": "Un tableau permet un accès direct en temps constant O(1) à n'importe quel élément par son index. Une liste chaînée permet une insertion rapide O(1) mais nécessite de parcourir la liste pour accéder à un élément. Pile (LIFO) et file (FIFO) organisent les données selon un ordre d'accès spécifique.", "approfondissements": [{"label": "Arbres et structures hiérarchiques", "link": {"type": "theme", "slug": "arbres-et-structures-hierarchiques"}}, {"label": "Tables de hachage", "link": {"type": "theme", "slug": "tables-de-hachage"}}, {"label": "Files de priorité", "link": {"type": "theme", "slug": "files-de-priorite"}}, {"label": "Structures de données persistantes", "link": {"type": "notion", "id": 501}}, {"label": "Choix de structure selon les opérations fréquentes", "link": {"type": "theme", "slug": "choix-de-structure-selon-les-operations-frequentes"}}], "sous_points": [{"terme": "Tableaux", "definition": "Un tableau stocke des éléments à des positions indexées, permettant un accès direct en temps constant."}, {"terme": "Listes", "definition": "Une liste chaînée relie ses éléments entre eux, permettant une insertion rapide mais un accès séquentiel."}, {"terme": "Piles", "definition": "Une pile suit le principe « dernier arrivé, premier sorti » (LIFO)."}, {"terme": "Files", "definition": "Une file suit le principe « premier arrivé, premier sorti » (FIFO)."}, {"terme": "Arbres, graphes", "definition": "Arbres et graphes organisent des données selon des relations hiérarchiques ou en réseau."}], "applications_list": [{"text": "Optimiser les bases de données et moteurs de recherche.", "icon": "computer"}, {"text": "Gérer un historique de navigation ou une file d'impression.", "icon": "computer"}, {"text": "Structurer les données des jeux vidéo.", "icon": "games"}]}, {"id": 502, "title": "Arbres", "category": "Informatique", "formulas": ["Arbre binaire : chaque nœud a ≤ 2 enfants", "Hauteur h, nombre de nœuds ≤ 2^{h+1}-1"], "details": "Les arbres sont des structures hiérarchiques très utilisées en algorithmique.", "images": ["arbres.png"], "correspondances": [{"id": 501, "title": "Structures de données"}, {"id": 504, "title": "Arbres de recherche"}], "tags": ["informatique", "arbres"], "niveau": "lycee", "definition": "Un arbre est une structure de données hiérarchique où chaque élément (nœud) peut avoir plusieurs 'enfants', formant une organisation ramifiée sans boucle.", "explication_formules": "Un arbre binaire limite chaque nœud à au plus deux enfants, ce qui simplifie de nombreux algorithmes. La hauteur h d'un arbre détermine sa capacité maximale (jusqu'à 2^(h+1)-1 nœuds), un facteur clé pour l'efficacité des recherches.", "approfondissements": [{"label": "Arbres binaires de recherche", "link": {"type": "theme", "slug": "arbres-binaires-de-recherche"}}, {"label": "Arbres équilibrés (AVL, rouge-noir)", "link": {"type": "theme", "slug": "arbres-equilibres-avl-rouge-noir"}}, {"label": "Arbres et algorithmes de compression (Huffman)", "link": {"type": "theme", "slug": "arbres-et-algorithmes-de-compression-huffman"}}, {"label": "Parcours d'arbres (préfixe, infixe, suffixe)", "link": {"type": "theme", "slug": "parcours-d-arbres-prefixe-infixe-suffixe"}}, {"label": "Arbres en apprentissage automatique (arbres de décision)", "link": {"type": "theme", "slug": "arbres-en-apprentissage-automatique-arbres-de-decision"}}], "sous_points": [{"terme": "Arbres binaires", "definition": "Un arbre binaire limite chaque nœud à au plus deux enfants."}, {"terme": "AVL", "definition": "Un arbre AVL se rééquilibre automatiquement pour garantir une hauteur toujours proche du minimum théorique."}, {"terme": "Rouges-noirs", "definition": "Un arbre rouge-noir utilise un coloriage de ses nœuds pour garantir une hauteur logarithmique."}, {"terme": "Parcours (préordre, postordre)", "definition": "Ces méthodes visitent tous les nœuds d'un arbre dans un ordre précis, avant ou après leurs enfants."}], "applications_list": [{"text": "Organiser les fichiers d'un système d'exploitation.", "icon": "computer"}, {"text": "Structurer les décisions dans un jeu (échecs).", "icon": "games"}, {"text": "Indexer efficacement des bases de données.", "icon": "computer"}]}, {"id": 503, "title": "Graphes", "category": "Informatique", "formulas": ["G = (V, E)", "Parcours BFS : O(V+E)", "Parcours DFS : O(V+E)"], "details": "Les graphes modélisent des réseaux de relations entre objets.", "images": ["graphes.png"], "correspondances": [{"id": 500, "title": "Algorithmes"}, {"id": 505, "title": "Plus courts chemins"}], "tags": ["informatique", "graphes"], "niveau": "lycee", "definition": "Un graphe modélise un réseau de relations entre objets (sommets) reliés par des connexions (arêtes) — l'outil mathématique universel pour décrire réseaux et connexions.", "explication_formules": "G=(V,E) note l'ensemble des sommets V et des arêtes E. Les parcours en largeur (BFS) et en profondeur (DFS) explorent systématiquement un graphe en temps O(V+E), proportionnel à sa taille totale.", "approfondissements": [{"label": "Graphes orientés vs non orientés", "link": {"type": "theme", "slug": "graphes-orientes-vs-non-orientes"}}, {"label": "Plus courts chemins (Dijkstra, Bellman-Ford)", "link": {"type": "notion", "id": 505}}, {"label": "Arbres couvrants minimaux", "link": {"type": "theme", "slug": "arbres-couvrants-minimaux"}}, {"label": "Colorations de graphes", "link": {"type": "theme", "slug": "colorations-de-graphes"}}, {"label": "Graphes et réseaux sociaux", "link": {"type": "theme", "slug": "graphes-et-reseaux-sociaux"}}], "sous_points": [{"terme": "Graphes orientés", "definition": "Dans un graphe orienté, chaque arête a un sens précis, comme une rue à sens unique."}, {"terme": "Graphes non orientés", "definition": "Dans un graphe non orienté, les connexions entre sommets sont symétriques."}, {"terme": "Graphes pondérés", "definition": "Un graphe pondéré attribue un poids (coût, distance) à chaque arête."}, {"terme": "Cycles", "definition": "Un cycle est un chemin qui revient à son point de départ sans répéter d'arête."}], "applications_list": [{"text": "Modéliser les réseaux sociaux et leurs connexions.", "icon": "network"}, {"text": "Calculer les itinéraires les plus courts (GPS, transport).", "icon": "navigation"}, {"text": "Analyser la structure d'internet et des réseaux de communication.", "icon": "network"}]}, {"id": 504, "title": "Arbres de recherche", "category": "Informatique", "formulas": ["Recherche : O(h)", "Insertion : O(h)"], "details": "Les arbres de recherche permettent des recherches rapides.", "images": ["arbres_recherche.png"], "correspondances": [{"id": 502, "title": "Arbres"}, {"id": 510, "title": "Complexité algorithmique"}], "tags": ["informatique", "arbres-recherche"], "niveau": "lycee", "definition": "Un arbre de recherche organise des données de façon à rendre la recherche, l'insertion et la suppression très efficaces, en exploitant un ordre naturel entre les éléments.", "explication_formules": "La recherche et l'insertion s'effectuent en temps O(h), proportionnel à la hauteur h de l'arbre — d'où l'importance de garder cette hauteur petite (arbres équilibrés) pour garantir l'efficacité même avec beaucoup de données.", "approfondissements": [{"label": "Arbres AVL (auto-équilibrés)", "link": {"type": "theme", "slug": "arbres-avl-auto-equilibres"}}, {"label": "Arbres rouge-noir", "link": {"type": "theme", "slug": "arbres-rouge-noir"}}, {"label": "Arbres B (bases de données)", "link": {"type": "theme", "slug": "arbres-b-bases-de-donnees"}}, {"label": "Complexité amortie", "link": {"type": "theme", "slug": "complexite-amortie"}}, {"label": "Comparaison avec les tables de hachage", "link": {"type": "theme", "slug": "comparaison-avec-les-tables-de-hachage"}}], "sous_points": [{"terme": "BST", "definition": "Un arbre binaire de recherche (BST) organise ses valeurs de façon à rendre la recherche efficace, en temps proportionnel à sa hauteur."}, {"terme": "AVL", "definition": "Un arbre AVL est un BST qui se rééquilibre automatiquement pour garantir une hauteur logarithmique."}, {"terme": "Rouges-noirs", "definition": "Un arbre rouge-noir garantit, via un coloriage de ses nœuds, une hauteur toujours logarithmique."}, {"terme": "Équilibrage", "definition": "L'équilibrage consiste à réorganiser un arbre pour éviter qu'il devienne trop « penché », ce qui ralentirait les recherches."}], "applications_list": [{"text": "Indexer efficacement les bases de données et systèmes de fichiers.", "icon": "computer"}, {"text": "Implémenter les dictionnaires ordonnés dans les langages de programmation.", "icon": "computer"}, {"text": "Optimiser les moteurs de recherche.", "icon": "computer"}]}, {"id": 505, "title": "Plus courts chemins", "category": "Informatique", "formulas": ["Dijkstra : O((V+E) log V)", "Bellman-Ford : O(VE)"], "details": "Trouver le chemin le plus court dans un graphe pondéré.", "images": ["plus_courts_chemins.png"], "correspondances": [{"id": 503, "title": "Graphes"}, {"id": 506, "title": "Algorithmes gloutons"}], "tags": ["informatique", "chemins"], "niveau": "lycee", "definition": "Les algorithmes de plus courts chemins trouvent le trajet le moins coûteux entre deux points d'un réseau, un problème central en informatique et en logistique.", "explication_formules": "L'algorithme de Dijkstra, en O((V+E)log V), trouve le plus court chemin quand tous les coûts sont positifs. L'algorithme de Bellman-Ford, plus lent en O(VE) mais plus général, fonctionne même avec des coûts négatifs (tant qu'il n'y a pas de cycle négatif).", "approfondissements": [{"label": "Algorithme A* (avec heuristique)", "link": {"type": "theme", "slug": "algorithme-a-avec-heuristique"}}, {"label": "Floyd-Warshall (tous les plus courts chemins)", "link": {"type": "theme", "slug": "floyd-warshall-tous-les-plus-courts-chemins"}}, {"label": "Graphes avec poids négatifs", "link": {"type": "theme", "slug": "graphes-avec-poids-negatifs"}}, {"label": "Applications au routage réseau", "link": {"type": "theme", "slug": "applications-au-routage-reseau"}}, {"label": "Plus courts chemins en programmation dynamique", "link": {"type": "theme", "slug": "plus-courts-chemins-en-programmation-dynamique"}}], "sous_points": [{"terme": "Graphes pondérés", "definition": "Un graphe pondéré attribue un coût à chaque arête, utilisé pour calculer le trajet le moins coûteux."}, {"terme": "Poids négatifs", "definition": "Certains algorithmes (Dijkstra) échouent avec des poids négatifs ; il faut alors utiliser Bellman-Ford."}, {"terme": "Heuristiques", "definition": "Une heuristique estime la distance restante jusqu'à l'objectif, accélérant la recherche (algorithme A*)."}], "applications_list": [{"text": "Calculer les itinéraires GPS les plus rapides.", "icon": "navigation"}, {"text": "Optimiser le routage des paquets sur internet.", "icon": "network"}, {"text": "Planifier la logistique de livraison.", "icon": "industry"}]}, {"id": 506, "title": "Algorithmes gloutons", "category": "Informatique", "formulas": ["Choix local optimal → solution globale (si conditions)", "Ex : activité, Huffman"], "details": "Les algorithmes gloutons choisissent la meilleure option locale à chaque étape.", "images": ["gloutons.png"], "correspondances": [{"id": 505, "title": "Plus courts chemins"}, {"id": 507, "title": "Programmation dynamique"}], "tags": ["informatique", "gloutons"], "niveau": "lycee", "definition": "Un algorithme glouton construit une solution étape par étape en faisant toujours le choix qui semble le meilleur immédiatement, sans revenir en arrière — rapide, mais pas toujours optimal.", "explication_formules": "Le principe du choix local optimal ne mène à une solution globale optimale que sous certaines conditions mathématiques précises (structure matroïdale) ; sinon, le résultat peut être sous-optimal malgré des choix individuellement raisonnables.", "approfondissements": [{"label": "Codage de Huffman (compression)", "link": {"type": "theme", "slug": "codage-de-huffman-compression"}}, {"label": "Problème de l'arbre couvrant minimal (Kruskal, Prim)", "link": {"type": "theme", "slug": "probleme-de-l-arbre-couvrant-minimal-kruskal-prim"}}, {"label": "Conditions de validité (matroïdes)", "link": {"type": "theme", "slug": "conditions-de-validite-matroides"}}, {"label": "Comparaison avec la programmation dynamique", "link": {"type": "theme", "slug": "comparaison-avec-la-programmation-dynamique"}}, {"label": "Algorithmes gloutons approchés (NP-difficiles)", "link": {"type": "theme", "slug": "algorithmes-gloutons-approches-np-difficiles"}}], "sous_points": [{"terme": "Conditions d'optimalité", "definition": "Un algorithme glouton ne garantit la solution optimale que sous certaines conditions mathématiques précises (structure matroïdale)."}, {"terme": "Contre-exemples", "definition": "Il existe des problèmes où le choix glouton local ne mène pas à la solution globale optimale, contrairement à l'intuition."}], "applications_list": [{"text": "Rendre la monnaie avec un minimum de pièces.", "icon": "finance"}, {"text": "Compresser des données efficacement (codage de Huffman).", "icon": "computer"}, {"text": "Planifier un emploi du temps.", "icon": "education"}]}, {"id": 507, "title": "Programmation dynamique", "category": "Informatique", "formulas": ["DP[i] = solution optimale pour i", "Complexité typique : O(n²)"], "details": "Technique algorithmique pour résoudre des problèmes optimaux en utilisant des sous-problèmes.", "images": ["dp.png"], "correspondances": [{"id": 506, "title": "Algorithmes gloutons"}, {"id": 508, "title": "Backtracking"}], "tags": ["informatique", "dp"], "niveau": "lycee", "definition": "La programmation dynamique résout un problème complexe en le décomposant en sous-problèmes plus simples, dont on mémorise les solutions pour éviter de les recalculer plusieurs fois.", "explication_formules": "DP[i] stocke la solution optimale pour un sous-problème de taille i, construite à partir des solutions déjà calculées pour des tailles plus petites. Cette réutilisation systématique ramène souvent une complexité exponentielle à une complexité polynomiale, typiquement O(n²).", "approfondissements": [{"label": "Problème du sac à dos", "link": {"type": "theme", "slug": "probleme-du-sac-a-dos"}}, {"label": "Distance d'édition (correction orthographique)", "link": {"type": "theme", "slug": "distance-d-edition-correction-orthographique"}}, {"label": "Programmation dynamique sur des arbres/graphes", "link": {"type": "theme", "slug": "programmation-dynamique-sur-des-arbres-graphes"}}, {"label": "Mémoïsation vs tabulation", "link": {"type": "theme", "slug": "memoisation-vs-tabulation"}}, {"label": "Applications en bio-informatique", "link": {"type": "theme", "slug": "applications-en-bio-informatique"}}], "sous_points": [{"terme": "Tableaux", "definition": "La programmation dynamique stocke souvent ses résultats intermédiaires dans un tableau pour éviter de les recalculer."}, {"terme": "Mémorisation", "definition": "La mémorisation (ou mémoïsation) conserve le résultat de chaque appel récursif pour le réutiliser directement si besoin."}, {"terme": "Reconstruction de solution", "definition": "Après avoir calculé la valeur optimale, on peut retracer les choix effectués pour reconstruire la solution complète."}], "applications_list": [{"text": "Optimiser des trajets et investissements sous contraintes.", "icon": "finance"}, {"text": "Aligner des séquences génétiques en bio-informatique.", "icon": "biology"}, {"text": "Résoudre des problèmes d'optimisation combinatoire.", "icon": "computer"}]}, {"id": 508, "title": "Backtracking", "category": "Informatique", "formulas": ["Exploration exhaustive avec retour arrière", "Complexité exponentielle"], "details": "Technique d’exploration exhaustive avec retour arrière.", "images": ["backtracking.png"], "correspondances": [{"id": 507, "title": "Programmation dynamique"}, {"id": 509, "title": "Recherche exhaustive"}], "tags": ["informatique", "backtracking"], "niveau": "lycee", "definition": "Le backtracking explore systématiquement toutes les solutions possibles d'un problème, en revenant en arrière dès qu'un choix mène à une impasse — une recherche exhaustive mais intelligente.", "explication_formules": "L'exploration construit progressivement une solution candidate et abandonne (revient en arrière) dès qu'une contrainte est violée, ce qui évite d'explorer inutilement des branches condamnées. La complexité reste exponentielle dans le pire cas, mais l'élagage la réduit fortement en pratique.", "approfondissements": [{"label": "Problème des huit reines", "link": {"type": "theme", "slug": "probleme-des-huit-reines"}}, {"label": "Élagage et bornes (branch and bound)", "link": {"type": "theme", "slug": "elagage-et-bornes-branch-and-bound"}}, {"label": "Satisfaction de contraintes (CSP)", "link": {"type": "theme", "slug": "satisfaction-de-contraintes-csp"}}, {"label": "Backtracking et résolution de Sudoku", "link": {"type": "theme", "slug": "backtracking-et-resolution-de-sudoku"}}, {"label": "Comparaison avec la programmation dynamique", "link": {"type": "theme", "slug": "comparaison-avec-la-programmation-dynamique"}}], "sous_points": [{"terme": "Arbres d'états", "definition": "Le backtracking explore un arbre de toutes les configurations possibles, construites progressivement."}, {"terme": "Pruning", "definition": "Le pruning (élagage) coupe les branches de l'arbre qui ne peuvent manifestement pas mener à une solution valide."}, {"terme": "Heuristiques", "definition": "Une heuristique guide l'ordre d'exploration pour trouver plus rapidement une solution valide."}], "applications_list": [{"text": "Résoudre des sudokus et puzzles combinatoires.", "icon": "games"}, {"text": "Générer toutes les solutions d'un problème de coloriage de graphe.", "icon": "computer"}, {"text": "Fonder les solveurs de contraintes en intelligence artificielle.", "icon": "computer"}]}, {"id": 509, "title": "Recherche exhaustive", "category": "Informatique", "formulas": ["Complexité : O(k^n)", "Exploration complète de l’espace des solutions"], "details": "Exploration de toutes les solutions possibles.", "images": ["exhaustive.png"], "correspondances": [{"id": 508, "title": "Backtracking"}, {"id": 510, "title": "Complexité algorithmique"}], "tags": ["informatique", "exhaustive"], "niveau": "lycee", "definition": "La recherche exhaustive teste systématiquement toutes les solutions possibles d'un problème pour garantir de trouver la meilleure, au prix d'un temps de calcul souvent très élevé.", "explication_formules": "La complexité O(kⁿ) croît de façon exponentielle avec la taille n du problème, ce qui rend cette méthode impraticable au-delà de tailles modestes — d'où l'intérêt des algorithmes gloutons ou de programmation dynamique quand ils s'appliquent.", "approfondissements": [{"label": "Complexité exponentielle et ses limites", "link": {"type": "theme", "slug": "complexite-exponentielle-et-ses-limites"}}, {"label": "Élagage pour réduire l'espace de recherche", "link": {"type": "theme", "slug": "elagage-pour-reduire-l-espace-de-recherche"}}, {"label": "Comparaison avec les heuristiques", "link": {"type": "theme", "slug": "comparaison-avec-les-heuristiques"}}, {"label": "Recherche exhaustive et cryptographie (attaque par force brute)", "link": {"type": "theme", "slug": "recherche-exhaustive-et-cryptographie-attaque-par-force-brut"}}, {"label": "Parallélisation de la recherche exhaustive", "link": {"type": "notion", "id": 509}}], "sous_points": [{"terme": "Brute force", "definition": "La force brute teste systématiquement toutes les solutions possibles, sans aucune optimisation."}, {"terme": "Heuristiques", "definition": "Une heuristique guide la recherche vers les solutions les plus prometteuses en premier."}, {"terme": "Pruning", "definition": "Le pruning élimine précocement les branches d'exploration qui ne peuvent pas aboutir à une meilleure solution."}], "applications_list": [{"text": "Trouver la solution garantie optimale d'un petit problème combinatoire.", "icon": "research"}, {"text": "Tester la validité d'une hypothèse sur un ensemble restreint de cas.", "icon": "research"}, {"text": "Vérifier des circuits électroniques de petite taille.", "icon": "electronics"}]}, {"id": 510, "title": "Complexité algorithmique", "category": "Informatique", "formulas": ["O(1), O(log n), O(n), O(n log n), O(n²), O(2^n)", "Classes : P, NP, NP‑complet"], "details": "La complexité mesure le temps ou la mémoire nécessaires à un algorithme.", "images": ["complexite.png"], "correspondances": [{"id": 500, "title": "Algorithmes"}, {"id": 509, "title": "Recherche exhaustive"}], "tags": ["informatique", "complexite"], "niveau": "prepa", "definition": "La complexité algorithmique classifie les algorithmes selon la façon dont leur temps de calcul (ou leur mémoire) augmente avec la taille des données à traiter.", "explication_formules": "Les classes O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ) forment une hiérarchie d'efficacité croissante en difficulté. Les classes P (problèmes résolubles rapidement) et NP (problèmes dont on peut vérifier rapidement une solution) structurent la théorie de la complexité, avec la question ouverte 'P=NP ?' comme énigme centrale.", "approfondissements": [{"label": "Classes P, NP et NP-complet", "link": {"type": "theme", "slug": "classes-p-np-et-np-complet"}}, {"label": "Réductions polynomiales", "link": {"type": "theme", "slug": "reductions-polynomiales"}}, {"label": "Complexité en espace", "link": {"type": "theme", "slug": "complexite-en-espace"}}, {"label": "Complexité amortie", "link": {"type": "theme", "slug": "complexite-amortie"}}, {"label": "Problèmes NP-complets classiques (voyageur de commerce)", "link": {"type": "theme", "slug": "problemes-np-complets-classiques-voyageur-de-commerce"}}], "sous_points": [{"terme": "Complexité temporelle", "definition": "La complexité temporelle mesure le temps de calcul d'un algorithme en fonction de la taille des données."}, {"terme": "Complexité spatiale", "definition": "La complexité spatiale mesure la mémoire consommée par un algorithme en fonction de la taille des données."}, {"terme": "Classes de complexité", "definition": "Les classes de complexité (P, NP...) regroupent les problèmes selon les ressources nécessaires à leur résolution."}], "applications_list": [{"text": "Prédire si un algorithme restera utilisable sur de très grandes données.", "icon": "computer"}, {"text": "Guider le choix d'algorithme en ingénierie logicielle.", "icon": "computer"}]}, {"id": 511, "title": "Logique booléenne", "category": "Informatique", "formulas": ["ET, OU, NON", "Tables de vérité"], "details": "La logique booléenne manipule des valeurs vraies ou fausses.", "images": ["logique.png"], "correspondances": [{"id": 512, "title": "Circuits logiques"}, {"id": 513, "title": "Automates"}], "tags": ["informatique", "logique"], "niveau": "lycee", "definition": "La logique booléenne manipule des valeurs qui ne peuvent être que vraies ou fausses, combinées par des opérateurs logiques (ET, OU, NON) — le langage fondamental de tout circuit numérique.", "explication_formules": "ET (AND) est vrai seulement si les deux entrées sont vraies. OU (OR) est vrai si au moins une entrée est vraie. NON (NOT) inverse la valeur. Une table de vérité liste systématiquement le résultat pour toutes les combinaisons possibles d'entrées.", "approfondissements": [{"label": "Portes logiques et circuits", "link": {"type": "notion", "id": 512}}, {"label": "Lois de De Morgan", "link": {"type": "theme", "slug": "lois-de-de-morgan"}}, {"label": "Formes normales (conjonctive, disjonctive)", "link": {"type": "theme", "slug": "formes-normales-conjonctive-disjonctive"}}, {"label": "Simplification de circuits (tables de Karnaugh)", "link": {"type": "theme", "slug": "simplification-de-circuits-tables-de-karnaugh"}}, {"label": "Logique et algèbre de Boole", "link": {"type": "theme", "slug": "logique-et-algebre-de-boole"}}], "sous_points": [{"terme": "Opérateurs", "definition": "Les opérateurs logiques ET, OU, NON combinent des valeurs vraies ou fausses pour produire un nouveau résultat logique."}, {"terme": "Simplifications", "definition": "Simplifier une expression logique la réécrit de façon équivalente mais plus courte, réduisant le nombre d'opérations nécessaires."}, {"terme": "Lois de De Morgan", "definition": "Ces lois relient négation, ET et OU : NON(A ET B) équivaut à (NON A) OU (NON B)."}], "applications_list": [{"text": "Fonder tous les circuits électroniques numériques.", "icon": "electronics"}, {"text": "Structurer les conditions dans la programmation informatique.", "icon": "computer"}, {"text": "Concevoir des systèmes de contrôle logique.", "icon": "industry"}]}, {"id": 512, "title": "Circuits logiques", "category": "Informatique", "formulas": ["Porte AND, OR, NOT", "Porte XOR"], "details": "Les circuits logiques implémentent la logique booléenne en matériel.", "images": ["circuits.png"], "correspondances": [{"id": 511, "title": "Logique booléenne"}, {"id": 514, "title": "Architecture des ordinateurs"}], "tags": ["informatique", "circuits"], "niveau": "lycee", "definition": "Les circuits logiques implémentent physiquement (avec des transistors) les opérations de la logique booléenne, formant la base matérielle de tous les ordinateurs.", "explication_formules": "Les portes AND, OR et NOT combinent leurs sorties pour réaliser des calculs complexes. La porte XOR (ou exclusif) est vraie seulement quand les deux entrées diffèrent, une opération très utilisée en cryptographie et en détection d'erreurs.", "approfondissements": [{"label": "Additionneurs binaires", "link": {"type": "theme", "slug": "additionneurs-binaires"}}, {"label": "Bascules et mémoire (circuits séquentiels)", "link": {"type": "theme", "slug": "bascules-et-memoire-circuits-sequentiels"}}, {"label": "Circuits combinatoires vs séquentiels", "link": {"type": "theme", "slug": "circuits-combinatoires-vs-sequentiels"}}, {"label": "Conception de circuits intégrés (VLSI)", "link": {"type": "theme", "slug": "conception-de-circuits-integres-vlsi"}}, {"label": "Portes logiques et cryptographie", "link": {"type": "theme", "slug": "portes-logiques-et-cryptographie"}}], "sous_points": [{"terme": "Simplification", "definition": "Simplifier un circuit logique réduit le nombre de portes nécessaires pour réaliser la même fonction."}, {"terme": "Karnaugh", "definition": "Les tables de Karnaugh permettent de simplifier visuellement une expression logique complexe."}, {"terme": "Circuits combinatoires", "definition": "Un circuit combinatoire calcule sa sortie uniquement à partir des entrées actuelles, sans mémoire interne."}], "applications_list": [{"text": "Concevoir des processeurs et circuits intégrés.", "icon": "electronics"}, {"text": "Réaliser des additionneurs et unités de calcul dans un ordinateur.", "icon": "electronics"}, {"text": "Fonder les systèmes de chiffrement simples (XOR).", "icon": "security"}]}, {"id": 513, "title": "Automates", "category": "Informatique", "formulas": ["Automate fini : (Q, Σ, δ, q0, F)", "Langages reconnus"], "details": "Les automates modélisent des systèmes à états finis.", "images": ["automates.png"], "correspondances": [{"id": 511, "title": "Logique booléenne"}, {"id": 515, "title": "Langages formels"}], "tags": ["informatique", "automates"], "niveau": "prepa", "definition": "Un automate fini est une machine abstraite qui lit une séquence de symboles et change d'état selon des règles précises, un modèle fondamental pour reconnaître des motifs dans du texte.", "explication_formules": "Un automate se définit par (Q,Σ,δ,q0,F) : l'ensemble des états Q, l'alphabet Σ, la fonction de transition δ, l'état initial q0 et les états finaux F. Les langages reconnus par un automate fini forment exactement la classe des langages réguliers.", "approfondissements": [{"label": "Automates déterministes vs non déterministes", "link": {"type": "theme", "slug": "automates-deterministes-vs-non-deterministes"}}, {"label": "Expressions régulières et théorème de Kleene", "link": {"type": "theme", "slug": "expressions-regulieres-et-theoreme-de-kleene"}}, {"label": "Automates à pile (langages algébriques)", "link": {"type": "theme", "slug": "automates-a-pile-langages-algebriques"}}, {"label": "Minimisation d'automates", "link": {"type": "theme", "slug": "minimisation-d-automates"}}, {"label": "Applications aux compilateurs", "link": {"type": "theme", "slug": "applications-aux-compilateurs"}}], "sous_points": [{"terme": "AFD", "definition": "Un automate fini déterministe (AFD) a toujours une seule transition possible par état et symbole lu."}, {"terme": "AFN", "definition": "Un automate fini non déterministe (AFN) peut avoir plusieurs transitions possibles, bien qu'équivalent en puissance à un AFD."}, {"terme": "Expressions régulières", "definition": "Les expressions régulières décrivent exactement les langages reconnus par un automate fini (théorème de Kleene)."}], "applications_list": [{"text": "Implémenter les expressions régulières de recherche de texte.", "icon": "computer"}, {"text": "Concevoir les analyseurs lexicaux des compilateurs.", "icon": "computer"}]}, {"id": 514, "title": "Architecture des ordinateurs", "category": "Informatique", "formulas": ["CPU, RAM, ROM", "Cycle fetch-decode-execute"], "details": "L’architecture décrit l’organisation interne des ordinateurs.", "images": ["architecture.png"], "correspondances": [{"id": 512, "title": "Circuits logiques"}, {"id": 516, "title": "Systèmes d’exploitation"}], "tags": ["informatique", "architecture"], "niveau": "lycee", "definition": "L'architecture des ordinateurs décrit comment les composants matériels (processeur, mémoire) sont organisés et coopèrent pour exécuter des programmes.", "explication_formules": "Le CPU (processeur), la RAM (mémoire vive) et la ROM (mémoire morte) jouent des rôles complémentaires. Le cycle fetch-decode-execute (chercher-décoder-exécuter) décrit la boucle fondamentale répétée en permanence par le processeur pour exécuter chaque instruction.", "approfondissements": [{"label": "Hiérarchie mémoire (cache, RAM, disque)", "link": {"type": "theme", "slug": "hierarchie-memoire-cache-ram-disque"}}, {"label": "Pipeline d'exécution", "link": {"type": "theme", "slug": "pipeline-d-execution"}}, {"label": "Architecture RISC vs CISC", "link": {"type": "theme", "slug": "architecture-risc-vs-cisc"}}, {"label": "Parallélisme et multi-cœurs", "link": {"type": "theme", "slug": "parallelisme-et-multi-c-urs"}}, {"label": "Architecture des GPU (calcul parallèle)", "link": {"type": "theme", "slug": "architecture-des-gpu-calcul-parallele"}}], "sous_points": [{"terme": "Registres", "definition": "Les registres sont de petites mémoires ultra-rapides intégrées au processeur, stockant les données en cours de traitement."}, {"terme": "ALU", "definition": "L'unité arithmétique et logique (ALU) effectue les calculs et les opérations logiques du processeur."}, {"terme": "Mémoire", "definition": "La mémoire stocke les données et instructions, organisée en plusieurs niveaux (cache, RAM, disque) selon vitesse et capacité."}, {"terme": "Bus", "definition": "Le bus est le circuit qui transporte les données entre les différents composants de l'ordinateur."}], "applications_list": [{"text": "Comprendre pourquoi certains programmes sont plus rapides que d'autres.", "icon": "computer"}, {"text": "Concevoir des systèmes embarqués efficaces.", "icon": "electronics"}, {"text": "Choisir le matériel adapté à une tâche informatique.", "icon": "computer"}]}, {"id": 515, "title": "Langages formels", "category": "Informatique", "formulas": ["Grammaire : (V, Σ, R, S)", "Langages réguliers, context-free"], "details": "Les langages formels décrivent des ensembles de chaînes.", "images": ["langages.png"], "correspondances": [{"id": 513, "title": "Automates"}, {"id": 517, "title": "Compilation"}], "tags": ["informatique", "langages"], "niveau": "prepa", "definition": "Les langages formels étudient de façon rigoureuse la structure des langages (informatiques ou mathématiques) via des grammaires qui définissent précisément quelles séquences de symboles sont valides.", "explication_formules": "Une grammaire (V,Σ,R,S) définit les règles de production permettant de construire toute phrase valide du langage à partir d'un symbole de départ S. Les langages réguliers (les plus simples) sont reconnus par des automates finis ; les langages context-free nécessitent des automates à pile.", "approfondissements": [{"label": "Hiérarchie de Chomsky", "link": {"type": "theme", "slug": "hierarchie-de-chomsky"}}, {"label": "Grammaires context-free et automates à pile", "link": {"type": "theme", "slug": "grammaires-context-free-et-automates-a-pile"}}, {"label": "Analyse syntaxique (parsing)", "link": {"type": "theme", "slug": "analyse-syntaxique-parsing"}}, {"label": "Langages récursivement énumérables", "link": {"type": "theme", "slug": "langages-recursivement-enumerables"}}, {"label": "Applications aux compilateurs et au NLP", "link": {"type": "theme", "slug": "applications-aux-compilateurs-et-au-nlp"}}], "sous_points": [{"terme": "Grammaires", "definition": "Une grammaire formelle définit les règles permettant de construire toute phrase valide d'un langage."}, {"terme": "Automates", "definition": "Les automates reconnaissent les langages définis par une grammaire, chaque niveau de complexité nécessitant un automate plus puissant."}, {"terme": "Hiérarchie de Chomsky", "definition": "Cette hiérarchie classe les langages formels en quatre niveaux de complexité croissante, selon le type de grammaire nécessaire."}], "applications_list": [{"text": "Concevoir les compilateurs et interpréteurs de langages de programmation.", "icon": "computer"}, {"text": "Définir la syntaxe des formats de données (JSON, XML).", "icon": "computer"}, {"text": "Fonder l'analyse du langage naturel.", "icon": "communication"}]}, {"id": 516, "title": "Systèmes d’exploitation", "category": "Informatique", "formulas": ["Processus, threads", "Mémoire virtuelle"], "details": "Les systèmes d’exploitation gèrent les ressources matérielles.", "images": ["os.png"], "correspondances": [{"id": 514, "title": "Architecture des ordinateurs"}, {"id": 518, "title": "Réseaux"}], "tags": ["informatique", "os"], "niveau": "lycee", "definition": "Un système d'exploitation gère les ressources matérielles d'un ordinateur (processeur, mémoire) et permet à plusieurs programmes de s'exécuter en semblant se partager ces ressources simultanément.", "explication_formules": "Un processus est un programme en cours d'exécution avec ses propres ressources ; un thread est une unité d'exécution plus légère au sein d'un même processus. La mémoire virtuelle donne à chaque programme l'illusion de disposer de toute la mémoire, gérée en réalité par le système d'exploitation.", "approfondissements": [{"label": "Ordonnancement des processus", "link": {"type": "theme", "slug": "ordonnancement-des-processus"}}, {"label": "Gestion de la mémoire virtuelle", "link": {"type": "theme", "slug": "gestion-de-la-memoire-virtuelle"}}, {"label": "Synchronisation et interblocage (deadlock)", "link": {"type": "theme", "slug": "synchronisation-et-interblocage-deadlock"}}, {"label": "Systèmes de fichiers", "link": {"type": "theme", "slug": "systemes-de-fichiers"}}, {"label": "Virtualisation et conteneurs", "link": {"type": "theme", "slug": "virtualisation-et-conteneurs"}}], "sous_points": [{"terme": "Planification", "definition": "La planification (ordonnancement) décide quel processus obtient l'accès au processeur à chaque instant."}, {"terme": "Synchronisation", "definition": "La synchronisation coordonne plusieurs processus qui partagent des ressources communes, évitant les conflits."}, {"terme": "Fichiers", "definition": "Le système d'exploitation gère l'organisation et l'accès aux fichiers stockés sur le disque."}], "applications_list": [{"text": "Exécuter plusieurs applications simultanément sur un ordinateur.", "icon": "computer"}, {"text": "Optimiser la gestion des ressources dans les systèmes embarqués.", "icon": "electronics"}, {"text": "Fonder la sécurité informatique (isolation des processus).", "icon": "security"}]}, {"id": 517, "title": "Compilation", "category": "Informatique", "formulas": ["Analyse lexicale → syntaxique → sémantique", "Génération de code"], "details": "La compilation traduit un langage source en langage machine.", "images": ["compilation.png"], "correspondances": [{"id": 515, "title": "Langages formels"}, {"id": 514, "title": "Architecture des ordinateurs"}], "tags": ["informatique", "compilation"], "niveau": "grandes-ecoles", "definition": "La compilation transforme un programme écrit dans un langage compréhensible par l'humain en instructions exécutables directement par le processeur, en plusieurs étapes rigoureuses.", "explication_formules": "L'analyse lexicale découpe le code source en unités élémentaires (tokens). L'analyse syntaxique vérifie que ces unités respectent la grammaire du langage. L'analyse sémantique vérifie la cohérence logique (types, portées de variables) avant de générer le code machine final.", "approfondissements": [{"label": "Arbre syntaxique abstrait (AST)", "link": {"type": "theme", "slug": "arbre-syntaxique-abstrait-ast"}}, {"label": "Optimisation de code", "link": {"type": "theme", "slug": "optimisation-de-code"}}, {"label": "Génération de code intermédiaire", "link": {"type": "theme", "slug": "generation-de-code-intermediaire"}}, {"label": "Compilation vs interprétation", "link": {"type": "theme", "slug": "compilation-vs-interpretation"}}, {"label": "Compilateurs Just-In-Time (JIT)", "link": {"type": "theme", "slug": "compilateurs-just-in-time-jit"}}], "sous_points": [{"terme": "Analyse", "definition": "L'analyse (lexicale, syntaxique) vérifie que le code source respecte la grammaire du langage de programmation."}, {"terme": "Optimisation", "definition": "L'optimisation réorganise le code généré pour qu'il s'exécute plus rapidement ou consomme moins de mémoire."}, {"terme": "Génération", "definition": "La génération de code traduit la représentation intermédiaire du programme en instructions machine exécutables."}], "applications_list": [{"text": "Fonder tous les langages de programmation compilés.", "icon": "computer"}, {"text": "Optimiser automatiquement le code pour l'exécution.", "icon": "computer"}, {"text": "Détecter des erreurs de programmation avant l'exécution.", "icon": "computer"}]}, {"id": 518, "title": "Réseaux", "category": "Informatique", "formulas": ["TCP/IP", "Modèle OSI"], "details": "Les réseaux permettent la communication entre machines.", "images": ["reseaux.png"], "correspondances": [{"id": 516, "title": "Systèmes d’exploitation"}, {"id": 519, "title": "Sécurité informatique"}], "tags": ["informatique", "reseaux"], "niveau": "lycee", "definition": "Les réseaux informatiques permettent à des ordinateurs distants de communiquer entre eux selon des protocoles standardisés, formant l'infrastructure d'internet et des réseaux locaux.", "explication_formules": "TCP/IP est la suite de protocoles fondamentale d'internet : IP achemine les paquets de données, TCP garantit leur livraison fiable et ordonnée. Le modèle OSI décompose la communication réseau en sept couches, chacune responsable d'un aspect spécifique (physique, transport, application...).", "approfondissements": [{"label": "Protocole IP et routage", "link": {"type": "theme", "slug": "protocole-ip-et-routage"}}, {"label": "Protocoles applicatifs (HTTP, DNS)", "link": {"type": "theme", "slug": "protocoles-applicatifs-http-dns"}}, {"label": "Sécurité réseau (pare-feu, VPN)", "link": {"type": "theme", "slug": "securite-reseau-pare-feu-vpn"}}, {"label": "Réseaux sans fil (WiFi, réseaux mobiles)", "link": {"type": "theme", "slug": "reseaux-sans-fil-wifi-reseaux-mobiles"}}, {"label": "Architecture d'internet et data centers", "link": {"type": "theme", "slug": "architecture-d-internet-et-data-centers"}}], "sous_points": [{"terme": "Protocoles", "definition": "Un protocole réseau définit les règles précises de communication entre ordinateurs (comme TCP/IP ou HTTP)."}, {"terme": "Routage", "definition": "Le routage détermine le chemin que doivent suivre les paquets de données à travers le réseau."}, {"terme": "Adresses IP", "definition": "Une adresse IP identifie de façon unique chaque appareil connecté à un réseau."}], "applications_list": [{"text": "Fonder toute la communication sur internet.", "icon": "network"}, {"text": "Concevoir des réseaux d'entreprise sécurisés.", "icon": "network"}, {"text": "Diagnostiquer des problèmes de connectivité.", "icon": "network"}]}, {"id": 519, "title": "Sécurité informatique", "category": "Informatique", "formulas": ["Chiffrement symétrique / asymétrique", "Hash : H(x)"], "details": "La sécurité informatique protège les données et les systèmes.", "images": ["securite.png"], "correspondances": [{"id": 518, "title": "Réseaux"}, {"id": 520, "title": "Cryptographie avancée"}], "tags": ["informatique", "securite"], "niveau": "lycee", "definition": "La sécurité informatique protège les systèmes et les données contre les accès non autorisés, en combinant chiffrement, authentification et détection des menaces.", "explication_formules": "Le chiffrement symétrique utilise la même clé pour chiffrer et déchiffrer (rapide mais nécessite un échange sécurisé de clé). Le chiffrement asymétrique utilise une paire de clés publique/privée. Une fonction de hachage H(x) transforme des données en une empreinte de taille fixe, utilisée pour vérifier l'intégrité sans révéler le contenu original.", "approfondissements": [{"label": "Chiffrement asymétrique (RSA)", "link": {"type": "theme", "slug": "chiffrement-asymetrique-rsa"}}, {"label": "Fonctions de hachage cryptographiques", "link": {"type": "theme", "slug": "fonctions-de-hachage-cryptographiques"}}, {"label": "Authentification multi-facteurs", "link": {"type": "theme", "slug": "authentification-multi-facteurs"}}, {"label": "Attaques par force brute et par dictionnaire", "link": {"type": "theme", "slug": "attaques-par-force-brute-et-par-dictionnaire"}}, {"label": "Sécurité des réseaux (pare-feu, détection d'intrusion)", "link": {"type": "theme", "slug": "securite-des-reseaux-pare-feu-detection-d-intrusion"}}], "sous_points": [{"terme": "Chiffrement", "definition": "Le chiffrement rend un message illisible sans la clé appropriée, protégeant sa confidentialité."}, {"terme": "Authentification", "definition": "L'authentification vérifie l'identité d'un utilisateur ou d'un système avant de lui accorder un accès."}, {"terme": "Intégrité", "definition": "L'intégrité garantit qu'un message n'a pas été modifié entre son envoi et sa réception."}], "applications_list": [{"text": "Sécuriser les mots de passe stockés.", "icon": "security"}, {"text": "Protéger les transactions bancaires en ligne.", "icon": "finance"}, {"text": "Détecter les intrusions dans les systèmes d'entreprise.", "icon": "security"}]}, {"id": 520, "title": "Cryptographie avancée", "category": "Informatique", "formulas": ["RSA : c = m^e mod n", "Diffie-Hellman"], "details": "La cryptographie avancée repose sur l’algèbre et la théorie des nombres.", "images": ["crypto_avancee.png"], "correspondances": [{"id": 519, "title": "Sécurité informatique"}, {"id": 113, "title": "Arithmétique modulaire"}], "tags": ["informatique", "crypto"], "niveau": "grandes-ecoles", "definition": "La cryptographie avancée en informatique développe les protocoles concrets (chiffrement, échange de clés) qui sécurisent les communications numériques modernes.", "explication_formules": "RSA c=mᵉ mod n repose sur la difficulté extrême de factoriser un grand nombre n produit de deux nombres premiers. Le protocole Diffie-Hellman permet à deux parties de construire une clé secrète commune en échangeant seulement des informations publiques, sans jamais transmettre la clé elle-même.", "approfondissements": [{"label": "Cryptographie sur courbes elliptiques", "link": {"type": "theme", "slug": "cryptographie-sur-courbes-elliptiques"}}, {"label": "Signatures numériques", "link": {"type": "theme", "slug": "signatures-numeriques"}}, {"label": "Infrastructure à clés publiques (PKI)", "link": {"type": "theme", "slug": "infrastructure-a-cles-publiques-pki"}}, {"label": "Cryptographie post-quantique", "link": {"type": "theme", "slug": "cryptographie-post-quantique"}}, {"label": "Protocoles d'échange de clés modernes", "link": {"type": "theme", "slug": "protocoles-d-echange-de-cles-modernes"}}], "sous_points": [{"terme": "Exponentiation modulaire", "definition": "Cette opération calcule efficacement aᵏ mod n, brique de base des calculs cryptographiques comme RSA."}, {"terme": "Signatures", "definition": "Une signature numérique prouve mathématiquement qu'un message provient bien d'un émetteur donné et n'a pas été altéré."}, {"terme": "Courbes elliptiques", "definition": "Les courbes elliptiques offrent une sécurité cryptographique élevée avec des clés bien plus courtes que RSA."}], "applications_list": [{"text": "Sécuriser les connexions HTTPS de tous les sites web.", "icon": "security"}, {"text": "Protéger les communications chiffrées de bout en bout.", "icon": "security"}, {"text": "Fonder la sécurité des cryptomonnaies.", "icon": "finance"}]}, {"id": 600, "title": "Inégalités classiques", "category": "Olympiades", "formulas": ["AM ≥ GM", "Cauchy-Schwarz : (Σ a_i b_i)² ≤ (Σ a_i²)(Σ b_i²)", "Jensen : f(convex) → f(E[X]) ≤ E[f(X)]"], "details": "Les inégalités sont au cœur des problèmes olympiques : optimisation, encadrements, preuves élégantes.", "images": ["inegalites.png"], "correspondances": [{"id": 601, "title": "Optimisation"}, {"id": 602, "title": "Techniques de factorisation"}], "tags": ["olympiades", "inegalites"], "niveau": "lycee", "definition": "Les inégalités classiques sont des outils incontournables des olympiades mathématiques, permettant de comparer des quantités et de prouver des bornes sans calcul explicite.", "explication_formules": "AM-GM dit que la moyenne arithmétique est toujours supérieure ou égale à la moyenne géométrique, avec égalité seulement si tous les termes sont égaux. L'inégalité de Cauchy-Schwarz borne un produit de sommes par le produit de sommes de carrés — un outil extrêmement polyvalent.", "approfondissements": [{"label": "Inégalité de réarrangement", "link": {"type": "theme", "slug": "inegalite-de-rearrangement"}}, {"label": "Inégalité de Schur", "link": {"type": "theme", "slug": "inegalite-de-schur"}}, {"label": "Inégalité de Jensen (convexité)", "link": {"type": "theme", "slug": "inegalite-de-jensen-convexite"}}, {"label": "Méthode SOS (somme de carrés)", "link": {"type": "theme", "slug": "methode-sos-somme-de-carres"}}, {"label": "Inégalités à plusieurs variables symétriques", "link": {"type": "theme", "slug": "inegalites-a-plusieurs-variables-symetriques"}}], "sous_points": [{"terme": "AM-GM", "definition": "L'inégalité entre moyenne arithmétique et géométrique dit que (a+b)/2 ≥ √(ab), avec égalité seulement si a=b."}, {"terme": "Cauchy-Schwarz", "definition": "Cette inégalité borne un produit de sommes par le produit de sommes de carrés."}, {"terme": "Hölder", "definition": "Cette inégalité généralise Cauchy-Schwarz à des puissances quelconques plutôt que seulement au carré."}, {"terme": "Minkowski", "definition": "Cette inégalité borne la norme d'une somme de vecteurs par la somme de leurs normes."}, {"terme": "Jensen", "definition": "Cette inégalité dit que l'image de la moyenne par une fonction convexe est inférieure ou égale à la moyenne des images."}], "applications_list": [{"text": "Résoudre des problèmes d'optimisation sans calcul différentiel.", "icon": "education"}, {"text": "Démontrer des résultats géométriques ou algébriques en compétition.", "icon": "education"}]}, {"id": 601, "title": "Optimisation", "category": "Olympiades", "formulas": ["AM-GM pour minimiser", "Symétrisation", "Méthode des extremums"], "details": "L’optimisation consiste à trouver le maximum ou le minimum d’une expression.", "images": ["optimisation.png"], "correspondances": [{"id": 600, "title": "Inégalités classiques"}, {"id": 603, "title": "Équations fonctionnelles"}], "tags": ["olympiades", "optimisation"], "niveau": "lycee", "definition": "L'optimisation en olympiades cherche à trouver la valeur maximale ou minimale d'une expression sous contraintes, généralement sans recourir au calcul différentiel classique.", "explication_formules": "AM-GM appliquée intelligemment transforme souvent un problème d'optimisation en une simple vérification d'égalité. La symétrisation exploite la symétrie d'un problème pour deviner que l'extremum est atteint quand toutes les variables sont égales.", "approfondissements": [{"label": "Méthode des multiplicateurs de Lagrange (approche avancée)", "link": {"type": "theme", "slug": "methode-des-multiplicateurs-de-lagrange-approche-avancee"}}, {"label": "Optimisation par substitution", "link": {"type": "theme", "slug": "optimisation-par-substitution"}}, {"label": "Cas d'égalité et leur interprétation", "link": {"type": "theme", "slug": "cas-d-egalite-et-leur-interpretation"}}, {"label": "Optimisation géométrique (aires, périmètres)", "link": {"type": "theme", "slug": "optimisation-geometrique-aires-perimetres"}}, {"label": "Lien avec la convexité", "link": {"type": "theme", "slug": "lien-avec-la-convexite"}}], "sous_points": [{"terme": "Symétrisation", "definition": "La symétrisation exploite la symétrie d'un problème pour deviner que l'extremum est atteint quand toutes les variables sont égales."}, {"terme": "Substitution intelligente", "definition": "Remplacer une expression complexe par une nouvelle variable révèle parfois une structure d'optimisation cachée."}, {"terme": "Convexité", "definition": "La convexité d'une fonction garantit l'existence et l'unicité d'un minimum global, simplifiant sa recherche."}], "applications_list": [{"text": "Résoudre des problèmes de compétition impliquant des contraintes algébriques.", "icon": "education"}, {"text": "Développer l'intuition pour l'optimisation en analyse et économie.", "icon": "finance"}]}, {"id": 602, "title": "Techniques de factorisation", "category": "Olympiades", "formulas": ["a³ + b³ + c³ - 3abc = (a+b+c)(a²+b²+c² - ab - bc - ca)", "a² + b² ≥ 2ab"], "details": "Les factorisations permettent de simplifier des expressions complexes.", "images": ["factorisation.png"], "correspondances": [{"id": 600, "title": "Inégalités classiques"}, {"id": 604, "title": "Symétries et invariants"}], "tags": ["olympiades", "factorisation"], "niveau": "lycee", "definition": "Les techniques de factorisation transforment une expression algébrique complexe en un produit de facteurs plus simples, révélant souvent une structure cachée essentielle pour résoudre un problème.", "explication_formules": "a³+b³+c³-3abc=(a+b+c)(a²+b²+c²-ab-bc-ca) est une identité remarquable très utilisée qui relie une somme de cubes à un produit, révélant immédiatement quand l'expression s'annule (a+b+c=0).", "approfondissements": [{"label": "Identités remarquables avancées", "link": {"type": "theme", "slug": "identites-remarquables-avancees"}}, {"label": "Factorisation par substitution", "link": {"type": "theme", "slug": "factorisation-par-substitution"}}, {"label": "Polynômes symétriques", "link": {"type": "theme", "slug": "polynomes-symetriques"}}, {"label": "Factorisation et divisibilité", "link": {"type": "theme", "slug": "factorisation-et-divisibilite"}}, {"label": "Utilisation des racines de l'unité", "link": {"type": "theme", "slug": "utilisation-des-racines-de-l-unite"}}], "sous_points": [{"terme": "Identités remarquables", "definition": "Ces formules comme (a+b)²=a²+2ab+b² permettent de développer ou factoriser rapidement des expressions courantes."}, {"terme": "Factorisations symétriques", "definition": "Certaines expressions symétriques en plusieurs variables se factorisent élégamment, révélant leur structure profonde."}], "applications_list": [{"text": "Résoudre des équations et prouver des identités en compétition.", "icon": "education"}, {"text": "Simplifier des expressions pour révéler une propriété cachée.", "icon": "research"}]}, {"id": 603, "title": "Équations fonctionnelles", "category": "Olympiades", "formulas": ["f(x+y)=f(x)+f(y)", "f(xy)=f(x)f(y)"], "details": "Les équations fonctionnelles sont fréquentes dans les concours.", "images": ["equations_fonctionnelles.png"], "correspondances": [{"id": 601, "title": "Optimisation"}, {"id": 605, "title": "Récurrences"}], "tags": ["olympiades", "equations-fonctionnelles"], "niveau": "prepa", "definition": "Une équation fonctionnelle impose une relation que doit vérifier une fonction inconnue pour toutes les valeurs possibles de ses variables, un grand classique des olympiades mathématiques.", "explication_formules": "f(x+y)=f(x)+f(y) (équation de Cauchy) caractérise, sous des hypothèses de régularité, exactement les fonctions linéaires f(x)=cx. f(xy)=f(x)f(y) caractérise, elle, les fonctions exponentielles ou puissances selon le contexte.", "approfondissements": [{"label": "Substitutions astucieuses (x=y=0, x=y)", "link": {"type": "theme", "slug": "substitutions-astucieuses-x-y-0-x-y"}}, {"label": "Équations fonctionnelles sur ℕ, ℤ, ℝ", "link": {"type": "notion", "id": 603}}, {"label": "Équations fonctionnelles multiplicatives", "link": {"type": "notion", "id": 603}}, {"label": "Points fixes de fonctions", "link": {"type": "theme", "slug": "points-fixes-de-fonctions"}}, {"label": "Régularité et hypothèses de continuité", "link": {"type": "theme", "slug": "regularite-et-hypotheses-de-continuite"}}], "sous_points": [{"terme": "Additivité", "definition": "Une fonction additive vérifie f(x+y)=f(x)+f(y) pour toutes valeurs de x et y."}, {"terme": "Multiplicativité", "definition": "Une fonction multiplicative vérifie f(xy)=f(x)f(y) pour toutes valeurs de x et y."}, {"terme": "Symétries", "definition": "Étudier les symétries d'une équation fonctionnelle (échanger x et y, par exemple) révèle souvent des contraintes supplémentaires sur f."}], "applications_list": [{"text": "Résoudre des problèmes de compétition de type « trouver toutes les fonctions vérifiant... ».", "icon": "education"}, {"text": "Développer l'intuition pour l'analyse fonctionnelle universitaire.", "icon": "research"}]}, {"id": 604, "title": "Symétries et invariants", "category": "Olympiades", "formulas": ["Invariant = quantité conservée", "Symétrie → réduction du problème"], "details": "Les invariants permettent de résoudre des problèmes complexes en identifiant ce qui ne change pas.", "images": ["invariants.png"], "correspondances": [{"id": 602, "title": "Techniques de factorisation"}, {"id": 606, "title": "Combinatoire avancée"}], "tags": ["olympiades", "invariants"], "niveau": "prepa", "definition": "Un invariant est une quantité qui reste inchangée au cours d'une transformation répétée d'un problème, un outil puissant pour prouver qu'un état final est impossible ou nécessaire.", "explication_formules": "Un invariant identifie une quantité (parité, somme, couleur) qui ne change jamais, quelle que soit l'opération effectuée. Un monovariant, variante affaiblie, évolue toujours dans le même sens (par exemple ne peut que décroître), ce qui garantit qu'un processus se termine.", "approfondissements": [{"label": "Monovariants et terminaison de processus", "link": {"type": "theme", "slug": "monovariants-et-terminaison-de-processus"}}, {"label": "Invariants de parité", "link": {"type": "theme", "slug": "invariants-de-parite"}}, {"label": "Invariants modulo n", "link": {"type": "theme", "slug": "invariants-modulo-n"}}, {"label": "Invariants en théorie des jeux", "link": {"type": "theme", "slug": "invariants-en-theorie-des-jeux"}}, {"label": "Symétries comme source d'invariants", "link": {"type": "theme", "slug": "symetries-comme-source-d-invariants"}}], "sous_points": [{"terme": "Invariants additifs", "definition": "Un invariant additif est une somme qui reste constante malgré les transformations autorisées d'un problème."}, {"terme": "Invariants multiplicatifs", "definition": "Un invariant multiplicatif est un produit (ou un rapport) qui reste constant malgré les transformations."}, {"terme": "Symétries géométriques", "definition": "Les symétries géométriques d'une figure produisent souvent des invariants naturels exploitables dans une démonstration."}], "applications_list": [{"text": "Prouver l'impossibilité de certaines configurations dans des jeux et puzzles.", "icon": "games"}, {"text": "Démontrer qu'un algorithme ou processus itératif se termine.", "icon": "computer"}]}, {"id": 605, "title": "Récurrences", "category": "Olympiades", "formulas": ["u_{n+1} = f(u_n)", "Méthode de descente infinie"], "details": "Les récursions et récurrences sont omniprésentes dans les problèmes olympiques.", "images": ["recurrence.png"], "correspondances": [{"id": 603, "title": "Équations fonctionnelles"}, {"id": 606, "title": "Combinatoire avancée"}], "tags": ["olympiades", "recurrence"], "niveau": "lycee", "definition": "Une suite récurrente définit chaque terme à partir du ou des termes précédents, ce qui permet de construire des séquences complexes à partir de règles simples et locales.", "explication_formules": "uₙ₊₁=f(uₙ) génère toute la suite à partir d'un terme initial et d'une règle f. La méthode de descente infinie prouve qu'aucune solution entière positive n'existe en montrant que toute solution supposée en engendrerait une plus petite, ce qui est impossible indéfiniment.", "approfondissements": [{"label": "Suites arithmético-géométriques", "link": {"type": "theme", "slug": "suites-arithmetico-geometriques"}}, {"label": "Points fixes et convergence", "link": {"type": "theme", "slug": "points-fixes-et-convergence"}}, {"label": "Descente infinie de Fermat", "link": {"type": "theme", "slug": "descente-infinie-de-fermat"}}, {"label": "Suites récurrentes linéaires d'ordre 2", "link": {"type": "theme", "slug": "suites-recurrentes-lineaires-d-ordre-2"}}, {"label": "Suites et fractions continues", "link": {"type": "theme", "slug": "suites-et-fractions-continues"}}], "sous_points": [{"terme": "Récurrences linéaires", "definition": "Une récurrence linéaire exprime chaque terme comme combinaison linéaire des précédents, comme uₙ₊₂=uₙ₊₁+uₙ (Fibonacci)."}, {"terme": "Récurrences non linéaires", "definition": "Une récurrence non linéaire implique des produits ou puissances des termes précédents, généralement plus difficile à résoudre explicitement."}, {"terme": "Descente infinie", "definition": "Cette méthode prouve l'absence de solution en montrant qu'une solution en engendrerait toujours une strictement plus petite."}], "applications_list": [{"text": "Modéliser des phénomènes qui évoluent étape par étape.", "icon": "finance"}, {"text": "Résoudre des problèmes de compétition sur les suites récurrentes.", "icon": "education"}]}, {"id": 606, "title": "Combinatoire avancée", "category": "Olympiades", "formulas": ["C(n,k) = n! / (k!(n-k)!)", "Principe des tiroirs", "Inclusion-exclusion"], "details": "La combinatoire est essentielle dans les concours mathématiques.", "images": ["combinatoire.png"], "correspondances": [{"id": 605, "title": "Récurrences"}, {"id": 607, "title": "Graphes olympiques"}], "tags": ["olympiades", "combinatoire"], "niveau": "prepa", "definition": "La combinatoire avancée développe des techniques sophistiquées de dénombrement pour compter des configurations complexes, souvent en évitant un comptage direct trop difficile.", "explication_formules": "Le principe des tiroirs (Dirichlet) garantit que si l'on range plus d'objets que de tiroirs, au moins un tiroir contient plusieurs objets — un principe simple mais extrêmement puissant. L'inclusion-exclusion permet de compter des unions d'ensembles en évitant de compter deux fois les intersections.", "approfondissements": [{"label": "Principe des tiroirs généralisé", "link": {"type": "theme", "slug": "principe-des-tiroirs-generalise"}}, {"label": "Inclusion-exclusion avancée", "link": {"type": "theme", "slug": "inclusion-exclusion-avancee"}}, {"label": "Double comptage", "link": {"type": "theme", "slug": "double-comptage"}}, {"label": "Bijections combinatoires", "link": {"type": "theme", "slug": "bijections-combinatoires"}}, {"label": "Combinatoire et théorie des graphes", "link": {"type": "theme", "slug": "combinatoire-et-theorie-des-graphes"}}], "sous_points": [{"terme": "Comptage", "definition": "Le comptage combinatoire dénombre systématiquement les configurations possibles d'un problème donné."}, {"terme": "Arrangements", "definition": "Un arrangement ordonne k objets choisis parmi n, en tenant compte de l'ordre."}, {"terme": "Partitions", "definition": "Une partition découpe un ensemble ou un entier en parties, sans tenir compte de l'ordre."}, {"terme": "Bijections", "definition": "Une preuve bijective compte un ensemble en le mettant en correspondance exacte avec un autre ensemble de taille connue."}], "applications_list": [{"text": "Résoudre des problèmes de dénombrement complexes en compétition.", "icon": "education"}, {"text": "Prouver l'existence de configurations par le principe des tiroirs.", "icon": "research"}]}, {"id": 607, "title": "Graphes olympiques", "category": "Olympiades", "formulas": ["Connexité", "Cycles", "Colorations"], "details": "Les graphes apparaissent dans de nombreux problèmes olympiques.", "images": ["graphes_olympiques.png"], "correspondances": [{"id": 606, "title": "Combinatoire avancée"}, {"id": 608, "title": "Théorie des nombres olympique"}], "tags": ["olympiades", "graphes"], "niveau": "prepa", "definition": "Cette notion applique la théorie des graphes à la résolution de problèmes de compétition mathématique, en modélisant des situations concrètes par des sommets et des arêtes.", "explication_formules": "La connexité détermine si l'on peut relier tous les sommets d'un graphe par des chemins. Un cycle est un chemin fermé qui revient à son point de départ. Une coloration attribue des couleurs aux sommets ou arêtes selon des contraintes précises (deux sommets voisins ne peuvent partager la même couleur, par exemple).", "approfondissements": [{"label": "Lemme des poignées de main", "link": {"type": "theme", "slug": "lemme-des-poignees-de-main"}}, {"label": "Théorème de Ramsey (cas simples)", "link": {"type": "theme", "slug": "theoreme-de-ramsey-cas-simples"}}, {"label": "Tournois et graphes orientés", "link": {"type": "theme", "slug": "tournois-et-graphes-orientes"}}, {"label": "Graphes bipartis", "link": {"type": "theme", "slug": "graphes-bipartis"}}, {"label": "Coloration de graphes en compétition", "link": {"type": "theme", "slug": "coloration-de-graphes-en-competition"}}], "sous_points": [{"terme": "Colorations", "definition": "Colorier les sommets d'un graphe sous contrainte révèle souvent des propriétés structurelles utiles à la résolution."}, {"terme": "Chemins", "definition": "Un chemin dans un graphe est une suite de sommets reliés par des arêtes successives."}, {"terme": "Arbres", "definition": "Un arbre est un graphe connexe sans cycle, la structure la plus « économe » en arêtes pour relier tous les sommets."}, {"terme": "Invariants", "definition": "Un invariant de graphe (comme la parité des degrés) reste constant et permet de prouver des impossibilités."}], "applications_list": [{"text": "Résoudre des problèmes de compétition impliquant des relations entre objets.", "icon": "education"}, {"text": "Développer l'intuition pour la théorie des graphes en informatique.", "icon": "computer"}]}, {"id": 608, "title": "Théorie des nombres olympique", "category": "Olympiades", "formulas": ["a ≡ b (mod n)", "PGCD, PPCM", "Petit théorème de Fermat"], "details": "La théorie des nombres est un pilier des olympiades.", "images": ["theorie_nombres.png"], "correspondances": [{"id": 609, "title": "Équations diophantiennes"}, {"id": 113, "title": "Arithmétique modulaire"}], "tags": ["olympiades", "nombres"], "niveau": "prepa", "definition": "La théorie des nombres olympique regroupe les techniques arithmétiques essentielles (congruences, divisibilité) pour résoudre les problèmes de théorie des nombres en compétition.", "explication_formules": "a≡b (mod n) permet de raisonner 'en cycle' sur les restes plutôt que sur les nombres entiers eux-mêmes, simplifiant énormément certains problèmes. Le petit théorème de Fermat (a^p≡a mod p) fournit un outil puissant pour analyser la divisibilité par un nombre premier.", "approfondissements": [{"label": "Ordre multiplicatif modulo n", "link": {"type": "theme", "slug": "ordre-multiplicatif-modulo-n"}}, {"label": "Résidus quadratiques", "link": {"type": "theme", "slug": "residus-quadratiques"}}, {"label": "Lifting the Exponent (LTE)", "link": {"type": "theme", "slug": "lifting-the-exponent-lte"}}, {"label": "Théorème chinois des restes en compétition", "link": {"type": "theme", "slug": "theoreme-chinois-des-restes-en-competition"}}, {"label": "Équations diophantiennes classiques", "link": {"type": "notion", "id": 609}}], "sous_points": [{"terme": "Congruences", "definition": "Une congruence a≡b (mod n) exprime que a et b ont le même reste dans la division par n."}, {"terme": "Divisibilité", "definition": "L'étude de la divisibilité examine quand un nombre en divise un autre exactement, sans reste."}, {"terme": "Équations diophantiennes", "definition": "Une équation diophantienne est une équation dont on cherche uniquement les solutions entières."}], "applications_list": [{"text": "Résoudre des problèmes de divisibilité et d'équations en nombres entiers.", "icon": "education"}, {"text": "Fonder les bases de la théorie des nombres approfondie.", "icon": "research"}]}, {"id": 609, "title": "Équations diophantiennes", "category": "Olympiades", "formulas": ["ax + by = c", "Méthode de descente infinie"], "details": "Les équations diophantiennes cherchent des solutions entières.", "images": ["diophantiennes.png"], "correspondances": [{"id": 608, "title": "Théorie des nombres olympique"}, {"id": 610, "title": "Géométrie olympique"}], "tags": ["olympiades", "diophantiennes"], "niveau": "prepa", "definition": "Une équation diophantienne est une équation dont on cherche uniquement les solutions en nombres entiers, un problème classique des olympiades avec des techniques de résolution spécifiques.", "explication_formules": "ax+by=c admet une solution entière si et seulement si le PGCD de a et b divise c (théorème de Bézout). La méthode de descente infinie prouve l'absence de solution en montrant que toute solution supposée en engendrerait indéfiniment de plus petites, ce qui est impossible.", "approfondissements": [{"label": "Équation de Pell-Fermat", "link": {"type": "theme", "slug": "equation-de-pell-fermat"}}, {"label": "Triplets pythagoriciens", "link": {"type": "theme", "slug": "triplets-pythagoriciens"}}, {"label": "Descente infinie de Fermat (approfondie)", "link": {"type": "theme", "slug": "descente-infinie-de-fermat-approfondie"}}, {"label": "Équations diophantiennes non linéaires", "link": {"type": "notion", "id": 609}}, {"label": "Théorème des deux carrés de Fermat", "link": {"type": "theme", "slug": "theoreme-des-deux-carres-de-fermat"}}], "sous_points": [{"terme": "Équations linéaires", "definition": "Une équation diophantienne linéaire ax+by=c admet une solution entière si et seulement si le PGCD de a et b divise c."}, {"terme": "Équations quadratiques", "definition": "Une équation diophantienne quadratique implique des carrés, comme l'équation de Pell-Fermat x²-ny²=1."}, {"terme": "Descentes", "definition": "La méthode de descente prouve l'absence de solution en en construisant indéfiniment de plus petites, ce qui est impossible."}], "applications_list": [{"text": "Résoudre des problèmes classiques comme les triplets pythagoriciens.", "icon": "education"}, {"text": "Fonder les bases de la théorie algébrique des nombres.", "icon": "research"}]}, {"id": 610, "title": "Géométrie olympique", "category": "Olympiades", "formulas": ["Pythagore", "Puissance d’un point", "Angles inscrits"], "details": "La géométrie olympique combine intuition et techniques avancées.", "images": ["geo_olympique.png"], "correspondances": [{"id": 206, "title": "Triangles"}, {"id": 204, "title": "Cercles"}], "tags": ["olympiades", "geometrie"], "niveau": "lycee", "definition": "La géométrie olympique mobilise des théorèmes classiques (Pythagore, puissance d'un point, angles inscrits) pour résoudre des problèmes de géométrie synthétique élégants et souvent surprenants.", "explication_formules": "Le théorème de Pythagore reste l'outil de base pour toute relation métrique dans un triangle rectangle. La puissance d'un point par rapport à un cercle mesure une relation constante entre les distances aux points d'intersection de toute droite passant par ce point.", "approfondissements": [{"label": "Puissance d'un point et axe radical", "link": {"type": "theme", "slug": "puissance-d-un-point-et-axe-radical"}}, {"label": "Angles inscrits et cocyclicité", "link": {"type": "theme", "slug": "angles-inscrits-et-cocyclicite"}}, {"label": "Théorème de Ptolémée", "link": {"type": "theme", "slug": "theoreme-de-ptolemee"}}, {"label": "Inversion géométrique", "link": {"type": "theme", "slug": "inversion-geometrique"}}, {"label": "Configurations classiques (orthocentre, cercle d'Euler)", "link": {"type": "theme", "slug": "configurations-classiques-orthocentre-cercle-d-euler"}}], "sous_points": [{"terme": "Cercles", "definition": "Les propriétés des cercles (puissance d'un point, angles inscrits) sont des outils fréquents en géométrie olympique."}, {"terme": "Triangles", "definition": "Les points et droites remarquables d'un triangle (orthocentre, cercle d'Euler) apparaissent souvent dans les problèmes olympiques."}, {"terme": "Transformations", "definition": "Les transformations géométriques (inversion, homothétie) permettent de simplifier des configurations complexes."}, {"terme": "Barycentres", "definition": "Les coordonnées barycentriques offrent parfois la preuve la plus rapide d'un résultat de concours de droites."}], "applications_list": [{"text": "Résoudre des problèmes de compétition de géométrie plane.", "icon": "education"}, {"text": "Développer une intuition géométrique fine.", "icon": "education"}]}, {"id": 611, "title": "Barycentres", "category": "Olympiades", "formulas": ["G = (mA A + mB B) / (mA + mB)", "Somme vectorielle pondérée"], "details": "Les barycentres permettent de résoudre des problèmes géométriques complexes.", "images": ["barycentres.png"], "correspondances": [{"id": 610, "title": "Géométrie olympique"}, {"id": 201, "title": "Vecteurs"}], "tags": ["olympiades", "barycentres"], "niveau": "lycee", "definition": "Le barycentre est le point d'équilibre d'un système de points pondérés — une généralisation du centre de gravité, très utile pour résoudre élégamment des problèmes de géométrie.", "explication_formules": "G=(mA·A+mB·B)/(mA+mB) place le barycentre plus proche du point ayant le plus grand poids. Cette formule se généralise à autant de points que nécessaire, et les relations vectorielles associées simplifient souvent des démonstrations géométriques complexes.", "approfondissements": [{"label": "Théorème de Ceva et Ménélaüs via les barycentres", "link": {"type": "theme", "slug": "theoreme-de-ceva-et-menelaus-via-les-barycentres"}}, {"label": "Coordonnées barycentriques", "link": {"type": "theme", "slug": "coordonnees-barycentriques"}}, {"label": "Barycentres et concours de cévianes", "link": {"type": "theme", "slug": "barycentres-et-concours-de-cevianes"}}, {"label": "Centre de gravité en physique", "link": {"type": "theme", "slug": "centre-de-gravite-en-physique"}}, {"label": "Barycentres en dimension supérieure", "link": {"type": "theme", "slug": "barycentres-en-dimension-superieure"}}], "sous_points": [{"terme": "Points remarquables", "definition": "Un barycentre pondéré permet de retrouver élégamment des points remarquables comme le centre de gravité d'un triangle."}, {"terme": "Transformations", "definition": "Les propriétés des barycentres se préservent par des transformations affines, un outil puissant en géométrie."}], "applications_list": [{"text": "Résoudre élégamment des problèmes de concours de droites.", "icon": "education"}, {"text": "Modéliser le centre de masse en physique.", "icon": "physics"}]}, {"id": 612, "title": "Colorations", "category": "Olympiades", "formulas": ["Coloration minimale", "Invariants de coloration"], "details": "Les colorations sont utilisées pour prouver des impossibilités.", "images": ["colorations.png"], "correspondances": [{"id": 607, "title": "Graphes olympiques"}, {"id": 604, "title": "Symétries et invariants"}], "tags": ["olympiades", "colorations"], "niveau": "prepa", "definition": "Les colorations attribuent des couleurs ou des étiquettes à des éléments d'une configuration selon des règles précises, souvent pour révéler un invariant qui prouve l'impossibilité d'une situation.", "explication_formules": "Une coloration minimale cherche le plus petit nombre de couleurs nécessaires pour satisfaire une contrainte donnée (par exemple, colorier un échiquier). Un invariant de coloration reste inchangé quelle que soit la transformation appliquée, permettant de prouver qu'un état final est inatteignable.", "approfondissements": [{"label": "Coloration d'échiquiers (argument classique)", "link": {"type": "theme", "slug": "coloration-d-echiquiers-argument-classique"}}, {"label": "Coloration de graphes", "link": {"type": "theme", "slug": "coloration-de-graphes"}}, {"label": "Nombre chromatique", "link": {"type": "theme", "slug": "nombre-chromatique"}}, {"label": "Colorations et parité", "link": {"type": "theme", "slug": "colorations-et-parite"}}, {"label": "Théorème des quatre couleurs", "link": {"type": "theme", "slug": "theoreme-des-quatre-couleurs"}}], "sous_points": [{"terme": "Colorations de graphes", "definition": "Colorier les sommets d'un graphe sans que deux voisins partagent la même couleur résout des problèmes d'attribution ou de conflit."}, {"terme": "Pavages", "definition": "Un argument de coloration permet souvent de prouver qu'un pavage donné est impossible."}], "applications_list": [{"text": "Prouver l'impossibilité de certains pavages en compétition.", "icon": "education"}, {"text": "Fonder la théorie de la coloration de graphes en planification.", "icon": "computer"}]}, {"id": 613, "title": "Pavages", "category": "Olympiades", "formulas": ["Pavage = partition du plan", "Invariants de parité"], "details": "Les pavages permettent de résoudre des problèmes de combinatoire géométrique.", "images": ["pavages.png"], "correspondances": [{"id": 612, "title": "Colorations"}, {"id": 606, "title": "Combinatoire avancée"}], "tags": ["olympiades", "pavages"], "niveau": "prepa", "definition": "Un pavage recouvre entièrement une surface (comme un plan ou un échiquier) avec des pièces données, sans trou ni chevauchement — un problème combinatoire classique en compétition.", "explication_formules": "Un pavage est une partition du plan (ou d'une figure) en pièces qui recouvrent exactement la surface sans se superposer. Les invariants de parité permettent souvent de prouver qu'un pavage donné est impossible, en montrant qu'une quantité comptée de deux façons différentes donne des résultats incompatibles.", "approfondissements": [{"label": "Pavages par dominos (argument de coloriage)", "link": {"type": "theme", "slug": "pavages-par-dominos-argument-de-coloriage"}}, {"label": "Polyominos et pavages du plan", "link": {"type": "theme", "slug": "polyominos-et-pavages-du-plan"}}, {"label": "Pavages périodiques et apériodiques", "link": {"type": "theme", "slug": "pavages-periodiques-et-aperiodiques"}}, {"label": "Théorème de Wang (indécidabilité du pavage)", "link": {"type": "theme", "slug": "theoreme-de-wang-indecidabilite-du-pavage"}}, {"label": "Pavages en cristallographie", "link": {"type": "theme", "slug": "pavages-en-cristallographie"}}], "sous_points": [{"terme": "Dominos", "definition": "Un domino recouvre exactement deux cases adjacentes ; un argument de coloriage en damier prouve souvent l'impossibilité d'un pavage donné."}, {"terme": "Trominos", "definition": "Un tromino est une pièce de trois cases ; paver une figure avec des trominos nécessite des arguments de coloriage plus subtils."}, {"terme": "Pavages impossibles", "definition": "Certaines figures ne peuvent être pavées par un jeu de pièces donné, ce que révèle un argument d'invariance bien choisi."}], "applications_list": [{"text": "Résoudre des problèmes classiques de pavage par dominos ou polyominos.", "icon": "education"}, {"text": "Concevoir des motifs de carrelage ou de mosaïque.", "icon": "art"}]}, {"id": 614, "title": "Symétrisation", "category": "Olympiades", "formulas": ["Symétrisation → réduction du problème", "AM-GM pour symétriser"], "details": "La symétrisation simplifie les problèmes en exploitant les symétries.", "images": ["symetrisation.png"], "correspondances": [{"id": 600, "title": "Inégalités classiques"}, {"id": 601, "title": "Optimisation"}], "tags": ["olympiades", "symetrisation"], "niveau": "prepa", "definition": "La symétrisation exploite la symétrie inhérente d'un problème pour deviner ou prouver que la solution optimale se produit dans une configuration symétrique, simplifiant considérablement la résolution.", "explication_formules": "La symétrisation transforme un problème avec plusieurs variables en un problème équivalent où l'on suppose (souvent à juste titre) que l'extremum est atteint quand toutes les variables sont égales, réduisant fortement la complexité de la preuve.", "approfondissements": [{"label": "Lien avec l'inégalité AM-GM", "link": {"type": "theme", "slug": "lien-avec-l-inegalite-am-gm"}}, {"label": "Symétrisation en géométrie", "link": {"type": "theme", "slug": "symetrisation-en-geometrie"}}, {"label": "Preuve rigoureuse de l'égalité des cas optimaux", "link": {"type": "theme", "slug": "preuve-rigoureuse-de-l-egalite-des-cas-optimaux"}}, {"label": "Fonctions symétriques et polynômes symétriques", "link": {"type": "theme", "slug": "fonctions-symetriques-et-polynomes-symetriques"}}, {"label": "Symétrisation de Steiner (géométrie avancée)", "link": {"type": "theme", "slug": "symetrisation-de-steiner-geometrie-avancee"}}], "sous_points": [{"terme": "Symétrisation de variables", "definition": "Réécrire un problème sous une forme symétrique en ses variables révèle souvent la structure de la solution optimale."}, {"terme": "Réduction", "definition": "Réduire le nombre de variables distinctes d'un problème simplifie souvent considérablement sa résolution."}], "applications_list": [{"text": "Simplifier la résolution de problèmes d'optimisation en compétition.", "icon": "education"}]}, {"id": 615, "title": "Méthode des invariants", "category": "Olympiades", "formulas": ["Invariant = quantité conservée", "Monovariant = quantité monotone"], "details": "Les invariants et monovariants sont essentiels pour les problèmes de transformations.", "images": ["monovariants.png"], "correspondances": [{"id": 604, "title": "Symétries et invariants"}, {"id": 613, "title": "Pavages"}], "tags": ["olympiades", "invariants"], "niveau": "prepa", "definition": "La méthode des invariants et monovariants fournit un cadre systématique pour prouver l'impossibilité d'un état final ou la terminaison forcée d'un processus itératif.", "explication_formules": "Un invariant est une quantité qui reste constante au fil des transformations, permettant de prouver qu'un état final incompatible est inatteignable. Un monovariant, qui évolue toujours dans le même sens (croissant ou décroissant), garantit qu'un processus se termine forcément après un nombre fini d'étapes.", "approfondissements": [{"label": "Choix judicieux d'un invariant", "link": {"type": "theme", "slug": "choix-judicieux-d-un-invariant"}}, {"label": "Monovariants et preuves de terminaison d'algorithmes", "link": {"type": "theme", "slug": "monovariants-et-preuves-de-terminaison-d-algorithmes"}}, {"label": "Invariants en théorie des jeux combinatoires", "link": {"type": "theme", "slug": "invariants-en-theorie-des-jeux-combinatoires"}}, {"label": "Invariants topologiques", "link": {"type": "theme", "slug": "invariants-topologiques"}}, {"label": "Applications à la vérification de programmes", "link": {"type": "theme", "slug": "applications-a-la-verification-de-programmes"}}], "sous_points": [{"terme": "Invariants additifs", "definition": "Un invariant additif est une somme qui ne change jamais malgré les transformations autorisées."}, {"terme": "Invariants multiplicatifs", "definition": "Un invariant multiplicatif est un produit qui ne change jamais malgré les transformations autorisées."}], "applications_list": [{"text": "Prouver la terminaison d'algorithmes et de jeux combinatoires.", "icon": "computer"}, {"text": "Résoudre des problèmes de compétition sur les transformations répétées.", "icon": "education"}]}, {"id": 700, "title": "Espaces vectoriels normés", "category": "Prépa", "formulas": ["Norme : ||x||", "Distance : d(x,y)=||x−y||", "Normes usuelles : ||x||₁, ||x||₂, ||x||∞"], "details": "Les espaces vectoriels normés permettent de mesurer des distances et des tailles de vecteurs.", "images": ["normes.png"], "correspondances": [{"id": 701, "title": "Espaces métriques"}, {"id": 104, "title": "Espaces vectoriels"}], "tags": ["prepa", "analyse", "normes"], "niveau": "prepa", "definition": "Un espace vectoriel normé est un espace vectoriel muni d'une norme (une mesure de 'longueur') qui permet de parler de distance, de convergence et de continuité sur des vecteurs.", "explication_formules": "La distance d(x,y)=‖x-y‖ dérive naturellement de la norme. Les normes usuelles ‖x‖1, ‖x‖2, ‖x‖∞ mesurent la 'taille' d'un vecteur de façons différentes (somme des valeurs absolues, distance euclidienne, valeur maximale) mais sont toutes équivalentes en dimension finie.", "approfondissements": [{"label": "Équivalence des normes en dimension finie", "link": {"type": "theme", "slug": "equivalence-des-normes-en-dimension-finie"}}, {"label": "Normes matricielles", "link": {"type": "theme", "slug": "normes-matricielles"}}, {"label": "Espaces de Banach (normes complètes)", "link": {"type": "notion", "id": 709}}, {"label": "Normes en apprentissage automatique (régularisation)", "link": {"type": "notion", "id": 530}}, {"label": "Applications aux méthodes numériques", "link": {"type": "theme", "slug": "applications-aux-methodes-numeriques"}}], "sous_points": [{"terme": "Normes équivalentes", "definition": "Deux normes sont équivalentes si elles définissent la même notion de convergence ; en dimension finie, toutes les normes le sont."}, {"terme": "Topologie induite", "definition": "La norme d'un espace vectoriel induit naturellement une topologie, définissant ouverts et convergence."}, {"terme": "Boules ouvertes", "definition": "Une boule ouverte regroupe tous les points à distance strictement inférieure à un rayon donné d'un centre."}], "applications_list": [{"text": "Fonder l'analyse fonctionnelle utilisée en apprentissage automatique.", "icon": "computer"}, {"text": "Mesurer l'erreur d'approximation dans les méthodes numériques.", "icon": "research"}]}, {"id": 701, "title": "Espaces métriques", "category": "Prépa", "formulas": ["Distance : d(x,y)", "Boule : B(x,r)", "Convergence : x_n → x"], "details": "Les espaces métriques généralisent la notion de distance.", "images": ["metriques.png"], "correspondances": [{"id": 700, "title": "Espaces vectoriels normés"}, {"id": 702, "title": "Topologie"}], "tags": ["prepa", "analyse", "metriques"], "niveau": "prepa", "definition": "Un espace métrique est un ensemble muni d'une notion de distance, le cadre le plus général pour parler de proximité, de convergence et de continuité, au-delà des seuls espaces vectoriels.", "explication_formules": "La distance d(x,y) doit vérifier symétrie, positivité et l'inégalité triangulaire d(x,z)≤d(x,y)+d(y,z). Une boule B(x,r) regroupe tous les points à distance inférieure à r de x, l'outil de base pour définir ouverts et convergence.", "approfondissements": [{"label": "Boules ouvertes et fermées", "link": {"type": "theme", "slug": "boules-ouvertes-et-fermees"}}, {"label": "Suites de Cauchy et complétude", "link": {"type": "theme", "slug": "suites-de-cauchy-et-completude"}}, {"label": "Espaces métriques compacts", "link": {"type": "notion", "id": 701}}, {"label": "Distance et topologie induite", "link": {"type": "theme", "slug": "distance-et-topologie-induite"}}, {"label": "Espaces métriques en apprentissage automatique", "link": {"type": "notion", "id": 701}}], "sous_points": [{"terme": "Convergence", "definition": "Dans un espace métrique, une suite converge vers une limite si la distance à cette limite tend vers zéro."}, {"terme": "Compacité", "definition": "Un espace est compact si de tout recouvrement par des ouverts, on peut extraire un sous-recouvrement fini."}, {"terme": "Continuité", "definition": "Une fonction est continue si l'image d'une suite convergente reste une suite convergente vers l'image de la limite."}, {"terme": "Complétude", "definition": "Un espace est complet si toute suite de Cauchy y converge effectivement, sans « trou »."}], "applications_list": [{"text": "Fonder rigoureusement toute l'analyse dans un cadre général.", "icon": "research"}, {"text": "Modéliser des notions de distance abstraites en apprentissage automatique.", "icon": "computer"}]}, {"id": 702, "title": "Topologie", "category": "Prépa", "formulas": ["Ouverts, fermés", "Adhérence, intérieur", "Frontière"], "details": "La topologie étudie les propriétés invariantes par déformation continue.", "images": ["topologie.png"], "correspondances": [{"id": 701, "title": "Espaces métriques"}, {"id": 703, "title": "Séries de fonctions"}, {"key": "sup:1952", "title": "Théorème de Zermelo (bon ordre)", "raison": "Le théorème de Tychonoff, qui affirme qu'un produit de compacts est compact, est équivalent à l'axiome du choix, lui-même équivalent au bon ordre de Zermelo."}, {"key": "sup:1519", "title": "Nombres p-adiques (introduction culturelle)", "raison": "L'anneau ℤ_p des entiers p-adiques, limite des ℤ/p^nℤ, est un espace topologique compact : la compacité y traduit des propriétés d'approximation modulo toutes les puissances de p."}, {"key": "sup:427", "title": "Théorème de Riesz (boule unité compacte)", "raison": "La boule unité fermée d'un espace normé est compacte si et seulement si l'espace est de dimension finie : la compacité sépare dimension finie et dimension infinie."}, {"key": "sup:440", "title": "Théorème du minimum sur un compact", "raison": "Une fonction continue (ou semi-continue inférieurement) sur un compact atteint son minimum : c'est le théorème d'existence de base en optimisation."}], "tags": ["prepa", "analyse", "topologie"], "niveau": "prepa", "definition": "La topologie étudie les notions de proximité et de continuité de façon encore plus abstraite qu'un espace métrique, en se concentrant uniquement sur ce qui compte comme 'ouvert' et 'fermé'.", "explication_formules": "Les ouverts et fermés forment le vocabulaire de base de la topologie ; leur complémentaire l'un de l'autre structure tout l'espace. L'adhérence et l'intérieur d'un ensemble mesurent respectivement ses 'bords inclus' et son 'cœur strict'.", "approfondissements": [{"label": "Compacité et connexité", "link": {"type": "theme", "slug": "compacite-et-connexite"}}, {"label": "Topologie produit et quotient", "link": {"type": "theme", "slug": "topologie-produit-et-quotient"}}, {"label": "Espaces topologiques non métrisables", "link": {"type": "theme", "slug": "espaces-topologiques-non-metrisables"}}, {"label": "Homéomorphismes", "link": {"type": "theme", "slug": "homeomorphismes"}}, {"label": "Applications aux variétés différentiables", "link": {"type": "notion", "id": 223}}], "sous_points": [{"terme": "Bases d'ouverts", "definition": "Une base d'ouverts permet de générer toute la topologie d'un espace à partir d'un ensemble restreint d'ouverts de référence."}, {"terme": "Compacité", "definition": "La compacité généralise l'idée d'un ensemble « fermé et borné » à des espaces topologiques abstraits."}, {"terme": "Connexité", "definition": "Un espace connexe ne peut pas être séparé en deux morceaux disjoints ouverts non vides."}], "applications_list": [{"text": "Fonder rigoureusement l'analyse et la géométrie différentielle avancées.", "icon": "research"}, {"text": "Étudier des espaces trop abstraits pour avoir une distance naturelle.", "icon": "research"}]}, {"id": 703, "title": "Séries de fonctions", "category": "Prépa", "formulas": ["Σ f_n(x)", "Convergence simple / uniforme", "Théorème de Weierstrass"], "details": "Les séries de fonctions généralisent les séries numériques.", "images": ["series_fonctions.png"], "correspondances": [{"id": 702, "title": "Topologie"}, {"id": 704, "title": "Séries de Fourier (niveau prépa)"}], "tags": ["prepa", "analyse", "series"], "niveau": "prepa", "definition": "Une série de fonctions est une somme infinie de fonctions plutôt que de nombres, dont la convergence peut dépendre du point x considéré — un concept plus subtil que la convergence de séries numériques.", "explication_formules": "La convergence simple examine la limite point par point, tandis que la convergence uniforme exige une convergence 'globalement contrôlée' sur tout un intervalle. Le théorème de Weierstrass garantit que si les termes sont bornés de façon sommable (convergence normale), alors la série converge uniformément.", "approfondissements": [{"label": "Convergence normale (critère de Weierstrass)", "link": {"type": "theme", "slug": "convergence-normale-critere-de-weierstrass"}}, {"label": "Continuité de la limite uniforme", "link": {"type": "theme", "slug": "continuite-de-la-limite-uniforme"}}, {"label": "Dérivation et intégration terme à terme", "link": {"type": "theme", "slug": "derivation-et-integration-terme-a-terme"}}, {"label": "Séries de fonctions holomorphes", "link": {"type": "theme", "slug": "series-de-fonctions-holomorphes"}}, {"label": "Applications aux séries entières et de Fourier", "link": {"type": "notion", "id": 7}}], "sous_points": [{"terme": "Convergence uniforme", "definition": "Une série de fonctions converge uniformément si le contrôle de l'erreur ne dépend pas du point considéré, propriété nécessaire pour dériver ou intégrer terme à terme."}, {"terme": "Échange limite/intégrale", "definition": "Sous convergence uniforme, on peut intervertir limite et intégrale (ou dérivée) d'une suite de fonctions sans changer le résultat."}], "applications_list": [{"text": "Justifier rigoureusement les développements en série entière et de Fourier.", "icon": "research"}, {"text": "Fonder les méthodes d'approximation de fonctions en calcul numérique.", "icon": "computer"}]}, {"id": 704, "title": "Séries de Fourier (niveau prépa)", "category": "Prépa", "formulas": ["f(x)=a0+Σ(an cos(nx)+bn sin(nx))", "an = ∫ f(x)cos(nx) dx", "bn = ∫ f(x)sin(nx) dx"], "details": "Décomposition d’une fonction en somme de sinusoïdes.", "images": ["fourier_prepa.png"], "correspondances": [{"id": 703, "title": "Séries de fonctions"}, {"id": 705, "title": "Analyse complexe (niveau prépa)"}], "tags": ["prepa", "analyse", "fourier"], "niveau": "prepa", "definition": "Cette notion présente les séries de Fourier au niveau des classes préparatoires, avec les outils rigoureux de convergence nécessaires à une utilisation correcte en analyse.", "explication_formules": "f(x)=a0+Σ(an cos(nx)+bn sin(nx)) décompose une fonction périodique en fréquences. Les coefficients an et bn se calculent par des intégrales qui projettent f sur chaque fréquence, exploitant l'orthogonalité des fonctions trigonométriques.", "approfondissements": [{"label": "Théorème de Dirichlet (convergence ponctuelle)", "link": {"type": "theme", "slug": "theoreme-de-dirichlet-convergence-ponctuelle"}}, {"label": "Égalité de Parseval", "link": {"type": "theme", "slug": "egalite-de-parseval"}}, {"label": "Convergence normale des séries de Fourier", "link": {"type": "notion", "id": 7}}, {"label": "Applications aux EDP au programme de prépa", "link": {"type": "theme", "slug": "applications-aux-edp-au-programme-de-prepa"}}, {"label": "Séries de Fourier complexes", "link": {"type": "notion", "id": 7}}], "sous_points": [{"terme": "Orthogonalité", "definition": "Les fonctions sinus et cosinus de fréquences différentes ont un produit d'intégrale nul sur une période, permettant de calculer isolément chaque coefficient."}, {"terme": "Convergence", "definition": "La convergence d'une série de Fourier vers la fonction d'origine dépend de la régularité de cette dernière (théorème de Dirichlet)."}, {"terme": "Transformée de Fourier", "definition": "Cette transformée généralise les séries de Fourier aux fonctions non périodiques, donnant un spectre continu."}], "applications_list": [{"text": "Résoudre les équations différentielles au programme de prépa.", "icon": "education"}, {"text": "Préparer aux applications en physique (vibrations, signaux).", "icon": "physics"}]}, {"id": 705, "title": "Analyse complexe (niveau prépa)", "category": "Prépa", "formulas": ["Holomorphie", "Résidus", "∮ f(z) dz"], "details": "Étude des fonctions complexes dérivables.", "images": ["complexe_prepa.png"], "correspondances": [{"id": 704, "title": "Séries de Fourier (niveau prépa)"}, {"id": 706, "title": "Transformations conformes"}], "tags": ["prepa", "analyse", "complexe"], "niveau": "prepa", "definition": "Cette notion présente l'analyse complexe au niveau des classes préparatoires, avec les résultats fondamentaux (holomorphie, résidus) nécessaires pour les concours d'entrée aux grandes écoles.", "explication_formules": "L'holomorphie exige qu'une fonction complexe soit dérivable au sens complexe, une condition bien plus forte que la dérivabilité réelle. Le calcul de résidus ∮f(z)dz permet d'évaluer des intégrales de contour complexes en une simple somme, technique très prisée aux concours.", "approfondissements": [{"label": "Conditions de Cauchy-Riemann", "link": {"type": "theme", "slug": "conditions-de-cauchy-riemann"}}, {"label": "Théorème des résidus (application aux concours)", "link": {"type": "theme", "slug": "theoreme-des-residus-application-aux-concours"}}, {"label": "Séries de Laurent", "link": {"type": "theme", "slug": "series-de-laurent"}}, {"label": "Fonctions méromorphes", "link": {"type": "theme", "slug": "fonctions-meromorphes"}}, {"label": "Applications aux intégrales réelles (technique de concours)", "link": {"type": "theme", "slug": "applications-aux-integrales-reelles-technique-de-concours"}}], "sous_points": [{"terme": "Cauchy", "definition": "La formule intégrale de Cauchy exprime la valeur d'une fonction holomorphe en tout point à partir de son comportement sur un contour l'entourant."}, {"terme": "Résidus", "definition": "Le théorème des résidus calcule une intégrale de contour comme une simple somme de résidus aux singularités entourées."}, {"terme": "Intégrales complexes", "definition": "Une intégrale complexe se calcule le long d'un chemin du plan complexe, souvent simplifiée par le théorème des résidus."}], "applications_list": [{"text": "Résoudre des problèmes de concours par intégrales complexes.", "icon": "education"}, {"text": "Préparer aux applications en mécanique des fluides et électromagnétisme.", "icon": "physics"}]}, {"id": 706, "title": "Transformations conformes", "category": "Prépa", "formulas": ["f holomorphe ⇒ conforme", "Préservation des angles"], "details": "Les transformations conformes préservent les angles.", "images": ["conformes.png"], "correspondances": [{"id": 705, "title": "Analyse complexe (niveau prépa)"}, {"id": 707, "title": "Équations différentielles avancées"}], "tags": ["prepa", "analyse", "conformes"], "niveau": "prepa", "definition": "Une transformation conforme préserve localement les angles (mais pas nécessairement les longueurs), une propriété remarquable des fonctions holomorphes très utile en géométrie et en physique.", "explication_formules": "f holomorphe ⇒ conforme (là où f'≠0) : c'est un résultat central de l'analyse complexe qui relie directement dérivabilité complexe et préservation géométrique des angles. Cette propriété permet de 'redresser' des configurations géométriques complexes sans en changer la structure angulaire locale.", "approfondissements": [{"label": "Automorphismes du disque unité", "link": {"type": "theme", "slug": "automorphismes-du-disque-unite"}}, {"label": "Transformations de Möbius (homographies)", "link": {"type": "theme", "slug": "transformations-de-mobius-homographies"}}, {"label": "Représentation conforme de Riemann", "link": {"type": "theme", "slug": "representation-conforme-de-riemann"}}, {"label": "Applications à la cartographie", "link": {"type": "theme", "slug": "applications-a-la-cartographie"}}, {"label": "Applications à l'électrostatique et la mécanique des fluides", "link": {"type": "theme", "slug": "applications-a-l-electrostatique-et-la-mecanique-des-fluides"}}], "sous_points": [{"terme": "Applications en physique", "definition": "Les transformations conformes simplifient certains problèmes bidimensionnels d'électrostatique ou d'écoulement de fluide."}, {"terme": "Géométrie complexe", "definition": "Une transformation conforme préserve localement les angles, une propriété remarquable des fonctions holomorphes."}], "applications_list": [{"text": "Résoudre des problèmes de mécanique des fluides et d'électrostatique.", "icon": "physics"}, {"text": "Fonder la cartographie (projections conformes comme Mercator).", "icon": "navigation"}]}, {"id": 707, "title": "Équations différentielles avancées", "category": "Prépa", "formulas": ["y' = ay", "y'' + ω² y = 0", "Méthode de variation de la constante"], "details": "Les ED décrivent l’évolution de systèmes physiques et mathématiques.", "images": ["ed_prepa.png"], "correspondances": [{"id": 706, "title": "Transformations conformes"}, {"id": 708, "title": "Espaces de Hilbert"}], "tags": ["prepa", "analyse", "ed"], "niveau": "prepa", "definition": "Cette notion présente les équations différentielles au niveau avancé des classes préparatoires, avec les méthodes de résolution systématiques exigées aux concours.", "explication_formules": "y'=ay décrit une croissance ou décroissance exponentielle. y''+ω²y=0 décrit un oscillateur harmonique parfait, solution sinusoïdale de pulsation ω. La méthode de variation de la constante trouve une solution particulière à partir de la solution générale de l'équation homogène associée.", "approfondissements": [{"label": "Systèmes différentiels linéaires (niveau concours)", "link": {"type": "theme", "slug": "systemes-differentiels-lineaires-niveau-concours"}}, {"label": "Résolution par changement de variable", "link": {"type": "theme", "slug": "resolution-par-changement-de-variable"}}, {"label": "Équations différentielles non linéaires classiques", "link": {"type": "notion", "id": 6}}, {"label": "Stabilité des solutions", "link": {"type": "theme", "slug": "stabilite-des-solutions"}}, {"label": "Applications à la physique du programme de prépa", "link": {"type": "theme", "slug": "applications-a-la-physique-du-programme-de-prepa"}}], "sous_points": [{"terme": "ED linéaires", "definition": "Une équation différentielle linéaire relie une fonction inconnue et ses dérivées de façon linéaire, ce qui permet de la résoudre systématiquement."}, {"terme": "Systèmes", "definition": "Un système d'équations différentielles couplées se résout souvent via la diagonalisation de la matrice associée."}, {"terme": "Équations d'ordre supérieur", "definition": "Une équation d'ordre n implique la dérivée n-ième de la fonction inconnue, se ramenant à un système d'ordre 1 par changement de variables."}], "applications_list": [{"text": "Résoudre les problèmes de mécanique et d'électricité au programme.", "icon": "electronics"}, {"text": "Préparer aux épreuves de mathématiques et physique des concours.", "icon": "education"}]}, {"id": 708, "title": "Espaces de Hilbert", "category": "Prépa", "formulas": ["Produit scalaire", "Complétude", "Base orthonormée"], "details": "Les espaces de Hilbert généralisent ℝⁿ aux fonctions.", "images": ["hilbert.png"], "correspondances": [{"id": 704, "title": "Séries de Fourier (niveau prépa)"}, {"id": 709, "title": "Espaces de Banach"}], "tags": ["prepa", "analyse", "hilbert"], "niveau": "prepa", "definition": "Un espace de Hilbert est un espace vectoriel muni d'un produit scalaire et complet, généralisant la géométrie euclidienne à des dimensions infinies — un concept central des programmes de prépa avancés.", "explication_formules": "Le produit scalaire munit l'espace d'une notion d'angle et de longueur. La complétude garantit qu'aucune suite de Cauchy ne 'manque' sa limite. Une base orthonormée permet de décomposer tout vecteur (ou fonction) en composantes indépendantes, comme les coefficients de Fourier.", "approfondissements": [{"label": "Bases hilbertiennes et séries de Fourier", "link": {"type": "notion", "id": 7}}, {"label": "Projection orthogonale sur un sous-espace", "link": {"type": "theme", "slug": "projection-orthogonale-sur-un-sous-espace"}}, {"label": "Théorème de représentation de Riesz", "link": {"type": "theme", "slug": "theoreme-de-representation-de-riesz"}}, {"label": "Opérateurs sur les espaces de Hilbert", "link": {"type": "notion", "id": 708}}, {"label": "Applications à la mécanique quantique", "link": {"type": "notion", "id": 420}}], "sous_points": [{"terme": "Orthogonalité", "definition": "L'orthogonalité dans un espace de Hilbert généralise la perpendicularité, mesurée via un produit scalaire nul."}, {"terme": "Projections", "definition": "La projection orthogonale d'un vecteur sur un sous-espace fermé en donne l'élément le plus proche, toujours unique."}, {"terme": "Séries de Fourier", "definition": "Les séries de Fourier sont un cas particulier de projection orthogonale dans l'espace de Hilbert L²."}], "applications_list": [{"text": "Fonder rigoureusement les séries de Fourier en physique.", "icon": "physics"}, {"text": "Préparer aux notions d'analyse fonctionnelle du supérieur.", "icon": "education"}]}, {"id": 709, "title": "Espaces de Banach", "category": "Prépa", "formulas": ["Norme", "Complétude", "Applications linéaires continues"], "details": "Les espaces de Banach sont des espaces normés complets.", "images": ["banach.png"], "correspondances": [{"id": 708, "title": "Espaces de Hilbert"}, {"id": 710, "title": "Séries entières avancées"}], "tags": ["prepa", "analyse", "banach"], "niveau": "prepa", "definition": "Un espace de Banach est un espace vectoriel normé complet — comme un espace de Hilbert, mais sans nécessairement de produit scalaire, un cadre plus général pour l'analyse fonctionnelle.", "explication_formules": "La complétude (toute suite de Cauchy converge dans l'espace) est la propriété essentielle qui distingue un espace de Banach d'un simple espace normé. Les applications linéaires continues entre espaces de Banach forment elles-mêmes un espace de Banach, un résultat structurant.", "approfondissements": [{"label": "Théorème du point fixe de Banach", "link": {"type": "theme", "slug": "theoreme-du-point-fixe-de-banach"}}, {"label": "Applications linéaires continues et normes d'opérateurs", "link": {"type": "notion", "id": 106}}, {"label": "Théorème de Hahn-Banach", "link": {"type": "theme", "slug": "theoreme-de-hahn-banach"}}, {"label": "Espaces de Banach de fonctions (Lᵖ, C⁰)", "link": {"type": "theme", "slug": "espaces-de-banach-de-fonctions-l-c"}}, {"label": "Applications aux équations différentielles", "link": {"type": "notion", "id": 6}}], "sous_points": [{"terme": "Applications linéaires", "definition": "Les applications linéaires continues entre espaces de Banach forment elles-mêmes un espace de Banach."}, {"terme": "Théorèmes de point fixe", "definition": "Le théorème du point fixe de Banach garantit qu'une application contractante sur un espace complet possède un unique point fixe."}], "applications_list": [{"text": "Fonder l'analyse fonctionnelle des équations différentielles et EDP.", "icon": "research"}, {"text": "Préparer aux concepts avancés des études supérieures scientifiques.", "icon": "education"}]}, {"id": 710, "title": "Séries entières avancées", "category": "Prépa", "formulas": ["Σ a_n (x−x0)^n", "Rayon de convergence R", "Test de Cauchy"], "details": "Les séries entières permettent de représenter des fonctions analytiques.", "images": ["series_entieres_prepa.png"], "correspondances": [{"id": 705, "title": "Analyse complexe (niveau prépa)"}, {"id": 709, "title": "Espaces de Banach"}], "tags": ["prepa", "analyse", "series-entieres"], "niveau": "prepa", "definition": "Cette notion présente les séries entières au niveau avancé des classes préparatoires, avec une attention particulière portée au rayon de convergence et à ses applications.", "explication_formules": "Σaₙ(x-x0)ⁿ converge si |x-x0|<R, où le rayon de convergence R se calcule via le test de Cauchy (racine n-ième des coefficients). Ce rayon détermine exactement le domaine de validité de la représentation en série entière d'une fonction.", "approfondissements": [{"label": "Rayon de convergence et critère de Cauchy-Hadamard", "link": {"type": "theme", "slug": "rayon-de-convergence-et-critere-de-cauchy-hadamard"}}, {"label": "Dérivation et intégration terme à terme", "link": {"type": "theme", "slug": "derivation-et-integration-terme-a-terme"}}, {"label": "Développement en série entière des fonctions usuelles", "link": {"type": "theme", "slug": "developpement-en-serie-entiere-des-fonctions-usuelles"}}, {"label": "Résolution d'équations différentielles par séries", "link": {"type": "notion", "id": 6}}, {"label": "Séries entières et fonctions génératrices", "link": {"type": "theme", "slug": "series-entieres-et-fonctions-generatrices"}}], "sous_points": [{"terme": "Convergence", "definition": "Une série entière converge à l'intérieur de son rayon de convergence R, calculé via le critère de Cauchy-Hadamard."}, {"terme": "Dérivation terme à terme", "definition": "À l'intérieur du rayon de convergence, on peut dériver une série entière terme à terme sans changer son rayon."}], "applications_list": [{"text": "Résoudre des équations différentielles par développement en série.", "icon": "research"}, {"text": "Calculer des sommes de séries classiques aux concours.", "icon": "education"}]}, {"id": 711, "title": "Algèbre linéaire avancée", "category": "Prépa", "formulas": ["A = P D P^{-1}", "Valeurs propres", "Formes quadratiques"], "details": "L’algèbre linéaire avancée étudie les transformations linéaires complexes.", "images": ["algebre_prepa.png"], "correspondances": [{"id": 108, "title": "Diagonalisation"}, {"id": 109, "title": "Formes quadratiques"}], "tags": ["prepa", "algebre"], "niveau": "prepa", "definition": "Cette notion synthétise l'algèbre linéaire avancée au niveau prépa, combinant diagonalisation, valeurs propres et formes quadratiques — le cœur du programme d'algèbre des classes préparatoires.", "explication_formules": "A=PDP⁻¹ résume la diagonalisation d'une matrice, technique omniprésente aux concours pour résoudre systèmes différentiels et calculer des puissances de matrices. Les formes quadratiques et leur signature complètent ce socle en reliant algèbre et géométrie.", "approfondissements": [{"label": "Réduction de Jordan (cas non diagonalisable)", "link": {"type": "theme", "slug": "reduction-de-jordan-cas-non-diagonalisable"}}, {"label": "Endomorphismes symétriques et théorème spectral", "link": {"type": "theme", "slug": "endomorphismes-symetriques-et-theoreme-spectral"}}, {"label": "Applications aux systèmes différentiels", "link": {"type": "theme", "slug": "applications-aux-systemes-differentiels"}}, {"label": "Espaces euclidiens et orthogonalité", "link": {"type": "theme", "slug": "espaces-euclidiens-et-orthogonalite"}}, {"label": "Exercices classiques de concours (algèbre linéaire)", "link": {"type": "theme", "slug": "exercices-classiques-de-concours-algebre-lineaire"}}], "sous_points": [{"terme": "Diagonalisation", "definition": "Diagonaliser une matrice la réécrit dans une base de vecteurs propres où elle devient diagonale, simplifiant tous les calculs."}, {"terme": "Trigonalisation", "definition": "Quand une matrice n'est pas diagonalisable, on peut souvent la trigonaliser (la rendre triangulaire) dans une base bien choisie."}, {"terme": "Formes quadratiques", "definition": "Une forme quadratique se réduit en somme de carrés, révélant sa signature indépendante de la méthode utilisée."}], "applications_list": [{"text": "Résoudre la majorité des exercices d'algèbre linéaire aux concours.", "icon": "education"}, {"text": "Préparer aux applications en physique (mécanique quantique).", "icon": "physics"}]}, {"id": 712, "title": "Probabilités avancées", "category": "Prépa", "formulas": ["E(X|Y)", "Cov(X,Y)", "Loi normale"], "details": "Les probabilités avancées étudient les variables continues et les vecteurs aléatoires.", "images": ["proba_prepa.png"], "correspondances": [{"id": 311, "title": "Lois normales"}, {"id": 310, "title": "Covariance et corrélation"}], "tags": ["prepa", "probabilites"], "niveau": "prepa", "definition": "Cette notion synthétise les probabilités avancées au niveau prépa, avec l'espérance conditionnelle et la covariance comme outils centraux pour analyser des variables aléatoires liées entre elles.", "explication_formules": "E(X|Y) donne la meilleure prévision de X sachant la valeur de Y. Cov(X,Y) mesure comment deux variables varient ensemble. La loi normale, omniprésente au programme, sert de référence pour de nombreux résultats asymptotiques (théorème central limite).", "approfondissements": [{"label": "Vecteurs gaussiens (niveau concours)", "link": {"type": "theme", "slug": "vecteurs-gaussiens-niveau-concours"}}, {"label": "Théorème central limite (démonstration et applications)", "link": {"type": "notion", "id": 313}}, {"label": "Chaînes de Markov (niveau prépa)", "link": {"type": "notion", "id": 314}}, {"label": "Exercices classiques de concours (probabilités)", "link": {"type": "theme", "slug": "exercices-classiques-de-concours-probabilites"}}, {"label": "Applications à la statistique inférentielle", "link": {"type": "theme", "slug": "applications-a-la-statistique-inferentielle"}}], "sous_points": [{"terme": "Densités", "definition": "La densité de probabilité d'une variable continue permet de calculer, par intégration, la probabilité de tout intervalle."}, {"terme": "Lois usuelles", "definition": "Les lois usuelles (uniforme, exponentielle, normale) modélisent des familles de phénomènes aléatoires récurrents."}, {"terme": "Indépendance", "definition": "Deux variables sont indépendantes si leur loi conjointe se factorise en le produit de leurs lois marginales."}], "applications_list": [{"text": "Résoudre les exercices de probabilités aux concours d'entrée.", "icon": "education"}, {"text": "Préparer aux applications en statistique et finance quantitative.", "icon": "finance"}]}, {"id": 713, "title": "Statistiques avancées", "category": "Prépa", "formulas": ["Estimateur", "Intervalle de confiance", "Test d’hypothèse"], "details": "La statistique avancée étudie l’inférence sur des données.", "images": ["stats_prepa.png"], "correspondances": [{"id": 712, "title": "Probabilités avancées"}, {"id": 310, "title": "Covariance et corrélation"}], "tags": ["prepa", "statistiques"], "niveau": "prepa", "definition": "Cette notion synthétise la statistique avancée au niveau prépa, couvrant l'estimation, les intervalles de confiance et les tests d'hypothèses exigés aux concours d'entrée aux grandes écoles.", "explication_formules": "Un estimateur utilise les données observées pour approcher un paramètre inconnu de la population. Un intervalle de confiance donne une fourchette de valeurs plausibles pour ce paramètre, avec un niveau de certitude choisi. Un test d'hypothèse décide si une hypothèse doit être rejetée à la lumière des données.", "approfondissements": [{"label": "Estimateurs sans biais et convergents", "link": {"type": "theme", "slug": "estimateurs-sans-biais-et-convergents"}}, {"label": "Intervalles de confiance (cas gaussien)", "link": {"type": "theme", "slug": "intervalles-de-confiance-cas-gaussien"}}, {"label": "Tests d'hypothèses classiques de concours", "link": {"type": "notion", "id": 319}}, {"label": "Théorème central limite appliqué à l'estimation", "link": {"type": "notion", "id": 313}}, {"label": "Applications à la science des données", "link": {"type": "theme", "slug": "applications-a-la-science-des-donnees"}}], "sous_points": [{"terme": "Estimateurs", "definition": "Un estimateur utilise les données observées pour approcher un paramètre inconnu de la population."}, {"terme": "Biais", "definition": "Un estimateur est sans biais s'il donne, en moyenne, la vraie valeur du paramètre recherché."}, {"terme": "Variance", "definition": "La variance d'un estimateur mesure sa précision : plus elle est faible, plus l'estimation est fiable d'un échantillon à l'autre."}], "applications_list": [{"text": "Résoudre les exercices de statistique aux concours d'entrée.", "icon": "education"}, {"text": "Préparer aux applications en science des données et ingénierie.", "icon": "data"}]}, {"id": 714, "title": "Physique avancée", "category": "Prépa", "formulas": ["Lagrangien L = T − V", "Équations d’Euler-Lagrange"], "details": "La physique avancée étudie les systèmes mécaniques complexes.", "images": ["physique_prepa.png"], "correspondances": [{"id": 410, "title": "Énergie"}, {"id": 407, "title": "Ondes"}], "tags": ["prepa", "physique"], "niveau": "prepa", "definition": "Cette notion synthétise la physique avancée au niveau prépa, centrée sur la mécanique analytique (lagrangien, équations d'Euler-Lagrange) qui unifie et généralise la mécanique newtonienne.", "explication_formules": "Le lagrangien L=T-V (énergie cinétique moins énergie potentielle) contient toute l'information dynamique d'un système. Les équations d'Euler-Lagrange, dérivées d'un principe variationnel, redonnent les équations du mouvement de Newton mais s'adaptent bien mieux aux systèmes complexes ou contraints.", "approfondissements": [{"label": "Équations de Hamilton (formulation alternative)", "link": {"type": "theme", "slug": "equations-de-hamilton-formulation-alternative"}}, {"label": "Coordonnées généralisées et contraintes", "link": {"type": "theme", "slug": "coordonnees-generalisees-et-contraintes"}}, {"label": "Symétries et lois de conservation (Noether)", "link": {"type": "theme", "slug": "symetries-et-lois-de-conservation-noether"}}, {"label": "Applications à la mécanique céleste", "link": {"type": "theme", "slug": "applications-a-la-mecanique-celeste"}}, {"label": "Passage à la mécanique quantique", "link": {"type": "notion", "id": 420}}], "sous_points": [{"terme": "Mécanique analytique", "definition": "La mécanique analytique (lagrangienne, hamiltonienne) reformule la dynamique classique à partir de principes variationnels."}, {"terme": "Oscillateurs", "definition": "Un oscillateur harmonique suit une équation différentielle x''+ω²x=0, modèle de référence de tout mouvement périodique."}, {"terme": "Champs", "definition": "Un champ associe une grandeur physique à chaque point de l'espace, comme le champ électrique ou gravitationnel."}], "applications_list": [{"text": "Résoudre les problèmes de mécanique avancée aux concours de physique.", "icon": "physics"}, {"text": "Préparer aux formulations modernes de la physique théorique.", "icon": "physics"}]}, {"id": 715, "title": "Informatique théorique", "category": "Prépa", "formulas": ["P, NP, NP‑complet", "Automates, grammaires"], "details": "L’informatique théorique étudie les limites du calcul.", "images": ["info_theorique.png"], "correspondances": [{"id": 510, "title": "Complexité algorithmique"}, {"id": 513, "title": "Automates"}], "tags": ["prepa", "informatique"], "niveau": "prepa", "definition": "Cette notion synthétise l'informatique théorique au niveau prépa, couvrant complexité algorithmique et théorie des langages formels, désormais intégrées au programme des classes préparatoires.", "explication_formules": "P, NP et NP-complet classifient les problèmes selon leur difficulté de résolution algorithmique. Les automates et grammaires formalisent rigoureusement la reconnaissance et la génération de langages, base de l'informatique théorique enseignée en prépa.", "approfondissements": [{"label": "Complexité des algorithmes classiques", "link": {"type": "theme", "slug": "complexite-des-algorithmes-classiques"}}, {"label": "Automates finis et expressions régulières", "link": {"type": "theme", "slug": "automates-finis-et-expressions-regulieres"}}, {"label": "Problèmes NP-complets classiques", "link": {"type": "theme", "slug": "problemes-np-complets-classiques"}}, {"label": "Récursivité et structures de données (programme prépa)", "link": {"type": "notion", "id": 501}}, {"label": "Applications aux exercices de concours (informatique)", "link": {"type": "theme", "slug": "applications-aux-exercices-de-concours-informatique"}}], "sous_points": [{"terme": "Automates", "definition": "Les automates reconnaissent les langages formels selon leur complexité, du plus simple (fini) au plus général (machine de Turing)."}, {"terme": "Langages", "definition": "Un langage formel est un ensemble de mots construits selon des règles précises (une grammaire)."}, {"terme": "Complexité", "definition": "La complexité algorithmique classe les problèmes selon les ressources (temps, mémoire) nécessaires à leur résolution."}], "applications_list": [{"text": "Résoudre les exercices d'informatique théorique aux concours.", "icon": "computer"}, {"text": "Préparer aux enseignements d'informatique fondamentale du supérieur.", "icon": "education"}]}, {"id": 11, "title": "Suites et séries numériques", "category": "Analyse", "formulas": ["Critère de Cauchy", "Séries de Riemann : Σ1/n^α converge ssi α>1", "Critère de d'Alembert"], "details": "Étude de la convergence des suites et séries réelles.", "images": ["series.png"], "correspondances": [{"id": 12, "title": "Théorèmes fondamentaux de l'analyse"}, {"id": 9, "title": "Séries entières"}], "tags": ["analyse", "series"], "niveau": "prepa", "definition": "Cette notion regroupe les critères permettant de savoir si une suite ou une série (somme infinie de termes) converge vers une limite finie ou diverge.", "explication_formules": "Le critère de Cauchy dit qu'une suite converge si ses termes deviennent arbitrairement proches les uns des autres. Les séries de Riemann Σ1/nᵅ convergent seulement si α>1 : c'est un exemple de référence auquel on compare d'autres séries.", "approfondissements": [{"label": "Critère de d'Alembert et de Cauchy", "link": {"type": "theme", "slug": "critere-de-d-alembert-et-de-cauchy"}}, {"label": "Séries alternées et critère de Leibniz", "link": {"type": "theme", "slug": "series-alternees-et-critere-de-leibniz"}}, {"label": "Convergence absolue vs semi-convergence", "link": {"type": "theme", "slug": "convergence-absolue-vs-semi-convergence"}}, {"label": "Séries de fonctions et convergence uniforme", "link": {"type": "theme", "slug": "series-de-fonctions-et-convergence-uniforme"}}, {"label": "Théorème de Bolzano-Weierstrass", "link": {"type": "theme", "slug": "theoreme-de-bolzano-weierstrass"}}], "sous_points": [{"terme": "Théorème de Bolzano-Weierstrass", "definition": "Ce théorème garantit que toute suite bornée de nombres réels possède une sous-suite convergente, même si la suite entière ne converge pas."}, {"terme": "Séries alternées (Leibniz)", "definition": "Une série alternée change de signe à chaque terme ; le critère de Leibniz garantit sa convergence dès que les termes décroissent vers zéro."}], "applications_list": [{"text": "Vérifier qu'un algorithme itératif comme Newton-Raphson converge bien.", "icon": "computer"}, {"text": "Vérifier qu'une série de perturbation utilisée en physique a un sens mathématique.", "icon": "physics"}]}, {"id": 12, "title": "Théorèmes fondamentaux de l'analyse", "category": "Analyse", "formulas": ["Théorème de Rolle", "TAF : f(b)-f(a)=f'(c)(b-a)", "Théorème des valeurs intermédiaires"], "details": "Résultats clés reliant dérivée et comportement global d'une fonction.", "images": ["taf.png"], "correspondances": [{"id": 11, "title": "Suites et séries numériques"}, {"id": 10, "title": "Développements limités"}], "tags": ["analyse", "derivation"], "niveau": "prepa", "definition": "Ces théorèmes relient le comportement local d'une fonction (sa dérivée) à son comportement global (ses variations sur un intervalle) — le socle de toute l'analyse différentielle.", "explication_formules": "Le théorème de Rolle dit que si f(a)=f(b), il existe un point où la tangente est horizontale. Le théorème des accroissements finis (TAF) généralise cela : f(b)-f(a)=f'(c)(b-a) pour un certain c entre a et b.", "approfondissements": [{"label": "Formule de Taylor-Lagrange", "link": {"type": "theme", "slug": "formule-de-taylor-lagrange"}}, {"label": "Théorème de Darboux", "link": {"type": "theme", "slug": "theoreme-de-darboux"}}, {"label": "Inégalité des accroissements finis", "link": {"type": "theme", "slug": "inegalite-des-accroissements-finis"}}, {"label": "Convexité et dérivée seconde", "link": {"type": "theme", "slug": "convexite-et-derivee-seconde"}}, {"label": "Théorème de la bijection", "link": {"type": "theme", "slug": "theoreme-de-la-bijection"}}], "sous_points": [{"terme": "Formule de Taylor-Lagrange", "definition": "Cette formule approxime une fonction par un polynôme et exprime précisément l'erreur commise à l'aide de la dérivée évaluée en un point intermédiaire inconnu."}, {"terme": "Formule de Taylor-Young", "definition": "Cette version de la formule de Taylor donne l'erreur sous forme d'un petit terme négligeable (o), sans préciser explicitement le point intermédiaire."}], "applications_list": [{"text": "Prouver qu'une fonction est croissante ou décroissante à partir du signe de sa dérivée.", "icon": "research"}, {"text": "Majorer une erreur d'approximation.", "icon": "research"}, {"text": "Justifier les méthodes numériques de résolution d'équations.", "icon": "computer"}]}, {"id": 13, "title": "Intégrale de Riemann", "category": "Analyse", "formulas": ["∫ₐᵇ f(x)dx = F(b)-F(a)", "Intégration par parties", "Changement de variable"], "details": "Construction et calcul de l'intégrale au sens de Riemann.", "images": ["riemann.png"], "correspondances": [{"id": 14, "title": "Fonctions de plusieurs variables"}, {"id": 7, "title": "Séries de Fourier"}], "tags": ["analyse", "integration"], "niveau": "prepa", "definition": "L'intégrale de Riemann formalise rigoureusement le calcul d'aire sous une courbe en découpant l'intervalle en petits rectangles dont on fait tendre la largeur vers zéro.", "explication_formules": "∫ₐᵇf(x)dx=F(b)-F(a) relie intégrale et primitive (théorème fondamental de l'analyse). L'intégration par parties transforme l'intégrale d'un produit en une autre intégrale souvent plus simple, en utilisant la dérivée d'un des deux facteurs.", "approfondissements": [{"label": "Intégrales généralisées et convergence", "link": {"type": "theme", "slug": "integrales-generalisees-et-convergence"}}, {"label": "Intégration des fractions rationnelles", "link": {"type": "theme", "slug": "integration-des-fractions-rationnelles"}}, {"label": "Intégrale de Lebesgue", "link": {"type": "theme", "slug": "integrale-de-lebesgue"}}, {"label": "Calcul de volumes de révolution", "link": {"type": "theme", "slug": "calcul-de-volumes-de-revolution"}}, {"label": "Intégrales à paramètre", "link": {"type": "theme", "slug": "integrales-a-parametre"}}], "sous_points": [{"terme": "Intégrales généralisées", "definition": "Une intégrale généralisée porte sur un intervalle infini ou une fonction non bornée, définie comme limite d'intégrales sur des intervalles finis."}, {"terme": "Critères de convergence", "definition": "Ces critères (comparaison, équivalent) permettent de déterminer si une intégrale généralisée converge sans nécessairement calculer sa valeur exacte."}], "applications_list": [{"text": "Calculer le travail d'une force variable en physique.", "icon": "physics"}, {"text": "Calculer la masse totale d'un objet à densité variable.", "icon": "physics"}, {"text": "Calculer la valeur moyenne d'une grandeur sur un intervalle de temps.", "icon": "data"}]}, {"id": 14, "title": "Fonctions de plusieurs variables", "category": "Analyse", "formulas": ["Gradient ∇f", "Théorème de Schwarz : ∂²f/∂x∂y=∂²f/∂y∂x", "Multiplicateurs de Lagrange"], "details": "Différentiabilité et extrema pour les fonctions à plusieurs variables.", "images": ["multivar.png"], "correspondances": [{"id": 15, "title": "Équations différentielles linéaires"}, {"id": 703, "title": "Séries de fonctions"}, {"key": "sup:102", "title": "Matrice d'une application linéaire", "raison": "La différentielle df(a) est l'application linéaire qui approche f près de a ; sa matrice dans les bases canoniques est la matrice jacobienne."}, {"key": "sup:541", "title": "Variétés différentielles : définition", "raison": "Par le théorème des fonctions implicites, {f=0} est une sous-variété là où df est de rang maximal : courbes, surfaces et variétés se décrivent par des équations."}, {"key": "sup:1240", "title": "Vecteurs aléatoires et matrice de covariance", "raison": "Pour Y=φ(X) avec φ un difféomorphisme, la densité de Y s'obtient par changement de variables : f_Y(y) = f_X(φ^(-1)(y)) · |det Dφ^(-1)(y)|."}, {"key": "sup:1769", "title": "Mécanique analytique et formalisme lagrangien (introduction culturelle)", "raison": "Le lagrangien L(q,q') est une fonction de plusieurs variables : annuler ses dérivées partielles donne les équations d'Euler–Lagrange, d/dt(∂L/∂q') = ∂L/∂q."}, {"key": "sup:1243", "title": "Méthode de Newton pour la résolution d'équations", "raison": "La méthode de Newton en plusieurs variables résout f(x)=0 par x_(k+1) = x_k − J(x_k)^(-1) f(x_k), où J est la matrice jacobienne."}], "tags": ["analyse", "optimisation"], "niveau": "prepa", "definition": "Cette branche étend la dérivation aux fonctions dépendant de plusieurs variables (comme la température en fonction de x, y et z), en étudiant comment elles varient dans chaque direction.", "explication_formules": "Le gradient ∇f regroupe toutes les dérivées partielles et indique la direction de plus forte croissance. Le théorème de Schwarz dit que l'ordre de dérivation par rapport à deux variables différentes n'a pas d'importance. Les multiplicateurs de Lagrange trouvent des extrema sous contrainte.", "approfondissements": [{"label": "Théorème des fonctions implicites", "link": {"type": "theme", "slug": "theoreme-des-fonctions-implicites"}}, {"label": "Matrice hessienne et extrema", "link": {"type": "theme", "slug": "matrice-hessienne-et-extrema"}}, {"label": "Théorème d'inversion locale", "link": {"type": "theme", "slug": "theoreme-d-inversion-locale"}}, {"label": "Multiplicateurs de Lagrange et KKT", "link": {"type": "theme", "slug": "multiplicateurs-de-lagrange-et-kkt"}}, {"label": "Champs de vecteurs (gradient, divergence, rotationnel)", "link": {"type": "theme", "slug": "champs-de-vecteurs-gradient-divergence-rotationnel"}}], "sous_points": [{"terme": "Matrice hessienne", "definition": "Cette matrice regroupe toutes les dérivées secondes d'une fonction à plusieurs variables ; son signe en un point critique révèle s'il s'agit d'un minimum, maximum ou col."}, {"terme": "Théorème des fonctions implicites", "definition": "Ce théorème garantit que, sous certaines conditions, une relation F(x,y)=0 définit localement y comme une fonction de x, même sans formule explicite."}], "applications_list": [{"text": "Optimiser un trajet ou une production sous contrainte de budget.", "icon": "finance"}, {"text": "Modéliser une surface météorologique (pression, température).", "icon": "environment"}, {"text": "Entraîner un réseau de neurones par descente de gradient.", "icon": "computer"}]}, {"id": 15, "title": "Équations différentielles linéaires", "category": "Analyse", "formulas": ["y'+a(x)y=b(x)", "Équation caractéristique : ar²+br+c=0", "X'=AX ⟹ X(t)=exp(tA)X₀"], "details": "Résolution des équations différentielles linéaires d'ordre 1 et 2.", "images": ["ed_lineaires.png"], "correspondances": [{"id": 6, "title": "Équations différentielles"}, {"id": 16, "title": "Transformées intégrales"}, {"key": "sup:205", "title": "Diagonalisation des matrices symétriques (spectral)", "raison": "Par séparation des variables, on décompose sur les fonctions propres du laplacien (Δφ=−λφ) : l'équation de la chaleur devient u_k' = −λ_k u_k, de solutions e^(−λ_k t)."}, {"key": "sup:573", "title": "Géodésiques et spectre du Laplacien", "raison": "Le laplacien de Laplace–Beltrami généralise Δ aux variétés riemanniennes : chaleur, ondes et problème de Dirichlet s'y posent, et son spectre encode la géométrie."}, {"key": "sup:598", "title": "Mouvement brownien", "raison": "Si B est un mouvement brownien, u(t,x)=E[f(x+B_t)] résout ∂_t u = ½ ∂_x² u avec u(0,·)=f : les solutions de l'EDP sont des espérances."}, {"key": "sup:1577", "title": "Équation des ondes : formule de d'Alembert", "raison": "L'équation des ondes ∂_t² u = c² ∂_x² u a pour solution générale f(x−ct)+g(x+ct) : deux ondes progressives, l'une vers la droite, l'autre vers la gauche (d'Alembert)."}, {"key": "sup:1672", "title": "Discrétisation d'une EDP elliptique", "raison": "Différences finies et éléments finis remplacent l'EDP par un grand système linéaire, résolu par des algorithmes itératifs."}], "tags": ["analyse", "equations-differentielles"], "niveau": "prepa", "definition": "Une équation différentielle linéaire relie une fonction inconnue et ses dérivées de façon linéaire (sans produit entre la fonction et ses dérivées), ce qui permet de la résoudre systématiquement.", "explication_formules": "y'+a(x)y=b(x) se résout par la méthode du facteur intégrant. Pour l'équation d'ordre 2 à coefficients constants, on résout l'équation caractéristique ar²+br+c=0 ; les racines donnent la forme des solutions. Un système X'=AX se résout via l'exponentielle de matrice.", "approfondissements": [{"label": "Théorème de Cauchy-Lipschitz", "link": {"type": "theme", "slug": "theoreme-de-cauchy-lipschitz"}}, {"label": "Résolution par transformée de Laplace", "link": {"type": "theme", "slug": "resolution-par-transformee-de-laplace"}}, {"label": "Systèmes différentiels et exponentielle de matrice", "link": {"type": "theme", "slug": "systemes-differentiels-et-exponentielle-de-matrice"}}, {"label": "Stabilité et portraits de phase", "link": {"type": "theme", "slug": "stabilite-et-portraits-de-phase"}}, {"label": "Équations non linéaires (Bernoulli, Riccati)", "link": {"type": "theme", "slug": "equations-non-lineaires-bernoulli-riccati"}}], "sous_points": [{"terme": "Théorème de Cauchy-Lipschitz", "definition": "Sous une condition de régularité, ce théorème garantit l'existence et l'unicité de la solution d'une équation différentielle pour une condition initiale donnée."}, {"terme": "Wronskien de deux solutions", "definition": "Le Wronskien, un déterminant construit à partir de deux solutions et de leurs dérivées, permet de tester si elles sont linéairement indépendantes."}], "applications_list": [{"text": "Modéliser un circuit RLC (résistance, inductance, condensateur).", "icon": "electronics"}, {"text": "Modéliser un système masse-ressort avec amortissement.", "icon": "physics"}, {"text": "Modéliser la croissance couplée de plusieurs espèces en écologie.", "icon": "environment"}]}, {"id": 16, "title": "Transformées intégrales", "category": "Analyse", "formulas": ["Laplace : L{f}(s)=∫f(t)e^{-st}dt", "Fourier : f̂(ξ)=∫f(x)e^{-2iπxξ}dx", "Théorème de convolution"], "details": "Outils pour résoudre équations différentielles et analyser des signaux.", "images": ["transformees.png"], "correspondances": [{"id": 15, "title": "Équations différentielles linéaires"}, {"id": 7, "title": "Séries de Fourier"}], "tags": ["analyse", "transformees"], "niveau": "prepa", "definition": "Les transformées intégrales (Laplace, Fourier) convertissent une fonction ou une équation différentielle en une autre représentation où les calculs deviennent souvent algébriques et plus simples.", "explication_formules": "La transformée de Laplace L{f}(s)=∫f(t)e^{-st}dt transforme dérivation en multiplication par s, changeant une équation différentielle en équation algébrique. Le théorème de convolution dit que la transformée d'un produit de convolution est le produit des transformées.", "approfondissements": [{"label": "Formule d'inversion de Bromwich", "link": {"type": "theme", "slug": "formule-d-inversion-de-bromwich"}}, {"label": "Fonction de transfert en automatique", "link": {"type": "theme", "slug": "fonction-de-transfert-en-automatique"}}, {"label": "Transformée de Fourier discrète (DFT/FFT)", "link": {"type": "theme", "slug": "transformee-de-fourier-discrete-dft-fft"}}, {"label": "Distributions et transformée de Dirac", "link": {"type": "theme", "slug": "distributions-et-transformee-de-dirac"}}, {"label": "Applications aux EDP (chaleur, ondes)", "link": {"type": "theme", "slug": "applications-aux-edp-chaleur-ondes"}}], "sous_points": [{"terme": "Formule d'inversion", "definition": "Cette formule permet de retrouver la fonction d'origine à partir de sa transformée (de Laplace ou de Fourier), inversant l'opération de transformation."}, {"terme": "Théorème de Plancherel", "definition": "Ce théorème dit que la transformée de Fourier préserve l'énergie totale d'un signal, établissant un lien précis entre une fonction et son spectre."}], "applications_list": [{"text": "Analyser la réponse d'un système électronique à une impulsion.", "icon": "electronics"}, {"text": "Concevoir des filtres de traitement du signal.", "icon": "communication"}, {"text": "Résoudre des équations différentielles complexes en ingénierie.", "icon": "industry"}]}, {"id": 17, "title": "Topologie générale", "category": "Analyse", "formulas": ["Espace métrique (E,d)", "Compacité : de tout recouvrement ouvert on extrait un sous-recouvrement fini", "Théorème du point fixe de Banach"], "details": "Cadre abstrait pour la continuité, la convergence et la compacité.", "images": ["topologie.png"], "correspondances": [{"id": 701, "title": "Espaces métriques"}, {"id": 702, "title": "Topologie"}], "tags": ["analyse", "topologie"], "niveau": "grandes-ecoles", "definition": "La topologie générale étudie les notions de proximité, de continuité et de convergence dans un cadre abstrait, au-delà du simple plan ou de l'espace usuel.", "explication_formules": "Un espace métrique (E,d) munit un ensemble d'une notion de distance. La compacité (tout recouvrement ouvert admet un sous-recouvrement fini) généralise l'idée d'un ensemble 'fermé et borné'. Le théorème du point fixe de Banach garantit qu'une fonction contractante a un unique point fixe.", "approfondissements": [{"label": "Compacité et théorème de Heine-Borel", "link": {"type": "theme", "slug": "compacite-et-theoreme-de-heine-borel"}}, {"label": "Connexité et connexité par arcs", "link": {"type": "theme", "slug": "connexite-et-connexite-par-arcs"}}, {"label": "Théorème de Baire", "link": {"type": "theme", "slug": "theoreme-de-baire"}}, {"label": "Topologie produit et topologie quotient", "link": {"type": "theme", "slug": "topologie-produit-et-topologie-quotient"}}, {"label": "Espaces complets et théorème du point fixe", "link": {"type": "theme", "slug": "espaces-complets-et-theoreme-du-point-fixe"}}], "sous_points": [{"terme": "Connexité", "definition": "Un espace est connexe s'il ne peut pas être séparé en deux morceaux disjoints ouverts non vides, c'est-à-dire s'il forme un seul bloc."}, {"terme": "Complétude", "definition": "Un espace est complet si toute suite de Cauchy (dont les termes se rapprochent indéfiniment) y converge effectivement, sans aucun « trou »."}, {"terme": "Théorème de Baire", "definition": "Dans un espace métrique complet, une intersection dénombrable d'ouverts denses reste dense, un résultat abstrait aux conséquences profondes en analyse."}], "applications_list": [{"text": "Garantir la convergence d'algorithmes itératifs de résolution numérique.", "icon": "computer"}, {"text": "Fonder rigoureusement l'analyse fonctionnelle utilisée en apprentissage automatique.", "icon": "computer"}]}, {"id": 18, "title": "Mesure et intégrale de Lebesgue", "category": "Analyse", "formulas": ["Théorème de convergence dominée", "Lemme de Fatou", "Théorème de Fubini-Tonelli"], "details": "Généralisation de l'intégrale de Riemann par la théorie de la mesure.", "images": ["lebesgue.png"], "correspondances": [{"id": 13, "title": "Intégrale de Riemann"}, {"id": 19, "title": "Espaces de Hilbert et opérateurs"}, {"key": "sup:1027", "title": "Cardinal d'un ensemble fini et dénombrabilité", "raison": "La mesure de Lebesgue est σ-additive, c'est-à-dire additive pour les réunions dénombrables : tout ensemble dénombrable, comme ℚ, est de mesure nulle."}, {"key": "sup:1611", "title": "Théorème de Stokes (version générale sur les variétés)", "raison": "Intégrer sur une variété revient à intégrer des formes différentielles dans des cartes ; la formule de Stokes ∫_M dω = ∫_(∂M) ω unifie les théorèmes de Green, de Gauss et de Stokes."}, {"key": "sup:1420", "title": "Espérance comme intégrale de Lebesgue", "raison": "L'espérance E[X] est l'intégrale de X par rapport à la probabilité P : elle unifie le cas discret (une somme) et le cas à densité (une intégrale)."}, {"key": "sup:1149", "title": "Méthode de Monte-Carlo : introduction", "raison": "La méthode de Monte-Carlo approche ∫ f dμ par la moyenne des f(X_i) sur des tirages indépendants : la loi des grands nombres garantit la convergence, avec une erreur en 1/√n."}], "tags": ["analyse", "mesure"], "niveau": "grandes-ecoles", "definition": "La mesure et l'intégrale de Lebesgue généralisent l'intégrale de Riemann en découpant selon les valeurs de la fonction plutôt que selon son domaine, ce qui permet d'intégrer des fonctions bien plus irrégulières.", "explication_formules": "Le théorème de convergence dominée permet d'échanger limite et intégrale sous des hypothèses très générales. Le lemme de Fatou donne une inégalité utile même sans convergence dominée. Le théorème de Fubini-Tonelli permet de calculer une intégrale double en intégrant successivement sur chaque variable.", "approfondissements": [{"label": "Espaces Lᵖ et inégalité de Hölder", "link": {"type": "theme", "slug": "espaces-l-et-inegalite-de-holder"}}, {"label": "Théorème de Radon-Nikodym", "link": {"type": "theme", "slug": "theoreme-de-radon-nikodym"}}, {"label": "Mesures de probabilité", "link": {"type": "theme", "slug": "mesures-de-probabilite"}}, {"label": "Convergence presque partout vs en mesure", "link": {"type": "theme", "slug": "convergence-presque-partout-vs-en-mesure"}}, {"label": "Intégration sur des variétés", "link": {"type": "theme", "slug": "integration-sur-des-varietes"}}], "sous_points": [{"terme": "Espaces Lᵖ", "definition": "Ces espaces regroupent les fonctions dont la puissance p-ième est intégrable, généralisant la notion de fonction « de taille finie »."}, {"terme": "Inégalités de Hölder et Minkowski", "definition": "Ces inégalités bornent respectivement l'intégrale d'un produit et la norme d'une somme de fonctions, outils essentiels de l'analyse fonctionnelle."}], "applications_list": [{"text": "Fonder rigoureusement les probabilités continues.", "icon": "data"}, {"text": "Manipuler des signaux irréguliers en traitement du signal.", "icon": "communication"}]}, {"id": 19, "title": "Espaces de Hilbert et opérateurs", "category": "Analyse", "formulas": ["Inégalité de Cauchy-Schwarz : |<x,y>|≤||x||·||y||", "Théorème de projection orthogonale", "Théorème de représentation de Riesz"], "details": "Analyse fonctionnelle dans les espaces à produit scalaire complets.", "images": ["hilbert.png"], "correspondances": [{"id": 708, "title": "Espaces de Hilbert"}, {"id": 18, "title": "Mesure et intégrale de Lebesgue"}, {"key": "sup:1473", "title": "Espaces hermitiens", "raison": "En dimension finie, tout espace euclidien ou hermitien est complet donc de Hilbert : l'algèbre linéaire est le cas fini de la théorie."}, {"key": "sup:205", "title": "Diagonalisation des matrices symétriques (spectral)", "raison": "Le théorème spectral prolonge la diagonalisation : un opérateur auto-adjoint compact se diagonalise dans une base hilbertienne, avec des valeurs propres réelles qui tendent vers 0."}, {"key": "sup:1584", "title": "Formulation variationnelle et méthode de Galerkine", "raison": "Pour −Δu=f avec conditions au bord, le théorème de représentation de Riesz (Lax–Milgram) donne une unique solution faible dans H^1_0 : l'EDP se ramène à trouver un représentant de Riesz dans un espace de Hilbert."}, {"key": "sup:1600", "title": "Intégrale stochastique d'Itô", "raison": "L'intégrale d'Itô est construite comme une isométrie entre espaces L² : E[(∫_0^t H dB)²] = E[∫_0^t H² ds]."}, {"key": "sup:799", "title": "Opérateurs auto-adjoints en mécanique quantique", "raison": "En dimension infinie, l'espace des états est L²(ℝ) ; position, impulsion et énergie sont des opérateurs auto-adjoints, et |ψ(x)|² est la densité de probabilité de présence."}, {"key": "sup:210", "title": "Diagonalisation des matrices hermitiennes", "raison": "En dimension finie, un opérateur auto-adjoint est représenté par une matrice hermitienne (A = A*) ; le théorème spectral dit qu'elle est diagonalisable dans une base orthonormée, à valeurs propres réelles."}, {"key": "sup:111", "title": "Produit scalaire", "raison": "Un opérateur T est auto-adjoint si (Tu|v) = (u|Tv) pour tout u,v : la notion dépend entièrement du produit scalaire choisi, et ses sous-espaces propres associés à des valeurs propres distinctes sont orthogonaux."}, {"id": 420, "title": "Mécanique quantique", "raison": "En mécanique quantique, une observable (position, impulsion, énergie) est représentée par un opérateur auto-adjoint sur un espace de Hilbert ; ses valeurs propres sont les résultats de mesure possibles."}, {"key": "sup:1337", "title": "Analyse en composantes principales (introduction)", "raison": "La matrice de covariance d'un jeu de données est symétrique réelle, donc auto-adjointe : le théorème spectral la diagonalise dans une base orthonormée de vecteurs propres, les axes principaux de l'ACP."}], "tags": ["analyse", "hilbert"], "niveau": "grandes-ecoles", "definition": "Un espace de Hilbert est un espace vectoriel muni d'un produit scalaire et complet (sans 'trou'), qui généralise la géométrie euclidienne à des dimensions infinies, notamment aux espaces de fonctions.", "explication_formules": "L'inégalité de Cauchy-Schwarz borne le produit scalaire par le produit des normes. Le théorème de projection orthogonale garantit qu'on peut toujours projeter un point sur un sous-espace fermé de façon unique. Le théorème de Riesz identifie les formes linéaires continues à des produits scalaires.", "approfondissements": [{"label": "Bases hilbertiennes et séries de Fourier", "link": {"type": "notion", "id": 7}}, {"label": "Opérateurs bornés et compacts", "link": {"type": "theme", "slug": "operateurs-bornes-et-compacts"}}, {"label": "Théorème spectral pour opérateurs auto-adjoints", "link": {"type": "theme", "slug": "theoreme-spectral-pour-operateurs-auto-adjoints"}}, {"label": "Espaces de Sobolev", "link": {"type": "theme", "slug": "espaces-de-sobolev"}}, {"label": "Applications à la mécanique quantique", "link": {"type": "notion", "id": 420}}], "sous_points": [{"terme": "Bases hilbertiennes", "definition": "Une base hilbertienne est un ensemble orthonormé complet de vecteurs (ou fonctions) permettant de décomposer tout élément de l'espace, comme les fonctions sinus/cosinus pour Fourier."}, {"terme": "Opérateurs bornés et compacts", "definition": "Un opérateur borné ne peut pas amplifier indéfiniment un vecteur ; un opérateur compact, plus contraint, transforme les ensembles bornés en ensembles quasi-finis."}], "applications_list": [{"text": "Fonder mathématiquement la mécanique quantique.", "icon": "physics"}, {"text": "Fonder le traitement du signal via les séries de Fourier dans L².", "icon": "communication"}, {"text": "Fonder les méthodes de moindres carrés en statistique.", "icon": "data"}]}, {"id": 20, "title": "Analyse complexe avancée", "category": "Analyse", "formulas": ["Formule intégrale de Cauchy", "Théorème des résidus", "Développement en série de Laurent"], "details": "Étude des fonctions holomorphes et de leurs propriétés remarquables.", "images": ["analyse_complexe_av.png"], "correspondances": [{"id": 8, "title": "Analyse complexe"}, {"id": 705, "title": "Analyse complexe (niveau prépa)"}], "tags": ["analyse", "complexe"], "niveau": "grandes-ecoles", "definition": "Cette notion approfondit l'analyse complexe avec des outils puissants (résidus, séries de Laurent) qui permettent de calculer des intégrales et de comprendre le comportement des fonctions autour de leurs singularités.", "explication_formules": "La formule intégrale de Cauchy exprime la valeur d'une fonction holomorphe en tout point à partir de son comportement sur un contour qui l'entoure. Le théorème des résidus permet de calculer une intégrale de contour comme une simple somme de résidus, souvent bien plus facile à évaluer.", "approfondissements": [{"label": "Classification des singularités (pôles, essentielles)", "link": {"type": "theme", "slug": "classification-des-singularites-poles-essentielles"}}, {"label": "Théorème de Rouché", "link": {"type": "theme", "slug": "theoreme-de-rouche"}}, {"label": "Fonctions méromorphes", "link": {"type": "theme", "slug": "fonctions-meromorphes"}}, {"label": "Prolongement analytique", "link": {"type": "theme", "slug": "prolongement-analytique"}}, {"label": "Représentation conforme de Riemann", "link": {"type": "theme", "slug": "representation-conforme-de-riemann"}}], "sous_points": [{"terme": "Conditions de Cauchy-Riemann", "definition": "Ces deux équations aux dérivées partielles caractérisent exactement les fonctions holomorphes, reliant dérivabilité complexe et propriétés des parties réelle et imaginaire."}, {"terme": "Théorème de Liouville", "definition": "Ce théorème dit qu'une fonction entière (holomorphe sur tout ℂ) et bornée est nécessairement constante — un résultat très restrictif propre au complexe."}], "applications_list": [{"text": "Calculer des intégrales réelles difficiles en passant par le plan complexe.", "icon": "research"}, {"text": "Application très utilisée en physique théorique.", "icon": "physics"}, {"text": "Application très utilisée en traitement du signal.", "icon": "communication"}]}, {"id": 21, "title": "Distributions et espaces de Sobolev", "category": "Analyse", "formulas": ["Dérivée au sens des distributions", "Distribution de Dirac δ", "Espace de Sobolev Wᵏ,ᵖ"], "details": "Généralisation des fonctions permettant de dériver des objets non dérivables classiquement.", "images": ["sobolev.png"], "correspondances": [{"id": 22, "title": "Équations aux dérivées partielles"}, {"id": 18, "title": "Mesure et intégrale de Lebesgue"}], "tags": ["analyse", "distributions"], "niveau": "grandes-ecoles", "definition": "Les distributions généralisent la notion de fonction pour pouvoir 'dériver' des objets qui ne sont pas dérivables au sens classique, comme un signal avec un saut brutal.", "explication_formules": "La distribution de Dirac δ représente une impulsion infiniment concentrée en un point, utile pour modéliser un choc instantané. Les espaces de Sobolev Wᵏ,ᵖ mesurent la régularité d'une fonction en contrôlant ses dérivées au sens des distributions.", "approfondissements": [{"label": "Injections de Sobolev", "link": {"type": "theme", "slug": "injections-de-sobolev"}}, {"label": "Formulation faible des EDP", "link": {"type": "theme", "slug": "formulation-faible-des-edp"}}, {"label": "Convolution de distributions", "link": {"type": "theme", "slug": "convolution-de-distributions"}}, {"label": "Transformée de Fourier des distributions", "link": {"type": "theme", "slug": "transformee-de-fourier-des-distributions"}}, {"label": "Applications aux éléments finis", "link": {"type": "theme", "slug": "applications-aux-elements-finis"}}], "sous_points": [{"terme": "Injections de Sobolev", "definition": "Ces théorèmes garantissent qu'une fonction suffisamment régulière au sens de Sobolev l'est aussi au sens classique, un pont essentiel entre les deux notions de régularité."}, {"terme": "Formulation faible des EDP", "definition": "Réécrire une équation aux dérivées partielles sous forme intégrale (testée contre des fonctions quelconques) permet de définir des solutions même quand la solution classique n'existe pas."}], "applications_list": [{"text": "Modéliser une force impulsionnelle en mécanique.", "icon": "physics"}, {"text": "Modéliser un signal électrique très bref.", "icon": "electronics"}, {"text": "Formuler rigoureusement les EDP utilisées en ingénierie.", "icon": "industry"}]}, {"id": 22, "title": "Équations aux dérivées partielles", "category": "Analyse", "formulas": ["Équation de la chaleur : ∂u/∂t=Δu", "Équation des ondes : ∂²u/∂t²=c²Δu", "Équation de Laplace : Δu=0"], "details": "Modélisation de phénomènes physiques par des équations impliquant plusieurs dérivées partielles.", "images": ["edp.png"], "correspondances": [{"id": 21, "title": "Distributions et espaces de Sobolev"}, {"id": 714, "title": "Physique avancée"}, {"key": "sup:205", "title": "Diagonalisation des matrices symétriques (spectral)", "raison": "Sur une chaîne discrétisée, l'équation devient u' = −Lu avec L symétrique positive : le théorème spectral donne u(t) = e^(−tL) u(0) en diagonalisant L dans une base orthonormée."}, {"key": "sup:954", "title": "Flot de Ricci (EDP)", "raison": "Le flot de Ricci ∂_t g = −2 Ric(g) est une équation de type chaleur pour la métrique : il lisse la courbure comme la chaleur lisse la température, ce qui a servi à Perelman pour la conjecture de Poincaré."}, {"key": "sup:598", "title": "Mouvement brownien", "raison": "La densité de B_t est le noyau de la chaleur : u(t,x) = E[f(x+B_t)] résout ∂_t u = ½ ∂_x² u avec u(0,·) = f ; les solutions de l'EDP sont des espérances."}, {"key": "sup:1674", "title": "Schémas aux différences finies pour l'équation de la chaleur", "raison": "Discrétiser ∂_t u = ∂_x² u par un schéma explicite aux différences finies n'est stable que si Δt ≤ Δx²/2 : le pas de temps est contraint par le pas d'espace."}], "tags": ["analyse", "edp"], "niveau": "grandes-ecoles", "definition": "Les équations aux dérivées partielles (EDP) relient une fonction de plusieurs variables à ses dérivées partielles : elles décrivent l'évolution de phénomènes physiques dans l'espace et le temps.", "explication_formules": "L'équation de la chaleur ∂u/∂t=Δu décrit la diffusion thermique. L'équation des ondes ∂²u/∂t²=c²Δu décrit la propagation d'une perturbation (son, lumière, vibration). L'équation de Laplace Δu=0 caractérise les états d'équilibre (potentiel électrique, température stationnaire).", "approfondissements": [{"label": "Séparation des variables", "link": {"type": "theme", "slug": "separation-des-variables"}}, {"label": "Fonction de Green", "link": {"type": "theme", "slug": "fonction-de-green"}}, {"label": "Formulation variationnelle et éléments finis", "link": {"type": "theme", "slug": "formulation-variationnelle-et-elements-finis"}}, {"label": "Équations de Navier-Stokes", "link": {"type": "theme", "slug": "equations-de-navier-stokes"}}, {"label": "Méthode des caractéristiques", "link": {"type": "theme", "slug": "methode-des-caracteristiques"}}], "sous_points": [{"terme": "Séparation des variables", "definition": "Cette technique cherche une solution sous forme de produit de fonctions d'une seule variable chacune, transformant l'EDP en plusieurs équations différentielles ordinaires."}, {"terme": "Fonction de Green", "definition": "La fonction de Green donne la réponse d'un système à une impulsion ponctuelle, permettant de reconstruire la solution générale par superposition."}], "applications_list": [{"text": "Simuler la propagation de la chaleur dans un matériau.", "icon": "industry"}, {"text": "Simuler la propagation du son ou de la lumière.", "icon": "audio"}, {"text": "Modéliser la diffusion d'un polluant dans l'atmosphère ou l'eau.", "icon": "environment"}]}, {"id": 23, "title": "Calcul des variations et optimisation", "category": "Analyse", "formulas": ["Équations d'Euler-Lagrange", "Conditions de Karush-Kuhn-Tucker (KKT)", "Multiplicateurs de Lagrange"], "details": "Recherche d'extrema de fonctionnelles et sous contraintes.", "images": ["variations.png"], "correspondances": [{"id": 14, "title": "Fonctions de plusieurs variables"}, {"id": 714, "title": "Physique avancée"}, {"key": "sup:206", "title": "Formes quadratiques et réduction de Gauss", "raison": "Une forme quadratique est convexe si et seulement si elle est positive : sa signature (réduction de Gauss, loi d'inertie de Sylvester) dit si un problème quadratique admet un minimum."}, {"key": "sup:251", "title": "Matrice hessienne", "raison": "Une fonction de classe C² est convexe si et seulement si sa hessienne est positive en tout point ; en un point critique, une hessienne définie positive donne un minimum local strict."}, {"key": "sup:351", "title": "Maximum de vraisemblance", "raison": "Pour les modèles exponentiels (gaussien, binomial, Poisson), l'opposé de la log-vraisemblance est convexe : l'estimateur du maximum de vraisemblance résout un problème d'optimisation convexe."}], "tags": ["analyse", "optimisation"], "niveau": "grandes-ecoles", "definition": "Le calcul des variations cherche à optimiser une quantité globale (comme une distance ou une énergie) qui dépend d'une fonction entière plutôt que d'un simple nombre.", "explication_formules": "Les équations d'Euler-Lagrange donnent la condition qu'une fonction doit vérifier pour minimiser ou maximiser une quantité globale — c'est l'équivalent de 'dérivée nulle' mais pour des fonctionnelles. Les conditions KKT généralisent cela à l'optimisation sous contraintes.", "approfondissements": [{"label": "Principe de moindre action en physique", "link": {"type": "theme", "slug": "principe-de-moindre-action-en-physique"}}, {"label": "Multiplicateurs de Lagrange", "link": {"type": "theme", "slug": "multiplicateurs-de-lagrange"}}, {"label": "Dualité de Fenchel-Rockafellar", "link": {"type": "theme", "slug": "dualite-de-fenchel-rockafellar"}}, {"label": "Méthode directe du calcul des variations", "link": {"type": "theme", "slug": "methode-directe-du-calcul-des-variations"}}, {"label": "Applications à l'apprentissage automatique", "link": {"type": "notion", "id": 530}}], "sous_points": [{"terme": "Dualité lagrangienne", "definition": "La dualité lagrangienne associe à un problème d'optimisation sous contraintes un problème « dual » souvent plus facile à résoudre, avec le même optimum sous conditions."}, {"terme": "Méthode directe du calcul des variations", "definition": "Cette méthode prouve l'existence d'un minimiseur d'une fonctionnelle en exploitant la compacité et la semi-continuité, sans le calculer explicitement."}], "applications_list": [{"text": "Trouver le trajet le plus rapide entre deux points (principe de Fermat en optique).", "icon": "navigation"}, {"text": "Concevoir la forme d'un pont minimisant les contraintes.", "icon": "construction"}, {"text": "Entraîner un modèle d'apprentissage automatique sous contraintes.", "icon": "computer"}]}, {"id": 24, "title": "Fonctions spéciales (Gamma, Bêta, Zêta)", "category": "Analyse", "formulas": ["Γ(x)=∫₀^∞ t^{x-1}e^{-t}dt", "Γ(n+1)=n!", "ζ(s)=Σ1/n^s"], "details": "Fonctions définies par des intégrales ou séries généralisant factorielle et sommes classiques.", "images": ["fonctions_speciales.png"], "correspondances": [{"id": 20, "title": "Analyse complexe avancée"}, {"id": 11, "title": "Suites et séries numériques"}], "tags": ["analyse", "fonctions-speciales"], "niveau": "grandes-ecoles", "definition": "Ces fonctions spéciales (Gamma, Bêta, Zêta) prolongent des opérations discrètes classiques (factorielle, sommes) à des valeurs continues ou complexes, révélant des liens profonds entre analyse et arithmétique.", "explication_formules": "La fonction Gamma Γ(x) prolonge la factorielle aux nombres non entiers, avec Γ(n+1)=n! pour les entiers. La fonction zêta de Riemann ζ(s)=Σ1/nˢ encode des informations profondes sur la répartition des nombres premiers, notamment via l'hypothèse de Riemann.", "approfondissements": [{"label": "Formule des compléments et prolongement de Γ", "link": {"type": "theme", "slug": "formule-des-complements-et-prolongement-de"}}, {"label": "Équation fonctionnelle de ζ", "link": {"type": "theme", "slug": "equation-fonctionnelle-de"}}, {"label": "Hypothèse de Riemann", "link": {"type": "theme", "slug": "hypothese-de-riemann"}}, {"label": "Fonction Bêta et lois de probabilité", "link": {"type": "theme", "slug": "fonction-beta-et-lois-de-probabilite"}}, {"label": "Nombres de Bernoulli", "link": {"type": "theme", "slug": "nombres-de-bernoulli"}}], "sous_points": [{"terme": "Prolongement analytique", "definition": "Le prolongement analytique étend le domaine de définition d'une fonction holomorphe au-delà de sa définition initiale, de façon unique."}, {"terme": "Valeur ζ(2)=π²/6", "definition": "Cette valeur remarquable de la fonction zêta de Riemann, découverte par Euler, relie de façon surprenante les entiers, les carrés et le nombre π."}], "applications_list": [{"text": "Calculer des probabilités dans des lois continues (Gamma, χ²).", "icon": "data"}, {"text": "Modéliser des phénomènes en physique statistique.", "icon": "physics"}, {"text": "Intervenir en théorie des nombres et en cryptographie.", "icon": "security"}]}, {"id": 121, "title": "Arithmétique avancée", "category": "Algèbre", "formulas": ["Théorème de Bézout : au+bv=pgcd(a,b)", "Petit théorème de Fermat : a^p≡a (mod p)", "Théorème chinois des restes"], "details": "Résultats fondamentaux de la théorie des nombres.", "images": ["arithmetique_av.png"], "correspondances": [{"id": 113, "title": "Arithmétique modulaire"}, {"id": 114, "title": "Cryptographie"}], "tags": ["algebre", "arithmetique"], "niveau": "prepa", "definition": "L'arithmétique avancée regroupe les résultats fondamentaux qui régissent la divisibilité et les nombres premiers entre eux, à la base de toute la théorie des nombres moderne.", "explication_formules": "Le théorème de Bézout dit que le PGCD de deux nombres s'écrit toujours comme combinaison entière des deux nombres (au+bv). Le petit théorème de Fermat donne a^p≡a (mod p) pour p premier, un résultat surprenant et très utile.", "approfondissements": [{"label": "Algorithme d'Euclide étendu", "link": {"type": "theme", "slug": "algorithme-d-euclide-etendu"}}, {"label": "Théorème chinois des restes", "link": {"type": "theme", "slug": "theoreme-chinois-des-restes"}}, {"label": "Théorème d'Euler et indicatrice φ", "link": {"type": "theme", "slug": "theoreme-d-euler-et-indicatrice"}}, {"label": "Tests de primalité", "link": {"type": "theme", "slug": "tests-de-primalite"}}, {"label": "Équations diophantiennes", "link": {"type": "notion", "id": 609}}], "sous_points": [{"terme": "Théorème d'Euler", "definition": "Ce théorème généralise le petit théorème de Fermat : a^φ(n)≡1 (mod n) si a est premier avec n."}, {"terme": "Indicatrice φ", "definition": "L'indicatrice d'Euler φ(n) compte le nombre d'entiers entre 1 et n qui sont premiers avec n, une fonction centrale en arithmétique modulaire."}], "applications_list": [{"text": "Vérifier rapidement la primalité de très grands nombres.", "icon": "security"}, {"text": "Résoudre des équations à solutions entières.", "icon": "research"}, {"text": "Fonder les tests de sécurité informatique.", "icon": "security"}]}, {"id": 122, "title": "Structures algébriques : groupes, anneaux, corps", "category": "Algèbre", "formulas": ["Groupe (G,*)", "Sous-groupe, morphisme de groupes", "Théorème de Lagrange : |H| divise |G|"], "details": "Cadre axiomatique commun à de nombreuses structures mathématiques.", "images": ["structures.png"], "correspondances": [{"id": 110, "title": "Groupes"}, {"id": 111, "title": "Anneaux"}], "tags": ["algebre", "structures"], "niveau": "prepa", "definition": "Cette notion présente le triptyque fondamental de l'algèbre abstraite (groupes, anneaux, corps) qui classe les structures selon les opérations qu'elles autorisent et leurs propriétés.", "explication_formules": "Un groupe n'a qu'une opération, un anneau en a deux (dont une sans inverse garanti), un corps a deux opérations totalement inversibles (sauf 0). Le théorème de Lagrange (|H| divise |G|) illustre la rigidité imposée par ces structures.", "approfondissements": [{"label": "Morphismes et isomorphismes", "link": {"type": "theme", "slug": "morphismes-et-isomorphismes"}}, {"label": "Groupes quotients et théorèmes d'isomorphisme", "link": {"type": "theme", "slug": "groupes-quotients-et-theoremes-d-isomorphisme"}}, {"label": "Idéaux et anneaux quotients", "link": {"type": "theme", "slug": "ideaux-et-anneaux-quotients"}}, {"label": "Extensions de corps", "link": {"type": "theme", "slug": "extensions-de-corps"}}, {"label": "Classification des structures finies", "link": {"type": "theme", "slug": "classification-des-structures-finies"}}], "sous_points": [{"terme": "Groupes quotients", "definition": "Un groupe quotient G/H « efface » les différences internes à un sous-groupe distingué H, produisant une structure plus simple."}, {"terme": "Idéaux", "definition": "Un idéal permet de construire un anneau quotient en identifiant tous ses éléments à zéro, généralisant l'arithmétique modulaire."}, {"terme": "Corps de fractions", "definition": "Le corps de fractions d'un anneau intègre plonge celui-ci dans un corps, comme ℤ se plonge dans ℚ."}], "applications_list": [{"text": "Servir de langage commun à la cryptographie (groupes et corps finis).", "icon": "security"}, {"text": "Structurer le codage via les anneaux de polynômes.", "icon": "computer"}, {"text": "Décrire les groupes de symétrie en physique théorique.", "icon": "physics"}]}, {"id": 123, "title": "Réduction des endomorphismes", "category": "Algèbre", "formulas": ["Polynôme caractéristique : χ_A(λ)=det(A−λI)", "Théorème de Cayley-Hamilton", "Réduction de Jordan"], "details": "Simplification de la représentation matricielle des applications linéaires.", "images": ["reduction.png"], "correspondances": [{"id": 107, "title": "Valeurs propres"}, {"id": 108, "title": "Diagonalisation"}, {"key": "sup:219", "title": "Systèmes différentiels linéaires par diagonalisation", "raison": "Pour X'=AX, diagonaliser A découple le système en équations x_i' = λ_i x_i, de solutions e^(λ_i t) : le signe de Re(λ_i) décide de la stabilité."}, {"key": "sup:1430", "title": "Courbure de Gauss d'une surface", "raison": "En un point d'une surface, les courbures principales sont les valeurs propres de l'endomorphisme de Weingarten ; leur produit est la courbure de Gauss."}, {"key": "sup:1337", "title": "Analyse en composantes principales (introduction)", "raison": "L'analyse en composantes principales diagonalise la matrice de covariance des données : les axes principaux sont ses vecteurs propres, classés par variance décroissante."}, {"key": "sup:1730", "title": "Valeurs propres numériques : méthode de la puissance itérée", "raison": "La méthode de la puissance itérée calcule la valeur propre dominante en multipliant un vecteur par A de façon répétée ; la convergence est gouvernée par le rapport |λ₂/λ₁|."}, {"id": 406, "title": "Oscillations", "raison": "Les modes propres d'un système de ressorts couplés sont les vecteurs propres de la matrice de raideur (pondérée par les masses) ; les fréquences propres sont les racines carrées des valeurs propres."}, {"key": "sup:1506", "title": "Mesure stationnaire d'une chaîne de Markov", "raison": "Une loi stationnaire π (πP=π) est un vecteur propre à gauche de la matrice de transition, pour la valeur propre 1 ; le trou spectral règle la vitesse de convergence vers l'équilibre."}, {"key": "sup:220", "title": "Décomposition en valeurs singulières (SVD)", "raison": "Pour une matrice symétrique, la SVD coïncide avec la diagonalisation usuelle (U = V) ; en général, A = UΣVᵀ généralise la réduction des endomorphismes aux matrices non carrées ou non diagonalisables."}], "tags": ["algebre", "reduction"], "niveau": "prepa", "definition": "Réduire un endomorphisme (une transformation linéaire d'un espace dans lui-même), c'est trouver la représentation la plus simple possible de cette transformation, généralement via ses valeurs propres.", "explication_formules": "Le polynôme caractéristique χ_A(λ)=det(A-λI) a pour racines les valeurs propres. Le théorème de Cayley-Hamilton dit qu'une matrice 'annule' toujours son propre polynôme caractéristique — un résultat étonnant et très utilisé.", "approfondissements": [{"label": "Lemme des noyaux", "link": {"type": "theme", "slug": "lemme-des-noyaux"}}, {"label": "Trigonalisation", "link": {"type": "theme", "slug": "trigonalisation"}}, {"label": "Réduction de Jordan pour matrices non diagonalisables", "link": {"type": "theme", "slug": "reduction-de-jordan-pour-matrices-non-diagonalisables"}}, {"label": "Polynôme minimal", "link": {"type": "theme", "slug": "polynome-minimal"}}, {"label": "Applications aux systèmes différentiels", "link": {"type": "theme", "slug": "applications-aux-systemes-differentiels"}}], "sous_points": [{"terme": "Sous-espaces propres", "definition": "Le sous-espace propre associé à une valeur propre λ regroupe tous les vecteurs propres associés à λ, plus le vecteur nul."}, {"terme": "Polynôme minimal", "definition": "Le polynôme minimal d'une matrice est le polynôme unitaire de plus petit degré qui l'annule, et il détermine sa diagonalisabilité."}], "applications_list": [{"text": "Simplifier le calcul de grandes puissances de matrices.", "icon": "computer"}, {"text": "Analyser la stabilité de systèmes physiques ou économiques.", "icon": "finance"}, {"text": "Comprendre le comportement asymptotique d'un algorithme itératif.", "icon": "computer"}]}, {"id": 124, "title": "Espaces euclidiens et hermitiens", "category": "Algèbre", "formulas": ["Procédé de Gram-Schmidt", "Matrices orthogonales : AᵀA=I", "Théorème spectral (matrices symétriques réelles)"], "details": "Espaces vectoriels munis d'un produit scalaire, réel ou complexe.", "images": ["euclidiens.png"], "correspondances": [{"id": 123, "title": "Réduction des endomorphismes"}, {"id": 203, "title": "Produit scalaire"}, {"key": "sup:481", "title": "Espaces de Hilbert", "raison": "Un espace de Hilbert est un espace euclidien ou hermitien complet : projections orthogonales, bases orthonormées et théorème de Pythagore se prolongent en dimension infinie."}, {"key": "sup:544", "title": "Variétés riemanniennes", "raison": "Une métrique riemannienne munit chaque espace tangent d'un produit scalaire qui varie avec le point : longueurs, angles et volumes se calculent alors sur une variété courbe."}, {"key": "sup:1590", "title": "Espérance conditionnelle : définition rigoureuse", "raison": "Dans L², la variance est le carré d'une norme et E[X] la meilleure approximation constante de X ; plus généralement, l'espérance conditionnelle E[X | 𝒢] est la projection orthogonale de X sur les variables 𝒢-mesurables."}, {"key": "sup:799", "title": "Opérateurs auto-adjoints en mécanique quantique", "raison": "L'état d'un système quantique à n niveaux est un vecteur unitaire de ℂ^n muni du produit hermitien ; la probabilité de trouver le système dans l'état φ vaut |(φ|ψ)|²."}, {"key": "sup:1250", "title": "Approximation au sens des moindres carrés", "raison": "Les moindres carrés cherchent la projection orthogonale de y sur l'espace engendré par les colonnes de X : β=(X^T X)^(-1) X^T y lorsque X^T X est inversible."}], "tags": ["algebre", "euclidien"], "niveau": "prepa", "definition": "Un espace euclidien (ou hermitien, en complexe) est un espace vectoriel muni d'un produit scalaire, ce qui permet d'y mesurer des longueurs, des angles et l'orthogonalité.", "explication_formules": "Le procédé de Gram-Schmidt construit systématiquement une base orthonormée à partir de n'importe quelle base. Les matrices orthogonales (AᵀA=I) préservent les longueurs et les angles : ce sont exactement les rotations et réflexions.", "approfondissements": [{"label": "Théorème spectral (matrices symétriques)", "link": {"type": "theme", "slug": "theoreme-spectral-matrices-symetriques"}}, {"label": "Projections orthogonales", "link": {"type": "theme", "slug": "projections-orthogonales"}}, {"label": "Espaces hermitiens (cas complexe)", "link": {"type": "theme", "slug": "espaces-hermitiens-cas-complexe"}}, {"label": "Décomposition QR", "link": {"type": "theme", "slug": "decomposition-qr"}}, {"label": "Applications à la mécanique quantique (opérateurs hermitiens)", "link": {"type": "notion", "id": 420}}], "sous_points": [{"terme": "Projections orthogonales", "definition": "La projection orthogonale d'un vecteur sur un sous-espace en donne l'élément le plus proche, un outil central des problèmes de moindres carrés."}, {"terme": "Diagonalisation des matrices symétriques", "definition": "Toute matrice symétrique réelle est diagonalisable dans une base orthonormée de vecteurs propres, un résultat central de l'algèbre euclidienne."}], "applications_list": [{"text": "Compresser des données en préservant au mieux l'information (ACP).", "icon": "data"}, {"text": "Effectuer des rotations en infographie 3D.", "icon": "art"}, {"text": "Résoudre des problèmes de moindres carrés en statistique.", "icon": "data"}]}, {"id": 125, "title": "Théorie de Galois", "category": "Algèbre", "formulas": ["Extension de corps K⊂L", "Groupe de Galois Gal(L/K)", "Théorème d'Abel-Ruffini"], "details": "Étude des extensions de corps via leurs groupes de symétries.", "images": ["galois.png"], "correspondances": [{"id": 122, "title": "Structures algébriques : groupes, anneaux, corps"}, {"id": 102, "title": "Polynômes"}], "tags": ["algebre", "galois"], "niveau": "grandes-ecoles", "definition": "La théorie de Galois relie la résolution des équations polynomiales aux symétries de leurs racines, en associant à chaque équation un groupe qui encode sa complexité algébrique.", "explication_formules": "Le groupe de Galois Gal(L/K) regroupe les symétries d'une extension de corps qui préservent le corps de base. Le théorème d'Abel-Ruffini montre qu'une équation de degré 5 ou plus n'est en général pas résoluble par radicaux (racines carrées, cubiques, etc.).", "approfondissements": [{"label": "Correspondance de Galois", "link": {"type": "theme", "slug": "correspondance-de-galois"}}, {"label": "Groupes résolubles", "link": {"type": "theme", "slug": "groupes-resolubles"}}, {"label": "Constructions à la règle et au compas", "link": {"type": "theme", "slug": "constructions-a-la-regle-et-au-compas"}}, {"label": "Extensions séparables et normales", "link": {"type": "theme", "slug": "extensions-separables-et-normales"}}, {"label": "Applications à la théorie des codes", "link": {"type": "theme", "slug": "applications-a-la-theorie-des-codes"}}], "sous_points": [{"terme": "Correspondance de Galois", "definition": "Ce théorème établit une bijection exacte entre les sous-groupes du groupe de Galois d'une extension et les corps intermédiaires de cette extension."}, {"terme": "Résolubilité par radicaux", "definition": "Une équation est résoluble par radicaux si ses solutions s'expriment à l'aide de racines carrées, cubiques, etc. ; cela dépend de la structure de son groupe de Galois."}], "applications_list": [{"text": "Expliquer pourquoi certaines constructions à la règle et au compas sont impossibles.", "icon": "research"}, {"text": "Fonder la théorie moderne des codes correcteurs.", "icon": "computer"}, {"text": "Fonder la cryptographie avancée.", "icon": "security"}]}, {"id": 126, "title": "Modules et algèbre homologique", "category": "Algèbre", "formulas": ["Module libre", "Théorème de structure des modules de type fini sur un anneau principal", "Suite exacte courte"], "details": "Généralisation des espaces vectoriels sur un anneau quelconque.", "images": ["modules.png"], "correspondances": [{"id": 123, "title": "Réduction des endomorphismes"}, {"id": 111, "title": "Anneaux"}], "tags": ["algebre", "modules"], "niveau": "grandes-ecoles", "definition": "Les modules généralisent les espaces vectoriels en remplaçant le corps des scalaires par un simple anneau, ce qui produit une théorie plus riche mais aussi plus subtile (pas toujours de base).", "explication_formules": "Le théorème de structure des modules de type fini sur un anneau principal généralise la diagonalisation des matrices et explique la réduction de Jordan sous un angle plus profond, via une décomposition en facteurs invariants.", "approfondissements": [{"label": "Modules libres et de type fini", "link": {"type": "theme", "slug": "modules-libres-et-de-type-fini"}}, {"label": "Foncteurs Ext et Tor", "link": {"type": "theme", "slug": "foncteurs-ext-et-tor"}}, {"label": "Suites exactes courtes et longues", "link": {"type": "theme", "slug": "suites-exactes-courtes-et-longues"}}, {"label": "Modules projectifs et injectifs", "link": {"type": "theme", "slug": "modules-projectifs-et-injectifs"}}, {"label": "Applications à la réduction de Jordan", "link": {"type": "theme", "slug": "applications-a-la-reduction-de-jordan"}}], "sous_points": [{"terme": "Foncteurs Ext et Tor", "definition": "Ces outils de l'algèbre homologique mesurent le défaut d'exactitude de certaines opérations sur les modules, révélant une information algébrique cachée."}, {"terme": "Modules projectifs et injectifs", "definition": "Ces modules ont des propriétés qui facilitent le prolongement ou la factorisation de morphismes, jouant un rôle clé en algèbre homologique."}], "applications_list": [{"text": "Comprendre la classification des groupes abéliens finis.", "icon": "research"}, {"text": "Fournir le cadre théorique de la topologie algébrique.", "icon": "research"}]}, {"id": 127, "title": "Représentations de groupes finis", "category": "Algèbre", "formulas": ["Caractère : χ(g)=Tr(ρ(g))", "Lemme de Schur", "Théorème de Maschke"], "details": "Étude des groupes finis via leurs actions linéaires.", "images": ["representations.png"], "correspondances": [{"id": 110, "title": "Groupes"}, {"id": 122, "title": "Structures algébriques : groupes, anneaux, corps"}], "tags": ["algebre", "representations"], "niveau": "grandes-ecoles", "definition": "Une représentation d'un groupe fini associe à chaque élément du groupe une matrice, de façon à transformer les symétries abstraites du groupe en objets linéaires concrets et calculables.", "explication_formules": "Le caractère χ(g)=Tr(ρ(g)) résume l'information essentielle d'une représentation sans avoir à connaître toute la matrice. Le théorème de Maschke garantit que toute représentation se décompose en briques élémentaires (irréductibles) quand l'ordre du groupe est premier avec la caractéristique.", "approfondissements": [{"label": "Lemme de Schur", "link": {"type": "theme", "slug": "lemme-de-schur"}}, {"label": "Table de caractères", "link": {"type": "theme", "slug": "table-de-caracteres"}}, {"label": "Relations d'orthogonalité des caractères", "link": {"type": "theme", "slug": "relations-d-orthogonalite-des-caracteres"}}, {"label": "Représentations induites", "link": {"type": "theme", "slug": "representations-induites"}}, {"label": "Applications à la physique des particules", "link": {"type": "theme", "slug": "applications-a-la-physique-des-particules"}}], "sous_points": [{"terme": "Table de caractères", "definition": "Une table de caractères résume toute l'information sur les représentations irréductibles d'un groupe fini en un tableau de nombres."}, {"terme": "Relations d'orthogonalité", "definition": "Les caractères des représentations irréductibles vérifient des relations d'orthogonalité, un outil puissant pour décomposer n'importe quelle représentation."}], "applications_list": [{"text": "Analyser les modes de vibration d'une molécule en chimie quantique.", "icon": "chemistry"}, {"text": "Classifier les particules élémentaires en physique.", "icon": "physics"}]}, {"id": 128, "title": "Formes quadratiques et bilinéaires", "category": "Algèbre", "formulas": ["Réduction de Gauss", "Signature (p,q)", "Loi d'inertie de Sylvester"], "details": "Étude des formes quadratiques et de leur classification.", "images": ["formes_quad.png"], "correspondances": [{"id": 109, "title": "Formes quadratiques"}, {"id": 124, "title": "Espaces euclidiens et hermitiens"}], "tags": ["algebre", "formes"], "niveau": "grandes-ecoles", "definition": "Cette notion approfondit l'étude des formes quadratiques et des formes bilinéaires symétriques associées, en particulier leur classification via la signature, indépendante du choix de base.", "explication_formules": "La réduction de Gauss transforme systématiquement une forme quadratique en somme de carrés. La loi d'inertie de Sylvester garantit que le nombre de carrés positifs et négatifs obtenus est toujours le même, quelle que soit la méthode de réduction utilisée.", "approfondissements": [{"label": "Réduction simultanée de deux formes", "link": {"type": "theme", "slug": "reduction-simultanee-de-deux-formes"}}, {"label": "Formes définies positives et convexité", "link": {"type": "theme", "slug": "formes-definies-positives-et-convexite"}}, {"label": "Théorème de Witt", "link": {"type": "theme", "slug": "theoreme-de-witt"}}, {"label": "Applications aux statistiques multivariées", "link": {"type": "theme", "slug": "applications-aux-statistiques-multivariees"}}, {"label": "Groupes orthogonaux et symplectiques", "link": {"type": "theme", "slug": "groupes-orthogonaux-et-symplectiques"}}], "sous_points": [{"terme": "Formes définies positives", "definition": "Une forme quadratique définie positive ne s'annule qu'en zéro et reste toujours strictement positive ailleurs, condition d'un minimum local strict."}, {"terme": "Matrices congruentes", "definition": "Deux matrices symétriques sont congruentes si elles représentent la même forme quadratique dans des bases différentes."}], "applications_list": [{"text": "Classifier les coniques et quadriques en géométrie.", "icon": "research"}, {"text": "Déterminer la nature d'un point critique en optimisation.", "icon": "research"}, {"text": "Étudier la stabilité énergétique d'un système physique.", "icon": "physics"}]}, {"id": 129, "title": "Algèbre tensorielle et multilinéaire", "category": "Algèbre", "formulas": ["Produit tensoriel V⊗W", "Formes multilinéaires alternées", "Déterminant comme forme n-linéaire alternée"], "details": "Construction d'objets combinant plusieurs espaces vectoriels.", "images": ["tenseurs.png"], "correspondances": [{"id": 105, "title": "Déterminant"}, {"id": 124, "title": "Espaces euclidiens et hermitiens"}, {"key": "sup:545", "title": "Tenseur métrique", "raison": "La métrique riemannienne g_ij est un tenseur, c'est-à-dire un élément du produit tensoriel E*⊗E* (formes bilinéaires sur l'espace tangent) : le produit tensoriel formalise la notion intuitive de tenseur utilisée en géométrie."}, {"key": "sup:335", "title": "Indépendance (variables continues)", "raison": "Si X et Y sont indépendantes, leur densité jointe se factorise f_(X,Y)(x,y) = f_X(x)·f_Y(y) : c'est le produit tensoriel des densités marginales, comme l'espace de deux qubits indépendants est le produit tensoriel de leurs espaces individuels."}, {"id": 420, "title": "Mécanique quantique", "raison": "L'espace des états de n qubits est le produit tensoriel de n espaces à 2 dimensions, ℂ²⊗...⊗ℂ² = ℂ^(2ⁿ) : cette croissance exponentielle fonde la puissance du calcul quantique ; l'intrication est un état qui ne se factorise pas en produit de facteurs."}], "tags": ["algebre", "tenseurs"], "niveau": "grandes-ecoles", "definition": "L'algèbre tensorielle construit des objets combinant plusieurs espaces vectoriels à la fois (les tenseurs), qui généralisent vecteurs, matrices et déterminants dans un cadre unifié.", "explication_formules": "Le produit tensoriel V⊗W combine deux espaces en un plus grand. Une forme multilinéaire alternée change de signe quand on échange deux arguments ; le déterminant en est l'exemple le plus important, vu comme une forme n-linéaire alternée sur les colonnes d'une matrice.", "approfondissements": [{"label": "Algèbre extérieure et formes différentielles", "link": {"type": "theme", "slug": "algebre-exterieure-et-formes-differentielles"}}, {"label": "Algèbre symétrique", "link": {"type": "theme", "slug": "algebre-symetrique"}}, {"label": "Tenseurs en physique (contraintes, courbure)", "link": {"type": "theme", "slug": "tenseurs-en-physique-contraintes-courbure"}}, {"label": "Produit tensoriel en informatique quantique", "link": {"type": "theme", "slug": "produit-tensoriel-en-informatique-quantique"}}, {"label": "Tenseurs et apprentissage profond", "link": {"type": "theme", "slug": "tenseurs-et-apprentissage-profond"}}], "sous_points": [{"terme": "Algèbre extérieure", "definition": "L'algèbre extérieure construit des objets antisymétriques (formes différentielles), essentiels pour généraliser l'intégration et le théorème de Stokes."}, {"terme": "Algèbre symétrique", "definition": "L'algèbre symétrique construit, à partir d'un espace vectoriel, l'espace de tous les polynômes possibles sur cet espace."}], "applications_list": [{"text": "Décrire les contraintes en mécanique des milieux continus.", "icon": "industry"}, {"text": "Représenter la courbure en relativité générale.", "icon": "space"}, {"text": "Structurer les calculs des réseaux de neurones profonds.", "icon": "computer"}]}, {"id": 130, "title": "Corps finis et applications", "category": "Algèbre", "formulas": ["𝔽_q avec q=p^n", "Groupe multiplicatif 𝔽_q* cyclique", "Polynômes cyclotomiques"], "details": "Corps ayant un nombre fini d'éléments, essentiels en cryptographie.", "images": ["corps_finis.png"], "correspondances": [{"id": 112, "title": "Corps"}, {"id": 520, "title": "Cryptographie avancée"}], "tags": ["algebre", "corps-finis"], "niveau": "grandes-ecoles", "definition": "Un corps fini contient un nombre fini d'éléments (toujours une puissance d'un nombre premier) et possède néanmoins toutes les propriétés d'un corps classique, avec des applications très concrètes.", "explication_formules": "𝔽_q existe pour q=pⁿ (p premier). Son groupe multiplicatif 𝔽_q* (les éléments non nuls) est toujours cyclique, une propriété remarquable qui simplifie énormément les calculs et est exploitée en cryptographie.", "approfondissements": [{"label": "Polynômes cyclotomiques", "link": {"type": "theme", "slug": "polynomes-cyclotomiques"}}, {"label": "Codes correcteurs (Reed-Solomon)", "link": {"type": "theme", "slug": "codes-correcteurs-reed-solomon"}}, {"label": "Courbes elliptiques sur corps finis", "link": {"type": "theme", "slug": "courbes-elliptiques-sur-corps-finis"}}, {"label": "Théorie de Galois des corps finis", "link": {"type": "theme", "slug": "theorie-de-galois-des-corps-finis"}}, {"label": "Applications à la cryptographie moderne", "link": {"type": "theme", "slug": "applications-a-la-cryptographie-moderne"}}], "sous_points": [{"terme": "Codes correcteurs", "definition": "Ces codes, construits à partir de polynômes sur un corps fini, corrigent efficacement les erreurs de transmission (CD, QR codes, satellites)."}, {"terme": "Applications à la cryptographie", "definition": "Les corps finis fournissent les problèmes difficiles (logarithme discret sur courbes elliptiques) qui sécurisent une grande partie de la cryptographie moderne."}], "applications_list": [{"text": "Construire les codes correcteurs des CD, QR codes et communications satellite.", "icon": "communication"}, {"text": "Fonder la cryptographie sur courbes elliptiques des cryptomonnaies.", "icon": "security"}]}, {"id": 131, "title": "Anneaux de polynômes et géométrie algébrique", "category": "Algèbre", "formulas": ["Théorème des zéros de Hilbert (Nullstellensatz)", "Idéaux premiers, idéaux maximaux", "Variétés algébriques"], "details": "Lien entre équations polynomiales et objets géométriques.", "images": ["anneaux_poly.png"], "correspondances": [{"id": 102, "title": "Polynômes"}, {"id": 126, "title": "Modules et algèbre homologique"}], "tags": ["algebre", "geometrie-algebrique"], "niveau": "grandes-ecoles", "definition": "Cette notion établit le pont entre équations polynomiales et objets géométriques : à chaque système d'équations correspond une 'forme' (variété algébrique) dans l'espace.", "explication_formules": "Le théorème des zéros de Hilbert (Nullstellensatz) établit une correspondance exacte entre idéaux d'un anneau de polynômes et sous-ensembles géométriques (variétés) qu'ils définissent — reliant algèbre pure et géométrie.", "approfondissements": [{"label": "Idéaux premiers et maximaux", "link": {"type": "theme", "slug": "ideaux-premiers-et-maximaux"}}, {"label": "Bases de Gröbner", "link": {"type": "theme", "slug": "bases-de-grobner"}}, {"label": "Anneaux principaux et factoriels", "link": {"type": "theme", "slug": "anneaux-principaux-et-factoriels"}}, {"label": "Variétés affines et projectives", "link": {"type": "theme", "slug": "varietes-affines-et-projectives"}}, {"label": "Applications à la cryptographie sur courbes", "link": {"type": "theme", "slug": "applications-a-la-cryptographie-sur-courbes"}}], "sous_points": [{"terme": "Anneaux principaux", "definition": "Un anneau principal a tous ses idéaux engendrés par un seul élément, une propriété qui simplifie considérablement son arithmétique."}, {"terme": "Anneaux factoriels", "definition": "Un anneau factoriel permet une décomposition unique en facteurs premiers (à l'ordre et aux unités près), comme dans ℤ."}, {"terme": "Bases de Gröbner", "definition": "Une base de Gröbner transforme un système d'équations polynomiales en une forme équivalente beaucoup plus facile à résoudre algorithmiquement."}], "applications_list": [{"text": "Fonder la géométrie algébrique moderne utilisée en cryptographie.", "icon": "security"}, {"text": "Structurer les calculs formels en informatique.", "icon": "computer"}]}, {"id": 132, "title": "Algèbres et groupes de Lie", "category": "Algèbre", "formulas": ["Crochet de Lie [X,Y]", "Algèbre 𝔰𝔩(n)", "Exponentielle de matrice exp(A)"], "details": "Structures algébriques associées aux groupes continus de symétries.", "images": ["lie.png"], "correspondances": [{"id": 127, "title": "Représentations de groupes finis"}, {"id": 123, "title": "Réduction des endomorphismes"}, {"key": "sup:1496", "title": "Groupe orthogonal O(n) et groupe spécial orthogonal SO(n)", "raison": "SO(n), le groupe des rotations de l'espace euclidien, est l'exemple le plus simple de groupe de Lie : un groupe qui est aussi une variété différentiable, sur laquelle les opérations de groupe sont lisses."}, {"key": "sup:578", "title": "Transformée de Fourier sur SU(2)", "raison": "L'analyse harmonique sur un groupe de Lie compact comme SU(2) généralise la transformée de Fourier classique : on décompose une fonction sur le groupe selon ses représentations irréductibles plutôt que sur les exponentielles e^(inθ)."}, {"id": 420, "title": "Mécanique quantique", "raison": "Le groupe SU(2), groupe de Lie des matrices unitaires 2×2 de déterminant 1, est le groupe de symétrie du spin d'une particule ; ses représentations irréductibles de dimension 2j+1 classent les états de spin j."}, {"key": "sup:535", "title": "Représentations unitaires", "raison": "Une représentation unitaire fait agir un groupe de Lie par des opérateurs unitaires sur un espace de Hilbert, ce qui préserve les probabilités en mécanique quantique (théorème de Wigner)."}], "tags": ["algebre", "lie"], "niveau": "grandes-ecoles", "definition": "Les algèbres et groupes de Lie décrivent les symétries continues (comme les rotations) en les 'linéarisant' au voisinage de la transformation identité, ce qui les rend beaucoup plus faciles à manipuler.", "explication_formules": "Le crochet de Lie [X,Y] mesure le défaut de commutation entre deux transformations infinitésimales. L'exponentielle de matrice exp(A) permet de reconstruire une transformation finie (comme une rotation complète) à partir de sa version infinitésimale.", "approfondissements": [{"label": "Classification de Cartan-Killing", "link": {"type": "theme", "slug": "classification-de-cartan-killing"}}, {"label": "Représentations des algèbres de Lie", "link": {"type": "theme", "slug": "representations-des-algebres-de-lie"}}, {"label": "Groupes de Lie compacts", "link": {"type": "theme", "slug": "groupes-de-lie-compacts"}}, {"label": "Applications à la physique des particules", "link": {"type": "theme", "slug": "applications-a-la-physique-des-particules"}}, {"label": "Groupes de jauge et interactions fondamentales", "link": {"type": "theme", "slug": "groupes-de-jauge-et-interactions-fondamentales"}}], "sous_points": [{"terme": "Représentations", "definition": "Représenter une algèbre de Lie par des matrices permet d'étudier concrètement les symétries continues qu'elle décrit."}, {"terme": "Classification de Cartan-Killing", "definition": "Cette classification répertorie toutes les algèbres de Lie simples possibles en quelques familles infinies et cinq cas exceptionnels."}], "applications_list": [{"text": "Décrire les symétries fondamentales de la mécanique classique.", "icon": "physics"}, {"text": "Décrire les groupes de jauge en physique des particules.", "icon": "physics"}, {"text": "Fonder la cinématique des bras articulés en robotique.", "icon": "robotics"}]}, {"id": 133, "title": "Théorie des nombres avancée", "category": "Algèbre", "formulas": ["Fonction indicatrice d'Euler φ(n)", "Théorème des nombres premiers : π(x)~x/ln(x)", "Fonction zêta de Riemann ζ(s)"], "details": "Étude approfondie des propriétés des entiers et des nombres premiers.", "images": ["nombres_av.png"], "correspondances": [{"id": 121, "title": "Arithmétique avancée"}, {"id": 24, "title": "Fonctions spéciales (Gamma, Bêta, Zêta)"}], "tags": ["algebre", "theorie-des-nombres"], "niveau": "grandes-ecoles", "definition": "Cette branche approfondie de la théorie des nombres étudie la répartition des nombres premiers et les fonctions qui en dérivent, à la croisée de l'algèbre et de l'analyse.", "explication_formules": "Le théorème des nombres premiers π(x)~x/ln(x) donne une estimation du nombre de nombres premiers inférieurs à x, montrant qu'ils se raréfient progressivement mais restent infinis. La fonction zêta de Riemann encode cette répartition de façon extrêmement précise.", "approfondissements": [{"label": "Fonctions arithmétiques (φ, Möbius)", "link": {"type": "theme", "slug": "fonctions-arithmetiques-mobius"}}, {"label": "Séries de Dirichlet", "link": {"type": "theme", "slug": "series-de-dirichlet"}}, {"label": "Théorème des nombres premiers", "link": {"type": "theme", "slug": "theoreme-des-nombres-premiers"}}, {"label": "Hypothèse de Riemann", "link": {"type": "theme", "slug": "hypothese-de-riemann"}}, {"label": "Applications à la cryptographie", "link": {"type": "theme", "slug": "applications-a-la-cryptographie"}}], "sous_points": [{"terme": "Fonctions arithmétiques", "definition": "Ces fonctions définies sur les entiers (comme φ ou la fonction de Möbius) encodent des propriétés de divisibilité et interviennent dans de nombreuses formules."}, {"terme": "Séries de Dirichlet", "definition": "Une série de Dirichlet Σaₙ/nˢ généralise la fonction zêta et encode des informations arithmétiques profondes sur la suite aₙ."}], "applications_list": [{"text": "Estimer la difficulté de factoriser de grands nombres (sécurité de RSA).", "icon": "security"}, {"text": "Fonder des algorithmes de test de primalité utilisés en cryptographie.", "icon": "security"}]}, {"id": 134, "title": "Cryptographie avancée (mathématiques)", "category": "Algèbre", "formulas": ["RSA : c≡mᵉ (mod n)", "Logarithme discret", "Courbes elliptiques : y²=x³+ax+b"], "details": "Fondements mathématiques de la sécurité des communications modernes.", "images": ["crypto_av.png"], "correspondances": [{"id": 114, "title": "Cryptographie"}, {"id": 130, "title": "Corps finis et applications"}], "tags": ["algebre", "crypto"], "niveau": "grandes-ecoles", "definition": "Cette notion approfondit les fondements mathématiques de la cryptographie moderne, notamment les problèmes considérés comme difficiles à résoudre qui garantissent la sécurité des communications.", "explication_formules": "RSA repose sur la difficulté de factoriser un grand nombre n=pq. Le logarithme discret consiste à retrouver x connaissant gˣ (mod n), problème réputé très difficile. Les courbes elliptiques y²=x³+ax+b offrent une sécurité équivalente à RSA avec des clés bien plus courtes.", "approfondissements": [{"label": "Cryptographie sur courbes elliptiques (ECC)", "link": {"type": "theme", "slug": "cryptographie-sur-courbes-elliptiques-ecc"}}, {"label": "Protocole de Diffie-Hellman", "link": {"type": "theme", "slug": "protocole-de-diffie-hellman"}}, {"label": "Cryptographie post-quantique", "link": {"type": "theme", "slug": "cryptographie-post-quantique"}}, {"label": "Fonctions à sens unique et preuves de connaissance", "link": {"type": "theme", "slug": "fonctions-a-sens-unique-et-preuves-de-connaissance"}}, {"label": "Attaques par factorisation et algorithme de Shor", "link": {"type": "theme", "slug": "attaques-par-factorisation-et-algorithme-de-shor"}}], "sous_points": [{"terme": "Diffie-Hellman", "definition": "Ce protocole permet à deux personnes de créer une clé secrète commune en échangeant seulement des informations publiques."}, {"terme": "Cryptographie sur courbes elliptiques", "definition": "Le groupe des points d'une courbe elliptique fournit un problème de logarithme discret particulièrement difficile, permettant une sécurité élevée avec des clés courtes."}], "applications_list": [{"text": "Sécuriser les transactions bancaires et les cryptomonnaies.", "icon": "finance"}, {"text": "Protéger les communications chiffrées de bout en bout.", "icon": "security"}, {"text": "Authentifier les connexions web sécurisées.", "icon": "security"}]}, {"id": 221, "title": "Géométrie différentielle des courbes", "category": "Géométrie", "formulas": ["Vecteur tangent unitaire", "Courbure κ", "Formules de Frenet"], "details": "Étude locale des courbes à l'aide de la dérivation.", "images": ["courbes_diff.png"], "correspondances": [{"id": 222, "title": "Géométrie différentielle des surfaces"}, {"id": 207, "title": "Trigonométrie"}], "tags": ["geometrie", "courbes"], "niveau": "grandes-ecoles", "definition": "La géométrie différentielle des courbes étudie la forme locale d'une courbe (à quel point elle 'tourne') en utilisant les outils du calcul différentiel plutôt que la géométrie classique.", "explication_formules": "Le vecteur tangent unitaire indique la direction instantanée de déplacement le long de la courbe. La courbure κ mesure à quelle vitesse cette direction change ; les formules de Frenet relient tangente, normale et binormale pour décrire complètement une courbe dans l'espace.", "approfondissements": [{"label": "Torsion et courbes gauches", "link": {"type": "theme", "slug": "torsion-et-courbes-gauches"}}, {"label": "Longueur d'arc et paramétrisation naturelle", "link": {"type": "theme", "slug": "longueur-d-arc-et-parametrisation-naturelle"}}, {"label": "Courbure et rayon osculateur", "link": {"type": "theme", "slug": "courbure-et-rayon-osculateur"}}, {"label": "Courbes de Bézier (CAO)", "link": {"type": "theme", "slug": "courbes-de-bezier-cao"}}, {"label": "Géodésiques sur une surface", "link": {"type": "theme", "slug": "geodesiques-sur-une-surface"}}], "sous_points": [{"terme": "Torsion", "definition": "La torsion mesure à quel point une courbe de l'espace s'écarte d'être plane, complétant la courbure pour la décrire complètement."}, {"terme": "Repère de Frenet dans l'espace", "definition": "Ce repère mobile (tangente, normale, binormale) accompagne un point le long d'une courbe et encode toute sa géométrie locale."}], "applications_list": [{"text": "Concevoir des routes et voies ferrées aux virages confortables.", "icon": "transport"}, {"text": "Programmer des trajectoires fluides en animation 3D.", "icon": "art"}, {"text": "Analyser la trajectoire d'un satellite.", "icon": "space"}]}, {"id": 222, "title": "Géométrie différentielle des surfaces", "category": "Géométrie", "formulas": ["Première forme fondamentale", "Courbure de Gauss K", "Theorema Egregium"], "details": "Étude locale des surfaces via leurs courbures.", "images": ["surfaces_diff.png"], "correspondances": [{"id": 221, "title": "Géométrie différentielle des courbes"}, {"id": 223, "title": "Variétés différentiables"}], "tags": ["geometrie", "surfaces"], "niveau": "grandes-ecoles", "definition": "La géométrie différentielle des surfaces étend l'étude de la courbure aux surfaces (comme une sphère ou une selle de cheval), en distinguant deux formes fondamentales qui décrivent leur géométrie locale.", "explication_formules": "La première forme fondamentale mesure les distances sur la surface. La courbure de Gauss K combine les deux courbures principales en un seul nombre. Le Theorema Egregium de Gauss montre que cette courbure ne dépend que des mesures internes à la surface, pas de la façon dont elle est plongée dans l'espace.", "approfondissements": [{"label": "Courbures principales et courbure moyenne", "link": {"type": "theme", "slug": "courbures-principales-et-courbure-moyenne"}}, {"label": "Géodésiques (plus courts chemins sur une surface)", "link": {"type": "theme", "slug": "geodesiques-plus-courts-chemins-sur-une-surface"}}, {"label": "Formule de Gauss-Bonnet", "link": {"type": "theme", "slug": "formule-de-gauss-bonnet"}}, {"label": "Surfaces minimales", "link": {"type": "theme", "slug": "surfaces-minimales"}}, {"label": "Applications à la cartographie", "link": {"type": "theme", "slug": "applications-a-la-cartographie"}}], "sous_points": [{"terme": "Seconde forme fondamentale", "definition": "Cette forme quadratique associée à une surface encode sa courbure locale, complétant la première forme fondamentale qui mesure les distances."}, {"terme": "Courbures principales", "definition": "En chaque point d'une surface, deux courbures extrêmes (principales) résument entièrement sa forme locale dans les deux directions les plus et moins courbées."}], "applications_list": [{"text": "Expliquer les déformations de la cartographie terrestre.", "icon": "navigation"}, {"text": "Concevoir des surfaces architecturales complexes.", "icon": "construction"}]}, {"id": 223, "title": "Variétés différentiables", "category": "Géométrie", "formulas": ["Cartes et atlas", "Espace tangent TₚM", "Théorème de Stokes généralisé"], "details": "Généralisation des surfaces en dimension quelconque.", "images": ["varietes.png"], "correspondances": [{"id": 222, "title": "Géométrie différentielle des surfaces"}, {"id": 224, "title": "Topologie algébrique"}, {"key": "sup:1535", "title": "Algèbres de Lie (introduction culturelle)", "raison": "L'espace tangent à l'identité d'un groupe de Lie est une algèbre de Lie : le crochet [X,Y] linéarise la non-commutativité du groupe."}, {"key": "sup:1181", "title": "Théorème des fonctions implicites", "raison": "Si df est de rang maximal, {f=0} est localement le graphe d'une fonction : c'est ainsi que les courbes et surfaces définies par des équations sont des sous-variétés."}, {"key": "sup:1768", "title": "Systèmes hamiltoniens (introduction culturelle)", "raison": "L'espace des phases d'un système mécanique est une variété munie d'une forme symplectique ; les équations de Hamilton y définissent un flot qui la conserve (théorème de Liouville)."}], "tags": ["geometrie", "varietes"], "niveau": "grandes-ecoles", "definition": "Une variété différentiable est un espace qui ressemble localement à ℝⁿ (comme la Terre semble plate localement bien qu'elle soit sphérique), permettant d'y faire du calcul différentiel malgré une forme globale complexe.", "explication_formules": "Les cartes et atlas découpent la variété en morceaux ressemblant chacun à ℝⁿ, recollés de façon cohérente. L'espace tangent TₚM représente toutes les directions possibles de déplacement depuis un point p, généralisant le plan tangent à une surface.", "approfondissements": [{"label": "Espace tangent et fibré tangent", "link": {"type": "theme", "slug": "espace-tangent-et-fibre-tangent"}}, {"label": "Formes différentielles", "link": {"type": "theme", "slug": "formes-differentielles"}}, {"label": "Théorème de Stokes généralisé", "link": {"type": "theme", "slug": "theoreme-de-stokes-generalise"}}, {"label": "Variétés riemanniennes", "link": {"type": "theme", "slug": "varietes-riemanniennes"}}, {"label": "Applications à la relativité générale", "link": {"type": "notion", "id": 422}}], "sous_points": [{"terme": "Champs de vecteurs", "definition": "Un champ de vecteurs associe une direction de déplacement à chaque point d'une variété, généralisant les champs de forces ou de vitesses."}, {"terme": "Formes différentielles", "definition": "Une forme différentielle généralise la notion de fonction à intégrer sur des courbes, surfaces ou volumes d'une variété."}], "applications_list": [{"text": "Modéliser l'espace-temps courbe en relativité générale.", "icon": "space"}, {"text": "Décrire l'espace des configurations d'un robot articulé.", "icon": "robotics"}, {"text": "Fonder la géométrie moderne utilisée en physique théorique.", "icon": "physics"}]}, {"id": 224, "title": "Topologie algébrique", "category": "Géométrie", "formulas": ["Groupe fondamental π₁(X)", "Caractéristique d'Euler : V−E+F=2", "Homologie singulière"], "details": "Étude des espaces topologiques via des invariants algébriques.", "images": ["topo_algebrique.png"], "correspondances": [{"id": 702, "title": "Topologie"}, {"id": 223, "title": "Variétés différentiables"}], "tags": ["geometrie", "topologie-algebrique"], "niveau": "grandes-ecoles", "definition": "La topologie algébrique associe à chaque espace géométrique des objets algébriques (groupes, nombres) qui capturent ses propriétés essentielles de forme, indépendamment de toute déformation continue.", "explication_formules": "Le groupe fondamental π₁(X) compte, en un sens, les 'trous' qu'on peut détecter avec une boucle. La caractéristique d'Euler V-E+F=2 (pour un polyèdre convexe) est un invariant remarquablement simple qui distingue les formes topologiquement différentes.", "approfondissements": [{"label": "Homologie et cohomologie", "link": {"type": "theme", "slug": "homologie-et-cohomologie"}}, {"label": "Théorème de van Kampen", "link": {"type": "theme", "slug": "theoreme-de-van-kampen"}}, {"label": "Classification des surfaces", "link": {"type": "theme", "slug": "classification-des-surfaces"}}, {"label": "Théorie des nœuds", "link": {"type": "theme", "slug": "theorie-des-n-uds"}}, {"label": "Applications à l'analyse topologique des données", "link": {"type": "theme", "slug": "applications-a-l-analyse-topologique-des-donnees"}}], "sous_points": [{"terme": "Théorème de van Kampen", "definition": "Ce théorème calcule le groupe fondamental d'un espace complexe en le décomposant en morceaux plus simples dont on connaît déjà les groupes fondamentaux."}, {"terme": "Suite de Mayer-Vietoris", "definition": "Cette suite exacte relie l'homologie d'un espace à celle de deux sous-espaces qui le recouvrent, un outil de calcul puissant."}], "applications_list": [{"text": "Analyser la structure de réseaux complexes (internet, réseaux sociaux).", "icon": "network"}, {"text": "Détecter des trous ou anomalies dans des données à haute dimension.", "icon": "data"}, {"text": "Classifier les formes en vision par ordinateur.", "icon": "computer"}]}, {"id": 225, "title": "Géométrie riemannienne", "category": "Géométrie", "formulas": ["Connexion de Levi-Civita", "Tenseur de courbure de Riemann", "Équation de la géodésique"], "details": "Étude de la courbure sur des variétés munies d'une métrique.", "images": ["riemannienne.png"], "correspondances": [{"id": 222, "title": "Géométrie différentielle des surfaces"}, {"id": 226, "title": "Géométrie symplectique et mécanique hamiltonienne"}, {"key": "sup:1632", "title": "Produits tensoriels d'espaces vectoriels", "raison": "Une métrique riemannienne est un champ de tenseurs symétriques définis positifs g_ij ; la courbure est elle aussi un tenseur, celui de Riemann."}, {"key": "sup:1364", "title": "Intégrale de Lebesgue : construction", "raison": "Dans une carte, la métrique définit une mesure de volume √det(g_ij) dx¹…dx^n : on peut ainsi intégrer sur une variété, et définir longueurs, aires et volumes."}, {"key": "sup:598", "title": "Mouvement brownien", "raison": "Le générateur du mouvement brownien est ½Δ ; sur une variété riemannienne il devient ½Δ_g (Laplace–Beltrami), et les trajectoires reflètent la courbure et le volume."}, {"id": 422, "title": "Relativité générale", "raison": "L'espace-temps est une variété lorentzienne (métrique de signature (−,+,+,+)) ; les équations d'Einstein relient sa courbure à la matière et à l'énergie."}], "tags": ["geometrie", "riemannienne"], "niveau": "grandes-ecoles", "definition": "La géométrie riemannienne étudie la courbure des espaces (variétés) munis d'une notion de distance, généralisant la géométrie des surfaces à des dimensions quelconques — le langage mathématique de la relativité générale.", "explication_formules": "La connexion de Levi-Civita permet de dériver des vecteurs le long d'une variété courbe de façon cohérente avec la métrique. Le tenseur de courbure de Riemann mesure précisément à quel point l'espace s'écarte d'être plat, en comparant le transport d'un vecteur le long de deux chemins différents.", "approfondissements": [{"label": "Courbure de Ricci et courbure scalaire", "link": {"type": "theme", "slug": "courbure-de-ricci-et-courbure-scalaire"}}, {"label": "Géodésiques et équation de la géodésique", "link": {"type": "theme", "slug": "geodesiques-et-equation-de-la-geodesique"}}, {"label": "Théorème de Gauss-Bonnet généralisé", "link": {"type": "theme", "slug": "theoreme-de-gauss-bonnet-generalise"}}, {"label": "Applications à la relativité générale", "link": {"type": "notion", "id": 422}}, {"label": "Flot de Ricci et théorème de Perelman", "link": {"type": "theme", "slug": "flot-de-ricci-et-theoreme-de-perelman"}}], "sous_points": [{"terme": "Courbure de Ricci", "definition": "La courbure de Ricci moyenne la courbure de Riemann dans toutes les directions en chaque point d'une variété."}, {"terme": "Théorème de Gauss-Bonnet généralisé", "definition": "Ce théorème relie la courbure totale d'une variété à sa topologie (sa caractéristique d'Euler), généralisant le résultat classique des surfaces."}], "applications_list": [{"text": "Fonder mathématiquement la relativité générale d'Einstein.", "icon": "space"}, {"text": "Modéliser des données sur des variétés courbes en apprentissage automatique.", "icon": "computer"}]}, {"id": 226, "title": "Géométrie symplectique et mécanique hamiltonienne", "category": "Géométrie", "formulas": ["Forme symplectique ω", "Crochet de Poisson {f,g}", "Théorème de Liouville (conservation du volume)"], "details": "Cadre géométrique naturel de la mécanique classique.", "images": ["symplectique.png"], "correspondances": [{"id": 714, "title": "Physique avancée"}, {"id": 223, "title": "Variétés différentiables"}], "tags": ["geometrie", "symplectique"], "niveau": "grandes-ecoles", "definition": "La géométrie symplectique fournit le cadre géométrique naturel de la mécanique classique, où l'espace des états (position et vitesse) possède une structure qui préserve certaines quantités au cours du temps.", "explication_formules": "La forme symplectique ω encode la structure géométrique de l'espace des phases. Le crochet de Poisson {f,g} mesure comment deux quantités physiques évoluent l'une par rapport à l'autre. Le théorème de Liouville garantit que le volume dans l'espace des phases se conserve au cours du temps.", "approfondissements": [{"label": "Équations de Hamilton", "link": {"type": "theme", "slug": "equations-de-hamilton"}}, {"label": "Théorème de Darboux", "link": {"type": "theme", "slug": "theoreme-de-darboux"}}, {"label": "Systèmes intégrables (Arnold-Liouville)", "link": {"type": "theme", "slug": "systemes-integrables-arnold-liouville"}}, {"label": "Applications à la mécanique céleste", "link": {"type": "theme", "slug": "applications-a-la-mecanique-celeste"}}, {"label": "Quantification géométrique", "link": {"type": "theme", "slug": "quantification-geometrique"}}], "sous_points": [{"terme": "Théorème de Darboux", "definition": "Ce théorème dit que toutes les variétés symplectiques de même dimension se ressemblent localement, un résultat de rigidité important."}, {"terme": "Systèmes intégrables", "definition": "Un système hamiltonien intégrable possède suffisamment de quantités conservées pour être résolu explicitement, un cas particulièrement structuré."}], "applications_list": [{"text": "Modéliser la mécanique céleste avec une grande précision.", "icon": "space"}, {"text": "Fonder la mécanique quantique à partir de la mécanique classique.", "icon": "physics"}]}, {"id": 227, "title": "Géométrie algébrique", "category": "Géométrie", "formulas": ["Courbes planes et théorème de Bézout", "Diviseurs sur une courbe", "Théorème de Riemann-Roch"], "details": "Étude des solutions d'équations polynomiales par des méthodes géométriques.", "images": ["geo_algebrique.png"], "correspondances": [{"id": 131, "title": "Anneaux de polynômes et géométrie algébrique"}, {"id": 20, "title": "Analyse complexe avancée"}], "tags": ["geometrie", "algebrique"], "niveau": "grandes-ecoles", "definition": "La géométrie algébrique étudie les formes géométriques (courbes, surfaces) définies comme solutions d'équations polynomiales, reliant intimement calcul algébrique et intuition géométrique.", "explication_formules": "Le théorème de Bézout prédit le nombre exact de points d'intersection entre deux courbes planes à partir de leurs degrés. Le théorème de Riemann-Roch relie le genre d'une courbe (nombre de 'trous') à des propriétés algébriques de ses fonctions.", "approfondissements": [{"label": "Diviseurs et fonctions rationnelles sur une courbe", "link": {"type": "theme", "slug": "diviseurs-et-fonctions-rationnelles-sur-une-courbe"}}, {"label": "Genre d'une courbe algébrique", "link": {"type": "theme", "slug": "genre-d-une-courbe-algebrique"}}, {"label": "Surfaces de Riemann", "link": {"type": "theme", "slug": "surfaces-de-riemann"}}, {"label": "Courbes elliptiques et cryptographie", "link": {"type": "theme", "slug": "courbes-elliptiques-et-cryptographie"}}, {"label": "Variétés projectives", "link": {"type": "theme", "slug": "varietes-projectives"}}], "sous_points": [{"terme": "Genre d'une courbe", "definition": "Le genre d'une courbe algébrique compte, intuitivement, son nombre de « trous » (comme un tore), déterminant profondément ses propriétés."}, {"terme": "Surfaces de Riemann", "definition": "Une surface de Riemann est une variété complexe de dimension 1, le cadre naturel pour étendre l'analyse complexe à des fonctions multiformes."}], "applications_list": [{"text": "Fonder la cryptographie sur courbes elliptiques des cryptomonnaies.", "icon": "security"}, {"text": "Résoudre des contraintes géométriques en robotique.", "icon": "robotics"}]}, {"id": 228, "title": "Géométrie projective", "category": "Géométrie", "formulas": ["Espace projectif ℙⁿ", "Coordonnées homogènes", "Homographies"], "details": "Extension de la géométrie affine incluant les points à l'infini.", "images": ["projective.png"], "correspondances": [{"id": 211, "title": "Transformations géométriques"}, {"id": 227, "title": "Géométrie algébrique"}], "tags": ["geometrie", "projective"], "niveau": "grandes-ecoles", "definition": "La géométrie projective ajoute des 'points à l'infini' à l'espace usuel, ce qui unifie le traitement des droites parallèles (qui se rencontrent alors 'à l'infini') et simplifie de nombreux théorèmes.", "explication_formules": "Les coordonnées homogènes représentent chaque point par plusieurs jeux de coordonnées proportionnelles, permettant d'inclure naturellement les points à l'infini. Une homographie est une transformation projective qui préserve l'alignement des points, même si elle déforme distances et angles.", "approfondissements": [{"label": "Théorèmes de Pascal et Desargues", "link": {"type": "theme", "slug": "theoremes-de-pascal-et-desargues"}}, {"label": "Dualité projective", "link": {"type": "theme", "slug": "dualite-projective"}}, {"label": "Birapport (invariant projectif)", "link": {"type": "theme", "slug": "birapport-invariant-projectif"}}, {"label": "Coniques projectives", "link": {"type": "theme", "slug": "coniques-projectives"}}, {"label": "Applications à la vision par ordinateur", "link": {"type": "theme", "slug": "applications-a-la-vision-par-ordinateur"}}], "sous_points": [{"terme": "Dualité projective", "definition": "En géométrie projective, points et droites jouent des rôles symétriques : tout théorème sur les points a un analogue en échangeant points et droites."}, {"terme": "Birapport", "definition": "Le birapport de quatre points alignés est une quantité qui reste invariante sous toute transformation projective."}], "applications_list": [{"text": "Fonder la vision par ordinateur et la reconstruction 3D.", "icon": "computer"}, {"text": "Modéliser le rendu en infographie 3D.", "icon": "art"}]}, {"id": 229, "title": "Théorie de Hodge et cohomologie", "category": "Géométrie", "formulas": ["Opérateur de Laplace-de Rham", "Décomposition de Hodge", "Théorème de de Rham"], "details": "Lien entre analyse, topologie et géométrie sur les variétés.", "images": ["hodge.png"], "correspondances": [{"id": 223, "title": "Variétés différentiables"}, {"id": 224, "title": "Topologie algébrique"}], "tags": ["geometrie", "hodge"], "niveau": "grandes-ecoles", "definition": "La théorie de Hodge établit un lien profond entre l'analyse (équations aux dérivées partielles), la topologie (forme globale) et la géométrie d'une variété, en décomposant ses formes différentielles.", "explication_formules": "L'opérateur de Laplace-de Rham généralise le laplacien usuel aux formes différentielles sur une variété. La décomposition de Hodge sépare toute forme en trois composantes canoniques (exacte, co-exacte, harmonique), révélant la structure topologique cachée dans l'analyse.", "approfondissements": [{"label": "Cohomologie de de Rham", "link": {"type": "theme", "slug": "cohomologie-de-de-rham"}}, {"label": "Formes harmoniques", "link": {"type": "theme", "slug": "formes-harmoniques"}}, {"label": "Structures kählériennes", "link": {"type": "theme", "slug": "structures-kahleriennes"}}, {"label": "Variétés de Calabi-Yau", "link": {"type": "theme", "slug": "varietes-de-calabi-yau"}}, {"label": "Applications à la théorie des cordes", "link": {"type": "theme", "slug": "applications-a-la-theorie-des-cordes"}}], "sous_points": [{"terme": "Formes harmoniques", "definition": "Une forme harmonique minimise une énergie associée et représente la partie topologiquement essentielle d'une forme différentielle."}, {"terme": "Structures kählériennes", "definition": "Une structure kählérienne combine harmonieusement géométrie complexe, riemannienne et symplectique sur une même variété."}], "applications_list": [{"text": "Décrire les dimensions cachées de l'espace-temps en théorie des cordes.", "icon": "space"}, {"text": "Traiter des maillages 3D complexes en infographie.", "icon": "art"}]}, {"id": 230, "title": "Géométrie hyperbolique et courbure négative", "category": "Géométrie", "formulas": ["Modèle du disque de Poincaré", "Espaces CAT(0)", "Bord à l'infini"], "details": "Géométrie non euclidienne où la somme des angles d'un triangle est inférieure à 180°.", "images": ["hyperbolique.png"], "correspondances": [{"id": 225, "title": "Géométrie riemannienne"}, {"id": 224, "title": "Topologie algébrique"}], "tags": ["geometrie", "hyperbolique"], "niveau": "grandes-ecoles", "definition": "La géométrie hyperbolique décrit des espaces à courbure négative constante, où les règles familières de la géométrie euclidienne (comme l'unicité de la parallèle) ne s'appliquent plus.", "explication_formules": "Le modèle du disque de Poincaré représente tout l'espace hyperbolique infini à l'intérieur d'un disque de rayon fini, avec des distances qui s'étirent près du bord. Les espaces CAT(0) généralisent la notion de courbure négative ou nulle à des espaces non nécessairement lisses.", "approfondissements": [{"label": "Modèles de la géométrie hyperbolique", "link": {"type": "theme", "slug": "modeles-de-la-geometrie-hyperbolique"}}, {"label": "Groupes hyperboliques", "link": {"type": "theme", "slug": "groupes-hyperboliques"}}, {"label": "Bord à l'infini", "link": {"type": "theme", "slug": "bord-a-l-infini"}}, {"label": "Applications aux réseaux hiérarchiques (IA)", "link": {"type": "theme", "slug": "applications-aux-reseaux-hierarchiques-ia"}}, {"label": "Pavages hyperboliques (Escher)", "link": {"type": "theme", "slug": "pavages-hyperboliques-escher"}}], "sous_points": [{"terme": "Géométrie des groupes", "definition": "La géométrie des groupes étudie les groupes à travers leur action sur des espaces géométriques, révélant des propriétés algébriques par des méthodes géométriques."}, {"terme": "Comparaison de courbure", "definition": "Comparer la courbure d'un espace à celle d'un modèle de référence (sphère, plan, espace hyperbolique) permet d'en déduire des propriétés globales."}], "applications_list": [{"text": "Étudier la croissance de structures algébriques.", "icon": "research"}, {"text": "Représenter des données hiérarchiques en apprentissage automatique.", "icon": "computer"}]}, {"id": 231, "title": "Fibrés vectoriels et classes caractéristiques", "category": "Géométrie", "formulas": ["Fibré vectoriel E→M", "Connexion et courbure d'un fibré", "Classes de Chern"], "details": "Objets géométriques associant un espace vectoriel à chaque point d'une variété.", "images": ["fibres.png"], "correspondances": [{"id": 223, "title": "Variétés différentiables"}, {"id": 226, "title": "Géométrie symplectique et mécanique hamiltonienne"}], "tags": ["geometrie", "fibres"], "niveau": "grandes-ecoles", "definition": "Un fibré vectoriel associe à chaque point d'une variété un espace vectoriel entier, comme si on 'collait' un petit espace à chaque endroit — un outil essentiel pour décrire des champs sur des espaces courbes.", "explication_formules": "Une connexion sur un fibré permet de comparer les vecteurs attachés à des points différents, et sa courbure mesure le défaut de cette comparaison le long d'un chemin fermé. Les classes de Chern sont des invariants qui résument la 'torsion' globale du fibré.", "approfondissements": [{"label": "Fibrés principaux", "link": {"type": "theme", "slug": "fibres-principaux"}}, {"label": "Théorie de jauge en physique", "link": {"type": "theme", "slug": "theorie-de-jauge-en-physique"}}, {"label": "Classes caractéristiques (Chern, Stiefel-Whitney)", "link": {"type": "theme", "slug": "classes-caracteristiques-chern-stiefel-whitney"}}, {"label": "K-théorie topologique", "link": {"type": "theme", "slug": "k-theorie-topologique"}}, {"label": "Applications aux interactions fondamentales", "link": {"type": "theme", "slug": "applications-aux-interactions-fondamentales"}}], "sous_points": [{"terme": "Fibrés principaux", "definition": "Un fibré principal généralise le fibré vectoriel en attachant un groupe à chaque point d'une variété, cadre géométrique des théories de jauge."}, {"terme": "Théorie de jauge", "definition": "Les théories de jauge décrivent les interactions fondamentales comme des connexions sur des fibrés, unifiant électromagnétisme et forces nucléaires."}], "applications_list": [{"text": "Fonder les théories de jauge en physique des particules.", "icon": "physics"}, {"text": "Modéliser des champs magnétiques sur des surfaces courbes.", "icon": "physics"}]}, {"id": 232, "title": "Transport optimal et inégalités géométriques", "category": "Géométrie", "formulas": ["Distance de Wasserstein", "Dualité de Kantorovich", "Inégalité isopérimétrique"], "details": "Comparaison optimale de distributions de masse et bornes géométriques.", "images": ["transport_optimal.png"], "correspondances": [{"id": 225, "title": "Géométrie riemannienne"}, {"id": 18, "title": "Mesure et intégrale de Lebesgue"}], "tags": ["geometrie", "transport-optimal"], "niveau": "grandes-ecoles", "definition": "Le transport optimal cherche la façon la plus économique de déplacer une distribution de masse vers une autre, un problème à l'intersection de la géométrie, de l'analyse et des probabilités.", "explication_formules": "La distance de Wasserstein mesure le 'coût' minimal pour transformer une distribution en une autre. L'inégalité isopérimétrique établit que, parmi toutes les figures de périmètre donné, le cercle maximise l'aire — un résultat géométrique très ancien retrouvé par des méthodes modernes.", "approfondissements": [{"label": "Dualité de Kantorovich", "link": {"type": "theme", "slug": "dualite-de-kantorovich"}}, {"label": "Théorème de Brenier", "link": {"type": "theme", "slug": "theoreme-de-brenier"}}, {"label": "Inégalité de Brunn-Minkowski", "link": {"type": "theme", "slug": "inegalite-de-brunn-minkowski"}}, {"label": "Applications à l'apprentissage automatique (GANs)", "link": {"type": "notion", "id": 530}}, {"label": "Géométrie de l'information", "link": {"type": "theme", "slug": "geometrie-de-l-information"}}], "sous_points": [{"terme": "Théorème de Brenier", "definition": "Ce théorème garantit l'existence et l'unicité d'une solution optimale au problème de transport quadratique, sous forme du gradient d'une fonction convexe."}, {"terme": "Inégalité de Brunn-Minkowski", "definition": "Cette inégalité géométrique compare le volume de la somme de deux ensembles à leurs volumes individuels."}], "applications_list": [{"text": "Comparer des distributions de données en apprentissage automatique.", "icon": "computer"}, {"text": "Optimiser la logistique de distribution de ressources.", "icon": "industry"}, {"text": "Analyser des images en traitement d'images.", "icon": "art"}]}, {"id": 312, "title": "Variables aléatoires continues", "category": "Probabilités", "formulas": ["Densité de probabilité f(x)", "Fonction de répartition F(x)=P(X≤x)", "E[X]=∫x f(x)dx"], "details": "Étude des variables aléatoires prenant un continuum de valeurs.", "images": ["va_continues.png"], "correspondances": [{"id": 311, "title": "Lois normales"}, {"id": 313, "title": "Théorème central limite"}], "tags": ["probabilites", "continues"], "niveau": "prepa", "definition": "Une variable aléatoire continue peut prendre n'importe quelle valeur dans un intervalle (contrairement au cas discret), et sa probabilité se calcule via une densité plutôt qu'une liste de valeurs.", "explication_formules": "La densité f(x) ne donne pas directement une probabilité, mais son intégrale sur un intervalle le fait : P(a≤X≤b)=∫ₐᵇf(x)dx. La fonction de répartition F(x)=P(X≤x) accumule progressivement cette probabilité.", "approfondissements": [{"label": "Lois usuelles continues (uniforme, exponentielle, normale)", "link": {"type": "theme", "slug": "lois-usuelles-continues-uniforme-exponentielle-normale"}}, {"label": "Changement de variable et théorème de transfert", "link": {"type": "theme", "slug": "changement-de-variable-et-theoreme-de-transfert"}}, {"label": "Densités conjointes", "link": {"type": "theme", "slug": "densites-conjointes"}}, {"label": "Simulation de variables aléatoires continues", "link": {"type": "notion", "id": 302}}, {"label": "Lien avec l'intégrale de Lebesgue", "link": {"type": "theme", "slug": "lien-avec-l-integrale-de-lebesgue"}}], "sous_points": [{"terme": "Loi uniforme", "definition": "La loi uniforme modélise un tirage sans préférence sur un intervalle : toutes les valeurs y sont également probables."}, {"terme": "Loi exponentielle", "definition": "La loi exponentielle modélise un temps d'attente sans mémoire, comme la durée avant la prochaine panne d'un équipement."}, {"terme": "Loi gaussienne", "definition": "La loi gaussienne (normale) modélise des mesures dispersées symétriquement autour d'une moyenne, en forme de cloche."}], "applications_list": [{"text": "Modéliser un temps d'attente ou une taille.", "icon": "data"}, {"text": "Représenter toute mesure physique continue.", "icon": "physics"}]}, {"id": 313, "title": "Théorème central limite", "category": "Probabilités", "formulas": ["√n (X̄ₙ−μ)/σ → N(0,1)", "Loi des grands nombres", "Théorème de Slutsky"], "details": "Justifie l'omniprésence de la loi normale dans les phénomènes aléatoires.", "images": ["tcl.png"], "correspondances": [{"id": 312, "title": "Variables aléatoires continues"}, {"id": 314, "title": "Chaînes de Markov"}, {"key": "sup:1029", "title": "Nombres complexes : forme trigonométrique et exponentielle", "raison": "Pour des variables centrées réduites, φ(t/√n)^n → e^(−t²/2) : la démonstration passe par la fonction caractéristique, à valeurs complexes, et le théorème de Lévy donne la convergence en loi."}, {"key": "sup:312", "title": "Transformée de Fourier : définition", "raison": "La fonction caractéristique est la transformée de Fourier de la loi, et la somme de variables indépendantes correspond à un produit de transformées : la démonstration devient un calcul."}, {"id": 425, "title": "Thermodynamique statistique", "raison": "Une grandeur macroscopique (énergie, pression) est une somme d'un très grand nombre de contributions microscopiques presque indépendantes : ses fluctuations sont gaussiennes, d'ordre 1/√N en valeur relative."}, {"key": "sup:1242", "title": "Simulation aléatoire et méthode de Monte-Carlo (introduction)", "raison": "La méthode de Monte-Carlo estime une espérance par une moyenne de n tirages ; le TCL donne l'erreur, de l'ordre σ/√n, et un intervalle de confiance asymptotique."}], "tags": ["probabilites", "tcl"], "niveau": "prepa", "definition": "Le théorème central limite explique pourquoi la loi normale apparaît si souvent : la somme (ou la moyenne) d'un grand nombre de variables aléatoires indépendantes tend toujours vers une loi normale, quelle que soit leur loi d'origine.", "explication_formules": "√n(X̄ₙ-μ)/σ → N(0,1) dit que l'écart entre la moyenne empirique et la vraie moyenne, correctement mis à l'échelle, suit approximativement une loi normale quand n devient grand. La loi des grands nombres garantit, elle, que la moyenne empirique se rapproche simplement de μ.", "approfondissements": [{"label": "Vitesse de convergence (théorème de Berry-Esseen)", "link": {"type": "theme", "slug": "vitesse-de-convergence-theoreme-de-berry-esseen"}}, {"label": "Théorème central limite fonctionnel", "link": {"type": "notion", "id": 313}}, {"label": "Applications aux sondages et intervalles de confiance", "link": {"type": "theme", "slug": "applications-aux-sondages-et-intervalles-de-confiance"}}, {"label": "Grandes déviations (au-delà du TCL)", "link": {"type": "theme", "slug": "grandes-deviations-au-dela-du-tcl"}}, {"label": "TCL pour variables dépendantes", "link": {"type": "theme", "slug": "tcl-pour-variables-dependantes"}}], "sous_points": [{"terme": "Convergence en loi", "definition": "La convergence en loi signifie que la répartition des valeurs d'une suite de variables aléatoires se rapproche d'une loi limite."}, {"terme": "Fonction caractéristique", "definition": "La fonction caractéristique d'une variable aléatoire est la transformée de Fourier de sa loi, un outil clé pour prouver la convergence."}], "applications_list": [{"text": "Justifier l'usage des sondages et intervalles de confiance.", "icon": "data"}, {"text": "Fonder les tests d'hypothèses utilisés en science et en médecine.", "icon": "medicine"}, {"text": "Expliquer pourquoi tant de mesures physiques suivent une loi normale.", "icon": "physics"}]}, {"id": 314, "title": "Chaînes de Markov", "category": "Probabilités", "formulas": ["Matrice de transition P", "Distribution stationnaire : πP=π", "Équation de Chapman-Kolmogorov"], "details": "Modélisation de processus sans mémoire évoluant dans le temps.", "images": ["markov.png"], "correspondances": [{"id": 315, "title": "Martingales et temps d'arrêt"}, {"id": 313, "title": "Théorème central limite"}, {"key": "sup:661", "title": "Automates finis", "raison": "Un automate fini est un système à états finis avec des transitions ; en munissant chaque transition d'une probabilité, on obtient une chaîne de Markov (automate probabiliste)."}, {"key": "sup:223", "title": "Matrices stochastiques, Perron-Frobenius", "raison": "La loi de X_n est μP^n, où P est la matrice de transition (lignes de somme 1) : une loi stationnaire vérifie πP = π, vecteur propre à gauche pour la valeur propre 1 (Perron–Frobenius)."}, {"key": "sup:219", "title": "Systèmes différentiels linéaires par diagonalisation", "raison": "En temps continu, les probabilités de transition vérifient P'(t) = P(t)Q, un système différentiel linéaire de solution P(t) = e^(tQ)."}, {"key": "sup:1740", "title": "Recuit simulé (introduction)", "raison": "Le recuit simulé (comme l'algorithme de Metropolis) construit une chaîne de Markov de loi stationnaire e^(−f/T)/Z, qui concentre la masse sur les minima de f quand T diminue."}, {"id": 503, "title": "Graphes", "raison": "Une chaîne de Markov est une marche aléatoire sur un graphe orienté pondéré ; PageRank est la loi stationnaire de la marche d'un surfeur aléatoire (avec téléportation) sur le graphe du web."}, {"id": 428, "title": "Physique statistique et transitions de phase", "raison": "L'algorithme de Metropolis construit une chaîne de Markov réversible dont la loi stationnaire est la distribution de Boltzmann e^(−E/kT)/Z : il simule l'équilibre thermique."}], "tags": ["probabilites", "markov"], "niveau": "prepa", "definition": "Une chaîne de Markov décrit un système qui évolue aléatoirement d'un état à un autre, où le futur ne dépend que de l'état présent et non de tout le passé — une hypothèse de 'mémoire courte'.", "explication_formules": "La matrice de transition P donne, pour chaque paire d'états, la probabilité de passer de l'un à l'autre en une étape. La distribution stationnaire πP=π décrit l'équilibre à long terme du système, indépendant de l'état de départ (sous conditions).", "approfondissements": [{"label": "États récurrents et transitoires", "link": {"type": "theme", "slug": "etats-recurrents-et-transitoires"}}, {"label": "Chaînes de Markov à temps continu", "link": {"type": "notion", "id": 314}}, {"label": "Théorème ergodique pour chaînes de Markov", "link": {"type": "notion", "id": 314}}, {"label": "Chaînes de Markov cachées", "link": {"type": "notion", "id": 314}}, {"label": "Applications au PageRank et à la génération de texte", "link": {"type": "theme", "slug": "applications-au-pagerank-et-a-la-generation-de-texte"}}], "sous_points": [{"terme": "États récurrents", "definition": "Un état récurrent d'une chaîne de Markov est visité une infinité de fois presque sûrement, si le processus continue indéfiniment."}, {"terme": "États transitoires", "definition": "Un état transitoire n'est visité qu'un nombre fini de fois avant que le processus ne le quitte définitivement."}, {"terme": "Théorème ergodique", "definition": "Ce théorème garantit que, sous certaines conditions, la fréquence de visite de chaque état converge vers sa probabilité stationnaire."}], "applications_list": [{"text": "Modéliser la météo (probabilité de pluie selon le temps du jour).", "icon": "environment"}, {"text": "Classer les pages web (algorithme PageRank de Google).", "icon": "network"}, {"text": "Générer du texte automatiquement (modèles de langage simples).", "icon": "computer"}]}, {"id": 315, "title": "Martingales et temps d'arrêt", "category": "Probabilités", "formulas": ["E[Xₙ₊₁|Fₙ]=Xₙ", "Théorème d'arrêt de Doob", "Inégalité de Doob"], "details": "Modélisation de jeux équitables et outils puissants de convergence.", "images": ["martingales.png"], "correspondances": [{"id": 314, "title": "Chaînes de Markov"}, {"id": 316, "title": "Mouvement brownien et calcul stochastique"}], "tags": ["probabilites", "martingales"], "niveau": "grandes-ecoles", "definition": "Une martingale est un processus aléatoire qui représente un jeu 'équitable' : en moyenne, la valeur future attendue est égale à la valeur actuelle, sans tendance à gagner ou perdre.", "explication_formules": "E[Xₙ₊₁|Fₙ]=Xₙ formalise l'équité : connaissant tout le passé jusqu'à l'instant n, la meilleure prévision pour l'instant suivant est simplement la valeur actuelle. Le théorème d'arrêt de Doob précise dans quelles conditions on peut arrêter le jeu à un instant aléatoire sans en changer l'espérance.", "approfondissements": [{"label": "Théorème de convergence des martingales", "link": {"type": "theme", "slug": "theoreme-de-convergence-des-martingales"}}, {"label": "Temps d'arrêt et stratégies optimales", "link": {"type": "theme", "slug": "temps-d-arret-et-strategies-optimales"}}, {"label": "Décomposition de Doob", "link": {"type": "theme", "slug": "decomposition-de-doob"}}, {"label": "Martingales en finance (absence d'arbitrage)", "link": {"type": "theme", "slug": "martingales-en-finance-absence-d-arbitrage"}}, {"label": "Inégalité de Doob", "link": {"type": "theme", "slug": "inegalite-de-doob"}}], "sous_points": [{"terme": "Décomposition de Doob", "definition": "Cette décomposition sépare un processus stochastique en une martingale (partie imprévisible) et un processus prévisible."}, {"terme": "Convergence presque sûre", "definition": "Une martingale bornée converge presque sûrement vers une limite, c'est-à-dire avec une probabilité 1."}], "applications_list": [{"text": "Modéliser des jeux de hasard équitables et des stratégies de trading.", "icon": "finance"}, {"text": "Fonder la théorie moderne de la finance mathématique.", "icon": "finance"}, {"text": "Prouver des théorèmes de convergence en probabilité.", "icon": "research"}]}, {"id": 316, "title": "Mouvement brownien et calcul stochastique", "category": "Probabilités", "formulas": ["Formule d'Itô", "dXₜ=μdt+σdWₜ", "Propriété de Markov du mouvement brownien"], "details": "Modélisation mathématique du bruit aléatoire continu.", "images": ["brownien.png"], "correspondances": [{"id": 315, "title": "Martingales et temps d'arrêt"}, {"id": 317, "title": "Équations différentielles stochastiques"}, {"key": "sup:303", "title": "Équation de la chaleur 1D", "raison": "La densité de B_t est le noyau de la chaleur : u(t,x) = E[f(x+B_t)] résout ∂_t u = ½ ∂_x² u avec u(0,·) = f ; les solutions de l'EDP sont des espérances."}, {"key": "sup:544", "title": "Variétés riemanniennes", "raison": "Sur une variété riemannienne, la diffusion de générateur ½Δ_g généralise le mouvement brownien : sa loi encode la courbure et le volume de la variété."}, {"key": "sup:856", "title": "Méthode de Monte-Carlo", "raison": "En finance, on estime un prix d'option par Monte-Carlo en simulant des trajectoires browniennes discrétisées et en moyennant le gain actualisé."}, {"id": 428, "title": "Physique statistique et transitions de phase", "raison": "Einstein a relié le brownien à la diffusion : E[x²]=2Dt avec D=kT/(6πηr) pour une sphère de rayon r dans un fluide de viscosité η, ce qui fait apparaître la constante de Boltzmann."}, {"key": "sup:1364", "title": "Intégrale de Lebesgue : construction", "raison": "La loi du mouvement brownien est une mesure de probabilité sur l'espace des trajectoires continues (mesure de Wiener) : sa construction et celle de l'intégrale d'Itô reposent sur la théorie de la mesure."}], "tags": ["probabilites", "brownien"], "niveau": "grandes-ecoles", "definition": "Le mouvement brownien modélise mathématiquement un déplacement complètement aléatoire et continu, à l'origine observé dans le mouvement erratique de particules dans un fluide.", "explication_formules": "La formule d'Itô est l'équivalent, pour ce mouvement aléatoire, de la règle de dérivation en chaîne classique — mais adaptée au caractère non dérivable des trajectoires browniennes. dXₜ=μdt+σdWₜ décrit un déplacement avec une tendance moyenne μ et une agitation aléatoire d'intensité σ.", "approfondissements": [{"label": "Calcul stochastique (intégrale d'Itô)", "link": {"type": "theme", "slug": "calcul-stochastique-integrale-d-ito"}}, {"label": "Équations différentielles stochastiques", "link": {"type": "notion", "id": 6}}, {"label": "Propriété de Markov du mouvement brownien", "link": {"type": "theme", "slug": "propriete-de-markov-du-mouvement-brownien"}}, {"label": "Applications à la finance (Black-Scholes)", "link": {"type": "theme", "slug": "applications-a-la-finance-black-scholes"}}, {"label": "Processus d'Ornstein-Uhlenbeck", "link": {"type": "theme", "slug": "processus-d-ornstein-uhlenbeck"}}], "sous_points": [{"terme": "Non-dérivabilité des trajectoires", "definition": "Les trajectoires du mouvement brownien sont continues mais ne sont dérivables en aucun point, ce qui empêche d'utiliser le calcul classique."}, {"terme": "Intégrale stochastique", "definition": "L'intégrale d'Itô définit rigoureusement l'intégration par rapport au mouvement brownien malgré cette non-dérivabilité."}], "applications_list": [{"text": "Fonder la modélisation des marchés financiers (prix des actions).", "icon": "finance"}, {"text": "Décrire la diffusion de particules ou de polluants dans un fluide.", "icon": "environment"}, {"text": "Modéliser le bruit dans les systèmes physiques et électroniques.", "icon": "electronics"}]}, {"id": 317, "title": "Équations différentielles stochastiques", "category": "Probabilités", "formulas": ["EDS : dXₜ=b(Xₜ)dt+σ(Xₜ)dWₜ", "Théorème d'existence et unicité (Lipschitz)", "Formule de Feynman-Kac"], "details": "Généralisation des équations différentielles au cadre aléatoire.", "images": ["eds.png"], "correspondances": [{"id": 316, "title": "Mouvement brownien et calcul stochastique"}, {"id": 322, "title": "Finance mathématique"}], "tags": ["probabilites", "eds"], "niveau": "grandes-ecoles", "definition": "Une équation différentielle stochastique généralise une équation différentielle classique en y ajoutant un terme de bruit aléatoire, pour modéliser des systèmes soumis à des perturbations imprévisibles.", "explication_formules": "dXₜ=b(Xₜ)dt+σ(Xₜ)dWₜ combine une évolution déterministe (le terme en dt) et une agitation aléatoire (le terme en dWₜ, lié au mouvement brownien). La formule de Feynman-Kac relie la résolution de telles équations à celle d'équations aux dérivées partielles classiques.", "approfondissements": [{"label": "Formule d'Itô multidimensionnelle", "link": {"type": "theme", "slug": "formule-d-ito-multidimensionnelle"}}, {"label": "Schéma numérique d'Euler-Maruyama", "link": {"type": "theme", "slug": "schema-numerique-d-euler-maruyama"}}, {"label": "Processus d'Ornstein-Uhlenbeck", "link": {"type": "theme", "slug": "processus-d-ornstein-uhlenbeck"}}, {"label": "Applications à la finance quantitative", "link": {"type": "theme", "slug": "applications-a-la-finance-quantitative"}}, {"label": "Équations différentielles stochastiques rétrogrades", "link": {"type": "notion", "id": 6}}], "sous_points": [{"terme": "Processus d'Ornstein-Uhlenbeck", "definition": "Ce processus stochastique modélise un phénomène aléatoire qui tend à revenir vers une valeur moyenne, comme un taux d'intérêt."}, {"terme": "Schéma d'Euler-Maruyama", "definition": "Ce schéma numérique discrétise une équation différentielle stochastique pour la simuler pas à pas sur ordinateur."}], "applications_list": [{"text": "Modéliser l'évolution du cours d'une action (modèle de Black-Scholes).", "icon": "finance"}, {"text": "Décrire la dynamique de populations soumises à des aléas environnementaux.", "icon": "environment"}, {"text": "Simuler des trajectoires de particules dans un fluide turbulent.", "icon": "physics"}]}, {"id": 318, "title": "Statistique mathématique", "category": "Probabilités", "formulas": ["Estimateur du maximum de vraisemblance", "Borne de Cramér-Rao", "Intervalle de confiance"], "details": "Inférence sur une population à partir d'un échantillon.", "images": ["statistique.png"], "correspondances": [{"id": 713, "title": "Statistiques avancées"}, {"id": 319, "title": "Tests d'hypothèses"}], "tags": ["probabilites", "statistique"], "niveau": "prepa", "definition": "La statistique mathématique développe des méthodes rigoureuses pour tirer des conclusions fiables sur une population entière à partir d'un échantillon limité de données observées.", "explication_formules": "L'estimateur du maximum de vraisemblance choisit, parmi tous les paramètres possibles, celui qui rend les données observées les plus probables. La borne de Cramér-Rao donne une limite théorique à la précision qu'un estimateur peut atteindre, quelle que soit la méthode utilisée.", "approfondissements": [{"label": "Biais et convergence d'un estimateur", "link": {"type": "theme", "slug": "biais-et-convergence-d-un-estimateur"}}, {"label": "Statistique exhaustive", "link": {"type": "theme", "slug": "statistique-exhaustive"}}, {"label": "Intervalles de confiance", "link": {"type": "theme", "slug": "intervalles-de-confiance"}}, {"label": "Tests d'hypothèses", "link": {"type": "notion", "id": 319}}, {"label": "Estimation bayésienne", "link": {"type": "theme", "slug": "estimation-bayesienne"}}], "sous_points": [{"terme": "Biais", "definition": "Un estimateur est sans biais s'il donne, en moyenne sur de nombreux échantillons, la vraie valeur du paramètre recherché."}, {"terme": "Convergence", "definition": "Un estimateur convergent devient de plus en plus précis à mesure que la taille de l'échantillon augmente."}, {"terme": "Tests d'hypothèses", "definition": "Un test d'hypothèse décide, à partir des données, si une hypothèse sur la population doit être rejetée ou non."}], "applications_list": [{"text": "Estimer des grandeurs inconnues à partir de sondages.", "icon": "data"}, {"text": "Analyser des essais cliniques en médecine.", "icon": "medicine"}, {"text": "Calibrer des modèles en science des données.", "icon": "data"}]}, {"id": 319, "title": "Tests d'hypothèses", "category": "Probabilités", "formulas": ["Erreur de première espèce α", "Lemme de Neyman-Pearson", "Test du χ²"], "details": "Méthodes pour valider ou rejeter statistiquement une hypothèse.", "images": ["tests.png"], "correspondances": [{"id": 318, "title": "Statistique mathématique"}, {"id": 313, "title": "Théorème central limite"}], "tags": ["probabilites", "tests"], "niveau": "prepa", "definition": "Un test d'hypothèse est une procédure statistique rigoureuse pour décider, à partir de données observées, si une hypothèse sur une population doit être rejetée ou non, en contrôlant le risque d'erreur.", "explication_formules": "L'erreur de première espèce α est le risque accepté de rejeter à tort une hypothèse vraie (typiquement fixé à 5%). Le lemme de Neyman-Pearson donne la façon optimale de construire un test pour un niveau d'erreur donné. Le test du χ² compare des fréquences observées à des fréquences théoriques attendues.", "approfondissements": [{"label": "Puissance d'un test et erreur de seconde espèce", "link": {"type": "theme", "slug": "puissance-d-un-test-et-erreur-de-seconde-espece"}}, {"label": "p-valeur et interprétation", "link": {"type": "theme", "slug": "p-valeur-et-interpretation"}}, {"label": "Tests paramétriques vs non paramétriques", "link": {"type": "theme", "slug": "tests-parametriques-vs-non-parametriques"}}, {"label": "Tests multiples et correction (Bonferroni)", "link": {"type": "theme", "slug": "tests-multiples-et-correction-bonferroni"}}, {"label": "Tests bayésiens", "link": {"type": "theme", "slug": "tests-bayesiens"}}], "sous_points": [{"terme": "Puissance d'un test", "definition": "La puissance d'un test mesure sa capacité à détecter un effet réel quand il existe effectivement."}, {"terme": "p-valeur", "definition": "La p-valeur mesure la probabilité d'observer un résultat au moins aussi extrême que celui obtenu, en supposant l'hypothèse nulle vraie."}], "applications_list": [{"text": "Valider l'efficacité d'un nouveau médicament en essai clinique.", "icon": "medicine"}, {"text": "Détecter une fraude ou une anomalie dans des données.", "icon": "security"}, {"text": "Vérifier scientifiquement une hypothèse en recherche.", "icon": "research"}]}, {"id": 320, "title": "Grandes déviations et concentration", "category": "Probabilités", "formulas": ["Inégalité de Markov", "Inégalité de Bienaymé-Tchebychev", "Théorème de Cramér (grandes déviations)"], "details": "Estimation de la probabilité d'événements rares.", "images": ["grandes_deviations.png"], "correspondances": [{"id": 313, "title": "Théorème central limite"}, {"id": 318, "title": "Statistique mathématique"}], "tags": ["probabilites", "concentration"], "niveau": "grandes-ecoles", "definition": "Les grandes déviations étudient la probabilité, généralement très faible, qu'une variable aléatoire s'écarte fortement de sa valeur moyenne attendue — les événements rares mais possibles.", "explication_formules": "L'inégalité de Markov borne grossièrement mais universellement la probabilité qu'une variable positive dépasse un seuil. Le théorème de Cramér affine cette estimation en donnant une décroissance exponentielle précise de la probabilité d'un écart important, via une fonction de taux.", "approfondissements": [{"label": "Inégalité de Bienaymé-Tchebychev", "link": {"type": "theme", "slug": "inegalite-de-bienayme-tchebychev"}}, {"label": "Fonction de taux et principe de grandes déviations", "link": {"type": "theme", "slug": "fonction-de-taux-et-principe-de-grandes-deviations"}}, {"label": "Inégalités de concentration modernes", "link": {"type": "theme", "slug": "inegalites-de-concentration-modernes"}}, {"label": "Applications à la gestion du risque", "link": {"type": "theme", "slug": "applications-a-la-gestion-du-risque"}}, {"label": "Grandes déviations en physique statistique", "link": {"type": "theme", "slug": "grandes-deviations-en-physique-statistique"}}], "sous_points": [{"terme": "Fonction de taux", "definition": "La fonction de taux quantifie, de façon exponentielle, la probabilité décroissante d'un écart important à la moyenne."}, {"terme": "Inégalités de concentration", "definition": "Ces inégalités bornent finement la probabilité qu'une somme de variables aléatoires s'écarte fortement de sa moyenne."}], "applications_list": [{"text": "Évaluer le risque d'événements catastrophiques rares en finance.", "icon": "finance"}, {"text": "Dimensionner des systèmes pour résister à des pics de charge exceptionnels.", "icon": "industry"}, {"text": "Analyser la fiabilité de systèmes critiques.", "icon": "industry"}]}, {"id": 321, "title": "Processus de Poisson et files d'attente", "category": "Probabilités", "formulas": ["P(N(t)=k)=e^{-λt}(λt)^k/k!", "Temps d'attente exponentiels", "Processus de naissance et de mort"], "details": "Modélisation d'événements aléatoires se produisant dans le temps.", "images": ["poisson.png"], "correspondances": [{"id": 314, "title": "Chaînes de Markov"}, {"id": 312, "title": "Variables aléatoires continues"}], "tags": ["probabilites", "poisson"], "niveau": "grandes-ecoles", "definition": "Le processus de Poisson modélise des événements qui se produisent aléatoirement dans le temps, de façon indépendante et à un rythme moyen constant — comme les appels reçus par un standard téléphonique.", "explication_formules": "P(N(t)=k)=e^{-λt}(λt)^k/k! donne la probabilité d'observer exactement k événements pendant une durée t, avec un taux moyen λ. Les temps d'attente entre deux événements successifs suivent naturellement une loi exponentielle.", "approfondissements": [{"label": "Files d'attente (modèle M/M/1)", "link": {"type": "theme", "slug": "files-d-attente-modele-m-m-1"}}, {"label": "Processus de naissance et de mort", "link": {"type": "theme", "slug": "processus-de-naissance-et-de-mort"}}, {"label": "Théorie du renouvellement", "link": {"type": "theme", "slug": "theorie-du-renouvellement"}}, {"label": "Processus de Poisson composé", "link": {"type": "theme", "slug": "processus-de-poisson-compose"}}, {"label": "Applications à la fiabilité des systèmes", "link": {"type": "theme", "slug": "applications-a-la-fiabilite-des-systemes"}}], "sous_points": [{"terme": "Files d'attente", "definition": "Une file d'attente modélise l'arrivée et le service aléatoires de clients, permettant de calculer le temps d'attente moyen."}, {"terme": "Théorie du renouvellement", "definition": "Cette théorie étudie des processus où un événement se répète à des intervalles aléatoires indépendants."}], "applications_list": [{"text": "Dimensionner un centre d'appels ou un guichet.", "icon": "communication"}, {"text": "Modéliser les pannes d'équipements.", "icon": "industry"}, {"text": "Gérer les stocks en fonction de la demande aléatoire des clients.", "icon": "finance"}]}, {"id": 322, "title": "Finance mathématique", "category": "Probabilités", "formulas": ["Formule de Black-Scholes", "Portefeuille auto-financé", "Mesure de probabilité risque-neutre"], "details": "Modélisation mathématique de la valorisation des produits financiers.", "images": ["finance.png"], "correspondances": [{"id": 316, "title": "Mouvement brownien et calcul stochastique"}, {"id": 317, "title": "Équations différentielles stochastiques"}], "tags": ["probabilites", "finance"], "niveau": "grandes-ecoles", "definition": "La finance mathématique utilise les probabilités et le calcul stochastique pour évaluer le juste prix des produits financiers complexes, comme les options, en modélisant l'incertitude du marché.", "explication_formules": "La formule de Black-Scholes donne le prix théorique d'une option en fonction du prix actuel de l'actif, de sa volatilité et du temps restant. Le principe d'absence d'opportunité d'arbitrage garantit qu'il n'existe pas de stratégie permettant de gagner de l'argent sans aucun risque.", "approfondissements": [{"label": "Modèle binomial de Cox-Ross-Rubinstein", "link": {"type": "theme", "slug": "modele-binomial-de-cox-ross-rubinstein"}}, {"label": "Gestion de portefeuille (Markowitz)", "link": {"type": "theme", "slug": "gestion-de-portefeuille-markowitz"}}, {"label": "Mesures de risque (VaR, CVaR)", "link": {"type": "theme", "slug": "mesures-de-risque-var-cvar"}}, {"label": "Options américaines et arrêt optimal", "link": {"type": "theme", "slug": "options-americaines-et-arret-optimal"}}, {"label": "Modèles de taux d'intérêt", "link": {"type": "theme", "slug": "modeles-de-taux-d-interet"}}], "sous_points": [{"terme": "Absence d'arbitrage", "definition": "Ce principe fondamental dit qu'il n'existe pas de stratégie permettant de gagner de l'argent sans aucun risque sur un marché financier."}, {"terme": "Modèle binomial de Cox-Ross-Rubinstein", "definition": "Ce modèle discret évalue le prix d'une option en simulant l'évolution du sous-jacent par une succession de hausses et de baisses."}], "applications_list": [{"text": "Évaluer et négocier des produits dérivés sur les marchés financiers.", "icon": "finance"}, {"text": "Gérer le risque d'un portefeuille d'investissement.", "icon": "finance"}, {"text": "Concevoir des stratégies de couverture (hedging).", "icon": "finance"}]}, {"id": 323, "title": "Séries temporelles", "category": "Probabilités", "formulas": ["Modèle ARMA(p,q)", "Modèle GARCH", "Théorème de Wold"], "details": "Analyse statistique de données indexées dans le temps.", "images": ["series_temp.png"], "correspondances": [{"id": 318, "title": "Statistique mathématique"}, {"id": 313, "title": "Théorème central limite"}], "tags": ["probabilites", "series-temporelles"], "niveau": "grandes-ecoles", "definition": "Les séries temporelles analysent des données observées dans l'ordre chronologique (ventes mensuelles, cours de bourse quotidien...) pour en comprendre la structure et prévoir leur évolution future.", "explication_formules": "Un modèle ARMA(p,q) combine une dépendance aux valeurs passées (partie autorégressive) et aux erreurs passées (moyenne mobile) pour décrire l'évolution d'une série. Le modèle GARCH modélise spécifiquement la volatilité, qui peut elle-même varier dans le temps.", "approfondissements": [{"label": "Stationnarité et différenciation", "link": {"type": "theme", "slug": "stationnarite-et-differenciation"}}, {"label": "Autocorrélation et autocorrélation partielle", "link": {"type": "theme", "slug": "autocorrelation-et-autocorrelation-partielle"}}, {"label": "Modèles GARCH (volatilité variable)", "link": {"type": "theme", "slug": "modeles-garch-volatilite-variable"}}, {"label": "Cointégration (séries liées à long terme)", "link": {"type": "theme", "slug": "cointegration-series-liees-a-long-terme"}}, {"label": "Prévision et intervalles de confiance", "link": {"type": "theme", "slug": "prevision-et-intervalles-de-confiance"}}], "sous_points": [{"terme": "Stationnarité", "definition": "Une série temporelle stationnaire a des propriétés statistiques (moyenne, variance) stables dans le temps."}, {"terme": "Autocorrélation", "definition": "L'autocorrélation mesure la dépendance d'une série avec ses propres valeurs passées."}, {"terme": "Prévision", "definition": "Prévoir une série temporelle utilise sa structure passée pour estimer ses valeurs futures, avec un intervalle d'incertitude."}], "applications_list": [{"text": "Prévoir les ventes futures d'une entreprise.", "icon": "finance"}, {"text": "Analyser et anticiper les fluctuations boursières.", "icon": "finance"}, {"text": "Modéliser des données climatiques ou épidémiologiques.", "icon": "environment"}]}, {"id": 419, "title": "Mécanique lagrangienne et hamiltonienne", "category": "Physique", "formulas": ["Lagrangien L=T−V", "Équations d'Euler-Lagrange", "Hamiltonien H=Σpq̇−L"], "details": "Formulations avancées de la mécanique classique fondées sur des principes variationnels.", "images": ["lagrangien.png"], "correspondances": [{"id": 714, "title": "Physique avancée"}, {"id": 226, "title": "Géométrie symplectique et mécanique hamiltonienne"}], "tags": ["physique", "mecanique-analytique"], "niveau": "prepa", "definition": "Les formulations lagrangienne et hamiltonienne réécrivent la mécanique classique de façon plus abstraite et puissante, fondées sur des principes d'optimisation plutôt que sur les forces directement.", "explication_formules": "Le lagrangien L=T-V (énergie cinétique moins énergie potentielle) résume toute la dynamique d'un système. Les équations d'Euler-Lagrange, dérivées d'un principe de moindre action, redonnent les lois de Newton mais s'adaptent bien mieux aux systèmes complexes ou contraints.", "approfondissements": [{"label": "Hamiltonien et équations canoniques", "link": {"type": "theme", "slug": "hamiltonien-et-equations-canoniques"}}, {"label": "Principe de moindre action", "link": {"type": "theme", "slug": "principe-de-moindre-action"}}, {"label": "Coordonnées généralisées", "link": {"type": "theme", "slug": "coordonnees-generalisees"}}, {"label": "Symétries et lois de conservation (Noether)", "link": {"type": "theme", "slug": "symetries-et-lois-de-conservation-noether"}}, {"label": "Mécanique céleste (orbites)", "link": {"type": "theme", "slug": "mecanique-celeste-orbites"}}], "sous_points": [{"terme": "Principe de moindre action", "definition": "Ce principe variationnel postule que la trajectoire réellement suivie par un système est celle qui rend stationnaire une quantité appelée action."}, {"terme": "Équations canoniques de Hamilton", "definition": "Ces équations décrivent l'évolution d'un système dans l'espace des phases (position et impulsion), formulation équivalente à celle de Newton."}], "applications_list": [{"text": "Modéliser des systèmes mécaniques complexes avec contraintes.", "icon": "industry"}, {"text": "Fonder la transition vers la mécanique quantique.", "icon": "physics"}]}, {"id": 420, "title": "Mécanique quantique", "category": "Physique", "formulas": ["Équation de Schrödinger : iℏ∂ψ/∂t=Ĥψ", "Relation de commutation [x̂,p̂]=iℏ", "Principe d'incertitude de Heisenberg"], "details": "Description du comportement des systèmes physiques à l'échelle microscopique.", "images": ["quantique.png"], "correspondances": [{"id": 19, "title": "Espaces de Hilbert et opérateurs"}, {"id": 421, "title": "Relativité restreinte"}], "tags": ["physique", "quantique"], "niveau": "grandes-ecoles", "definition": "La mécanique quantique décrit le comportement de la matière et de l'énergie à l'échelle microscopique (atomes, particules), où les phénomènes classiques cèdent la place à des lois profondément différentes.", "explication_formules": "L'équation de Schrödinger iℏ∂ψ/∂t=Ĥψ décrit l'évolution de la fonction d'onde ψ, qui contient toute l'information sur un système quantique. Le principe d'incertitude de Heisenberg impose une limite fondamentale à la précision simultanée de la position et de la vitesse d'une particule.", "approfondissements": [{"label": "Fonction d'onde et probabilités", "link": {"type": "theme", "slug": "fonction-d-onde-et-probabilites"}}, {"label": "Effet tunnel", "link": {"type": "theme", "slug": "effet-tunnel"}}, {"label": "Spin et particules identiques", "link": {"type": "theme", "slug": "spin-et-particules-identiques"}}, {"label": "Intrication quantique", "link": {"type": "theme", "slug": "intrication-quantique"}}, {"label": "Applications à l'informatique quantique", "link": {"type": "theme", "slug": "applications-a-l-informatique-quantique"}}], "sous_points": [{"terme": "Espace de Hilbert des états", "definition": "En mécanique quantique, l'état d'un système est représenté par un vecteur dans un espace de Hilbert."}, {"terme": "Opérateurs observables", "definition": "Les grandeurs physiques mesurables (position, énergie) sont représentées par des opérateurs hermitiens agissant sur l'espace des états."}], "applications_list": [{"text": "Fonder le fonctionnement des transistors et de l'électronique moderne.", "icon": "electronics"}, {"text": "Concevoir des lasers et semi-conducteurs.", "icon": "electronics"}, {"text": "Développer l'informatique quantique émergente.", "icon": "computer"}]}, {"id": 421, "title": "Relativité restreinte", "category": "Physique", "formulas": ["Transformation de Lorentz", "E=mc²", "Intervalle d'espace-temps : ds²=c²dt²−dx²"], "details": "Théorie unifiant espace et temps pour les vitesses proches de celle de la lumière.", "images": ["relativite_restreinte.png"], "correspondances": [{"id": 422, "title": "Relativité générale"}, {"id": 420, "title": "Mécanique quantique"}], "tags": ["physique", "relativite"], "niveau": "prepa", "definition": "La relativité restreinte révise les notions classiques d'espace et de temps pour des objets se déplaçant à des vitesses proches de celle de la lumière, où temps et espace deviennent inséparables.", "explication_formules": "La transformation de Lorentz remplace les lois classiques du changement de repère aux vitesses élevées. E=mc² montre l'équivalence fondamentale entre masse et énergie. L'intervalle d'espace-temps ds²=c²dt²-dx² reste invariant quel que soit l'observateur, contrairement au temps et à l'espace pris séparément.", "approfondissements": [{"label": "Dilatation du temps et contraction des longueurs", "link": {"type": "theme", "slug": "dilatation-du-temps-et-contraction-des-longueurs"}}, {"label": "Quadrivecteurs", "link": {"type": "theme", "slug": "quadrivecteurs"}}, {"label": "Équivalence masse-énergie", "link": {"type": "theme", "slug": "equivalence-masse-energie"}}, {"label": "Effet Doppler relativiste", "link": {"type": "theme", "slug": "effet-doppler-relativiste"}}, {"label": "Transition vers la relativité générale", "link": {"type": "notion", "id": 422}}], "sous_points": [{"terme": "Dilatation du temps", "definition": "En relativité restreinte, le temps s'écoule plus lentement pour un objet en mouvement rapide, vu par un observateur au repos."}, {"terme": "Contraction des longueurs", "definition": "Un objet en mouvement rapide apparaît raccourci dans la direction du mouvement, vu par un observateur au repos."}], "applications_list": [{"text": "Corriger les horloges des satellites GPS.", "icon": "navigation"}, {"text": "Fonder la physique des accélérateurs de particules.", "icon": "research"}]}, {"id": 422, "title": "Relativité générale", "category": "Physique", "formulas": ["Équations d'Einstein : Gμν=8πG/c⁴ Tμν", "Métrique de Schwarzschild", "Tenseur de courbure de Ricci"], "details": "Théorie géométrique de la gravitation reliant courbure et matière.", "images": ["relativite_generale.png"], "correspondances": [{"id": 225, "title": "Géométrie riemannienne"}, {"id": 421, "title": "Relativité restreinte"}], "tags": ["physique", "relativite-generale"], "niveau": "grandes-ecoles", "definition": "La relativité générale décrit la gravité non pas comme une force, mais comme une courbure de l'espace-temps provoquée par la présence de masse et d'énergie.", "explication_formules": "Les équations d'Einstein Gμν=8πG/c⁴Tμν relient la courbure de l'espace-temps (membre de gauche) à la distribution de matière et d'énergie (membre de droite). La métrique de Schwarzschild décrit la courbure autour d'un objet massif sphérique, comme une étoile ou un trou noir.", "approfondissements": [{"label": "Géodésiques et trajectoires en espace-temps courbe", "link": {"type": "theme", "slug": "geodesiques-et-trajectoires-en-espace-temps-courbe"}}, {"label": "Trous noirs et horizon des événements", "link": {"type": "theme", "slug": "trous-noirs-et-horizon-des-evenements"}}, {"label": "Ondes gravitationnelles", "link": {"type": "theme", "slug": "ondes-gravitationnelles"}}, {"label": "Cosmologie relativiste", "link": {"type": "theme", "slug": "cosmologie-relativiste"}}, {"label": "Tests expérimentaux de la relativité générale", "link": {"type": "notion", "id": 422}}], "sous_points": [{"terme": "Géodésiques", "definition": "Une géodésique est la trajectoire naturelle d'un objet en chute libre dans un espace-temps courbe, généralisant la ligne droite."}, {"terme": "Trous noirs", "definition": "Un trou noir est une région où la gravité est si intense que rien, pas même la lumière, ne peut s'en échapper."}], "applications_list": [{"text": "Corriger avec précision les horloges des satellites GPS.", "icon": "navigation"}, {"text": "Expliquer la déviation de la lumière par les astres massifs.", "icon": "space"}, {"text": "Fonder l'astrophysique moderne (trous noirs, ondes gravitationnelles).", "icon": "space"}]}, {"id": 423, "title": "Électromagnétisme avancé", "category": "Physique", "formulas": ["Équations de Maxwell", "Force de Lorentz : F=q(E+v×B)", "Équation d'onde électromagnétique"], "details": "Théorie unifiée de l'électricité, du magnétisme et de la lumière.", "images": ["em_avance.png"], "correspondances": [{"id": 418, "title": "Électromagnétisme"}, {"id": 421, "title": "Relativité restreinte"}], "tags": ["physique", "electromagnetisme"], "niveau": "prepa", "definition": "Cette notion approfondit l'électromagnétisme avec un formalisme plus avancé (forces, ondes, formes différentielles) permettant de traiter des situations complexes en ingénierie et en physique théorique.", "explication_formules": "Les équations de Maxwell régissent tous les phénomènes électromagnétiques. La force de Lorentz F=q(E+v×B) combine l'effet des champs électrique et magnétique sur une charge en mouvement. L'équation d'onde électromagnétique montre que lumière et ondes radio se propagent à la même vitesse universelle c.", "approfondissements": [{"label": "Potentiels électromagnétiques et jauge de Lorenz", "link": {"type": "theme", "slug": "potentiels-electromagnetiques-et-jauge-de-lorenz"}}, {"label": "Rayonnement d'une antenne", "link": {"type": "theme", "slug": "rayonnement-d-une-antenne"}}, {"label": "Électromagnétisme dans les milieux (diélectriques, conducteurs)", "link": {"type": "theme", "slug": "electromagnetisme-dans-les-milieux-dielectriques-conducteurs"}}, {"label": "Formulation covariante (relativiste)", "link": {"type": "theme", "slug": "formulation-covariante-relativiste"}}, {"label": "Métamatériaux et applications", "link": {"type": "theme", "slug": "metamateriaux-et-applications"}}], "sous_points": [{"terme": "Formulation en formes différentielles", "definition": "Réécrire les équations de Maxwell avec des formes différentielles les rend remarquablement compactes et révèle leur structure géométrique."}, {"terme": "Potentiels vecteur et scalaire", "definition": "Ces potentiels permettent de reformuler les équations de Maxwell plus simplement, à partir desquels champs électrique et magnétique se déduisent."}], "applications_list": [{"text": "Concevoir des antennes, radars et systèmes de communication avancés.", "icon": "communication"}, {"text": "Modéliser la propagation des ondes dans des matériaux complexes.", "icon": "research"}]}, {"id": 424, "title": "Mécanique des fluides", "category": "Physique", "formulas": ["Équations de Navier-Stokes", "Équation de continuité", "Nombre de Reynolds"], "details": "Étude du mouvement des liquides et des gaz.", "images": ["fluides_av.png"], "correspondances": [{"id": 414, "title": "Fluides"}, {"id": 425, "title": "Thermodynamique statistique"}], "tags": ["physique", "fluides"], "niveau": "prepa", "definition": "La mécanique des fluides avancée étudie mathématiquement le mouvement des liquides et des gaz, avec des équations bien plus complètes que le modèle simplifié de Bernoulli.", "explication_formules": "Les équations de Navier-Stokes généralisent la loi de Newton (F=ma) à un fluide continu, en tenant compte de sa viscosité. Le nombre de Reynolds compare les forces d'inertie aux forces visqueuses et détermine si un écoulement sera laminaire (régulier) ou turbulent (chaotique).", "approfondissements": [{"label": "Turbulence et théorie du chaos", "link": {"type": "theme", "slug": "turbulence-et-theorie-du-chaos"}}, {"label": "Couche limite", "link": {"type": "theme", "slug": "couche-limite"}}, {"label": "Écoulements compressibles (aérodynamique supersonique)", "link": {"type": "theme", "slug": "ecoulements-compressibles-aerodynamique-supersonique"}}, {"label": "Problème d'existence et régularité (prix du millénaire)", "link": {"type": "theme", "slug": "probleme-d-existence-et-regularite-prix-du-millenaire"}}, {"label": "Simulation numérique (CFD)", "link": {"type": "theme", "slug": "simulation-numerique-cfd"}}], "sous_points": [{"terme": "Écoulements laminaires", "definition": "Un écoulement laminaire est régulier et prévisible, organisé en couches parallèles qui ne se mélangent pas."}, {"terme": "Écoulements turbulents", "definition": "Un écoulement turbulent est chaotique et tourbillonnant, imprévisible dans le détail malgré des équations déterministes."}], "applications_list": [{"text": "Prévoir la météo et les courants océaniques à grande échelle.", "icon": "environment"}, {"text": "Optimiser l'aérodynamique des avions et voitures de course.", "icon": "transport"}, {"text": "Concevoir des systèmes de climatisation efficaces.", "icon": "industry"}]}, {"id": 425, "title": "Thermodynamique statistique", "category": "Physique", "formulas": ["Entropie de Boltzmann : S=k ln(Ω)", "Fonction de partition Z", "Distribution de Boltzmann"], "details": "Lien entre les propriétés microscopiques et macroscopiques de la matière.", "images": ["thermo_stat.png"], "correspondances": [{"id": 411, "title": "Thermodynamique"}, {"id": 424, "title": "Mécanique des fluides"}], "tags": ["physique", "thermo-stat"], "niveau": "grandes-ecoles", "definition": "La thermodynamique statistique explique les lois macroscopiques de la thermodynamique (température, entropie) à partir du comportement statistique d'un très grand nombre de particules microscopiques.", "explication_formules": "L'entropie de Boltzmann S=k ln(Ω) relie l'entropie macroscopique au nombre Ω de configurations microscopiques possibles pour un même état observable. La fonction de partition Z résume toute l'information statistique d'un système à l'équilibre thermique.", "approfondissements": [{"label": "Distribution de Boltzmann", "link": {"type": "theme", "slug": "distribution-de-boltzmann"}}, {"label": "Ensembles statistiques (microcanonique, canonique)", "link": {"type": "theme", "slug": "ensembles-statistiques-microcanonique-canonique"}}, {"label": "Transitions de phase et point critique", "link": {"type": "theme", "slug": "transitions-de-phase-et-point-critique"}}, {"label": "Lien entropie-information (Shannon)", "link": {"type": "theme", "slug": "lien-entropie-information-shannon"}}, {"label": "Applications à la physique des matériaux", "link": {"type": "theme", "slug": "applications-a-la-physique-des-materiaux"}}], "sous_points": [{"terme": "Ensembles statistiques", "definition": "Un ensemble statistique (microcanonique, canonique) décrit un système physique en contact ou non avec un thermostat extérieur."}, {"terme": "Transitions de phase", "definition": "Une transition de phase est un changement brutal d'état de la matière (fusion, ébullition), étudié via la physique statistique."}], "applications_list": [{"text": "Expliquer l'irréversibilité de l'écoulement de la chaleur.", "icon": "research"}, {"text": "Fonder la conception des réfrigérateurs et moteurs thermiques.", "icon": "industry"}, {"text": "Comprendre les transitions de phase (fusion, ébullition).", "icon": "chemistry"}]}, {"id": 426, "title": "Théorie de jauge et interactions fondamentales", "category": "Physique", "formulas": ["Équations de Yang-Mills", "Groupe de jauge SU(N)", "Connexion sur un fibré principal"], "details": "Cadre mathématique décrivant les interactions fondamentales de la physique des particules.", "images": ["jauge.png"], "correspondances": [{"id": 231, "title": "Fibrés vectoriels et classes caractéristiques"}, {"id": 423, "title": "Électromagnétisme avancé"}], "tags": ["physique", "jauge"], "niveau": "grandes-ecoles", "definition": "Les théories de jauge décrivent les interactions fondamentales de la physique des particules (électromagnétique, faible, forte) comme des conséquences de symétries mathématiques profondes.", "explication_formules": "Les équations de Yang-Mills généralisent les équations de Maxwell à des symétries plus complexes que celle de l'électromagnétisme. Le groupe de jauge SU(N) détermine quelle interaction fondamentale est décrite (SU(3) pour l'interaction forte, par exemple).", "approfondissements": [{"label": "Modèle Standard de la physique des particules", "link": {"type": "theme", "slug": "modele-standard-de-la-physique-des-particules"}}, {"label": "Brisure spontanée de symétrie", "link": {"type": "theme", "slug": "brisure-spontanee-de-symetrie"}}, {"label": "Boson de Higgs", "link": {"type": "theme", "slug": "boson-de-higgs"}}, {"label": "Interaction forte et chromodynamique quantique", "link": {"type": "theme", "slug": "interaction-forte-et-chromodynamique-quantique"}}, {"label": "Unification des forces fondamentales", "link": {"type": "theme", "slug": "unification-des-forces-fondamentales"}}], "sous_points": [{"terme": "Fibrés principaux", "definition": "Un fibré principal attache un groupe de symétrie à chaque point de l'espace-temps, le cadre géométrique des théories de jauge."}, {"terme": "Brisure de symétrie", "definition": "Un système peut posséder une symétrie parfaite dans ses équations tout en adoptant un état final qui la brise."}], "applications_list": [{"text": "Fonder théoriquement le Modèle Standard de la physique des particules.", "icon": "research"}, {"text": "Comprendre les accélérateurs de particules comme le LHC.", "icon": "research"}]}, {"id": 427, "title": "Systèmes dynamiques et chaos", "category": "Physique", "formulas": ["Exposants de Lyapunov", "Bifurcation de Hopf", "Attracteur étrange"], "details": "Étude de l'évolution des systèmes sensibles aux conditions initiales.", "images": ["chaos.png"], "correspondances": [{"id": 15, "title": "Équations différentielles linéaires"}, {"id": 425, "title": "Thermodynamique statistique"}], "tags": ["physique", "chaos"], "niveau": "grandes-ecoles", "definition": "Les systèmes dynamiques et le chaos étudient comment des systèmes régis par des règles déterministes simples peuvent produire un comportement extrêmement imprévisible à long terme.", "explication_formules": "Les exposants de Lyapunov mesurent à quelle vitesse deux trajectoires infiniment proches s'écartent l'une de l'autre au fil du temps ; un exposant positif signale du chaos (sensibilité extrême aux conditions initiales). Une bifurcation de Hopf marque un changement qualitatif brutal du comportement d'un système quand un paramètre varie.", "approfondissements": [{"label": "Attracteurs étranges (Lorenz)", "link": {"type": "theme", "slug": "attracteurs-etranges-lorenz"}}, {"label": "Bifurcations et diagrammes de bifurcation", "link": {"type": "theme", "slug": "bifurcations-et-diagrammes-de-bifurcation"}}, {"label": "Théorie KAM (stabilité des systèmes intégrables)", "link": {"type": "theme", "slug": "theorie-kam-stabilite-des-systemes-integrables"}}, {"label": "Chaos en météorologie", "link": {"type": "theme", "slug": "chaos-en-meteorologie"}}, {"label": "Applications à la biologie des populations", "link": {"type": "theme", "slug": "applications-a-la-biologie-des-populations"}}], "sous_points": [{"terme": "Théorème de Poincaré-Bendixson", "definition": "Ce théorème classifie le comportement à long terme des systèmes dynamiques plans : point fixe, cycle, ou rien d'autre."}, {"terme": "Sections de Poincaré", "definition": "Une section de Poincaré réduit l'étude d'un système dynamique continu à celle d'une application discrète plus facile à analyser."}], "applications_list": [{"text": "Expliquer pourquoi la météo n'est prévisible qu'à court terme.", "icon": "environment"}, {"text": "Analyser la stabilité des écosystèmes et des populations.", "icon": "biology"}, {"text": "Comprendre les fluctuations des marchés financiers.", "icon": "finance"}]}, {"id": 428, "title": "Physique statistique et transitions de phase", "category": "Physique", "formulas": ["Modèle d'Ising", "Point critique et exposants critiques", "Groupe de renormalisation (introduction)"], "details": "Étude des changements d'état de la matière à l'échelle macroscopique.", "images": ["transitions_phase.png"], "correspondances": [{"id": 425, "title": "Thermodynamique statistique"}, {"id": 427, "title": "Systèmes dynamiques et chaos"}], "tags": ["physique", "transitions-phase"], "niveau": "grandes-ecoles", "definition": "La physique statistique des transitions de phase étudie comment un système change brutalement d'état (aimantation, changement d'état de la matière) au voisinage d'un point critique.", "explication_formules": "Le modèle d'Ising, très simplifié, capture néanmoins l'essentiel du comportement des matériaux magnétiques près de leur température critique. Les exposants critiques décrivent comment certaines grandeurs physiques divergent ou s'annulent près du point critique, souvent de façon universelle (indépendante des détails microscopiques).", "approfondissements": [{"label": "Modèle d'Ising et champ moyen", "link": {"type": "theme", "slug": "modele-d-ising-et-champ-moyen"}}, {"label": "Groupe de renormalisation", "link": {"type": "theme", "slug": "groupe-de-renormalisation"}}, {"label": "Universalité des exposants critiques", "link": {"type": "theme", "slug": "universalite-des-exposants-critiques"}}, {"label": "Transitions de phase du second ordre", "link": {"type": "theme", "slug": "transitions-de-phase-du-second-ordre"}}, {"label": "Applications hors de la physique (réseaux, épidémies)", "link": {"type": "theme", "slug": "applications-hors-de-la-physique-reseaux-epidemies"}}], "sous_points": [{"terme": "Phénomènes coopératifs", "definition": "Un phénomène coopératif émerge du comportement collectif de nombreuses particules en interaction, comme l'aimantation spontanée."}, {"terme": "Universalité", "definition": "L'universalité désigne le fait que des systèmes très différents partagent les mêmes exposants critiques près d'une transition de phase."}], "applications_list": [{"text": "Comprendre l'aimantation des matériaux ferromagnétiques.", "icon": "industry"}, {"text": "Analyser des transitions dans des réseaux sociaux ou épidémies.", "icon": "network"}]}, {"id": 429, "title": "Théorie quantique des champs (introduction)", "category": "Physique", "formulas": ["Intégrale de chemin de Feynman", "Propagateur", "Quantification canonique"], "details": "Extension de la mécanique quantique aux champs et aux particules.", "images": ["tqc.png"], "correspondances": [{"id": 420, "title": "Mécanique quantique"}, {"id": 426, "title": "Théorie de jauge et interactions fondamentales"}], "tags": ["physique", "tqc"], "niveau": "grandes-ecoles", "definition": "La théorie quantique des champs unifie mécanique quantique et relativité restreinte, en décrivant les particules elles-mêmes comme des excitations de champs fondamentaux remplissant tout l'espace.", "explication_formules": "L'intégrale de chemin de Feynman calcule la probabilité d'un processus en sommant sur toutes les trajectoires possibles, pas seulement la plus probable classiquement. Le propagateur décrit comment une perturbation se propage d'un point à un autre dans un champ quantique.", "approfondissements": [{"label": "Diagrammes de Feynman", "link": {"type": "theme", "slug": "diagrammes-de-feynman"}}, {"label": "Renormalisation", "link": {"type": "theme", "slug": "renormalisation"}}, {"label": "Quantification des champs", "link": {"type": "theme", "slug": "quantification-des-champs"}}, {"label": "Théorie quantique des champs et particules virtuelles", "link": {"type": "notion", "id": 429}}, {"label": "Modèle Standard", "link": {"type": "theme", "slug": "modele-standard"}}], "sous_points": [{"terme": "Diagrammes de Feynman", "definition": "Ces diagrammes représentent visuellement les interactions entre particules, chaque élément graphique correspondant à un terme mathématique du calcul."}, {"terme": "Renormalisation", "definition": "Cette technique retire des infinis qui apparaissent naturellement dans les calculs de théorie quantique des champs pour obtenir des prédictions finies."}], "applications_list": [{"text": "Fonder le Modèle Standard de la physique des particules.", "icon": "research"}, {"text": "Prédire les résultats des expériences en accélérateurs de particules.", "icon": "research"}]}, {"id": 430, "title": "Cosmologie mathématique", "category": "Physique", "formulas": ["Métrique de Friedmann-Lemaître-Robertson-Walker", "Équation de Friedmann", "Constante cosmologique Λ"], "details": "Application de la relativité générale à la structure et l'évolution de l'univers.", "images": ["cosmologie.png"], "correspondances": [{"id": 422, "title": "Relativité générale"}, {"id": 428, "title": "Physique statistique et transitions de phase"}], "tags": ["physique", "cosmologie"], "niveau": "grandes-ecoles", "definition": "La cosmologie mathématique applique la relativité générale à l'univers dans son ensemble, pour modéliser sa forme, son évolution et son expansion à très grande échelle.", "explication_formules": "La métrique de Friedmann-Lemaître-Robertson-Walker décrit un univers en expansion homogène et isotrope. L'équation de Friedmann relie le taux d'expansion de l'univers à sa densité de matière et d'énergie, y compris la constante cosmologique Λ associée à l'énergie noire.", "approfondissements": [{"label": "Big Bang et rayonnement fossile", "link": {"type": "theme", "slug": "big-bang-et-rayonnement-fossile"}}, {"label": "Énergie noire et constante cosmologique", "link": {"type": "theme", "slug": "energie-noire-et-constante-cosmologique"}}, {"label": "Inflation cosmique", "link": {"type": "theme", "slug": "inflation-cosmique"}}, {"label": "Matière noire", "link": {"type": "theme", "slug": "matiere-noire"}}, {"label": "Structure à grande échelle de l'univers", "link": {"type": "theme", "slug": "structure-a-grande-echelle-de-l-univers"}}], "sous_points": [{"terme": "Expansion de l'univers", "definition": "L'expansion de l'univers désigne l'éloignement mutuel des galaxies observé et expliqué par la relativité générale."}, {"terme": "Modèle du Big Bang", "definition": "Ce modèle cosmologique décrit l'univers comme ayant émergé d'un état extrêmement dense et chaud il y a environ 13,8 milliards d'années."}], "applications_list": [{"text": "Expliquer et prédire l'expansion observée de l'univers.", "icon": "space"}, {"text": "Interpréter le rayonnement fossile.", "icon": "space"}, {"text": "Estimer l'âge et la composition de l'univers.", "icon": "space"}]}, {"id": 521, "title": "Calculabilité et machines de Turing", "category": "Informatique", "formulas": ["Machine de Turing", "Problème de l'arrêt (indécidable)", "Thèse de Church-Turing"], "details": "Étude des limites théoriques de ce qui peut être calculé algorithmiquement.", "images": ["turing.png"], "correspondances": [{"id": 510, "title": "Complexité algorithmique"}, {"id": 522, "title": "Classes de complexité P et NP"}], "tags": ["informatique", "calculabilite"], "niveau": "grandes-ecoles", "definition": "La calculabilité étudie les limites théoriques absolues de ce qu'un ordinateur peut calculer, indépendamment de sa puissance ou de sa vitesse — certains problèmes sont tout simplement insolubles algorithmiquement.", "explication_formules": "Une machine de Turing est un modèle abstrait de calcul universel, capable en principe d'exécuter tout algorithme possible. Le problème de l'arrêt (déterminer si un programme donné va terminer ou tourner indéfiniment) est prouvé indécidable : aucun algorithme ne peut le résoudre pour tous les programmes.", "approfondissements": [{"label": "Thèse de Church-Turing", "link": {"type": "theme", "slug": "these-de-church-turing"}}, {"label": "Problème de l'arrêt et indécidabilité", "link": {"type": "theme", "slug": "probleme-de-l-arret-et-indecidabilite"}}, {"label": "Fonctions récursives", "link": {"type": "theme", "slug": "fonctions-recursives"}}, {"label": "Théorème de Rice", "link": {"type": "theme", "slug": "theoreme-de-rice"}}, {"label": "Machines de Turing universelles", "link": {"type": "theme", "slug": "machines-de-turing-universelles"}}], "sous_points": [{"terme": "Fonctions récursives", "definition": "Les fonctions récursives forment une classe précise de fonctions calculables, équivalente en puissance aux machines de Turing."}, {"terme": "Théorème de Rice", "definition": "Ce théorème dit qu'aucune propriété non triviale du comportement d'un programme ne peut être décidée algorithmiquement pour tous les cas."}], "applications_list": [{"text": "Comprendre les limites de la vérification automatique de programmes.", "icon": "computer"}, {"text": "Fonder théoriquement toute l'informatique.", "icon": "computer"}]}, {"id": 522, "title": "Classes de complexité P et NP", "category": "Informatique", "formulas": ["P ⊆ NP ⊆ PSPACE", "NP-complétude", "Théorème de Cook-Levin"], "details": "Classification des problèmes selon les ressources nécessaires à leur résolution.", "images": ["complexite_pnp.png"], "correspondances": [{"id": 521, "title": "Calculabilité et machines de Turing"}, {"id": 510, "title": "Complexité algorithmique"}, {"key": "sup:1544", "title": "Graphes eulériens et hamiltoniens", "raison": "Décider si un graphe a un circuit eulérien est polynomial (connexité et degrés pairs), alors que décider s'il a un circuit hamiltonien est NP-complet : deux énoncés voisins, deux classes de complexité."}, {"key": "sup:1893", "title": "Algorithmes de factorisation (introduction, lien cryptographie)", "raison": "La sécurité de RSA repose sur l'hypothèse qu'aucun algorithme polynomial ne factorise les grands entiers : le problème est dans NP, mais on ne sait pas s'il est dans P."}, {"key": "sup:1090", "title": "Programmation linéaire : introduction", "raison": "La programmation linéaire est dans P (méthode de l'ellipsoïde, points intérieurs), alors que la même programmation en nombres entiers est NP-difficile."}], "tags": ["informatique", "complexite"], "niveau": "grandes-ecoles", "definition": "Les classes P et NP distinguent les problèmes qu'on peut résoudre rapidement (P) de ceux dont on peut au moins vérifier rapidement une solution proposée (NP) — l'une des plus grandes questions ouvertes de l'informatique.", "explication_formules": "P⊆NP⊆PSPACE établit une hiérarchie d'inclusion entre classes de complexité. Un problème NP-complet est, en un sens précis, aussi difficile que n'importe quel problème de NP : le résoudre efficacement résoudrait tous les autres. Le théorème de Cook-Levin a établi le tout premier problème NP-complet (SAT).", "approfondissements": [{"label": "Problème P=NP (un million de dollars à la clé)", "link": {"type": "theme", "slug": "probleme-p-np-un-million-de-dollars-a-la-cle"}}, {"label": "Réductions polynomiales", "link": {"type": "theme", "slug": "reductions-polynomiales"}}, {"label": "Problèmes NP-complets classiques", "link": {"type": "theme", "slug": "problemes-np-complets-classiques"}}, {"label": "Approximation de problèmes NP-difficiles", "link": {"type": "theme", "slug": "approximation-de-problemes-np-difficiles"}}, {"label": "Classes de complexité randomisées", "link": {"type": "notion", "id": 522}}], "sous_points": [{"terme": "Réductions polynomiales", "definition": "Réduire un problème A à un problème B en temps polynomial montre que B est au moins aussi difficile que A."}, {"terme": "Problèmes NP-complets classiques", "definition": "Le voyageur de commerce et SAT sont des exemples emblématiques de problèmes NP-complets, très difficiles à résoudre exactement."}], "applications_list": [{"text": "Comprendre pourquoi certains problèmes d'optimisation restent difficiles.", "icon": "research"}, {"text": "Justifier la sécurité de la cryptographie moderne.", "icon": "security"}]}, {"id": 523, "title": "Logique et théorie des ensembles", "category": "Informatique", "formulas": ["Axiomes de ZFC", "Lemme de Zorn", "Théorèmes d'incomplétude de Gödel"], "details": "Fondements logiques et ensemblistes des mathématiques.", "images": ["logique_ensembles.png"], "correspondances": [{"id": 521, "title": "Calculabilité et machines de Turing"}, {"id": 511, "title": "Logique booléenne"}], "tags": ["informatique", "logique"], "niveau": "grandes-ecoles", "definition": "Cette notion fonde les mathématiques elles-mêmes sur des bases logiques rigoureuses (théorie des ensembles), et explore les limites profondes de ce qui peut être prouvé dans un système formel.", "explication_formules": "Les axiomes de ZFC forment le socle standard de toutes les mathématiques modernes. Le lemme de Zorn (équivalent à l'axiome du choix) garantit l'existence d'éléments maximaux dans certaines structures. Les théorèmes d'incomplétude de Gödel montrent qu'aucun système assez puissant ne peut prouver sa propre cohérence, ni prouver toutes les vérités qu'il peut exprimer.", "approfondissements": [{"label": "Axiome du choix et ses conséquences", "link": {"type": "theme", "slug": "axiome-du-choix-et-ses-consequences"}}, {"label": "Hypothèse du continu", "link": {"type": "theme", "slug": "hypothese-du-continu"}}, {"label": "Théorèmes d'incomplétude de Gödel (approfondi)", "link": {"type": "theme", "slug": "theoremes-d-incompletude-de-godel-approfondi"}}, {"label": "Théorie des modèles", "link": {"type": "theme", "slug": "theorie-des-modeles"}}, {"label": "Calculabilité et logique", "link": {"type": "theme", "slug": "calculabilite-et-logique"}}], "sous_points": [{"terme": "Axiome du choix", "definition": "Cet axiome garantit qu'on peut toujours choisir un élément dans chaque ensemble d'une collection, même infinie."}, {"terme": "Hypothèse du continu", "definition": "Cette hypothèse affirme qu'il n'existe pas d'ensemble de taille strictement intermédiaire entre ℕ et ℝ ; elle est indécidable dans ZFC."}], "applications_list": [{"text": "Fonder rigoureusement toutes les mathématiques modernes.", "icon": "education"}, {"text": "Comprendre les limites de la preuve automatique de théorèmes en IA.", "icon": "computer"}]}, {"id": 524, "title": "Théorie de l'information", "category": "Informatique", "formulas": ["Entropie de Shannon : H(X)=−Σp log p", "Capacité de canal", "Théorème de codage sans bruit"], "details": "Quantification mathématique de l'information et de sa transmission.", "images": ["info_theorie.png"], "correspondances": [{"id": 518, "title": "Réseaux"}, {"id": 525, "title": "Algorithmique numérique"}], "tags": ["informatique", "information"], "niveau": "grandes-ecoles", "definition": "La théorie de l'information quantifie mathématiquement la quantité d'information contenue dans un message, et détermine les limites théoriques de sa compression et de sa transmission fiable.", "explication_formules": "L'entropie de Shannon H(X)=-Σp log p mesure l'incertitude moyenne (donc l'information) portée par une source aléatoire. La capacité de canal donne le débit maximal d'information transmissible de façon fiable à travers un canal bruité, une limite théorique infranchissable.", "approfondissements": [{"label": "Codage de source (compression optimale)", "link": {"type": "theme", "slug": "codage-de-source-compression-optimale"}}, {"label": "Codage de canal et codes correcteurs", "link": {"type": "theme", "slug": "codage-de-canal-et-codes-correcteurs"}}, {"label": "Théorème de Shannon (codage sans bruit)", "link": {"type": "theme", "slug": "theoreme-de-shannon-codage-sans-bruit"}}, {"label": "Entropie et apprentissage automatique", "link": {"type": "notion", "id": 530}}, {"label": "Théorie de l'information quantique", "link": {"type": "notion", "id": 524}}], "sous_points": [{"terme": "Codage source", "definition": "Le codage source vise à représenter l'information avec le moins de bits possible, la limite étant l'entropie de Shannon."}, {"terme": "Codes correcteurs d'erreurs", "definition": "Ces codes ajoutent une redondance calculée pour détecter et corriger automatiquement les erreurs de transmission."}], "applications_list": [{"text": "Concevoir des algorithmes de compression optimaux (ZIP, JPEG, MP3).", "icon": "data"}, {"text": "Déterminer le débit maximal d'une liaison de télécommunication.", "icon": "communication"}, {"text": "Fonder les codes correcteurs d'erreurs.", "icon": "computer"}]}, {"id": 525, "title": "Algorithmique numérique", "category": "Informatique", "formulas": ["Méthode de Newton-Raphson", "Interpolation de Lagrange", "Quadrature de Gauss"], "details": "Méthodes de calcul approché pour résoudre des problèmes mathématiques.", "images": ["algo_numerique.png"], "correspondances": [{"id": 507, "title": "Programmation dynamique"}, {"id": 526, "title": "Transformée de Fourier rapide et traitement du signal"}], "tags": ["informatique", "numerique"], "niveau": "prepa", "definition": "L'algorithmique numérique développe des méthodes de calcul approché pour résoudre des problèmes mathématiques qui n'ont pas de solution exacte simple à calculer directement.", "explication_formules": "La méthode de Newton-Raphson trouve rapidement une racine d'une fonction en suivant successivement ses tangentes. L'interpolation de Lagrange construit un polynôme passant exactement par un ensemble de points donnés. La quadrature de Gauss calcule une intégrale approchée avec une précision optimale pour un nombre donné de points d'évaluation.", "approfondissements": [{"label": "Stabilité et convergence des méthodes numériques", "link": {"type": "theme", "slug": "stabilite-et-convergence-des-methodes-numeriques"}}, {"label": "Résolution numérique d'équations différentielles", "link": {"type": "notion", "id": 6}}, {"label": "Méthodes itératives pour systèmes linéaires", "link": {"type": "theme", "slug": "methodes-iteratives-pour-systemes-lineaires"}}, {"label": "Analyse d'erreur numérique", "link": {"type": "theme", "slug": "analyse-d-erreur-numerique"}}, {"label": "Applications à la simulation scientifique", "link": {"type": "theme", "slug": "applications-a-la-simulation-scientifique"}}], "sous_points": [{"terme": "Stabilité", "definition": "Une méthode numérique stable ne voit pas ses erreurs s'amplifier au fil des calculs successifs."}, {"terme": "Convergence des schémas numériques", "definition": "La convergence garantit qu'une méthode numérique se rapproche effectivement de la solution exacte recherchée."}], "applications_list": [{"text": "Résoudre numériquement des équations sans formule explicite.", "icon": "research"}, {"text": "Simuler des phénomènes physiques complexes.", "icon": "physics"}, {"text": "Calibrer des modèles scientifiques à partir de données expérimentales.", "icon": "research"}]}, {"id": 526, "title": "Transformée de Fourier rapide et traitement du signal", "category": "Informatique", "formulas": ["FFT (Fast Fourier Transform)", "Théorème de Shannon-Nyquist", "Convolution discrète"], "details": "Algorithmes efficaces d'analyse fréquentielle des signaux.", "images": ["fft.png"], "correspondances": [{"id": 7, "title": "Séries de Fourier"}, {"id": 525, "title": "Algorithmique numérique"}, {"key": "sup:1030", "title": "Racines n-ièmes d'un nombre complexe", "raison": "La FFT s'appuie sur les racines n-ièmes de l'unité : les carrés des racines d'ordre n sont les racines d'ordre n/2, ce qui permet de découper le calcul en deux moitiés."}, {"key": "sup:312", "title": "Transformée de Fourier : définition", "raison": "Le théorème de convolution change f∗g en produit f̂·ĝ : avec la FFT, convoluer deux signaux de n points coûte O(n log n) au lieu de O(n²)."}, {"key": "sup:339", "title": "Fonction caractéristique", "raison": "La loi d'une somme de variables indépendantes est une convolution, donc un produit de fonctions caractéristiques : la FFT sert à les calculer et à les inverser numériquement, par exemple pour évaluer des prix d'options."}], "tags": ["informatique", "signal"], "niveau": "grandes-ecoles", "definition": "La transformée de Fourier rapide (FFT) est un algorithme extrêmement efficace pour calculer numériquement la décomposition en fréquences d'un signal, rendant possible le traitement du signal en temps réel.", "explication_formules": "La FFT calcule en O(n log n) ce qui prendrait naïvement O(n²) opérations, une accélération considérable pour de grands signaux. Le théorème de Shannon-Nyquist détermine la fréquence minimale d'échantillonnage nécessaire pour reconstruire fidèlement un signal continu à partir de mesures discrètes.", "approfondissements": [{"label": "Échantillonnage et théorème de Nyquist", "link": {"type": "theme", "slug": "echantillonnage-et-theoreme-de-nyquist"}}, {"label": "Convolution rapide via la FFT", "link": {"type": "theme", "slug": "convolution-rapide-via-la-fft"}}, {"label": "Filtrage numérique", "link": {"type": "theme", "slug": "filtrage-numerique"}}, {"label": "Transformée en ondelettes", "link": {"type": "theme", "slug": "transformee-en-ondelettes"}}, {"label": "Applications au traitement d'image et audio", "link": {"type": "theme", "slug": "applications-au-traitement-d-image-et-audio"}}], "sous_points": [{"terme": "Échantillonnage", "definition": "L'échantillonnage transforme un signal continu en une suite de valeurs discrètes mesurées à intervalles réguliers."}, {"terme": "Filtrage numérique", "definition": "Un filtre numérique modifie sélectivement certaines fréquences d'un signal, par exemple pour atténuer le bruit."}], "applications_list": [{"text": "Compresser l'audio (MP3) et l'image (JPEG).", "icon": "audio"}, {"text": "Analyser des signaux en temps réel (reconnaissance vocale).", "icon": "audio"}, {"text": "Traiter des images médicales (IRM, scanner).", "icon": "medicine"}]}, {"id": 527, "title": "Cryptographie computationnelle", "category": "Informatique", "formulas": ["Problème du logarithme discret", "Protocole de Diffie-Hellman", "Fonctions à sens unique"], "details": "Sécurité informatique fondée sur la difficulté de certains problèmes mathématiques.", "images": ["crypto_comput.png"], "correspondances": [{"id": 134, "title": "Cryptographie avancée (mathématiques)"}, {"id": 519, "title": "Sécurité informatique"}], "tags": ["informatique", "crypto"], "niveau": "grandes-ecoles", "definition": "La cryptographie computationnelle étudie les problèmes mathématiques réputés difficiles à résoudre par ordinateur, qui garantissent la sécurité pratique des systèmes cryptographiques modernes.", "explication_formules": "Le problème du logarithme discret (retrouver x connaissant gˣ mod n) est présumé très difficile pour des groupes bien choisis. Le protocole de Diffie-Hellman exploite précisément cette difficulté pour permettre un échange de clé sécurisé sans jamais transmettre la clé elle-même.", "approfondissements": [{"label": "Fonctions à sens unique", "link": {"type": "theme", "slug": "fonctions-a-sens-unique"}}, {"label": "Preuves à divulgation nulle de connaissance", "link": {"type": "theme", "slug": "preuves-a-divulgation-nulle-de-connaissance"}}, {"label": "Protocoles d'authentification avancés", "link": {"type": "theme", "slug": "protocoles-d-authentification-avances"}}, {"label": "Cryptographie et blockchain", "link": {"type": "theme", "slug": "cryptographie-et-blockchain"}}, {"label": "Attaques cryptanalytiques", "link": {"type": "theme", "slug": "attaques-cryptanalytiques"}}], "sous_points": [{"terme": "Preuves à divulgation nulle de connaissance", "definition": "Ce protocole permet de prouver qu'on connaît une information secrète sans jamais la révéler."}], "applications_list": [{"text": "Sécuriser les échanges de clés dans les protocoles web modernes.", "icon": "security"}, {"text": "Fonder les preuves d'identité numériques.", "icon": "security"}, {"text": "Concevoir des protocoles avancés (vote électronique, blockchain).", "icon": "security"}]}, {"id": 528, "title": "Théorie des graphes et combinatoire algébrique", "category": "Informatique", "formulas": ["Matrice laplacienne d'un graphe", "Polynôme chromatique", "Théorème de Kuratowski (planarité)"], "details": "Étude algébrique et combinatoire des structures de graphes.", "images": ["graphes_algebre.png"], "correspondances": [{"id": 503, "title": "Graphes"}, {"id": 522, "title": "Classes de complexité P et NP"}], "tags": ["informatique", "graphes"], "niveau": "grandes-ecoles", "definition": "Cette notion applique des outils algébriques (matrices, polynômes) à l'étude des graphes, révélant des propriétés structurelles profondes invisibles à l'œil nu.", "explication_formules": "La matrice laplacienne d'un graphe encode sa structure de connexions et permet, via ses valeurs propres, d'analyser sa connectivité globale. Le polynôme chromatique compte le nombre de façons de colorier un graphe avec un nombre donné de couleurs sans que deux sommets voisins partagent la même couleur.", "approfondissements": [{"label": "Théorie spectrale des graphes", "link": {"type": "theme", "slug": "theorie-spectrale-des-graphes"}}, {"label": "Graphes expanseurs", "link": {"type": "theme", "slug": "graphes-expanseurs"}}, {"label": "Théorème de Kuratowski (planarité)", "link": {"type": "theme", "slug": "theoreme-de-kuratowski-planarite"}}, {"label": "Coloration de graphes et applications", "link": {"type": "theme", "slug": "coloration-de-graphes-et-applications"}}, {"label": "Détection de communautés dans les réseaux", "link": {"type": "theme", "slug": "detection-de-communautes-dans-les-reseaux"}}], "sous_points": [{"terme": "Expanseurs", "definition": "Un graphe expanseur est à la fois peu dense et très bien connecté, une propriété exploitée en informatique théorique."}, {"terme": "Théorie spectrale des graphes", "definition": "Cette théorie étudie les valeurs propres de la matrice d'un graphe pour en révéler des propriétés structurelles profondes."}], "applications_list": [{"text": "Analyser la robustesse des réseaux sociaux face aux pannes.", "icon": "network"}, {"text": "Résoudre des problèmes de planification (fréquences, emplois du temps).", "icon": "industry"}, {"text": "Détecter des communautés dans un réseau.", "icon": "network"}]}, {"id": 529, "title": "Automates et langages formels avancés", "category": "Informatique", "formulas": ["Théorème de Kleene", "Lemme de pompage", "Grammaires hors contexte"], "details": "Théorie formelle des langages reconnus par des automates.", "images": ["automates_av.png"], "correspondances": [{"id": 513, "title": "Automates"}, {"id": 515, "title": "Langages formels"}], "tags": ["informatique", "automates"], "niveau": "grandes-ecoles", "definition": "Cette notion approfondit la théorie des automates et des langages formels, avec des résultats structurants sur ce que ces machines abstraites peuvent ou ne peuvent pas reconnaître.", "explication_formules": "Le théorème de Kleene établit l'équivalence exacte entre expressions régulières et langages reconnus par un automate fini. Le lemme de pompage fournit une méthode rigoureuse pour prouver qu'un langage n'est PAS régulier, en montrant qu'il ne peut pas être 'répété' de la façon requise.", "approfondissements": [{"label": "Grammaires hors contexte et automates à pile", "link": {"type": "theme", "slug": "grammaires-hors-contexte-et-automates-a-pile"}}, {"label": "Hiérarchie de Chomsky complète", "link": {"type": "theme", "slug": "hierarchie-de-chomsky-complete"}}, {"label": "Minimisation d'automates", "link": {"type": "theme", "slug": "minimisation-d-automates"}}, {"label": "Théorème de Chomsky-Schützenberger", "link": {"type": "theme", "slug": "theoreme-de-chomsky-schutzenberger"}}, {"label": "Applications à la vérification formelle", "link": {"type": "theme", "slug": "applications-a-la-verification-formelle"}}], "sous_points": [{"terme": "Automates à pile", "definition": "Un automate à pile ajoute une mémoire (la pile) à un automate fini, lui permettant de reconnaître des langages plus riches."}, {"terme": "Hiérarchie de Chomsky", "definition": "Cette hiérarchie classe les langages formels en quatre niveaux, chacun reconnu par une classe d'automates de plus en plus puissante."}], "applications_list": [{"text": "Concevoir des analyseurs syntaxiques robustes pour les compilateurs.", "icon": "computer"}, {"text": "Valider formellement des protocoles de communication.", "icon": "network"}]}, {"id": 530, "title": "Apprentissage automatique (fondements mathématiques)", "category": "Informatique", "formulas": ["Descente de gradient stochastique", "Fonction de perte (loss)", "Régularisation L1/L2"], "details": "Fondements mathématiques des algorithmes d'apprentissage à partir de données.", "images": ["ml_fondements.png"], "correspondances": [{"id": 525, "title": "Algorithmique numérique"}, {"id": 318, "title": "Statistique mathématique"}], "tags": ["informatique", "machine-learning"], "niveau": "grandes-ecoles", "definition": "L'apprentissage automatique développe des algorithmes qui améliorent leurs performances sur une tâche en s'entraînant sur des données, plutôt qu'en suivant des règles explicitement programmées.", "explication_formules": "La descente de gradient stochastique ajuste progressivement les paramètres d'un modèle pour minimiser une fonction de perte (l'écart entre prédictions et réalité), en utilisant à chaque étape seulement un petit échantillon de données. La régularisation L1/L2 pénalise les modèles trop complexes pour éviter le sur-apprentissage.", "approfondissements": [{"label": "Réseaux de neurones et rétropropagation", "link": {"type": "theme", "slug": "reseaux-de-neurones-et-retropropagation"}}, {"label": "Sur-apprentissage et validation croisée", "link": {"type": "theme", "slug": "sur-apprentissage-et-validation-croisee"}}, {"label": "Apprentissage supervisé vs non supervisé", "link": {"type": "theme", "slug": "apprentissage-supervise-vs-non-supervise"}}, {"label": "Optimisation convexe en apprentissage automatique", "link": {"type": "theme", "slug": "optimisation-convexe-en-apprentissage-automatique"}}, {"label": "Réseaux de neurones profonds (deep learning)", "link": {"type": "theme", "slug": "reseaux-de-neurones-profonds-deep-learning"}}], "sous_points": [{"terme": "Optimisation convexe", "definition": "De nombreux algorithmes d'apprentissage automatique reposent sur la minimisation d'une fonction convexe, garantissant un minimum global."}, {"terme": "Sur-apprentissage", "definition": "Un modèle en sur-apprentissage mémorise les données d'entraînement sans généraliser correctement à de nouvelles données."}], "applications_list": [{"text": "Fonder la reconnaissance d'images et de la parole.", "icon": "computer"}, {"text": "Alimenter les systèmes de recommandation (Netflix, Amazon).", "icon": "computer"}, {"text": "Entraîner les grands modèles de langage.", "icon": "computer"}]}, {"id": 616, "title": "Inégalités classiques avancées", "category": "Olympiades", "formulas": ["AM-GM : (a+b)/2 ≥ √(ab)", "Inégalité de Cauchy-Schwarz", "Inégalité de réarrangement"], "details": "Outils incontournables pour prouver des inégalités en olympiades.", "images": ["inegalites_av.png"], "correspondances": [{"id": 600, "title": "Inégalités classiques"}, {"id": 617, "title": "Ordre multiplicatif et théorie des nombres olympique"}], "tags": ["olympiades", "inegalites"], "niveau": "prepa", "definition": "Cette notion approfondit les inégalités classiques avec des techniques plus puissantes, indispensables pour aborder les problèmes d'inégalités les plus difficiles des olympiades internationales.", "explication_formules": "L'inégalité de réarrangement dit que la somme des produits est maximale quand les deux suites sont triées dans le même ordre, et minimale quand elles sont triées en ordre opposé. Cauchy-Schwarz, sous sa forme la plus générale, reste l'outil le plus polyvalent pour borner des sommes de produits.", "approfondissements": [{"label": "Inégalité de Schur", "link": {"type": "theme", "slug": "inegalite-de-schur"}}, {"label": "Méthode SOS (somme de carrés) avancée", "link": {"type": "theme", "slug": "methode-sos-somme-de-carres-avancee"}}, {"label": "Inégalités avec contraintes (Lagrange en compétition)", "link": {"type": "theme", "slug": "inegalites-avec-contraintes-lagrange-en-competition"}}, {"label": "Inégalité de Muirhead", "link": {"type": "theme", "slug": "inegalite-de-muirhead"}}, {"label": "Inégalités intégrales (niveau avancé)", "link": {"type": "theme", "slug": "inegalites-integrales-niveau-avance"}}], "sous_points": [{"terme": "Inégalité de Jensen", "definition": "Cette inégalité dit que l'image de la moyenne par une fonction convexe est toujours inférieure ou égale à la moyenne des images."}, {"terme": "Inégalité de Schur", "definition": "Cette inégalité classique pour réels positifs complète souvent AM-GM et Cauchy-Schwarz dans les problèmes à trois variables."}], "applications_list": [{"text": "Résoudre les problèmes d'inégalités les plus exigeants des olympiades internationales.", "icon": "education"}, {"text": "Développer une maîtrise technique transférable à l'analyse convexe.", "icon": "research"}]}, {"id": 617, "title": "Ordre multiplicatif et théorie des nombres olympique", "category": "Olympiades", "formulas": ["Ordre de a modulo n", "Petit théorème de Fermat", "Lifting the Exponent (LTE)"], "details": "Techniques avancées de théorie des nombres pour les olympiades.", "images": ["ordre_multiplicatif.png"], "correspondances": [{"id": 608, "title": "Théorie des nombres olympique"}, {"id": 121, "title": "Arithmétique avancée"}], "tags": ["olympiades", "theorie-des-nombres"], "niveau": "prepa", "definition": "Cette notion approfondit la théorie des nombres olympique avec des techniques avancées (ordre multiplicatif, Lifting the Exponent) pour résoudre des problèmes de divisibilité particulièrement difficiles.", "explication_formules": "L'ordre de a modulo n est le plus petit entier k tel que aᵏ≡1 (mod n), une notion clé pour analyser la structure cyclique de l'arithmétique modulaire. La technique du Lifting the Exponent (LTE) calcule précisément la puissance d'un nombre premier divisant une expression du type aⁿ-bⁿ, bien plus rapidement qu'une analyse directe.", "approfondissements": [{"label": "Lifting the Exponent (LTE) en détail", "link": {"type": "theme", "slug": "lifting-the-exponent-lte-en-detail"}}, {"label": "Résidus quadratiques et loi de réciprocité", "link": {"type": "theme", "slug": "residus-quadratiques-et-loi-de-reciprocite"}}, {"label": "Ordre multiplicatif et groupes cycliques", "link": {"type": "theme", "slug": "ordre-multiplicatif-et-groupes-cycliques"}}, {"label": "Théorème de Zsygmondy", "link": {"type": "theme", "slug": "theoreme-de-zsygmondy"}}, {"label": "Équations exponentielles diophantiennes", "link": {"type": "notion", "id": 609}}], "sous_points": [{"terme": "Résidus quadratiques", "definition": "Un résidu quadratique modulo p est un carré parfait dans l'arithmétique modulaire, étudié via la loi de réciprocité quadratique."}, {"terme": "Équations diophantiennes", "definition": "L'ordre multiplicatif éclaire souvent la résolution d'équations diophantiennes impliquant des puissances."}], "applications_list": [{"text": "Résoudre les problèmes de théorie des nombres les plus techniques des olympiades.", "icon": "education"}, {"text": "Développer une intuition avancée pour la théorie algébrique des nombres.", "icon": "research"}]}, {"id": 618, "title": "Double comptage et principes d'invariance", "category": "Olympiades", "formulas": ["Principe des tiroirs (Dirichlet)", "Double comptage", "Invariants et semi-invariants"], "details": "Techniques combinatoires puissantes pour les preuves d'existence.", "images": ["double_comptage.png"], "correspondances": [{"id": 606, "title": "Combinatoire avancée"}, {"id": 615, "title": "Méthode des invariants"}], "tags": ["olympiades", "combinatoire"], "niveau": "prepa", "definition": "Cette notion combine le double comptage et les principes d'invariance en des techniques combinatoires avancées, permettant de résoudre des problèmes de dénombrement particulièrement subtils.", "explication_formules": "Le double comptage évalue une même quantité de deux façons différentes pour en déduire une égalité non triviale entre deux expressions a priori sans rapport apparent. Le principe des tiroirs, poussé à l'extrême, garantit l'existence de configurations denses dans de grands ensembles structurés.", "approfondissements": [{"label": "Double comptage avancé (identités combinatoires)", "link": {"type": "theme", "slug": "double-comptage-avance-identites-combinatoires"}}, {"label": "Principe des tiroirs généralisé (version forte)", "link": {"type": "theme", "slug": "principe-des-tiroirs-generalise-version-forte"}}, {"label": "Combinatoire extrémale", "link": {"type": "theme", "slug": "combinatoire-extremale"}}, {"label": "Théorème de Ramsey (cas généraux)", "link": {"type": "theme", "slug": "theoreme-de-ramsey-cas-generaux"}}, {"label": "Applications à la théorie des graphes", "link": {"type": "theme", "slug": "applications-a-la-theorie-des-graphes"}}], "sous_points": [{"terme": "Coloriages", "definition": "Un coloriage bien choisi révèle une contrainte cachée qui prouve l'impossibilité d'une configuration."}, {"terme": "Monovariants", "definition": "Un monovariant, quantité qui évolue toujours dans le même sens, prouve qu'un processus itératif se termine forcément."}], "applications_list": [{"text": "Résoudre les problèmes combinatoires les plus difficiles des olympiades.", "icon": "education"}, {"text": "Fonder les bases de la combinatoire extrémale universitaire.", "icon": "research"}]}, {"id": 619, "title": "Puissance d'un point et inversion", "category": "Olympiades", "formulas": ["Puissance d'un point : P(M)=MA·MB", "Inversion de centre O et rapport k", "Théorème de Ptolémée"], "details": "Techniques avancées de géométrie synthétique pour les olympiades.", "images": ["inversion.png"], "correspondances": [{"id": 610, "title": "Géométrie olympique"}, {"id": 611, "title": "Barycentres"}], "tags": ["olympiades", "geometrie"], "niveau": "prepa", "definition": "Cette notion regroupe des techniques avancées de géométrie synthétique (puissance d'un point, inversion) qui transforment des problèmes de géométrie complexes en configurations beaucoup plus simples à analyser.", "explication_formules": "La puissance d'un point P(M)=MA·MB relie de façon constante les distances aux intersections d'une droite avec un cercle. L'inversion de centre O et rapport k transforme cercles et droites les uns en les autres selon des règles précises, simplifiant radicalement certaines configurations géométriques complexes.", "approfondissements": [{"label": "Inversion géométrique avancée", "link": {"type": "theme", "slug": "inversion-geometrique-avancee"}}, {"label": "Théorème de Ptolémée et ses généralisations", "link": {"type": "theme", "slug": "theoreme-de-ptolemee-et-ses-generalisations"}}, {"label": "Axe radical et faisceaux de cercles", "link": {"type": "theme", "slug": "axe-radical-et-faisceaux-de-cercles"}}, {"label": "Configurations projectives en géométrie olympique", "link": {"type": "notion", "id": 610}}, {"label": "Géométrie inversive et cercles orthogonaux", "link": {"type": "theme", "slug": "geometrie-inversive-et-cercles-orthogonaux"}}], "sous_points": [{"terme": "Cercles orthogonaux", "definition": "Deux cercles orthogonaux se coupent à angle droit ; cette propriété se préserve par inversion géométrique."}, {"terme": "Transformation par inversion", "definition": "L'inversion transforme cercles et droites les uns dans les autres selon des règles précises, simplifiant certaines configurations."}], "applications_list": [{"text": "Résoudre les problèmes de géométrie les plus techniques des olympiades.", "icon": "education"}, {"text": "Transformer un problème insoluble en exercice élémentaire par inversion.", "icon": "research"}]}, {"id": 620, "title": "Polynômes et équations fonctionnelles avancés", "category": "Olympiades", "formulas": ["Relations coefficients-racines", "Équation de Cauchy : f(x+y)=f(x)+f(y)", "Polynômes à coefficients entiers"], "details": "Techniques de résolution de problèmes portant sur des polynômes ou fonctions inconnues.", "images": ["poly_fonc_av.png"], "correspondances": [{"id": 603, "title": "Équations fonctionnelles"}, {"id": 102, "title": "Polynômes"}], "tags": ["olympiades", "polynomes"], "niveau": "prepa", "definition": "Cette notion approfondit les équations fonctionnelles et polynomiales avec des techniques avancées, pour résoudre les problèmes les plus exigeants impliquant des fonctions ou polynômes inconnus.", "explication_formules": "Les relations coefficients-racines (relations de Viète) relient directement les coefficients d'un polynôme à des combinaisons symétriques de ses racines, sans avoir besoin de les calculer explicitement. L'équation de Cauchy f(x+y)=f(x)+f(y), combinée à des hypothèses de régularité, caractérise exactement les fonctions linéaires.", "approfondissements": [{"label": "Polynômes à coefficients entiers et congruences", "link": {"type": "theme", "slug": "polynomes-a-coefficients-entiers-et-congruences"}}, {"label": "Substitutions avancées en équations fonctionnelles", "link": {"type": "notion", "id": 603}}, {"label": "Polynômes irréductibles en compétition", "link": {"type": "theme", "slug": "polynomes-irreductibles-en-competition"}}, {"label": "Équations fonctionnelles multivariables", "link": {"type": "notion", "id": 603}}, {"label": "Points fixes et itération de fonctions", "link": {"type": "theme", "slug": "points-fixes-et-iteration-de-fonctions"}}], "sous_points": [{"terme": "Substitutions astucieuses", "definition": "Essayer des substitutions simples (x=0, y=0, x=y) dans une équation fonctionnelle révèle souvent rapidement des informations essentielles."}, {"terme": "Points fixes", "definition": "Un point fixe d'une fonction vérifie f(x)=x ; en trouver un est souvent l'étape clé pour résoudre une équation fonctionnelle."}], "applications_list": [{"text": "Résoudre les problèmes de polynômes les plus difficiles des olympiades.", "icon": "education"}, {"text": "Développer une intuition transférable à l'algèbre abstraite.", "icon": "research"}]}, {"id": 621, "title": "Théorie des graphes en olympiades", "category": "Olympiades", "formulas": ["Lemme des poignées de main", "Théorème de Ramsey (cas simples)", "Coloration de graphes"], "details": "Application de la théorie des graphes à des problèmes de compétition.", "images": ["graphes_olymp.png"], "correspondances": [{"id": 607, "title": "Graphes olympiques"}, {"id": 528, "title": "Théorie des graphes et combinatoire algébrique"}], "tags": ["olympiades", "graphes"], "niveau": "prepa", "definition": "Cette notion approfondit l'usage de la théorie des graphes en compétition mathématique, avec des résultats structurants comme le théorème de Ramsey pour résoudre des problèmes combinatoires complexes.", "explication_formules": "Le lemme des poignées de main dit que la somme des degrés de tous les sommets d'un graphe est toujours paire (chaque arête est comptée deux fois). Le théorème de Ramsey garantit que, dans un graphe suffisamment grand, on trouve forcément une structure régulière (triangle monochrome, par exemple), quel que soit l'aléa apparent de la coloration.", "approfondissements": [{"label": "Théorème de Ramsey (cas généraux et nombres de Ramsey)", "link": {"type": "theme", "slug": "theoreme-de-ramsey-cas-generaux-et-nombres-de-ramsey"}}, {"label": "Graphes extrémaux", "link": {"type": "theme", "slug": "graphes-extremaux"}}, {"label": "Tournois et propriétés structurelles", "link": {"type": "theme", "slug": "tournois-et-proprietes-structurelles"}}, {"label": "Théorie de Ramsey en combinatoire additive", "link": {"type": "theme", "slug": "theorie-de-ramsey-en-combinatoire-additive"}}, {"label": "Applications à l'informatique théorique", "link": {"type": "notion", "id": 715}}], "sous_points": [{"terme": "Graphes extrémaux", "definition": "La théorie des graphes extrémaux cherche le nombre maximal d'arêtes qu'un graphe peut avoir sans contenir une sous-structure interdite."}, {"terme": "Tournois", "definition": "Un tournoi est un graphe orienté complet représentant les résultats de matchs entre tous les participants."}], "applications_list": [{"text": "Résoudre les problèmes de théorie des graphes les plus avancés.", "icon": "education"}, {"text": "Fonder les bases de la combinatoire extrémale et de la théorie de Ramsey.", "icon": "research"}]}, {"id": 622, "title": "Stratégies de preuve avancées", "category": "Olympiades", "formulas": ["Récurrence forte", "Descente infinie de Fermat", "Principe extrémal"], "details": "Méthodes de démonstration classiques en olympiades mathématiques.", "images": ["strategies_preuve.png"], "correspondances": [{"id": 605, "title": "Récurrences"}, {"id": 609, "title": "Équations diophantiennes"}], "tags": ["olympiades", "methodes"], "niveau": "prepa", "definition": "Cette notion regroupe les grandes stratégies de démonstration utilisées en compétition mathématique, une véritable boîte à outils méthodologique indispensable pour tout mathématicien olympique.", "explication_formules": "La récurrence forte suppose la propriété vraie pour TOUS les rangs précédents (pas seulement le précédent immédiat) pour la prouver au rang suivant. La descente infinie de Fermat prouve l'absence de solution en montrant qu'une solution supposée en engendrerait indéfiniment de plus petites — contradiction logique inévitable.", "approfondissements": [{"label": "Principe extrémal (choisir l'élément extrémal)", "link": {"type": "theme", "slug": "principe-extremal-choisir-l-element-extremal"}}, {"label": "Preuve par contradiction avancée", "link": {"type": "theme", "slug": "preuve-par-contradiction-avancee"}}, {"label": "Induction structurelle", "link": {"type": "theme", "slug": "induction-structurelle"}}, {"label": "Stratégies de bijection", "link": {"type": "theme", "slug": "strategies-de-bijection"}}, {"label": "Heuristiques de résolution de problèmes (Pólya)", "link": {"type": "theme", "slug": "heuristiques-de-resolution-de-problemes-polya"}}], "sous_points": [{"terme": "Choix de l'élément extrémal", "definition": "Cette stratégie consiste à choisir l'élément le plus grand, le plus petit ou le plus particulier d'une configuration pour en tirer une conclusion."}, {"terme": "Contradiction", "definition": "La preuve par contradiction suppose le contraire de ce qu'on veut prouver et en déduit une absurdité, validant ainsi l'énoncé initial."}], "applications_list": [{"text": "Structurer méthodiquement l'approche de tout problème de compétition.", "icon": "education"}]}, {"id": 623, "title": "Coloriages et pavages avancés", "category": "Olympiades", "formulas": ["Argument de coloriage (échiquier)", "Invariant de parité", "Pavages par polyominos"], "details": "Résolution de problèmes de pavage et de coloriage par arguments d'invariance.", "images": ["coloriages_av.png"], "correspondances": [{"id": 612, "title": "Colorations"}, {"id": 613, "title": "Pavages"}], "tags": ["olympiades", "coloriages"], "niveau": "prepa", "definition": "Cette notion approfondit les techniques de coloriage et de pavage avec des arguments d'invariance avancés, pour prouver l'impossibilité de configurations complexes en compétition.", "explication_formules": "L'argument de coloriage (échiquier) attribue des couleurs alternées et compte combien de cases de chaque couleur sont recouvertes par une pièce donnée, révélant une contrainte incontournable. L'invariant de parité (modulo 2) permet souvent de prouver élégamment qu'une configuration est totalement impossible.", "approfondissements": [{"label": "Pavages par polyominos complexes", "link": {"type": "theme", "slug": "pavages-par-polyominos-complexes"}}, {"label": "Colorations à plusieurs couleurs (arguments modulo n)", "link": {"type": "theme", "slug": "colorations-a-plusieurs-couleurs-arguments-modulo-n"}}, {"label": "Invariants topologiques en pavage", "link": {"type": "theme", "slug": "invariants-topologiques-en-pavage"}}, {"label": "Théorème de Wang et indécidabilité", "link": {"type": "theme", "slug": "theoreme-de-wang-et-indecidabilite"}}, {"label": "Applications aux fractales et à l'auto-similarité", "link": {"type": "theme", "slug": "applications-aux-fractales-et-a-l-auto-similarite"}}], "sous_points": [{"terme": "Coloriages multicolores", "definition": "Un coloriage utilisant plus de deux couleurs permet de révéler des contraintes plus fines qu'un simple damier."}, {"terme": "Arguments modulo n", "definition": "Étudier une quantité modulo n bien choisi révèle souvent une contrainte cachée qui prouve l'impossibilité d'une configuration."}], "applications_list": [{"text": "Résoudre les problèmes de pavage et coloriage les plus techniques.", "icon": "education"}, {"text": "Fonder les bases de la combinatoire géométrique universitaire.", "icon": "research"}]}, {"id": 716, "title": "Méthodologie de rédaction en prépa", "category": "Prépa", "formulas": ["Structure : hypothèses ⟹ conclusion", "Quantificateurs ∀ / ∃ rigoureux", "Citation précise des théorèmes utilisés"], "details": "Bonnes pratiques de rédaction mathématique rigoureuse attendues en classes préparatoires.", "images": ["redaction_prepa.png"], "correspondances": [{"id": 717, "title": "Préparation aux colles et oraux"}, {"id": 700, "title": "Espaces vectoriels normés"}], "tags": ["prepa", "methodologie"], "niveau": "prepa", "definition": "La méthodologie de rédaction en prépa regroupe les bonnes pratiques de présentation rigoureuse d'une démonstration mathématique, une compétence évaluée à chaque copie de concours.", "explication_formules": "La structure hypothèses ⟹ conclusion organise clairement tout raisonnement mathématique. L'usage rigoureux des quantificateurs ∀/∃ évite toute ambiguïté logique. La citation précise des théorèmes utilisés (nom exact, hypothèses vérifiées) est exigée pour justifier chaque étape.", "approfondissements": [{"label": "Rédaction d'une démonstration par récurrence", "link": {"type": "theme", "slug": "redaction-d-une-demonstration-par-recurrence"}}, {"label": "Justification des théorèmes cités (hypothèses vérifiées)", "link": {"type": "theme", "slug": "justification-des-theoremes-cites-hypotheses-verifiees"}}, {"label": "Présentation claire des calculs intermédiaires", "link": {"type": "theme", "slug": "presentation-claire-des-calculs-intermediaires"}}, {"label": "Éviter les erreurs de rigueur classiques", "link": {"type": "theme", "slug": "eviter-les-erreurs-de-rigueur-classiques"}}, {"label": "Rédaction sous contrainte de temps (épreuve de 4h)", "link": {"type": "theme", "slug": "redaction-sous-contrainte-de-temps-epreuve-de-4h"}}], "sous_points": [{"terme": "Clarté", "definition": "Une rédaction claire structure chaque étape du raisonnement de façon à ce qu'elle soit facilement suivie par le correcteur."}, {"terme": "Rigueur logique", "definition": "La rigueur logique exige que chaque affirmation soit justifiée par une hypothèse, un théorème ou un calcul explicite."}, {"terme": "Justification de chaque étape", "definition": "Chaque étape d'une démonstration doit être justifiée, même les passages qui semblent évidents, pour obtenir tous les points de rigueur."}], "applications_list": [{"text": "Maximiser sa note aux épreuves écrites de concours.", "icon": "education"}, {"text": "Développer une rigueur transférable à toute discipline scientifique.", "icon": "education"}]}, {"id": 717, "title": "Préparation aux colles et oraux", "category": "Prépa", "formulas": ["Plan type d'un exposé de colle", "Gestion du temps (20-30 min)", "Questions de cours vs exercices"], "details": "Stratégies pour aborder efficacement les colles hebdomadaires et oraux de concours.", "images": ["colles_oraux.png"], "correspondances": [{"id": 716, "title": "Méthodologie de rédaction en prépa"}, {"id": 718, "title": "Structure des concours écrits (Mines-Ponts, Centrale, X-ENS)"}], "tags": ["prepa", "colles"], "niveau": "prepa", "definition": "La préparation aux colles et oraux couvre les stratégies pour aborder efficacement l'exercice hebdomadaire de colle et les oraux de concours, un exercice oral spécifique aux classes préparatoires françaises.", "explication_formules": "Un plan type d'exposé de colle structure la présentation (rappel du cours, démonstration, exemple d'application) en un temps limité de 20 à 30 minutes. La distinction entre questions de cours (démonstration attendue précisément) et exercices (recherche autonome) guide la préparation.", "approfondissements": [{"label": "Techniques de mémorisation des démonstrations de cours", "link": {"type": "theme", "slug": "techniques-de-memorisation-des-demonstrations-de-cours"}}, {"label": "Gestion du stress à l'oral", "link": {"type": "theme", "slug": "gestion-du-stress-a-l-oral"}}, {"label": "Réactivité face aux questions du colleur/jury", "link": {"type": "theme", "slug": "reactivite-face-aux-questions-du-colleur-jury"}}, {"label": "Utilisation efficace du tableau", "link": {"type": "theme", "slug": "utilisation-efficace-du-tableau"}}, {"label": "Différences entre colles et oraux de concours", "link": {"type": "theme", "slug": "differences-entre-colles-et-oraux-de-concours"}}], "sous_points": [{"terme": "Maîtrise du cours", "definition": "Bien connaître son cours est la condition nécessaire pour répondre efficacement aux questions imprévues d'une colle ou d'un oral."}, {"terme": "Réactivité face aux questions", "definition": "Savoir réagir avec souplesse à une question inattendue, sans paniquer, est une compétence qui se développe avec l'entraînement."}], "applications_list": [{"text": "Maximiser ses performances aux colles hebdomadaires.", "icon": "education"}, {"text": "Se préparer efficacement aux oraux de concours.", "icon": "education"}]}, {"id": 718, "title": "Structure des concours écrits (Mines-Ponts, Centrale, X-ENS)", "category": "Prépa", "formulas": ["Épreuves de mathématiques 1 et 2", "Barème et points de rigueur", "Gestion du temps sur 4h"], "details": "Panorama des grandes écoles d'ingénieurs françaises et de leurs épreuves écrites.", "images": ["concours_ecrits.png"], "correspondances": [{"id": 717, "title": "Préparation aux colles et oraux"}, {"id": 719, "title": "Programme MPSI/MP : synthèse"}], "tags": ["prepa", "concours"], "niveau": "prepa", "definition": "Chaque grande école d'ingénieurs française organise ses propres épreuves écrites, avec des styles et des exigences différents (Mines-Ponts, Centrale-Supélec, X-ENS, e3a...) qu'il faut connaître pour bien se préparer.", "explication_formules": "Les épreuves de mathématiques 1 et 2 couvrent généralement analyse et algèbre séparément. Le barème valorise fortement les points de rigueur (justifications complètes), pas seulement le résultat final. La gestion du temps sur 4h impose de prioriser les questions accessibles avant les plus difficiles.", "approfondissements": [{"label": "Différences de style entre concours (analyse comparative)", "link": {"type": "theme", "slug": "differences-de-style-entre-concours-analyse-comparative"}}, {"label": "Stratégie de priorisation des questions", "link": {"type": "theme", "slug": "strategie-de-priorisation-des-questions"}}, {"label": "Annales et exercices types par concours", "link": {"type": "theme", "slug": "annales-et-exercices-types-par-concours"}}, {"label": "Gestion du stress en épreuve écrite", "link": {"type": "theme", "slug": "gestion-du-stress-en-epreuve-ecrite"}}, {"label": "Analyse des rapports de jury", "link": {"type": "theme", "slug": "analyse-des-rapports-de-jury"}}], "sous_points": [{"terme": "Différences de style entre concours", "definition": "X-ENS privilégie des sujets théoriques et exigeants en rigueur, Mines-Ponts des sujets plus calculatoires, Centrale un équilibre entre les deux."}], "applications_list": [{"text": "Adapter sa stratégie de révision selon les concours visés.", "icon": "education"}, {"text": "Optimiser sa gestion du temps le jour de l'épreuve.", "icon": "education"}]}, {"id": 719, "title": "Programme MPSI/MP : synthèse", "category": "Prépa", "formulas": ["Algèbre linéaire et bilinéaire", "Analyse réelle et complexe", "Probabilités sur univers finis"], "details": "Vue d'ensemble du programme de mathématiques en filière MPSI/MP.", "images": ["programme_mp.png"], "correspondances": [{"id": 711, "title": "Algèbre linéaire avancée"}, {"id": 720, "title": "Programme PCSI/PC : synthèse"}], "tags": ["prepa", "programme"], "niveau": "prepa", "definition": "La filière MPSI/MP (Mathématiques, Physique, Sciences de l'Ingénieur) est la plus mathématique des classes préparatoires scientifiques, avec un programme dense couvrant algèbre, analyse et probabilités.", "explication_formules": "L'algèbre linéaire et bilinéaire (espaces vectoriels, réduction, formes quadratiques) forme le socle du programme d'algèbre. L'analyse réelle et complexe couvre suites, séries, intégration et analyse complexe. Les probabilités sur univers finis introduisent les bases du calcul probabiliste rigoureux.", "approfondissements": [{"label": "Programme détaillé de première année (MPSI)", "link": {"type": "theme", "slug": "programme-detaille-de-premiere-annee-mpsi"}}, {"label": "Programme détaillé de deuxième année (MP)", "link": {"type": "theme", "slug": "programme-detaille-de-deuxieme-annee-mp"}}, {"label": "Répartition des coefficients selon les concours", "link": {"type": "theme", "slug": "repartition-des-coefficients-selon-les-concours"}}, {"label": "Options MP (informatique renforcée, physique)", "link": {"type": "theme", "slug": "options-mp-informatique-renforcee-physique"}}, {"label": "Poursuite d'études après MP", "link": {"type": "theme", "slug": "poursuite-d-etudes-apres-mp"}}], "sous_points": [{"terme": "Progression sur les deux années", "definition": "Le programme de MPSI puis MP construit progressivement des bases solides en algèbre et en analyse, de plus en plus abstraites."}], "applications_list": [{"text": "Se préparer aux concours d'entrée aux grandes écoles et aux ENS.", "icon": "education"}]}, {"id": 720, "title": "Programme PCSI/PC : synthèse", "category": "Prépa", "formulas": ["Analyse et algèbre du tronc commun", "Probabilités", "Applications à la physique-chimie"], "details": "Vue d'ensemble du programme de mathématiques en filière PCSI/PC, orienté applications physiques.", "images": ["programme_pc.png"], "correspondances": [{"id": 719, "title": "Programme MPSI/MP : synthèse"}, {"id": 714, "title": "Physique avancée"}], "tags": ["prepa", "programme"], "niveau": "prepa", "definition": "La filière PCSI/PC (Physique, Chimie) équilibre mathématiques, physique et chimie, avec un programme de mathématiques orienté vers les applications physiques plutôt que vers l'abstraction pure.", "explication_formules": "Le tronc commun d'analyse et d'algèbre reste rigoureux mais souvent introduit via des applications physiques concrètes. Les probabilités et leurs applications à la physique-chimie (mesures, incertitudes) complètent un programme volontairement plus appliqué que celui de MP.", "approfondissements": [{"label": "Programme détaillé de première année (PCSI)", "link": {"type": "theme", "slug": "programme-detaille-de-premiere-annee-pcsi"}}, {"label": "Programme détaillé de deuxième année (PC)", "link": {"type": "theme", "slug": "programme-detaille-de-deuxieme-annee-pc"}}, {"label": "Lien mathématiques-physique dans le programme PC", "link": {"type": "theme", "slug": "lien-mathematiques-physique-dans-le-programme-pc"}}, {"label": "Comparaison avec la filière MP", "link": {"type": "theme", "slug": "comparaison-avec-la-filiere-mp"}}, {"label": "Poursuite d'études après PC", "link": {"type": "theme", "slug": "poursuite-d-etudes-apres-pc"}}], "sous_points": [{"terme": "Lien fort entre mathématiques et physique-chimie", "definition": "En filière PC, de nombreux outils mathématiques (équations différentielles, séries de Fourier) sont introduits directement à travers leurs applications en physique."}], "applications_list": [{"text": "Se préparer aux concours pour un profil physique-chimie/mathématiques.", "icon": "education"}]}, {"id": 721, "title": "Khôlles de mathématiques : formats et attentes", "category": "Prépa", "formulas": ["Question de cours (démonstration exigée)", "Exercice d'application", "Exercice de recherche"], "details": "Format typique d'une khôlle et attentes du colleur.", "images": ["kholles.png"], "correspondances": [{"id": 717, "title": "Préparation aux colles et oraux"}, {"id": 716, "title": "Méthodologie de rédaction en prépa"}], "tags": ["prepa", "kholles"], "niveau": "prepa", "definition": "La khôlle est l'exercice oral hebdomadaire caractéristique des classes préparatoires françaises, où l'élève est interrogé individuellement par un enseignant sur le programme récent.", "explication_formules": "Une question de cours exige une démonstration précise et complète, attendue mot pour mot dans sa rigueur. Un exercice d'application teste la maîtrise directe du cours. Un exercice de recherche évalue la capacité à raisonner de façon autonome face à une situation nouvelle.", "approfondissements": [{"label": "Préparation ciblée par matière (maths, physique, SI)", "link": {"type": "theme", "slug": "preparation-ciblee-par-matiere-maths-physique-si"}}, {"label": "Gestion du stress face à un examinateur", "link": {"type": "theme", "slug": "gestion-du-stress-face-a-un-examinateur"}}, {"label": "Utilisation efficace du temps de préparation", "link": {"type": "theme", "slug": "utilisation-efficace-du-temps-de-preparation"}}, {"label": "Différences entre colleurs (styles variés)", "link": {"type": "theme", "slug": "differences-entre-colleurs-styles-varies"}}, {"label": "Progression mesurable au fil de l'année", "link": {"type": "theme", "slug": "progression-mesurable-au-fil-de-l-annee"}}], "sous_points": [{"terme": "Interaction avec le colleur", "definition": "Une khôlle est un dialogue actif avec l'examinateur, qui peut orienter les questions selon les réponses données."}, {"terme": "Gestion du tableau", "definition": "Structurer clairement son tableau pendant une khôlle aide à communiquer efficacement son raisonnement à l'examinateur."}], "applications_list": [{"text": "Progresser régulièrement grâce à un retour individualisé hebdomadaire.", "icon": "education"}, {"text": "S'entraîner dans des conditions proches de l'oral de concours.", "icon": "education"}]}, {"id": 722, "title": "Résolution de problèmes ouverts type concours", "category": "Prépa", "formulas": ["Analyse du problème avant rédaction", "Recherche de cas particuliers", "Conjecture puis démonstration"], "details": "Méthodologie pour aborder les problèmes longs et ouverts typiques des concours.", "images": ["problemes_ouverts.png"], "correspondances": [{"id": 718, "title": "Structure des concours écrits (Mines-Ponts, Centrale, X-ENS)"}, {"id": 622, "title": "Stratégies de preuve avancées"}], "tags": ["prepa", "methodologie"], "niveau": "prepa", "definition": "Les problèmes ouverts de type concours demandent souvent une approche méthodique en plusieurs étapes, où l'énoncé guide progressivement vers un résultat parfois surprenant.", "explication_formules": "L'analyse du problème avant rédaction identifie la structure globale et les outils pertinents avant de se lancer dans les calculs. La recherche de cas particuliers (petites valeurs, cas limites) permet souvent de deviner le résultat général avant de le démontrer rigoureusement.", "approfondissements": [{"label": "Décomposition d'un problème long en sous-questions", "link": {"type": "theme", "slug": "decomposition-d-un-probleme-long-en-sous-questions"}}, {"label": "Utilisation des questions précédentes (indices du sujet)", "link": {"type": "theme", "slug": "utilisation-des-questions-precedentes-indices-du-sujet"}}, {"label": "Conjecture et vérification sur des cas particuliers", "link": {"type": "theme", "slug": "conjecture-et-verification-sur-des-cas-particuliers"}}, {"label": "Gestion du temps sur un problème long", "link": {"type": "theme", "slug": "gestion-du-temps-sur-un-probleme-long"}}, {"label": "Techniques de blocage et déblocage", "link": {"type": "theme", "slug": "techniques-de-blocage-et-deblocage"}}], "sous_points": [{"terme": "Prise de recul", "definition": "Prendre du recul sur un problème permet d'identifier la structure générale avant de se lancer dans les calculs détaillés."}, {"terme": "Changement de stratégie si blocage", "definition": "Face à un blocage, il est souvent utile de changer complètement d'approche plutôt que d'insister sur une méthode qui ne fonctionne pas."}], "applications_list": [{"text": "Aborder efficacement les longs problèmes de concours.", "icon": "education"}, {"text": "Développer une méthode de travail transférable à la recherche.", "icon": "research"}]}, {"id": 723, "title": "Admissions en grandes écoles après prépa", "category": "Prépa", "formulas": ["Classement national par banque d'épreuves", "Vœux et affectations", "Dossier scolaire et oraux"], "details": "Panorama du processus d'admission aux grandes écoles après les classes préparatoires.", "images": ["admissions.png"], "correspondances": [{"id": 718, "title": "Structure des concours écrits (Mines-Ponts, Centrale, X-ENS)"}, {"id": 717, "title": "Préparation aux colles et oraux"}], "tags": ["prepa", "admissions"], "niveau": "grandes-ecoles", "definition": "Après deux ou trois années de classe préparatoire, les élèves candidatent aux grandes écoles via un processus d'admission basé sur les résultats aux concours et parfois un dossier scolaire.", "explication_formules": "Le classement national par banque d'épreuves (Mines-Ponts, Centrale-Supélec, X-ENS, e3a, etc.) détermine l'ordre de préférence pour l'attribution des places. Les vœux et affectations suivent un algorithme qui associe chaque candidat à l'école la plus haute dans ses préférences où son classement le permet.", "approfondissements": [{"label": "Fonctionnement des banques d'épreuves communes", "link": {"type": "theme", "slug": "fonctionnement-des-banques-d-epreuves-communes"}}, {"label": "Stratégie de choix des concours selon le profil", "link": {"type": "theme", "slug": "strategie-de-choix-des-concours-selon-le-profil"}}, {"label": "Oraux d'admission (format et préparation)", "link": {"type": "theme", "slug": "oraux-d-admission-format-et-preparation"}}, {"label": "Comparaison des débouchés selon les écoles", "link": {"type": "theme", "slug": "comparaison-des-debouches-selon-les-ecoles"}}, {"label": "Alternatives (admissions parallèles, doubles diplômes)", "link": {"type": "theme", "slug": "alternatives-admissions-paralleles-doubles-diplomes"}}], "sous_points": [{"terme": "Banques d'épreuves", "definition": "Une banque d'épreuves mutualise les résultats d'un même concours écrit entre plusieurs écoles, simplifiant les candidatures multiples."}, {"terme": "Oraux d'admission", "definition": "Les oraux d'admission, en fin de processus, évaluent la réactivité et la solidité des connaissances face à des questions imprévues."}], "applications_list": [{"text": "Optimiser sa stratégie de choix de concours et de vœux.", "icon": "education"}, {"text": "Comprendre l'aboutissement du parcours en classe préparatoire.", "icon": "education"}]}, {"id": 324, "title": "Combinatoire fondamentale", "category": "Probabilités", "formulas": ["Arrangements : A(n,k)=n!/(n-k)!", "Combinaisons : C(n,k)=n!/(k!(n-k)!)", "Binôme de Newton : (x+y)ⁿ=Σ C(n,k) xⁿ⁻ᵏyᵏ"], "details": "Étude des configurations, arrangements et dénombrements d'objets discrets.", "images": ["combinatoire.svg"], "correspondances": [{"key": "sup:673", "title": "Classes P, NP", "raison": "Le nombre de configurations (n! permutations, 2^n sous-ensembles) croît plus vite que tout polynôme : l'explosion combinatoire explique pourquoi la recherche exhaustive est impraticable pour les problèmes NP-complets."}, {"key": "sup:66", "title": "Séries entières usuelles", "raison": "Une suite de dénombrements (a_n) se code dans la série génératrice Σ a_n x^n : par exemple 1/(1−x−x²) = Σ F_(n+1) x^n donne les nombres de Fibonacci, et le rayon de convergence donne leur croissance."}, {"key": "sup:148", "title": "Bernoulli et binomiale", "raison": "Le nombre de façons de placer k succès parmi n épreuves est le coefficient binomial C(n,k) : la loi binomiale P(X=k) = C(n,k)·p^k(1−p)^(n−k) est un dénombrement pondéré."}, {"key": "sup:1396", "title": "Actions de groupes", "raison": "Compter des configurations à symétrie près revient à compter les orbites d'un groupe : le lemme de Burnside donne |X/G| = (1/|G|)·Σ_g |Fix(g)|."}, {"id": 425, "title": "Thermodynamique statistique", "raison": "L'entropie de Boltzmann S = k ln Ω compte les micro-états Ω compatibles avec un état macroscopique : c'est de la combinatoire."}], "tags": ["probabilites", "combinatoire"], "niveau": "prepa", "definition": "La combinatoire compte, de façon rigoureuse et systématique, le nombre de configurations possibles d'un ensemble d'objets — répondre précisément à la question 'combien de façons ?'.", "explication_formules": "Les arrangements A(n,k)=n!/(n-k)! comptent les façons d'ordonner k objets choisis parmi n. Les combinaisons C(n,k) comptent les mêmes choix mais sans tenir compte de l'ordre. Le binôme de Newton relie ces coefficients au développement de (x+y)ⁿ.", "approfondissements": [{"label": "Principe d'inclusion-exclusion", "link": {"type": "theme", "slug": "principe-d-inclusion-exclusion"}}, {"label": "Partitions d'un ensemble ou d'un entier", "link": {"type": "theme", "slug": "partitions-d-un-ensemble-ou-d-un-entier"}}, {"label": "Combinatoire des graphes", "link": {"type": "theme", "slug": "combinatoire-des-graphes"}}, {"label": "Combinatoire et probabilités (dénombrement de cas)", "link": {"type": "theme", "slug": "combinatoire-et-probabilites-denombrement-de-cas"}}, {"label": "Combinatoire et intelligence artificielle (espace de recherche)", "link": {"type": "theme", "slug": "combinatoire-et-intelligence-artificielle-espace-de-recherch"}}], "sous_points": [{"terme": "Principe des tiroirs", "definition": "Ce principe garantit que si l'on range plus d'objets que de tiroirs disponibles, au moins un tiroir contient plusieurs objets."}, {"terme": "Principe d'inclusion-exclusion", "definition": "Ce principe calcule la taille d'une union d'ensembles en additionnant leurs tailles puis en corrigeant les intersections comptées plusieurs fois."}, {"terme": "Coefficients binomiaux", "definition": "Le coefficient C(n,k) compte le nombre de façons de choisir k éléments parmi n, sans tenir compte de l'ordre."}, {"terme": "Triangle de Pascal", "definition": "Ce triangle de nombres permet de calculer facilement les coefficients binomiaux par additions successives, sans factorielles."}], "applications_list": [{"text": "Calculer le nombre de mots de passe possibles en sécurité informatique.", "icon": "security"}, {"text": "Déterminer les chances de gagner à une loterie.", "icon": "games"}, {"text": "Dénombrer les configurations d'un jeu de cartes ou d'un tournoi.", "icon": "games"}]}];
window.THEMES = {"fonctions-reciproques": {"title": "Fonctions réciproques", "description": "La fonction réciproque d'une fonction bijective f, notée f⁻¹, « annule » l'effet de f ; sa dérivée s'obtient à partir de celle de f par une formule simple."}, "fonctions-periodiques": {"title": "Fonctions périodiques", "description": "Une fonction périodique répète son motif à intervalles réguliers ; les séries de Fourier permettent de décomposer toute fonction périodique raisonnable en somme de sinus et cosinus."}, "fonctions-a-plusieurs-variables": {"title": "Fonctions à plusieurs variables", "description": "Une fonction de plusieurs variables associe un nombre à un vecteur d'entrées, et nécessite des outils spécifiques (dérivées partielles, gradient) pour étudier ses variations."}, "fonctions-generatrices": {"title": "Fonctions génératrices", "description": "Une fonction génératrice encode une suite de nombres comme les coefficients d'une série entière, transformant des problèmes combinatoires en manipulations algébriques sur les séries."}, "composition-et-iteration-de-fonctions": {"title": "Composition et itération de fonctions", "description": "Répéter une fonction sur elle-même (f∘f∘f...) fait apparaître des comportements riches : points fixes, cycles, voire chaos, étudiés en dynamique des systèmes."}, "limites-a-l-infini-et-asymptotes": {"title": "Limites à l'infini et asymptotes", "description": "Le comportement d'une fonction quand x tend vers l'infini révèle ses asymptotes horizontales, verticales ou obliques, essentielles pour tracer son graphe."}, "formes-indeterminees-et-regle-de-l-hopital": {"title": "Formes indéterminées et règle de l'Hôpital", "description": "Face à une forme indéterminée comme 0/0, la règle de l'Hôpital permet de calculer une limite en dérivant séparément le numérateur et le dénominateur."}, "limites-de-suites-recurrentes": {"title": "Limites de suites récurrentes", "description": "Une suite définie par uₙ₊₁=f(uₙ) converge, si elle converge, vers un point fixe de f ; étudier la limite revient souvent à résoudre f(l)=l."}, "continuite-uniforme": {"title": "Continuité uniforme", "description": "Une fonction est uniformément continue si le contrôle de la variation ne dépend pas du point considéré, une notion plus forte que la simple continuité."}, "ordres-de-grandeur-et-equivalents": {"title": "Ordres de grandeur et équivalents", "description": "Deux fonctions sont équivalentes si leur rapport tend vers 1 ; cette notion simplifie énormément le calcul de limites en ne gardant que le terme dominant."}, "continuite-uniforme-vs-simple": {"title": "Continuité uniforme vs simple", "description": "La continuité simple est locale (point par point), la continuité uniforme est globale : sur un intervalle fermé borné, les deux notions coïncident (théorème de Heine)."}, "theoreme-de-heine": {"title": "Théorème de Heine", "description": "Sur un intervalle fermé borné (compact), toute fonction continue est automatiquement uniformément continue — un résultat qui unifie deux notions de continuité a priori différentes."}, "prolongement-par-continuite": {"title": "Prolongement par continuité", "description": "Quand une fonction admet une limite finie en un point où elle n'est pas définie, on peut la prolonger en ce point pour la rendre continue."}, "fonctions-lipschitziennes": {"title": "Fonctions lipschitziennes", "description": "Une fonction lipschitzienne ne peut pas varier plus vite qu'un taux fixé : |f(x)-f(y)|≤K|x-y|, une condition de régularité utilisée pour garantir l'unicité des solutions d'équations différentielles."}, "continuite-en-dimension-superieure": {"title": "Continuité en dimension supérieure", "description": "La continuité d'une fonction de plusieurs variables doit être vérifiée selon toutes les directions d'approche possibles, pas seulement à gauche et à droite comme en une variable."}, "derivees-partielles-et-gradient": {"title": "Dérivées partielles et gradient", "description": "Une dérivée partielle mesure la variation d'une fonction par rapport à une seule variable, les autres étant fixées ; le gradient les regroupe toutes en un vecteur."}, "derivation-implicite": {"title": "Dérivation implicite", "description": "Quand une relation F(x,y)=0 définit implicitement y en fonction de x sans formule explicite, on peut néanmoins calculer dy/dx en dérivant la relation terme à terme."}, "theoreme-des-accroissements-finis": {"title": "Théorème des accroissements finis", "description": "Ce théorème garantit qu'il existe un point où la tangente à la courbe est parallèle à la corde reliant les extrémités de l'intervalle, formalisé par f(b)-f(a)=f'(c)(b-a)."}, "derivees-d-ordre-superieur-et-convexite": {"title": "Dérivées d'ordre supérieur et convexité", "description": "Les dérivées successives d'une fonction renseignent sur des propriétés de plus en plus fines de sa courbe, la dérivée seconde donnant notamment sa convexité."}, "differentielle-et-approximation-lineaire": {"title": "Différentielle et approximation linéaire", "description": "La différentielle d'une fonction en un point donne la meilleure approximation linéaire de son comportement au voisinage immédiat de ce point."}, "integrales-generalisees-bornes-infinies": {"title": "Intégrales généralisées (bornes infinies)", "description": "Une intégrale sur un intervalle infini (ou avec une fonction non bornée) se définit comme une limite d'intégrales sur des intervalles finis qui s'étendent progressivement."}, "integration-par-parties": {"title": "Intégration par parties", "description": "Cette technique transforme l'intégrale d'un produit de deux fonctions en une autre intégrale souvent plus simple, en dérivant l'une et en intégrant l'autre."}, "integrale-de-lebesgue": {"title": "Intégrale de Lebesgue", "description": "L'intégrale de Lebesgue découpe selon les valeurs de la fonction plutôt que selon son domaine, ce qui permet d'intégrer des fonctions bien plus irrégulières que ne le permet Riemann."}, "calcul-de-volumes-par-integration": {"title": "Calcul de volumes par intégration", "description": "Empiler des tranches infinitésimales d'aire connue et les intégrer permet de calculer le volume de solides complexes sans formule géométrique directe."}, "integrales-multiples": {"title": "Intégrales multiples", "description": "Une intégrale multiple (double, triple) calcule un volume ou une masse en intégrant successivement sur chaque variable, selon le théorème de Fubini."}, "equations-du-second-ordre": {"title": "Équations du second ordre", "description": "Une équation différentielle du second ordre implique la dérivée seconde de la fonction inconnue ; l'équation caractéristique associée détermine la forme de ses solutions."}, "systemes-differentiels-couples": {"title": "Systèmes différentiels couplés", "description": "Plusieurs équations différentielles peuvent être liées entre elles (la solution de l'une dépend des autres), et se résolvent souvent en les regroupant sous forme matricielle X'=AX."}, "resolution-par-transformee-de-laplace": {"title": "Résolution par transformée de Laplace", "description": "La transformée de Laplace convertit une équation différentielle linéaire en une équation algébrique, plus facile à résoudre, avant de revenir à la solution originale par transformée inverse."}, "stabilite-des-points-d-equilibre": {"title": "Stabilité des points d'équilibre", "description": "Un point d'équilibre d'une équation différentielle est stable si les trajectoires voisines y restent proches ; ce comportement se lit souvent sur le signe des valeurs propres du système linéarisé."}, "transformee-de-fourier-cas-non-periodique": {"title": "Transformée de Fourier (cas non périodique)", "description": "Contrairement à la série de Fourier (fonctions périodiques), la transformée de Fourier s'applique à des fonctions quelconques et donne un spectre continu de fréquences."}, "fft-et-traitement-numerique-du-signal": {"title": "FFT et traitement numérique du signal", "description": "La transformée de Fourier rapide calcule en O(n log n) le contenu fréquentiel d'un signal numérique, rendant possible le traitement audio et vidéo en temps réel."}, "analyse-spectrale-sur-varietes": {"title": "Analyse spectrale sur variétés", "description": "Étude des valeurs propres du laplacien sur une variété courbe : elles encodent des informations géométriques profondes, comme dans la question « peut-on entendre la forme d'un tambour ? »."}, "ondelettes-et-analyse-multi-resolution": {"title": "Ondelettes et analyse multi-résolution", "description": "Contrairement à Fourier (fréquences pures), les ondelettes décomposent un signal en motifs localisés à la fois en temps et en fréquence, idéal pour la compression d'image (JPEG 2000)."}, "theoreme-des-residus": {"title": "Théorème des résidus", "description": "Ce théorème calcule une intégrale sur un contour fermé du plan complexe comme une simple somme des résidus (coefficients caractéristiques) aux singularités entourées."}, "series-de-laurent": {"title": "Séries de Laurent", "description": "Une série de Laurent généralise la série de Taylor en autorisant des puissances négatives, permettant de décrire le comportement d'une fonction autour d'une singularité."}, "fonctions-holomorphes-et-harmoniques": {"title": "Fonctions holomorphes et harmoniques", "description": "Une fonction holomorphe (dérivable au sens complexe) a des parties réelle et imaginaire qui sont harmoniques, c'est-à-dire solutions de l'équation de Laplace."}, "prolongement-analytique": {"title": "Prolongement analytique", "description": "Le prolongement analytique étend le domaine de définition d'une fonction holomorphe au-delà de sa définition initiale, de façon unique, en exploitant sa rigidité remarquable."}, "developpements-limites": {"title": "Développements limités", "description": "Un développement limité approxime une fonction par un polynôme au voisinage d'un point, avec une erreur contrôlée qui tend vers zéro plus vite que le dernier terme gardé."}, "fonctions-analytiques": {"title": "Fonctions analytiques", "description": "Une fonction analytique coïncide localement avec sa série de Taylor : connaître son comportement sur un petit intervalle détermine entièrement son comportement partout ailleurs."}, "series-de-laurent-puissances-negatives": {"title": "Séries de Laurent (puissances négatives)", "description": "La partie à puissances négatives d'une série de Laurent capture le comportement singulier d'une fonction holomorphe près d'un pôle ou d'une singularité essentielle."}, "rayon-de-convergence-et-critere-de-cauchy-hadamard": {"title": "Rayon de convergence et critère de Cauchy-Hadamard", "description": "Le rayon de convergence d'une série entière se calcule via la formule de Cauchy-Hadamard, qui utilise la racine n-ième des coefficients de la série."}, "formule-de-taylor-avec-reste": {"title": "Formule de Taylor avec reste", "description": "La formule de Taylor approxime une fonction par un polynôme et fournit une expression précise du reste (l'erreur commise), sous forme de Lagrange ou intégrale."}, "developpements-asymptotiques": {"title": "Développements asymptotiques", "description": "Un développement asymptotique décrit précisément le comportement d'une fonction près d'une limite (souvent l'infini), au-delà d'un simple équivalent."}, "regle-de-l-hopital-via-dl": {"title": "Règle de l'Hôpital via DL", "description": "Un développement limité peut souvent remplacer la règle de l'Hôpital pour lever une forme indéterminée, en donnant directement le terme dominant du quotient."}, "dl-a-plusieurs-variables": {"title": "DL à plusieurs variables", "description": "Le développement limité d'une fonction de plusieurs variables généralise la formule de Taylor à l'aide du gradient et de la matrice hessienne."}, "densite-de-dans": {"title": "Densité de ℚ dans ℝ", "description": "Entre deux nombres réels distincts, aussi proches soient-ils, il existe toujours un nombre rationnel — les rationnels sont partout « denses » dans les réels."}, "borne-superieure-et-axiome-de-completude": {"title": "Borne supérieure et axiome de complétude", "description": "L'axiome de la borne supérieure garantit que toute partie non vide et majorée de ℝ possède un plus petit majorant — la propriété qui distingue ℝ de ℚ."}, "nombres-irrationnels-et-transcendants": {"title": "Nombres irrationnels et transcendants", "description": "Un nombre irrationnel n'est pas une fraction (comme √2) ; un nombre transcendant, plus rare encore, n'est racine d'aucun polynôme à coefficients entiers (comme π ou e)."}, "construction-de-coupures-de-dedekind": {"title": "Construction de ℝ (coupures de Dedekind)", "description": "Les coupures de Dedekind construisent rigoureusement les nombres réels à partir des rationnels, en définissant chaque réel comme une partition de ℚ en deux morceaux."}, "suites-de-cauchy-et-completude": {"title": "Suites de Cauchy et complétude", "description": "Une suite de Cauchy voit ses termes se rapprocher indéfiniment les uns des autres ; un espace est complet si toute suite de Cauchy y converge effectivement."}, "forme-trigonometrique-et-exponentielle": {"title": "Forme trigonométrique et exponentielle", "description": "Un nombre complexe s'écrit aussi r(cos θ+i sin θ)=re^{iθ}, une forme qui rend triviaux le calcul de produits, de puissances et de racines."}, "formule-de-moivre-et-racines-n-iemes": {"title": "Formule de Moivre et racines n-ièmes", "description": "La formule de Moivre (cos θ+i sin θ)ⁿ=cos(nθ)+i sin(nθ) permet de calculer facilement les racines n-ièmes de n'importe quel nombre complexe."}, "applications-en-electronique-impedance": {"title": "Applications en électronique (impédance)", "description": "Les nombres complexes simplifient l'analyse des circuits en courant alternatif : l'impédance combine résistance et effets de déphasage en un seul nombre complexe."}, "factorisation-et-relations-de-viete": {"title": "Factorisation et relations de Viète", "description": "Les relations de Viète relient directement les coefficients d'un polynôme à des combinaisons symétriques de ses racines, sans avoir besoin de les calculer."}, "theoreme-de-d-alembert-gauss": {"title": "Théorème de d'Alembert-Gauss", "description": "Ce théorème fondamental garantit que ℂ est algébriquement clos : tout polynôme non constant à coefficients complexes possède au moins une racine complexe."}, "polynomes-irreductibles-et-critere-d-eisenstein": {"title": "Polynômes irréductibles et critère d'Eisenstein", "description": "Un polynôme irréductible ne peut pas être factorisé en polynômes de degré strictement plus petit ; le critère d'Eisenstein fournit un test pratique pour prouver l'irréductibilité sur ℚ."}, "interpolation-polynomiale-lagrange": {"title": "Interpolation polynomiale (Lagrange)", "description": "Le polynôme d'interpolation de Lagrange est l'unique polynôme de degré minimal passant exactement par un ensemble donné de points, construit par une formule explicite."}, "polynomes-sur-les-corps-finis-cryptographie": {"title": "Polynômes sur les corps finis (cryptographie)", "description": "Les polynômes irréductibles sur un corps fini permettent de construire des extensions de corps finis, utilisées pour bâtir des codes correcteurs et des systèmes cryptographiques."}, "decomposition-en-valeurs-singulieres-svd": {"title": "Décomposition en valeurs singulières (SVD)", "description": "La SVD écrit une matrice comme un produit de trois matrices (rotation, dilatation, rotation), révélant sa structure géométrique essentielle, utilisée massivement en apprentissage automatique."}, "matrices-orthogonales-et-rotations": {"title": "Matrices orthogonales et rotations", "description": "Une matrice orthogonale (AᵀA=I) préserve exactement les longueurs et les angles : ce sont précisément les rotations et réflexions de l'espace euclidien."}, "exponentielle-de-matrice": {"title": "Exponentielle de matrice", "description": "L'exponentielle d'une matrice exp(A), définie par une série, généralise l'exponentielle usuelle et donne la solution explicite des systèmes différentiels linéaires X'=AX."}, "matrices-stochastiques-et-chaines-de-markov": {"title": "Matrices stochastiques et chaînes de Markov", "description": "Une matrice stochastique, dont chaque colonne somme à 1, décrit les probabilités de transition d'une chaîne de Markov entre différents états."}, "sous-espaces-et-somme-directe": {"title": "Sous-espaces et somme directe", "description": "Une somme directe décompose un espace vectoriel en sous-espaces qui ne se recoupent qu'en zéro, permettant de décomposer tout vecteur de façon unique."}, "theoreme-de-la-base-incomplete": {"title": "Théorème de la base incomplète", "description": "Ce théorème garantit que toute famille libre de vecteurs peut être complétée en une base de l'espace tout entier, en lui ajoutant des vecteurs bien choisis."}, "espaces-de-fonctions-dimension-infinie": {"title": "Espaces de fonctions (dimension infinie)", "description": "L'ensemble des fonctions continues sur un intervalle forme un espace vectoriel de dimension infinie, un cadre essentiel pour l'analyse fonctionnelle et les séries de Fourier."}, "developpement-selon-une-ligne-colonne": {"title": "Développement selon une ligne/colonne", "description": "Le déterminant d'une matrice peut se calculer récursivement en le développant selon n'importe quelle ligne ou colonne, une méthode pratique pour les matrices de petite taille."}, "determinant-et-changement-de-base": {"title": "Déterminant et changement de base", "description": "Le déterminant d'un endomorphisme ne dépend pas de la base choisie pour le représenter : c'est un invariant intrinsèque de la transformation elle-même."}, "comatrice-et-formule-de-cramer": {"title": "Comatrice et formule de Cramer", "description": "La comatrice permet de calculer l'inverse d'une matrice sans pivot de Gauss ; la formule de Cramer résout un système linéaire directement à l'aide de déterminants."}, "determinant-comme-forme-multilineaire-alternee": {"title": "Déterminant comme forme multilinéaire alternée", "description": "Le déterminant est l'unique forme qui est linéaire par rapport à chaque colonne, change de signe si on échange deux colonnes, et vaut 1 sur la matrice identité."}, "wronskien-determinant-de-fonctions": {"title": "Wronskien (déterminant de fonctions)", "description": "Le Wronskien de plusieurs fonctions (un déterminant construit à partir de leurs dérivées successives) permet de tester si elles sont linéairement indépendantes."}, "noyau-et-image-theoreme-du-rang": {"title": "Noyau et image (théorème du rang)", "description": "Le noyau et l'image d'une application linéaire mesurent respectivement ce qu'elle « écrase » et ce qu'elle « atteint » ; le théorème du rang relie leurs dimensions à celle de l'espace de départ."}, "changement-de-base-et-matrices-de-passage": {"title": "Changement de base et matrices de passage", "description": "Une matrice de passage convertit les coordonnées d'un vecteur d'une base à une autre, permettant de choisir la base la plus adaptée à un calcul."}, "dualite-et-formes-lineaires": {"title": "Dualité et formes linéaires", "description": "L'espace dual regroupe toutes les formes linéaires (fonctions linéaires à valeurs scalaires) définies sur un espace vectoriel, un concept clé de l'algèbre linéaire abstraite."}, "composition-et-inversibilite": {"title": "Composition et inversibilité", "description": "Composer deux applications linéaires inversibles donne une application inversible ; cette propriété structure le groupe des transformations linéaires inversibles GLₙ."}, "diagonalisation-et-polynome-minimal": {"title": "Diagonalisation et polynôme minimal", "description": "Une matrice est diagonalisable si et seulement si son polynôme minimal n'a que des racines simples — un critère souvent plus rapide à vérifier que le calcul direct des sous-espaces propres."}, "theoreme-spectral-matrices-symetriques": {"title": "Théorème spectral (matrices symétriques)", "description": "Toute matrice symétrique réelle est diagonalisable dans une base orthonormée de vecteurs propres, un résultat central qui unifie algèbre linéaire et géométrie euclidienne."}, "multiplicite-algebrique-vs-geometrique": {"title": "Multiplicité algébrique vs géométrique", "description": "La multiplicité algébrique d'une valeur propre compte sa répétition dans le polynôme caractéristique ; la multiplicité géométrique compte la dimension du sous-espace propre associé — elles ne coïncident pas toujours."}, "decomposition-en-valeurs-singulieres": {"title": "Décomposition en valeurs singulières", "description": "Cette décomposition (SVD) généralise la diagonalisation à toute matrice, même non carrée, et est à la base de la compression de données et de la réduction de dimension (PCA)."}, "rayon-spectral-et-convergence-d-algorithmes": {"title": "Rayon spectral et convergence d'algorithmes", "description": "Le rayon spectral (la plus grande valeur propre en module) détermine si un algorithme itératif basé sur une matrice va converger ou diverger."}, "critere-de-diagonalisabilite": {"title": "Critère de diagonalisabilité", "description": "Une matrice est diagonalisable si et seulement si la somme des dimensions de ses sous-espaces propres égale la dimension totale de l'espace."}, "reduction-de-jordan-cas-non-diagonalisable": {"title": "Réduction de Jordan (cas non diagonalisable)", "description": "Même quand une matrice n'est pas diagonalisable, la réduction de Jordan trouve la forme presque diagonale la plus simple possible, avec des blocs caractéristiques."}, "diagonalisation-simultanee": {"title": "Diagonalisation simultanée", "description": "Deux matrices qui commutent peuvent être diagonalisées dans une même base, un résultat très utile en mécanique quantique (observables compatibles) et en statistique."}, "decomposition-spectrale-des-operateurs": {"title": "Décomposition spectrale des opérateurs", "description": "La décomposition spectrale généralise la diagonalisation aux opérateurs sur des espaces de dimension infinie, essentielle en mécanique quantique pour décrire les observables physiques."}, "loi-d-inertie-de-sylvester": {"title": "Loi d'inertie de Sylvester", "description": "Ce théorème garantit que la signature d'une forme quadratique (nombre de coefficients positifs, négatifs, nuls après diagonalisation) ne dépend pas de la méthode de réduction utilisée."}, "reduction-de-gauss": {"title": "Réduction de Gauss", "description": "Cette méthode transforme systématiquement une forme quadratique en une somme de carrés, révélant directement sa signature et sa classification."}, "coniques-et-surfaces-quadratiques": {"title": "Coniques et surfaces quadratiques", "description": "Les formes quadratiques classifient entièrement les coniques (ellipse, parabole, hyperbole) et leurs analogues en dimension supérieure (ellipsoïdes, paraboloïdes, hyperboloïdes)."}, "applications-aux-statistiques-multivariees-covariance": {"title": "Applications aux statistiques multivariées (covariance)", "description": "La matrice de covariance d'un vecteur aléatoire multivarié est une forme quadratique dont les propriétés algébriques (positivité, valeurs propres) structurent toute l'analyse statistique associée."}, "sous-groupes-et-groupes-quotients": {"title": "Sous-groupes et groupes quotients", "description": "Un sous-groupe hérite de la structure du groupe qui le contient ; un groupe quotient, lui, « efface » l'information interne à un sous-groupe distingué."}, "groupes-symetriques-et-permutations": {"title": "Groupes symétriques et permutations", "description": "Le groupe symétrique Sₙ regroupe toutes les permutations de n objets ; toute permutation se décompose en cycles, dont la parité définit la signature."}, "action-de-groupe-et-formule-des-classes": {"title": "Action de groupe et formule des classes", "description": "Quand un groupe agit sur un ensemble, la formule des classes relie la taille de chaque orbite à la taille du stabilisateur, un outil clé pour compter des configurations symétriques."}, "groupes-de-lie-et-symetries-continues": {"title": "Groupes de Lie et symétries continues", "description": "Un groupe de Lie combine structure de groupe et structure géométrique lisse, le langage naturel des symétries continues (rotations, translations) en physique."}, "ideaux-et-anneaux-quotients": {"title": "Idéaux et anneaux quotients", "description": "Un idéal est un sous-ensemble d'un anneau stable par absorption ; l'anneau quotient associé « efface » les différences internes à cet idéal, comme ℤ/nℤ efface les multiples de n."}, "anneaux-integres-et-corps-de-fractions": {"title": "Anneaux intègres et corps de fractions", "description": "Un anneau intègre n'a pas de « diviseurs de zéro » ; on peut toujours le plonger dans un corps de fractions, comme ℤ se plonge dans ℚ."}, "anneaux-principaux-et-factoriels": {"title": "Anneaux principaux et factoriels", "description": "Un anneau principal a tous ses idéaux engendrés par un seul élément ; un anneau factoriel permet une décomposition unique en facteurs premiers, comme dans ℤ."}, "anneaux-de-polynomes": {"title": "Anneaux de polynômes", "description": "L'ensemble des polynômes à coefficients dans un anneau forme lui-même un anneau, avec une arithmétique (division, PGCD) qui imite celle des entiers."}, "applications-en-cryptographie-et-codage": {"title": "Applications en cryptographie et codage", "description": "Les structures d'anneaux et de corps fondent à la fois la cryptographie moderne (RSA, courbes elliptiques) et les codes correcteurs d'erreurs utilisés en télécommunications."}, "extensions-de-corps-et-degre": {"title": "Extensions de corps et degré", "description": "Le degré d'une extension de corps mesure la dimension de L vu comme espace vectoriel sur K, une quantité clé pour prouver l'impossibilité de certaines constructions."}, "corps-finis-et-theorie-de-galois": {"title": "Corps finis et théorie de Galois", "description": "La théorie de Galois s'applique élégamment aux corps finis, expliquant pourquoi leur groupe multiplicatif est toujours cyclique et structurant leurs extensions."}, "corps-de-rupture-et-de-decomposition": {"title": "Corps de rupture et de décomposition", "description": "Le corps de rupture d'un polynôme est le plus petit corps où il possède une racine ; le corps de décomposition, où il se factorise complètement."}, "corps-algebriquement-clos": {"title": "Corps algébriquement clos", "description": "Un corps est algébriquement clos si tout polynôme non constant y admet une racine ; ℂ est le corps algébriquement clos le plus utilisé (théorème de d'Alembert-Gauss)."}, "applications-aux-codes-correcteurs": {"title": "Applications aux codes correcteurs", "description": "Les corps finis et les polynômes permettent de construire des codes qui détectent et corrigent automatiquement les erreurs de transmission, utilisés dans les CD, QR codes et communications satellite."}, "theoreme-chinois-des-restes": {"title": "Théorème chinois des restes", "description": "Ce théorème garantit qu'un système de congruences à modules premiers entre eux possède toujours une solution unique modulo le produit des modules."}, "petit-theoreme-de-fermat": {"title": "Petit théorème de Fermat", "description": "Si p est premier et a n'est pas multiple de p, alors a^(p-1)≡1 (mod p) — un résultat surprenant qui fonde de nombreux tests de primalité."}, "inversibilite-modulo-n": {"title": "Inversibilité modulo n", "description": "Un nombre a est inversible modulo n si et seulement s'il est premier avec n ; cette inversibilité est la clé de voûte de nombreux algorithmes cryptographiques."}, "applications-a-la-cryptographie-rsa": {"title": "Applications à la cryptographie RSA", "description": "RSA exploite la difficulté de factoriser un grand nombre produit de deux nombres premiers, un problème d'arithmétique modulaire réputé impossible à résoudre efficacement."}, "residus-quadratiques": {"title": "Résidus quadratiques", "description": "Un résidu quadratique modulo p est un carré parfait dans l'arithmétique modulaire ; leur étude, via la loi de réciprocité quadratique, est un grand classique de la théorie des nombres."}, "logarithme-discret-et-diffie-hellman": {"title": "Logarithme discret et Diffie-Hellman", "description": "Le problème du logarithme discret (retrouver x connaissant gˣ) est réputé très difficile ; il fonde le protocole Diffie-Hellman d'échange sécurisé de clé."}, "cryptographie-sur-courbes-elliptiques": {"title": "Cryptographie sur courbes elliptiques", "description": "Le groupe des points d'une courbe elliptique fournit un problème de logarithme discret particulièrement difficile, permettant une cryptographie très sûre avec des clés courtes."}, "fonctions-de-hachage-cryptographiques": {"title": "Fonctions de hachage cryptographiques", "description": "Une fonction de hachage transforme des données de taille quelconque en une empreinte de taille fixe, impossible à inverser, utilisée pour vérifier l'intégrité et stocker des mots de passe."}, "cryptographie-post-quantique": {"title": "Cryptographie post-quantique", "description": "Face à la menace des ordinateurs quantiques (algorithme de Shor), de nouveaux protocoles cryptographiques sont développés sur des problèmes résistants même au calcul quantique (réseaux euclidiens, codes)."}, "preuves-a-divulgation-nulle-de-connaissance": {"title": "Preuves à divulgation nulle de connaissance", "description": "Ce protocole cryptographique permet de prouver qu'on connaît une information secrète sans jamais la révéler, utilisé en authentification et dans certaines cryptomonnaies."}, "equations-parametriques-de-droites-et-plans": {"title": "Équations paramétriques de droites et plans", "description": "Une droite ou un plan peut être décrit par un point de départ et une ou plusieurs directions, en faisant varier un ou deux paramètres réels."}, "positions-relatives-parallelisme-intersection": {"title": "Positions relatives (parallélisme, intersection)", "description": "Deux droites du plan sont soit parallèles, soit sécantes en un unique point ; résoudre leur système d'équations détermine immédiatement leur configuration."}, "distance-entre-deux-droites": {"title": "Distance entre deux droites", "description": "Deux droites parallèles ont une distance constante entre elles ; deux droites sécantes ont une distance nulle (elles se coupent)."}, "faisceaux-de-droites-et-de-plans": {"title": "Faisceaux de droites et de plans", "description": "Un faisceau de droites regroupe toutes les droites passant par un même point ; un faisceau de plans, tous les plans contenant une même droite."}, "produit-vectoriel-dimension-3": {"title": "Produit vectoriel (dimension 3)", "description": "Le produit vectoriel u×v produit un nouveau vecteur perpendiculaire à u et v, dont la norme donne l'aire du parallélogramme qu'ils engendrent."}, "combinaisons-lineaires-et-colinearite": {"title": "Combinaisons linéaires et colinéarité", "description": "Deux vecteurs sont colinéaires si l'un est un multiple de l'autre ; leurs combinaisons linéaires (u+v, 2u-3v...) permettent de reconstruire tout vecteur du plan."}, "vecteurs-et-translations": {"title": "Vecteurs et translations", "description": "Une translation déplace tous les points d'une figure du même vecteur, l'exemple le plus simple de transformation géométrique préservant toutes les distances."}, "vecteurs-aleatoires-en-probabilite": {"title": "Vecteurs aléatoires en probabilité", "description": "Un vecteur aléatoire combine plusieurs variables aléatoires liées, dont l'étude géométrique (via la matrice de covariance) relève à la fois de l'algèbre et des probabilités."}, "distance-dans-l-espace-3d": {"title": "Distance dans l'espace (3D)", "description": "La distance entre deux points de l'espace se calcule par une généralisation directe du théorème de Pythagore à trois coordonnées."}, "mediatrice-d-un-segment": {"title": "Médiatrice d'un segment", "description": "La médiatrice d'un segment regroupe tous les points équidistants de ses deux extrémités ; elle est perpendiculaire au segment en son milieu."}, "distance-euclidienne-vs-autres-normes": {"title": "Distance euclidienne vs autres normes", "description": "La distance euclidienne (issue du théorème de Pythagore) n'est qu'une des façons possibles de mesurer un écart ; d'autres normes (Manhattan, Chebyshev) sont utiles selon le contexte."}, "barycentres-ponderes": {"title": "Barycentres pondérés", "description": "Un barycentre pondéré place le point d'équilibre d'un système selon des poids choisis, généralisant le simple centre de gravité (poids égaux)."}, "distances-dans-des-espaces-abstraits": {"title": "Distances dans des espaces abstraits", "description": "La notion de distance se généralise à des espaces très abstraits (fonctions, données textuelles), à condition de vérifier les axiomes de symétrie et d'inégalité triangulaire."}, "produit-vectoriel-et-produit-mixte": {"title": "Produit vectoriel et produit mixte", "description": "Le produit mixte (u,v,w) combine trois vecteurs pour donner le volume signé du parallélépipède qu'ils engendrent, en utilisant le produit vectoriel et le produit scalaire."}, "projections-orthogonales": {"title": "Projections orthogonales", "description": "La projection orthogonale d'un point sur une droite ou un plan en donne le point le plus proche, un outil essentiel en géométrie et en statistique (moindres carrés)."}, "angle-entre-deux-vecteurs-en-haute-dimension": {"title": "Angle entre deux vecteurs en haute dimension", "description": "Même en dimension quelconque, l'angle entre deux vecteurs se calcule via le produit scalaire, exactement comme dans le plan ou l'espace usuel."}, "similarite-cosinus-en-ia": {"title": "Similarité cosinus en IA", "description": "La similarité cosinus mesure l'angle entre deux vecteurs de données pour évaluer leur ressemblance, très utilisée en apprentissage automatique (recherche de documents similaires)."}, "equation-generale-du-cercle": {"title": "Équation générale du cercle", "description": "L'équation x²+y²+Dx+Ey+F=0 décrit un cercle (ou un point, ou l'ensemble vide) selon le signe d'une quantité liée à D, E et F."}, "puissance-d-un-point-par-rapport-a-un-cercle": {"title": "Puissance d'un point par rapport à un cercle", "description": "Cette quantité, positive à l'extérieur du cercle et négative à l'intérieur, est un outil puissant pour résoudre des problèmes de géométrie du cercle."}, "coniques-generalisation-du-cercle": {"title": "Coniques (généralisation du cercle)", "description": "Ellipse, parabole et hyperbole sont obtenues en coupant un cône par un plan sous différents angles, le cercle en étant le cas particulier le plus symétrique."}, "spheres-cercle-en-3-dimensions": {"title": "Sphères (cercle en 3 dimensions)", "description": "La sphère généralise le cercle à trois dimensions : l'ensemble des points à distance fixe d'un centre, avec volume (4/3)πr³ et aire 4πr²."}, "angles-orientes": {"title": "Angles orientés", "description": "Un angle orienté tient compte du sens de rotation (horaire ou antihoraire), ce qui permet de distinguer des configurations que la mesure d'angle simple confond."}, "angle-inscrit-et-angle-au-centre": {"title": "Angle inscrit et angle au centre", "description": "Un angle inscrit dans un cercle vaut toujours la moitié de l'angle au centre qui intercepte le même arc — un résultat classique de géométrie du cercle."}, "trigonometrie-et-cercle-unite": {"title": "Trigonométrie et cercle unité", "description": "Le cosinus et le sinus d'un angle sont, par définition, les coordonnées du point correspondant sur le cercle de rayon 1 centré à l'origine."}, "angles-en-geometrie-spherique": {"title": "Angles en géométrie sphérique", "description": "Sur une sphère, la somme des angles d'un triangle dépasse toujours 180°, contrairement à la géométrie plane — un excès directement lié à l'aire du triangle."}, "angles-diedres-en-3d": {"title": "Angles dièdres en 3D", "description": "Un angle dièdre mesure l'ouverture entre deux plans qui se coupent selon une droite, un concept essentiel en cristallographie et en architecture."}, "theoreme-d-al-kashi-loi-des-cosinus": {"title": "Théorème d'Al-Kashi (loi des cosinus)", "description": "Cette généralisation du théorème de Pythagore relie les trois côtés d'un triangle quelconque à l'un de ses angles, via a²=b²+c²-2bc·cos A."}, "theoreme-de-thales": {"title": "Théorème de Thalès", "description": "Ce théorème relie les longueurs de segments coupés par des droites parallèles, un outil fondamental pour calculer des longueurs inaccessibles."}, "points-remarquables-centre-de-gravite-orthocentre": {"title": "Points remarquables (centre de gravité, orthocentre)", "description": "Un triangle possède plusieurs points remarquables (centre de gravité, orthocentre, centre du cercle circonscrit) dont les positions relatives révèlent une structure géométrique riche."}, "triangles-semblables": {"title": "Triangles semblables", "description": "Deux triangles semblables ont les mêmes angles et des côtés proportionnels, un outil puissant pour calculer des longueurs inaccessibles par simple proportionnalité."}, "triangulation-en-topographie-et-infographie": {"title": "Triangulation en topographie et infographie", "description": "Trianguler un ensemble de points permet de calculer des distances inaccessibles en topographie, et de construire des maillages 3D en infographie."}, "formules-de-duplication-et-linearisation": {"title": "Formules de duplication et linéarisation", "description": "Ces formules trigonométriques expriment cos(2a) et sin(2a) à partir de cos a et sin a, ou inversement transforment un produit en somme de sinus/cosinus."}, "fonctions-trigonometriques-reciproques": {"title": "Fonctions trigonométriques réciproques", "description": "arcsin, arccos et arctan inversent respectivement sin, cos et tan sur un intervalle où elles sont bijectives, permettant de retrouver un angle à partir d'un rapport."}, "trigonometrie-spherique": {"title": "Trigonométrie sphérique", "description": "Cette trigonométrie adapte les formules usuelles aux triangles tracés sur une sphère, essentielle pour la navigation maritime et aérienne à longue distance."}, "fonctions-hyperboliques": {"title": "Fonctions hyperboliques", "description": "Les fonctions sh, ch et th généralisent sin, cos et tan en remplaçant le cercle par une hyperbole, avec la relation ch²x-sh²x=1."}, "losanges-trapezes-et-proprietes-specifiques": {"title": "Losanges, trapèzes et propriétés spécifiques", "description": "Le losange a ses diagonales perpendiculaires, le trapèze a deux côtés parallèles : chaque quadrilatère particulier hérite de propriétés propres utiles en géométrie."}, "quadrilateres-inscriptibles": {"title": "Quadrilatères inscriptibles", "description": "Un quadrilatère est inscriptible dans un cercle si et seulement si ses angles opposés sont supplémentaires (leur somme vaut 180°)."}, "theoreme-de-varignon": {"title": "Théorème de Varignon", "description": "Ce théorème dit que les milieux des côtés de n'importe quel quadrilatère forment toujours un parallélogramme, quelle que soit la forme du quadrilatère initial."}, "quadrilateres-en-3d-parallelepipedes": {"title": "Quadrilatères en 3D (parallélépipèdes)", "description": "Un parallélépipède est l'analogue 3D du parallélogramme : un solide dont les six faces sont des parallélogrammes, dont le cube est le cas le plus symétrique."}, "pavages-par-quadrilateres": {"title": "Pavages par quadrilatères", "description": "Tout quadrilatère, même non régulier, peut paver le plan sans trou ni recouvrement en l'assemblant avec des copies tournées de lui-même."}, "affixe-d-un-vecteur-et-d-un-point": {"title": "Affixe d'un vecteur et d'un point", "description": "L'affixe d'un point est le nombre complexe qui lui correspond ; celle d'un vecteur AB est la différence des affixes de B et A, traduisant la géométrie en calcul algébrique."}, "similitudes-directes-et-indirectes": {"title": "Similitudes directes et indirectes", "description": "Une similitude directe préserve l'orientation de la figure (rotation, homothétie) ; une similitude indirecte l'inverse (comme une symétrie combinée à une homothétie)."}, "racines-n-iemes-de-l-unite-et-polygones-reguliers": {"title": "Racines n-ièmes de l'unité et polygones réguliers", "description": "Les racines n-ièmes de l'unité, réparties sur le cercle unité, forment exactement les sommets d'un polygone régulier à n côtés."}, "polygones-reguliers-et-construction": {"title": "Polygones réguliers et construction", "description": "Un polygone régulier a tous ses côtés et angles égaux ; sa construction à la règle et au compas n'est possible que pour certains nombres de côtés (résultat de Gauss-Wantzel)."}, "triangulation-de-polygones": {"title": "Triangulation de polygones", "description": "Tout polygone peut être découpé en triangles ne se chevauchant pas, une opération de base pour le calcul d'aire et le rendu graphique."}, "polygones-convexes-vs-non-convexes": {"title": "Polygones convexes vs non convexes", "description": "Un polygone convexe ne « rentre » jamais vers l'intérieur ; cette distinction change fondamentalement les algorithmes de triangulation et de calcul d'aire."}, "theoreme-de-pick-aire-sur-grille": {"title": "Théorème de Pick (aire sur grille)", "description": "Ce théorème calcule l'aire d'un polygone dont les sommets sont sur une grille entière, à partir du simple comptage des points intérieurs et frontière."}, "polyedres-polygones-en-3d": {"title": "Polyèdres (polygones en 3D)", "description": "Un polyèdre est un solide dont les faces sont des polygones ; la relation d'Euler V-E+F=2 relie le nombre de sommets, arêtes et faces pour tout polyèdre convexe."}, "composition-de-transformations": {"title": "Composition de transformations", "description": "Enchaîner plusieurs transformations géométriques (rotation puis translation, par exemple) produit une nouvelle transformation dont la nature dépend de l'ordre des opérations."}, "isometries-et-groupe-des-isometries-du-plan": {"title": "Isométries et groupe des isométries du plan", "description": "Les isométries (translations, rotations, symétries) préservent toutes les distances ; elles forment un groupe qui structure entièrement la géométrie euclidienne plane."}, "similitudes": {"title": "Similitudes", "description": "Une similitude combine une homothétie et une isométrie : elle préserve les angles et multiplie toutes les longueurs par un même rapport."}, "transformations-en-3d-matrices-homogenes": {"title": "Transformations en 3D (matrices homogènes)", "description": "Les coordonnées homogènes permettent de représenter rotations ET translations par une seule multiplication matricielle, simplifiant grandement les calculs en infographie."}, "groupes-de-symetrie-et-pavages": {"title": "Groupes de symétrie et pavages", "description": "Les 17 groupes de symétrie du plan classifient entièrement tous les pavages périodiques possibles, un résultat esthétiquement riche (motifs d'Escher, mosaïques)."}, "cercle-inscrit-et-exinscrit": {"title": "Cercle inscrit et exinscrit", "description": "Le cercle inscrit est tangent aux trois côtés d'un triangle depuis l'intérieur ; les cercles exinscrits, au nombre de trois, sont tangents depuis l'extérieur."}, "droite-d-euler": {"title": "Droite d'Euler", "description": "Dans tout triangle, le centre de gravité, l'orthocentre et le centre du cercle circonscrit sont toujours alignés sur une même droite, appelée droite d'Euler."}, "cercle-des-neuf-points": {"title": "Cercle des neuf points", "description": "Ce cercle remarquable passe par neuf points caractéristiques d'un triangle (milieux des côtés, pieds des hauteurs, milieux des segments joignant l'orthocentre aux sommets)."}, "puissance-d-un-point": {"title": "Puissance d'un point", "description": "La puissance d'un point par rapport à un cercle est une quantité constante qui relie les distances aux points d'intersection de toute droite passant par ce point."}, "theoreme-de-l-angle-inscrit": {"title": "Théorème de l'angle inscrit", "description": "Un angle inscrit dans un cercle ne dépend que de l'arc qu'il intercepte, pas de la position exacte du sommet sur le cercle."}, "groupe-des-symetries-d-une-figure": {"title": "Groupe des symétries d'une figure", "description": "L'ensemble des transformations qui laissent une figure globalement invariante forme un groupe, dont la taille et la structure caractérisent la symétrie de la figure."}, "symetries-en-cristallographie": {"title": "Symétries en cristallographie", "description": "Les 230 groupes d'espace cristallographiques classifient toutes les symétries possibles des structures cristallines, un résultat essentiel en chimie du solide."}, "symetries-et-invariance-en-physique": {"title": "Symétries et invariance en physique", "description": "Le théorème de Noether relie chaque symétrie continue d'un système physique à une quantité conservée (l'énergie pour l'invariance temporelle, par exemple)."}, "symetrie-et-pavages-du-plan": {"title": "Symétrie et pavages du plan", "description": "Un pavage périodique du plan possède un groupe de symétrie qui décrit toutes ses invariances (translations, rotations, réflexions possibles)."}, "symetrie-axiale-en-3d-plans-de-symetrie": {"title": "Symétrie axiale en 3D (plans de symétrie)", "description": "En trois dimensions, la symétrie axiale du plan devient une symétrie par rapport à un plan entier, qui réfléchit chaque point perpendiculairement à travers ce plan."}, "composition-d-homotheties": {"title": "Composition d'homothéties", "description": "Composer deux homothéties donne soit une nouvelle homothétie, soit une translation, selon que le produit de leurs rapports vaut 1 ou non."}, "homotheties-et-theoreme-de-thales": {"title": "Homothéties et théorème de Thalès", "description": "Le théorème de Thalès peut se voir comme une conséquence directe des propriétés des homothéties, qui préservent le parallélisme et les rapports de longueurs."}, "rapport-d-homothetie-negatif": {"title": "Rapport d'homothétie négatif", "description": "Une homothétie de rapport négatif combine un agrandissement/réduction avec une symétrie par rapport au centre, inversant l'orientation de la figure."}, "homotheties-en-3d": {"title": "Homothéties en 3D", "description": "Une homothétie de l'espace multiplie toutes les distances à un centre fixe par un même rapport, et multiplie les volumes par le cube de ce rapport."}, "fractales-et-auto-similarite-homotheties-repetees": {"title": "Fractales et auto-similarité (homothéties répétées)", "description": "Une fractale se répète à toutes les échelles via des homothéties successives, produisant des figures d'une complexité infinie à partir de règles simples."}, "affinites-et-matrices-2-2": {"title": "Affinités et matrices 2×2", "description": "Toute affinité du plan se représente par une matrice 2×2 combinée à une translation, ce qui permet de la calculer et de la composer facilement."}, "cisaillement-shear": {"title": "Cisaillement (shear)", "description": "Un cisaillement déforme une figure en décalant progressivement ses points selon une direction fixe, préservant les aires mais pas les angles."}, "projections-en-infographie": {"title": "Projections en infographie", "description": "Une projection (orthogonale ou perspective) transforme une scène 3D en une image 2D, technique fondamentale du rendu en infographie et en CAO."}, "affinites-et-coniques": {"title": "Affinités et coniques", "description": "Une affinité peut transformer un cercle en ellipse tout en préservant certaines propriétés algébriques, un lien utile pour étudier les coniques par des transformations simples."}, "transformations-affines-en-3d": {"title": "Transformations affines en 3D", "description": "Les transformations affines de l'espace (rotation, translation, mise à l'échelle) se combinent en une seule matrice 4×4 en coordonnées homogènes, standard en infographie 3D."}, "intersections-de-droites-et-de-plans": {"title": "Intersections de droites et de plans", "description": "Deux droites, deux plans ou une droite et un plan peuvent être parallèles, sécants ou confondus ; résoudre le système d'équations associé détermine leur configuration exacte."}, "equations-cartesiennes-vs-parametriques": {"title": "Équations cartésiennes vs paramétriques", "description": "Une équation cartésienne décrit une figure par une contrainte (ax+by=c) ; une équation paramétrique la décrit par un point qui se déplace selon un paramètre."}, "distance-d-un-point-a-une-droite-un-plan": {"title": "Distance d'un point à une droite/un plan", "description": "Cette distance se calcule par une formule directe utilisant les coordonnées du point et l'équation de la droite ou du plan, sans chercher le point le plus proche."}, "produit-vectoriel-et-orientation": {"title": "Produit vectoriel et orientation", "description": "Le sens du produit vectoriel dépend de l'orientation choisie de l'espace (règle de la main droite), une convention essentielle en physique et en infographie."}, "positions-relatives-de-droites-gauches-secantes": {"title": "Positions relatives de droites (gauches, sécantes)", "description": "Dans l'espace, deux droites peuvent être parallèles, sécantes, ou « gauches » (ni parallèles ni sécantes) — une configuration impossible dans le plan."}, "distance-entre-deux-droites-de-l-espace": {"title": "Distance entre deux droites de l'espace", "description": "Dans l'espace, deux droites peuvent être non parallèles et non sécantes (« gauches ») ; leur distance minimale se calcule via le produit vectoriel de leurs directions."}, "coordonnees-cylindriques-et-spheriques": {"title": "Coordonnées cylindriques et sphériques", "description": "Ces systèmes de coordonnées, adaptés respectivement aux symétries cylindriques et sphériques, simplifient énormément les calculs d'intégrales et d'équations en physique."}, "coordonnees-spheriques": {"title": "Coordonnées sphériques", "description": "Un point de l'espace se repère par une distance à l'origine et deux angles (latitude, longitude), un système naturel pour décrire des phénomènes à symétrie sphérique."}, "geometrie-spherique-triangles-sur-une-sphere": {"title": "Géométrie sphérique (triangles sur une sphère)", "description": "Sur une sphère, les côtés d'un triangle sont des arcs de grand cercle, et la somme de ses angles dépasse toujours 180°."}, "volume-et-aire-par-integration": {"title": "Volume et aire par intégration", "description": "L'intégration permet de calculer précisément volumes et aires de formes complexes en les découpant en tranches infinitésimales dont on connaît la mesure."}, "spheres-en-dimension-n": {"title": "Sphères en dimension n", "description": "La sphère se généralise à n'importe quelle dimension ; son volume et son aire suivent des formules faisant intervenir la fonction Gamma."}, "geodesiques-sur-une-sphere": {"title": "Géodésiques sur une sphère", "description": "Sur une sphère, les géodésiques sont les grands cercles (comme l'équateur) — c'est pourquoi les avions suivent des trajectoires courbes sur une carte plate."}, "cylindre-oblique": {"title": "Cylindre oblique", "description": "Un cylindre oblique, dont l'axe n'est pas perpendiculaire à la base, a néanmoins le même volume qu'un cylindre droit de même base et hauteur (principe de Cavalieri)."}, "volume-par-integration-methode-des-disques": {"title": "Volume par intégration (méthode des disques)", "description": "Cette méthode calcule le volume d'un solide de révolution en intégrant l'aire des disques circulaires engendrés par la rotation d'une courbe."}, "sections-coniques-d-un-cylindre": {"title": "Sections coniques d'un cylindre", "description": "Couper un cylindre par un plan incliné produit une ellipse, tandis qu'un plan perpendiculaire à l'axe produit un cercle."}, "cylindre-et-coordonnees-cylindriques": {"title": "Cylindre et coordonnées cylindriques", "description": "Les coordonnées cylindriques, adaptées à la symétrie du cylindre, simplifient grandement le calcul de son volume et de ses propriétés par intégration."}, "cylindre-creux-tube": {"title": "Cylindre creux (tube)", "description": "Le volume d'un tube s'obtient en soustrayant le volume du cylindre intérieur à celui du cylindre extérieur, une application directe de la différence de volumes."}, "sections-coniques-cercle-ellipse-parabole-hyperbole": {"title": "Sections coniques (cercle, ellipse, parabole, hyperbole)", "description": "Selon l'angle sous lequel un plan coupe un cône, on obtient un cercle, une ellipse, une parabole ou une hyperbole — les quatre coniques classiques."}, "cone-tronque": {"title": "Cône tronqué", "description": "Le volume d'un cône tronqué (privé de sa pointe) se calcule comme la différence entre le volume du cône entier et celui de la petite pointe retirée."}, "volume-par-integration": {"title": "Volume par intégration", "description": "Le volume d'un solide s'obtient en intégrant l'aire de ses sections transversales successives le long d'un axe."}, "cone-et-coordonnees-coniques": {"title": "Cône et coordonnées coniques", "description": "Les coordonnées adaptées à la symétrie conique simplifient le calcul du volume et des propriétés géométriques du cône par intégration."}, "cones-en-optique-cone-de-lumiere": {"title": "Cônes en optique (cône de lumière)", "description": "En relativité, le « cône de lumière » délimite géométriquement les événements qu'un signal lumineux peut atteindre depuis un point donné de l'espace-temps."}, "tribu-et-evenements-complexes": {"title": "Tribu et événements complexes", "description": "Une tribu est une collection d'événements stable par complémentaire et union dénombrable, le cadre formel nécessaire pour définir rigoureusement une probabilité sur un univers infini."}, "univers-infini-denombrable-ou-continu": {"title": "Univers infini (dénombrable ou continu)", "description": "Quand l'univers d'une expérience aléatoire est infini, la théorie de la mesure devient indispensable pour définir des probabilités cohérentes sur cet ensemble."}, "evenements-incompatibles-et-complementaires": {"title": "Événements incompatibles et complémentaires", "description": "Deux événements incompatibles ne peuvent jamais se produire simultanément ; deux événements complémentaires couvrent, à eux deux, la totalité des possibilités."}, "modelisation-probabiliste-d-un-phenomene-reel": {"title": "Modélisation probabiliste d'un phénomène réel", "description": "Choisir une loi de probabilité adaptée pour représenter un phénomène réel (météo, panne, sondage) est la première étape essentielle de toute analyse statistique rigoureuse."}, "simulation-de-monte-carlo": {"title": "Simulation de Monte-Carlo", "description": "Cette méthode estime une quantité difficile à calculer analytiquement en simulant un grand nombre de scénarios aléatoires et en moyennant les résultats obtenus."}, "loi-des-grands-nombres": {"title": "Loi des grands nombres", "description": "Cette loi garantit que la moyenne d'un grand nombre d'observations indépendantes se rapproche de l'espérance théorique, justifiant l'usage des fréquences comme estimation des probabilités."}, "denombrement-combinatoire-pour-cas-equiprobables": {"title": "Dénombrement (combinatoire) pour cas équiprobables", "description": "Quand toutes les issues d'une expérience ont la même probabilité, la calculer revient à un simple problème de comptage combinatoire (arrangements, combinaisons)."}, "probabilites-sur-univers-infini": {"title": "Probabilités sur univers infini", "description": "Quand l'univers des possibles est infini (dénombrable ou continu), la notion de probabilité nécessite le cadre rigoureux de la théorie de la mesure pour rester cohérente."}, "interpretation-frequentiste-vs-bayesienne": {"title": "Interprétation fréquentiste vs bayésienne", "description": "L'approche fréquentiste voit la probabilité comme une fréquence à long terme ; l'approche bayésienne la voit comme un degré de croyance actualisable avec de nouvelles données."}, "variables-discretes-vs-continues": {"title": "Variables discrètes vs continues", "description": "Une variable discrète ne prend que des valeurs isolées (souvent entières) ; une variable continue peut prendre toute valeur dans un intervalle, ce qui change fondamentalement les outils de calcul."}, "fonction-de-repartition": {"title": "Fonction de répartition", "description": "La fonction de répartition F(x)=P(X≤x) accumule progressivement la probabilité d'une variable aléatoire et caractérise entièrement sa loi, discrète ou continue."}, "lois-usuelles-binomiale-poisson-normale": {"title": "Lois usuelles (binomiale, Poisson, normale)", "description": "Ces trois lois de référence modélisent respectivement un nombre de succès sur des essais répétés, des événements rares, et des phénomènes continus symétriques autour d'une moyenne."}, "fonctions-de-variables-aleatoires": {"title": "Fonctions de variables aléatoires", "description": "Appliquer une fonction à une variable aléatoire (comme X²) produit une nouvelle variable aléatoire, dont la loi se déduit de celle de X par changement de variable."}, "vecteurs-aleatoires-plusieurs-variables-liees": {"title": "Vecteurs aléatoires (plusieurs variables liées)", "description": "Un vecteur aléatoire regroupe plusieurs variables aléatoires étudiées conjointement, dont la loi jointe capture toute l'information sur leurs liens mutuels."}, "independance-conditionnelle": {"title": "Indépendance conditionnelle", "description": "Deux variables peuvent devenir indépendantes une fois qu'on connaît une troisième variable, même si elles ne le sont pas globalement — un concept clé des réseaux bayésiens."}, "arbres-de-probabilite": {"title": "Arbres de probabilité", "description": "Un arbre de probabilité représente visuellement les différentes issues successives d'une expérience aléatoire, facilitant le calcul de probabilités conditionnelles et composées."}, "linearite-de-l-esperance": {"title": "Linéarité de l'espérance", "description": "L'espérance d'une somme de variables aléatoires est toujours la somme de leurs espérances, même si les variables ne sont pas indépendantes — une propriété très puissante."}, "esperance-conditionnelle": {"title": "Espérance conditionnelle", "description": "L'espérance conditionnelle E(X|Y) donne la meilleure prévision de X une fois connue la valeur de Y, généralisant la moyenne simple à un contexte informé."}, "theoreme-de-transfert": {"title": "Théorème de transfert", "description": "Ce théorème calcule l'espérance d'une fonction g(X) directement à partir de la loi de X, sans avoir besoin de déterminer explicitement la loi de g(X)."}, "esperance-en-dimension-infinie": {"title": "Espérance en dimension infinie", "description": "L'espérance se généralise à des espaces de fonctions ou de processus, un concept clé de l'analyse stochastique et de la théorie des probabilités avancée."}, "esperance-et-valeur-actuelle-en-finance": {"title": "Espérance et valeur actuelle en finance", "description": "En finance, l'espérance sous la mesure risque-neutre donne directement la valeur actuelle d'un actif financier futur incertain, principe central de l'évaluation des produits dérivés."}, "inegalite-de-bienayme-tchebychev": {"title": "Inégalité de Bienaymé-Tchebychev", "description": "Cette inégalité borne la probabilité qu'une variable s'écarte fortement de sa moyenne, en fonction uniquement de sa variance, sans connaître sa loi exacte."}, "variance-d-une-somme-de-variables": {"title": "Variance d'une somme de variables", "description": "La variance d'une somme de variables aléatoires indépendantes est la somme de leurs variances ; sinon, il faut ajouter les termes de covariance croisée."}, "loi-normale-et-ecart-type": {"title": "Loi normale et écart-type", "description": "L'écart-type détermine entièrement la largeur de la courbe en cloche de la loi normale : environ 68% des valeurs se situent à moins d'un écart-type de la moyenne."}, "probabilites-a-priori-et-a-posteriori": {"title": "Probabilités a priori et a posteriori", "description": "La probabilité a priori reflète la croyance initiale avant observation ; la probabilité a posteriori l'actualise après avoir pris en compte une nouvelle donnée, via la formule de Bayes."}, "statistique-bayesienne": {"title": "Statistique bayésienne", "description": "Cette approche traite les paramètres inconnus eux-mêmes comme des variables aléatoires, dont on actualise la loi de probabilité à mesure que de nouvelles données arrivent."}, "reseaux-bayesiens": {"title": "Réseaux bayésiens", "description": "Un réseau bayésien représente graphiquement les dépendances conditionnelles entre plusieurs variables, permettant un raisonnement probabiliste efficace même avec de nombreuses variables liées."}, "filtre-de-kalman-bayes-en-continu": {"title": "Filtre de Kalman (Bayes en continu)", "description": "Le filtre de Kalman met à jour en continu une estimation d'état à partir de mesures bruitées, appliquant l'esprit bayésien à des systèmes dynamiques (navigation GPS, robotique)."}, "paradoxe-du-faux-positif": {"title": "Paradoxe du faux positif", "description": "Même un test très fiable peut produire une majorité de faux positifs si la maladie ou l'anomalie recherchée est rare dans la population testée — un piège d'interprétation classique."}, "loi-de-poisson-evenements-rares": {"title": "Loi de Poisson (événements rares)", "description": "La loi de Poisson modélise le nombre d'événements rares se produisant dans un intervalle de temps fixé, comme le nombre d'appels reçus par un standard."}, "approximation-de-la-binomiale-par-la-normale": {"title": "Approximation de la binomiale par la normale", "description": "Quand le nombre d'essais est grand, la loi binomiale se rapproche d'une loi normale, ce qui simplifie considérablement les calculs de probabilité."}, "loi-hypergeometrique": {"title": "Loi hypergéométrique", "description": "Cette loi modélise un tirage sans remise dans une population finie, contrairement à la loi binomiale qui suppose un tirage avec remise."}, "applications-au-controle-qualite": {"title": "Applications au contrôle qualité", "description": "Les lois discrètes (binomiale, Poisson) permettent d'estimer la proportion de pièces défectueuses et de définir des seuils d'alerte statistiquement fondés en production."}, "independance-de-plusieurs-variables": {"title": "Indépendance de plusieurs variables", "description": "L'indépendance mutuelle de plusieurs variables aléatoires exige que la factorisation de leur loi conjointe fonctionne pour tout sous-ensemble, une condition plus forte que l'indépendance deux à deux."}, "correlation-vs-independance-nuance-importante": {"title": "Corrélation vs indépendance (nuance importante)", "description": "Deux variables indépendantes sont toujours non corrélées, mais l'inverse est faux : une corrélation nulle n'implique pas l'indépendance (seulement l'absence de lien linéaire)."}, "tests-d-independance-statistique": {"title": "Tests d'indépendance statistique (χ²)", "description": "Le test du χ² d'indépendance compare les fréquences observées croisées de deux variables aux fréquences attendues sous l'hypothèse d'indépendance, pour détecter un lien statistique."}, "lois-marginales-et-conditionnelles": {"title": "Lois marginales et conditionnelles", "description": "La loi marginale d'une variable s'obtient en « oubliant » les autres variables du vecteur ; la loi conditionnelle décrit son comportement sachant la valeur des autres."}, "matrice-de-covariance": {"title": "Matrice de covariance", "description": "Cette matrice regroupe toutes les covariances entre les composantes d'un vecteur aléatoire, résumant leur structure de dépendance linéaire mutuelle."}, "vecteurs-gaussiens": {"title": "Vecteurs gaussiens", "description": "Un vecteur gaussien a la propriété remarquable que toute combinaison linéaire de ses composantes suit aussi une loi normale, ce qui simplifie énormément son étude."}, "independance-de-vecteurs-aleatoires": {"title": "Indépendance de vecteurs aléatoires", "description": "Deux vecteurs aléatoires sont indépendants si leur loi conjointe se factorise en le produit de leurs lois marginales respectives."}, "applications-a-la-statistique-multivariee": {"title": "Applications à la statistique multivariée", "description": "La covariance et les vecteurs gaussiens fondent l'analyse statistique de plusieurs variables liées simultanément, comme en analyse en composantes principales."}, "regression-lineaire": {"title": "Régression linéaire", "description": "La régression linéaire ajuste la meilleure droite possible à un nuage de points, minimisant la somme des carrés des écarts (méthode des moindres carrés)."}, "correlation-ne-signifie-pas-causalite": {"title": "Corrélation ne signifie pas causalité", "description": "Deux variables corrélées ne sont pas nécessairement liées par une relation de cause à effet ; un facteur externe caché peut expliquer leur évolution commune."}, "covariance-en-analyse-en-composantes-principales": {"title": "Covariance en analyse en composantes principales", "description": "L'analyse en composantes principales diagonalise la matrice de covariance des données pour identifier les directions de variance maximale, réduisant la dimension sans perdre trop d'information."}, "copules-dependance-au-dela-de-la-correlation": {"title": "Copules (dépendance au-delà de la corrélation)", "description": "Une copule décrit toute la structure de dépendance entre variables aléatoires, au-delà de la simple corrélation linéaire, très utilisée en finance pour modéliser les risques joints."}, "loi-normale-centree-reduite": {"title": "Loi normale centrée réduite", "description": "Cette version standardisée de la loi normale (moyenne 0, écart-type 1) sert de référence universelle pour lire les tables et calculer des probabilités normales quelconques."}, "vecteurs-gaussiens-multivaries": {"title": "Vecteurs gaussiens multivariés", "description": "La loi d'un vecteur gaussien multivarié est entièrement déterminée par son vecteur de moyennes et sa matrice de covariance, rien d'autre n'est nécessaire."}, "tests-statistiques-bases-sur-la-normale": {"title": "Tests statistiques basés sur la normale", "description": "De nombreux tests classiques (test de Student, test z) supposent que les données suivent une loi normale, hypothèse souvent justifiée par le théorème central limite."}, "approximation-normale-de-la-binomiale": {"title": "Approximation normale de la binomiale", "description": "Cette approximation, valide sous certaines conditions sur n et p, remplace un calcul combinatoire lourd par une simple lecture de table de la loi normale."}, "analyse-dimensionnelle": {"title": "Analyse dimensionnelle", "description": "Vérifier que les unités d'une équation physique sont cohérentes de chaque côté permet de détecter des erreurs et parfois de deviner la forme d'une loi physique."}, "systeme-international-d-unites": {"title": "Système International d'unités", "description": "Ce système regroupe sept unités de base (mètre, kilogramme, seconde...) définies avec une précision extrême, à partir desquelles toutes les autres unités physiques se construisent."}, "incertitudes-de-mesure": {"title": "Incertitudes de mesure", "description": "Toute mesure physique comporte une incertitude qu'il faut estimer et propager dans les calculs, une compétence essentielle pour interpréter correctement des résultats expérimentaux."}, "grandeurs-vectorielles-vs-scalaires": {"title": "Grandeurs vectorielles vs scalaires", "description": "Une grandeur scalaire (température, masse) se résume à un nombre ; une grandeur vectorielle (force, vitesse) nécessite en plus une direction et un sens."}, "constantes-physiques-fondamentales": {"title": "Constantes physiques fondamentales", "description": "Des constantes comme la vitesse de la lumière c, la constante de Planck ℏ ou la constante gravitationnelle G apparaissent universellement dans les lois physiques et fixent leurs échelles caractéristiques."}, "mouvement-uniformement-accelere": {"title": "Mouvement uniformément accéléré", "description": "Un mouvement à accélération constante, comme une chute libre, suit des formules de position et de vitesse simples, quadratiques et linéaires en temps respectivement."}, "cinematique-relative-changement-de-referentiel": {"title": "Cinématique relative (changement de référentiel)", "description": "La vitesse et la position d'un objet dépendent du référentiel choisi ; les lois de composition des vitesses relient les mesures effectuées dans deux référentiels différents."}, "cinematique-en-coordonnees-polaires": {"title": "Cinématique en coordonnées polaires", "description": "Décrire un mouvement en coordonnées polaires (distance et angle) plutôt que cartésiennes simplifie grandement l'étude des trajectoires circulaires ou en spirale."}, "trajectoires-parametriques": {"title": "Trajectoires paramétriques", "description": "Décrire une trajectoire par des équations paramétriques x(t) et y(t) permet de calculer directement vitesse et accélération par simple dérivation par rapport au temps."}, "troisieme-loi-de-newton-action-reaction": {"title": "Troisième loi de Newton (action-réaction)", "description": "Cette loi dit que si un corps A exerce une force sur un corps B, alors B exerce sur A une force de même intensité mais de sens opposé."}, "dynamique-en-referentiel-non-galileen": {"title": "Dynamique en référentiel non galiléen", "description": "Dans un référentiel accéléré ou tournant, des forces fictives (centrifuge, Coriolis) doivent être ajoutées aux forces réelles pour que les lois de Newton restent valables."}, "systemes-de-points-materiels": {"title": "Systèmes de points matériels", "description": "Étudier un système de plusieurs points matériels en interaction nécessite de suivre à la fois le mouvement global (centre de masse) et les mouvements relatifs entre points."}, "mecanique-lagrangienne-formulation-alternative": {"title": "Mécanique lagrangienne (formulation alternative)", "description": "La mécanique lagrangienne réécrit la dynamique classique à partir d'un principe variationnel, offrant une alternative plus puissante aux lois de Newton pour les systèmes complexes."}, "dynamique-relativiste": {"title": "Dynamique relativiste", "description": "Aux vitesses proches de celle de la lumière, la dynamique newtonienne doit être remplacée par une version relativiste où la masse effective augmente avec la vitesse."}, "forces-de-frottement-statique-vs-dynamique": {"title": "Forces de frottement statique vs dynamique", "description": "Le frottement statique empêche un objet immobile de bouger jusqu'à un certain seuil ; le frottement dynamique, généralement plus faible, s'oppose au mouvement une fois qu'il a commencé."}, "force-elastique-et-oscillateur-harmonique": {"title": "Force élastique et oscillateur harmonique", "description": "La force de rappel d'un ressort (loi de Hooke) produit un mouvement oscillatoire sinusoïdal parfait, modèle de référence de tout oscillateur harmonique."}, "forces-fictives-referentiel-non-inertiel": {"title": "Forces fictives (référentiel non inertiel)", "description": "Dans un référentiel accéléré, des forces apparentes (centrifuge, Coriolis) doivent être introduites pour continuer à appliquer les lois de Newton, bien qu'elles ne correspondent à aucune interaction réelle."}, "force-de-trainee-resistance-de-l-air": {"title": "Force de traînée (résistance de l'air)", "description": "La traînée aérodynamique s'oppose au mouvement d'un objet dans l'air et croît généralement avec le carré de sa vitesse, un facteur clé en aéronautique et en automobile."}, "champs-de-force-et-energie-potentielle": {"title": "Champs de force et énergie potentielle", "description": "Une force conservative dérive toujours d'une énergie potentielle ; connaître cette énergie permet de retrouver entièrement la force par simple dérivation."}, "theoreme-de-l-energie-cinetique": {"title": "Théorème de l'énergie cinétique", "description": "Ce théorème dit que la variation d'énergie cinétique d'un objet égale le travail total des forces qui s'exercent sur lui — un lien direct entre force et mouvement."}, "puissance-instantanee-vs-moyenne": {"title": "Puissance instantanée vs moyenne", "description": "La puissance instantanée varie à chaque instant ; la puissance moyenne, obtenue en intégrant sur une période, donne une mesure plus utile pour comparer des systèmes en régime périodique."}, "rendement-energetique": {"title": "Rendement énergétique", "description": "Le rendement d'une machine compare l'énergie utile produite à l'énergie totale consommée ; il est toujours inférieur à 100% à cause des pertes inévitables (frottement, chaleur)."}, "travail-des-forces-conservatives": {"title": "Travail des forces conservatives", "description": "Le travail d'une force conservative ne dépend que du point de départ et d'arrivée, jamais du chemin suivi — c'est cette propriété qui permet de lui associer une énergie potentielle."}, "puissance-en-electricite-p-ui": {"title": "Puissance en électricité (P=UI)", "description": "La puissance électrique consommée ou fournie par un composant est le produit de la tension à ses bornes et du courant qui le traverse."}, "force-centripete": {"title": "Force centripète", "description": "Cette force, dirigée vers le centre du cercle, est nécessaire pour maintenir un objet en mouvement circulaire, contrant sa tendance naturelle à suivre une trajectoire rectiligne."}, "orbites-et-lois-de-kepler": {"title": "Orbites et lois de Kepler", "description": "Les trois lois de Kepler décrivent précisément le mouvement elliptique des planètes autour du Soleil, plus tard expliquées par la loi de gravitation universelle de Newton."}, "moment-cinetique": {"title": "Moment cinétique", "description": "Le moment cinétique mesure la quantité de rotation d'un objet ; sa conservation explique pourquoi une patineuse tourne plus vite en ramenant ses bras vers son corps."}, "oscillateur-amorti-et-resonance": {"title": "Oscillateur amorti et résonance", "description": "Un oscillateur amorti perd progressivement de l'énergie par frottement ; sa résonance se produit quand une force extérieure oscille à sa fréquence propre, amplifiant fortement le mouvement."}, "oscillations-couplees": {"title": "Oscillations couplées", "description": "Quand plusieurs oscillateurs sont reliés entre eux (pendules couplés par un ressort), leur mouvement combiné se décompose en modes propres, chacun oscillant à sa fréquence caractéristique."}, "pendule-petites-vs-grandes-oscillations": {"title": "Pendule (petites vs grandes oscillations)", "description": "Pour de petites oscillations, un pendule suit une loi sinusoïdale simple ; pour de grandes amplitudes, son mouvement devient plus complexe et sa période dépend de l'amplitude."}, "oscillations-forcees": {"title": "Oscillations forcées", "description": "Un système oscillant soumis à une force extérieure périodique adopte, après un régime transitoire, un mouvement à la fréquence de cette force imposée."}, "analogie-avec-les-circuits-electriques-lc": {"title": "Analogie avec les circuits électriques (LC)", "description": "Un circuit électrique LC (inductance-capacité) obéit à une équation différentielle identique à celle d'un oscillateur mécanique, une analogie très féconde en physique."}, "ondes-stationnaires": {"title": "Ondes stationnaires", "description": "Une onde stationnaire résulte de la superposition de deux ondes de même fréquence se propageant en sens opposés, produisant des points fixes (nœuds) qui ne vibrent jamais."}, "interferences-et-diffraction": {"title": "Interférences et diffraction", "description": "Les interférences résultent de la superposition de plusieurs ondes ; la diffraction est l'étalement d'une onde en rencontrant un obstacle ou une ouverture — deux signatures de la nature ondulatoire."}, "effet-doppler": {"title": "Effet Doppler", "description": "L'effet Doppler explique pourquoi la fréquence d'une onde perçue change lorsque la source ou l'observateur est en mouvement, comme la sirène d'une ambulance qui s'éloigne."}, "ondes-electromagnetiques": {"title": "Ondes électromagnétiques", "description": "Les ondes électromagnétiques (lumière, radio, rayons X) se propagent dans le vide à la vitesse de la lumière, résultant de l'oscillation couplée de champs électrique et magnétique."}, "ondes-en-mecanique-quantique-fonction-d-onde": {"title": "Ondes en mécanique quantique (fonction d'onde)", "description": "La fonction d'onde d'une particule quantique se propage selon l'équation de Schrödinger, comme une onde, bien que son interprétation reste probabiliste et non matérielle."}, "reflexion-totale-interne": {"title": "Réflexion totale interne", "description": "Au-delà d'un certain angle, la lumière ne peut plus sortir d'un milieu plus dense vers un milieu moins dense et se réfléchit entièrement — le principe des fibres optiques."}, "formation-d-images-miroirs-lentilles": {"title": "Formation d'images (miroirs, lentilles)", "description": "Miroirs et lentilles forment des images en faisant converger ou diverger les rayons lumineux selon des lois géométriques précises, exploitées dans tous les instruments optiques."}, "aberrations-optiques": {"title": "Aberrations optiques", "description": "Une aberration optique est un défaut de formation d'image dû aux imperfections d'une lentille ou d'un miroir (flou, distorsion, franges colorées), que les instruments cherchent à corriger."}, "fibres-optiques": {"title": "Fibres optiques", "description": "Une fibre optique guide la lumière sur de longues distances par réflexion totale interne répétée, fondement des télécommunications à très haut débit."}, "optique-instrumentale-telescopes-microscopes": {"title": "Optique instrumentale (télescopes, microscopes)", "description": "Télescopes et microscopes combinent lentilles et miroirs pour agrandir des objets lointains ou minuscules, en corrigeant autant que possible les aberrations optiques."}, "experience-des-fentes-de-young": {"title": "Expérience des fentes de Young", "description": "Cette expérience historique, faisant passer de la lumière par deux fentes, produit des franges d'interférence qui prouvent la nature ondulatoire de la lumière."}, "reseaux-de-diffraction": {"title": "Réseaux de diffraction", "description": "Un réseau de diffraction, constitué de fentes très rapprochées, décompose la lumière en ses différentes couleurs avec une précision bien supérieure à un prisme."}, "polarisation-de-la-lumiere": {"title": "Polarisation de la lumière", "description": "La polarisation décrit la direction d'oscillation du champ électrique d'une onde lumineuse, exploitée dans les lunettes de soleil polarisantes et les écrans LCD."}, "coherence-optique": {"title": "Cohérence optique", "description": "Deux sources lumineuses sont cohérentes si leur déphasage reste constant dans le temps, condition nécessaire pour observer des interférences stables."}, "holographie": {"title": "Holographie", "description": "Un hologramme enregistre à la fois l'amplitude et la phase de la lumière diffusée par un objet, permettant de reconstruire une image en trois dimensions."}, "energie-potentielle-elastique": {"title": "Énergie potentielle élastique", "description": "L'énergie stockée dans un ressort comprimé ou étiré vaut (1/2)kx², proportionnelle au carré de la déformation, une conséquence directe de la loi de Hooke."}, "theoreme-de-l-energie-mecanique": {"title": "Théorème de l'énergie mécanique", "description": "En l'absence de frottement, la somme de l'énergie cinétique et de l'énergie potentielle d'un système reste constante tout au long de son mouvement."}, "conservation-de-l-energie-avec-frottement-dissipation": {"title": "Conservation de l'énergie avec frottement (dissipation)", "description": "En présence de frottement, l'énergie mécanique n'est plus conservée : elle se dissipe en chaleur, mais l'énergie totale (mécanique + thermique) reste, elle, toujours constante."}, "energie-en-relativite-e-mc": {"title": "Énergie en relativité (E=mc²)", "description": "Cette équation célèbre montre que masse et énergie sont équivalentes et interconvertibles, principe exploité dans les réactions nucléaires qui libèrent une énergie considérable."}, "energie-en-mecanique-quantique": {"title": "Énergie en mécanique quantique", "description": "En mécanique quantique, l'énergie d'un système est souvent quantifiée (limitée à des valeurs discrètes), contrairement à la physique classique où elle varie continûment."}, "cycles-thermodynamiques-carnot-otto": {"title": "Cycles thermodynamiques (Carnot, Otto)", "description": "Un cycle thermodynamique décrit une suite de transformations qui ramène un système à son état initial ; le cycle de Carnot est théoriquement le plus efficace possible pour un moteur thermique."}, "entropie-et-second-principe": {"title": "Entropie et second principe", "description": "Le second principe de la thermodynamique impose que l'entropie totale d'un système isolé ne peut qu'augmenter, expliquant l'irréversibilité de nombreux phénomènes naturels."}, "changements-d-etat-et-diagrammes-de-phase": {"title": "Changements d'état et diagrammes de phase", "description": "Un diagramme de phase représente graphiquement les conditions de température et pression où la matière est solide, liquide ou gazeuse."}, "thermodynamique-statistique-lien-microscopique": {"title": "Thermodynamique statistique (lien microscopique)", "description": "La thermodynamique statistique explique les grandeurs macroscopiques (température, pression, entropie) comme des moyennes statistiques du comportement d'un très grand nombre de particules microscopiques."}, "machines-thermiques-et-rendement": {"title": "Machines thermiques et rendement", "description": "Le rendement d'une machine thermique (moteur, réfrigérateur) est toujours limité par le second principe de la thermodynamique, avec un maximum théorique donné par le cycle de Carnot."}, "theorie-cinetique-des-gaz": {"title": "Théorie cinétique des gaz", "description": "Cette théorie déduit les propriétés macroscopiques d'un gaz (pression, température) du mouvement statistique désordonné de ses molécules constitutives."}, "gaz-reels-et-equation-de-van-der-waals": {"title": "Gaz réels et équation de van der Waals", "description": "Contrairement au gaz parfait idéalisé, un gaz réel interagit et occupe un volume propre ; l'équation de van der Waals corrige PV=nRT pour en tenir compte."}, "transformations-isotherme-isobare-adiabatique": {"title": "Transformations isotherme, isobare, adiabatique", "description": "Ces transformations thermodynamiques particulières maintiennent respectivement la température, la pression ou l'absence d'échange de chaleur constantes, simplifiant les calculs sur un gaz."}, "melanges-de-gaz-loi-de-dalton": {"title": "Mélanges de gaz (loi de Dalton)", "description": "La loi de Dalton dit que la pression totale d'un mélange de gaz est la somme des pressions partielles que chaque gaz exercerait seul dans le même volume."}, "applications-en-meteorologie": {"title": "Applications en météorologie", "description": "Les équations de la mécanique des fluides, résolues numériquement, sont à la base de toutes les prévisions météorologiques modernes."}, "principe-de-pascal": {"title": "Principe de Pascal", "description": "Ce principe dit qu'une pression appliquée à un fluide incompressible se transmet intégralement dans toutes les directions, fondement des systèmes hydrauliques (freins, vérins)."}, "poussee-d-archimede": {"title": "Poussée d'Archimède", "description": "Tout corps plongé dans un fluide subit une force verticale vers le haut égale au poids du volume de fluide déplacé, expliquant pourquoi certains objets flottent."}, "pression-atmospherique-et-altitude": {"title": "Pression atmosphérique et altitude", "description": "La pression atmosphérique diminue avec l'altitude car il y a de moins en moins d'air au-dessus, un effet ressenti en montagne et exploité en aviation."}, "pression-dans-les-gaz-theorie-cinetique": {"title": "Pression dans les gaz (théorie cinétique)", "description": "La théorie cinétique explique la pression d'un gaz comme le résultat statistique des chocs incessants de ses molécules contre les parois du récipient."}, "applications-aux-systemes-hydrauliques": {"title": "Applications aux systèmes hydrauliques", "description": "L'équation de Bernoulli et le principe de Pascal permettent de dimensionner des systèmes hydrauliques (vérins, freins) qui démultiplient une force grâce à la pression d'un fluide."}, "equations-de-navier-stokes-fluides-visqueux": {"title": "Équations de Navier-Stokes (fluides visqueux)", "description": "Ces équations décrivent le mouvement d'un fluide visqueux en généralisant la loi de Newton, mais leur résolution générale en trois dimensions reste un problème mathématique ouvert."}, "ecoulements-laminaires-et-turbulents": {"title": "Écoulements laminaires et turbulents", "description": "Un écoulement laminaire est régulier et prévisible en couches parallèles ; un écoulement turbulent est chaotique et tourbillonnant — la transition entre les deux dépend du nombre de Reynolds."}, "portance-et-trainee-aerodynamique": {"title": "Portance et traînée aérodynamique", "description": "La portance soulève un avion perpendiculairement à l'écoulement de l'air ; la traînée s'oppose à son avancement — l'optimisation de leur rapport est centrale en aéronautique."}, "nombre-de-reynolds": {"title": "Nombre de Reynolds", "description": "Ce nombre sans dimension compare les forces d'inertie aux forces visqueuses dans un écoulement, déterminant s'il sera laminaire (régulier) ou turbulent (chaotique)."}, "applications-a-la-meteorologie": {"title": "Applications à la météorologie", "description": "La sensibilité extrême aux conditions initiales (effet papillon) explique pourquoi les prévisions météo restent fiables seulement à court terme malgré des modèles très précis."}, "circuits-en-serie-et-en-parallele": {"title": "Circuits en série et en parallèle", "description": "En série, les résistances s'additionnent directement ; en parallèle, ce sont leurs inverses qui s'additionnent — deux règles de base de l'analyse de circuits."}, "lois-de-kirchhoff": {"title": "Lois de Kirchhoff", "description": "Ces deux lois (conservation du courant à un nœud, conservation de la tension sur une boucle) permettent de résoudre systématiquement n'importe quel circuit électrique."}, "circuits-rc-et-rl-regime-transitoire": {"title": "Circuits RC et RL (régime transitoire)", "description": "Un circuit contenant une résistance et un condensateur (ou une bobine) ne réagit pas instantanément à un changement de tension, mais suit une évolution exponentielle caractéristique."}, "circuits-en-courant-alternatif": {"title": "Circuits en courant alternatif", "description": "En courant alternatif, les grandeurs électriques oscillent sinusoïdalement ; les nombres complexes simplifient grandement l'analyse de tels circuits via la notion d'impédance."}, "puissance-et-rendement-electrique": {"title": "Puissance et rendement électrique", "description": "Le rendement d'un appareil électrique compare la puissance utile qu'il fournit à la puissance totale qu'il consomme, la différence étant dissipée en pertes (souvent thermiques)."}, "potentiel-electrique": {"title": "Potentiel électrique", "description": "Le potentiel électrique est une grandeur scalaire dont dérive le champ électrique ; sa différence entre deux points (la tension) détermine le travail fourni à une charge qui s'y déplace."}, "theoreme-de-gauss": {"title": "Théorème de Gauss", "description": "Ce théorème relie le flux d'un champ électrique à travers une surface fermée à la charge totale contenue à l'intérieur, un outil puissant pour calculer des champs très symétriques."}, "lien-avec-le-champ-magnetique-electromagnetisme": {"title": "Lien avec le champ magnétique (électromagnétisme)", "description": "Électricité et magnétisme sont deux aspects d'un même phénomène : une charge en mouvement crée un champ magnétique, et un champ magnétique variable crée un champ électrique."}, "induction-electromagnetique-loi-de-faraday": {"title": "Induction électromagnétique (loi de Faraday)", "description": "Cette loi dit qu'un champ magnétique variable crée un courant électrique induit, principe fondamental exploité dans tous les générateurs et transformateurs électriques."}, "moteurs-et-generateurs-electriques": {"title": "Moteurs et générateurs électriques", "description": "Un moteur convertit l'énergie électrique en mouvement grâce à la force de Lorentz ; un générateur fait l'inverse grâce à l'induction électromagnétique — deux faces d'un même principe."}, "champ-magnetique-terrestre": {"title": "Champ magnétique terrestre", "description": "Le champ magnétique de la Terre, généré par les mouvements du noyau liquide, protège la planète des particules chargées du vent solaire."}, "materiaux-ferromagnetiques": {"title": "Matériaux ferromagnétiques", "description": "Ces matériaux (fer, nickel) peuvent conserver une aimantation permanente grâce à l'alignement collectif de leurs moments magnétiques atomiques, jusqu'à une température critique (point de Curie)."}, "resonance-magnetique-nucleaire-irm": {"title": "Résonance magnétique nucléaire (IRM)", "description": "L'IRM exploite la résonance des noyaux atomiques dans un fort champ magnétique pour produire des images détaillées des tissus mous du corps humain, sans rayonnement ionisant."}, "ondes-electromagnetiques-et-spectre": {"title": "Ondes électromagnétiques et spectre", "description": "Le spectre électromagnétique regroupe, selon leur fréquence, les ondes radio, micro-ondes, infrarouges, lumière visible, ultraviolets, rayons X et rayons gamma."}, "formulation-en-formes-differentielles": {"title": "Formulation en formes différentielles", "description": "Réécrire les équations de Maxwell avec des formes différentielles les rend remarquablement compactes et révèle leur structure géométrique profonde."}, "electromagnetisme-relativiste": {"title": "Électromagnétisme relativiste", "description": "L'électromagnétisme est naturellement compatible avec la relativité restreinte ; les champs électrique et magnétique se transforment l'un en l'autre selon le référentiel de l'observateur."}, "rayonnement-electromagnetique": {"title": "Rayonnement électromagnétique", "description": "Toute charge accélérée émet un rayonnement électromagnétique, principe exploité dans les antennes radio et responsable de phénomènes comme la lumière émise par les étoiles."}, "applications-aux-telecommunications": {"title": "Applications aux télécommunications", "description": "Les ondes électromagnétiques, décrites par les équations de Maxwell, portent l'information dans toutes les technologies sans fil (radio, wifi, téléphonie mobile)."}, "complexite-temporelle-et-spatiale": {"title": "Complexité temporelle et spatiale", "description": "La complexité temporelle mesure le temps de calcul d'un algorithme ; la complexité spatiale mesure sa consommation de mémoire — deux critères souvent en compromis."}, "algorithmes-de-tri-rapides-fusion": {"title": "Algorithmes de tri (rapides, fusion)", "description": "Le tri rapide et le tri fusion trient un tableau en O(n log n) en moyenne, bien plus efficacement que les méthodes naïves en O(n²)."}, "algorithmes-recursifs": {"title": "Algorithmes récursifs", "description": "Un algorithme récursif résout un problème en s'appelant lui-même sur une version plus petite du même problème, jusqu'à atteindre un cas de base trivial."}, "analyse-du-pire-cas-vs-cas-moyen": {"title": "Analyse du pire cas vs cas moyen", "description": "Le pire cas garantit une borne de performance quelles que soient les données ; le cas moyen, souvent plus optimiste, suppose une distribution typique des entrées."}, "algorithmes-gloutons-et-programmation-dynamique": {"title": "Algorithmes gloutons et programmation dynamique", "description": "Ces deux familles d'algorithmes construisent une solution étape par étape, mais la programmation dynamique explore plusieurs possibilités là où le glouton s'engage définitivement à chaque étape."}, "arbres-et-structures-hierarchiques": {"title": "Arbres et structures hiérarchiques", "description": "Les arbres modélisent naturellement toute structure hiérarchique : dossiers de fichiers, organigrammes, ou arbres généalogiques."}, "tables-de-hachage": {"title": "Tables de hachage", "description": "Une table de hachage permet un accès quasi instantané aux données via une fonction de hachage qui calcule directement leur emplacement en mémoire."}, "files-de-priorite": {"title": "Files de priorité", "description": "Une file de priorité extrait toujours en premier l'élément le plus prioritaire, structure de données clé pour des algorithmes comme Dijkstra ou le tri par tas."}, "choix-de-structure-selon-les-operations-frequentes": {"title": "Choix de structure selon les opérations fréquentes", "description": "Le choix d'une structure de données (tableau, liste, arbre, table de hachage) dépend des opérations les plus fréquentes qu'on doit y effectuer efficacement."}, "arbres-binaires-de-recherche": {"title": "Arbres binaires de recherche", "description": "Dans cet arbre, chaque nœud a au plus deux enfants, avec toutes les valeurs plus petites à gauche et plus grandes à droite, permettant une recherche efficace."}, "arbres-equilibres-avl-rouge-noir": {"title": "Arbres équilibrés (AVL, rouge-noir)", "description": "Ces structures garantissent que la hauteur de l'arbre reste logarithmique par rapport au nombre d'éléments, assurant des opérations rapides même sur de grandes quantités de données."}, "arbres-et-algorithmes-de-compression-huffman": {"title": "Arbres et algorithmes de compression (Huffman)", "description": "L'algorithme de Huffman construit un arbre binaire optimal qui attribue des codes courts aux symboles fréquents, minimisant la taille totale d'un fichier compressé."}, "parcours-d-arbres-prefixe-infixe-suffixe": {"title": "Parcours d'arbres (préfixe, infixe, suffixe)", "description": "Ces trois façons de parcourir un arbre binaire (avant, entre, ou après avoir visité ses enfants) produisent des ordres différents utiles selon l'application recherchée."}, "arbres-en-apprentissage-automatique-arbres-de-decision": {"title": "Arbres en apprentissage automatique (arbres de décision)", "description": "Un arbre de décision classe des données en posant une succession de questions simples, chaque nœud représentant un test sur une caractéristique des données."}, "graphes-orientes-vs-non-orientes": {"title": "Graphes orientés vs non orientés", "description": "Dans un graphe orienté, chaque arête a un sens précis (comme une rue à sens unique) ; dans un graphe non orienté, les connexions sont symétriques."}, "arbres-couvrants-minimaux": {"title": "Arbres couvrants minimaux", "description": "Un arbre couvrant minimal relie tous les sommets d'un graphe pondéré avec le coût total minimal, calculé par les algorithmes de Kruskal ou Prim."}, "colorations-de-graphes": {"title": "Colorations de graphes", "description": "Le nombre chromatique d'un graphe est le nombre minimal de couleurs nécessaires pour le colorier valablement, un problème NP-difficile en général."}, "graphes-et-reseaux-sociaux": {"title": "Graphes et réseaux sociaux", "description": "Un réseau social se modélise naturellement comme un graphe, où les sommets sont les personnes et les arêtes leurs relations, permettant d'en analyser la structure."}, "arbres-avl-auto-equilibres": {"title": "Arbres AVL (auto-équilibrés)", "description": "Un arbre AVL se rééquilibre automatiquement après chaque insertion ou suppression, garantissant une hauteur toujours proche du minimum théorique, donc des recherches rapides."}, "arbres-rouge-noir": {"title": "Arbres rouge-noir", "description": "Cet arbre auto-équilibré garantit, grâce à un coloriage de ses nœuds, que sa hauteur reste logarithmique, utilisé notamment dans les implémentations standards de dictionnaires triés."}, "arbres-b-bases-de-donnees": {"title": "Arbres B (bases de données)", "description": "Les arbres B, avec de nombreux enfants par nœud, sont optimisés pour minimiser les accès disque, ce qui les rend standards dans les bases de données."}, "complexite-amortie": {"title": "Complexité amortie", "description": "La complexité amortie mesure le coût moyen d'une opération sur une longue séquence, même si certaines opérations individuelles sont ponctuellement coûteuses."}, "comparaison-avec-les-tables-de-hachage": {"title": "Comparaison avec les tables de hachage", "description": "Les arbres de recherche maintiennent un ordre (utile pour parcourir les données triées) là où les tables de hachage sont plus rapides mais non ordonnées."}, "algorithme-a-avec-heuristique": {"title": "Algorithme A* (avec heuristique)", "description": "Cet algorithme trouve le plus court chemin plus rapidement que Dijkstra en utilisant une estimation (heuristique) de la distance restante jusqu'à l'objectif."}, "floyd-warshall-tous-les-plus-courts-chemins": {"title": "Floyd-Warshall (tous les plus courts chemins)", "description": "Cet algorithme calcule le plus court chemin entre toutes les paires de sommets d'un graphe simultanément, plus efficace que d'appliquer Dijkstra à chaque paire."}, "graphes-avec-poids-negatifs": {"title": "Graphes avec poids négatifs", "description": "Quand un graphe contient des arêtes de poids négatif, l'algorithme de Dijkstra échoue ; il faut alors utiliser Bellman-Ford, plus lent mais capable de gérer ce cas."}, "applications-au-routage-reseau": {"title": "Applications au routage réseau", "description": "Les algorithmes de plus court chemin déterminent comment les paquets de données doivent voyager efficacement à travers le réseau internet."}, "plus-courts-chemins-en-programmation-dynamique": {"title": "Plus courts chemins en programmation dynamique", "description": "Certains algorithmes de plus court chemin (Bellman-Ford, Floyd-Warshall) sont en réalité des applications directes du principe de la programmation dynamique."}, "codage-de-huffman-compression": {"title": "Codage de Huffman (compression)", "description": "Ce codage attribue des séquences binaires plus courtes aux symboles les plus fréquents d'un message, minimisant sa taille totale de façon prouvée optimale."}, "probleme-de-l-arbre-couvrant-minimal-kruskal-prim": {"title": "Problème de l'arbre couvrant minimal (Kruskal, Prim)", "description": "Ces deux algorithmes gloutons trouvent, chacun à sa manière, l'arbre couvrant minimal d'un graphe pondéré, garantissant tous deux la solution optimale."}, "conditions-de-validite-matroides": {"title": "Conditions de validité (matroïdes)", "description": "Un matroïde est une structure mathématique qui garantit qu'un algorithme glouton trouve bien la solution optimale, un cadre théorique qui unifie de nombreux problèmes d'optimisation."}, "comparaison-avec-la-programmation-dynamique": {"title": "Comparaison avec la programmation dynamique", "description": "Contrairement à un algorithme glouton, la programmation dynamique explore systématiquement plusieurs choix possibles et garantit la solution optimale, au prix d'un temps de calcul plus élevé."}, "algorithmes-gloutons-approches-np-difficiles": {"title": "Algorithmes gloutons approchés (NP-difficiles)", "description": "Pour de nombreux problèmes NP-difficiles, un algorithme glouton ne garantit pas la solution optimale mais en donne une approximation raisonnable en temps polynomial."}, "probleme-du-sac-a-dos": {"title": "Problème du sac à dos", "description": "Ce problème d'optimisation classique cherche à maximiser la valeur d'objets placés dans un sac de capacité limitée, résolu efficacement par programmation dynamique."}, "distance-d-edition-correction-orthographique": {"title": "Distance d'édition (correction orthographique)", "description": "La distance d'édition compte le nombre minimal d'opérations (insertion, suppression, substitution) pour transformer un mot en un autre, calculée efficacement par programmation dynamique."}, "programmation-dynamique-sur-des-arbres-graphes": {"title": "Programmation dynamique sur des arbres/graphes", "description": "La programmation dynamique s'applique aussi aux arbres et graphes, en résolvant récursivement un problème sur des sous-structures avant de combiner les résultats."}, "memoisation-vs-tabulation": {"title": "Mémoïsation vs tabulation", "description": "La mémoïsation stocke les résultats calculés au fur et à mesure des appels récursifs ; la tabulation construit la solution de façon itérative de bas en haut — deux façons d'implémenter la programmation dynamique."}, "applications-en-bio-informatique": {"title": "Applications en bio-informatique", "description": "La programmation dynamique permet d'aligner efficacement des séquences génétiques (ADN, protéines) pour détecter des similarités et des mutations."}, "probleme-des-huit-reines": {"title": "Problème des huit reines", "description": "Ce problème classique demande de placer huit reines sur un échiquier sans qu'aucune ne puisse en attaquer une autre, résolu efficacement par backtracking."}, "elagage-et-bornes-branch-and-bound": {"title": "Élagage et bornes (branch and bound)", "description": "Cette technique accélère la recherche exhaustive en calculant des bornes qui permettent d'abandonner immédiatement les branches qui ne peuvent pas mener à une meilleure solution."}, "satisfaction-de-contraintes-csp": {"title": "Satisfaction de contraintes (CSP)", "description": "Un problème de satisfaction de contraintes cherche des valeurs pour des variables qui respectent simultanément toutes les contraintes imposées, résolu souvent par backtracking."}, "backtracking-et-resolution-de-sudoku": {"title": "Backtracking et résolution de Sudoku", "description": "Résoudre un Sudoku par backtracking consiste à essayer une valeur, continuer, et revenir en arrière dès qu'une contradiction apparaît, jusqu'à trouver une grille valide."}, "complexite-exponentielle-et-ses-limites": {"title": "Complexité exponentielle et ses limites", "description": "Un algorithme de complexité exponentielle devient rapidement impraticable, même sur des ordinateurs très puissants, dès que la taille des données dépasse quelques dizaines d'éléments."}, "elagage-pour-reduire-l-espace-de-recherche": {"title": "Élagage pour réduire l'espace de recherche", "description": "Éliminer précocement les branches d'exploration qui ne peuvent manifestement pas aboutir permet de réduire considérablement le temps de calcul d'un algorithme exhaustif."}, "comparaison-avec-les-heuristiques": {"title": "Comparaison avec les heuristiques", "description": "Une heuristique donne une solution rapide mais sans garantie d'optimalité ; une méthode exacte garantit l'optimalité mais peut être bien plus lente."}, "recherche-exhaustive-et-cryptographie-attaque-par-force-brut": {"title": "Recherche exhaustive et cryptographie (attaque par force brute)", "description": "Une attaque par force brute teste systématiquement toutes les clés possibles ; la sécurité cryptographique repose sur le fait que cet espace est bien trop vaste pour être exploré en un temps raisonnable."}, "classes-p-np-et-np-complet": {"title": "Classes P, NP et NP-complet", "description": "P regroupe les problèmes résolubles rapidement, NP ceux dont une solution se vérifie rapidement, et NP-complet les problèmes de NP les plus difficiles à résoudre."}, "reductions-polynomiales": {"title": "Réductions polynomiales", "description": "Réduire un problème A à un problème B en temps polynomial montre que B est au moins aussi difficile que A — un outil essentiel pour classifier la complexité des problèmes."}, "complexite-en-espace": {"title": "Complexité en espace", "description": "En plus du temps de calcul, un algorithme consomme de la mémoire ; la complexité en espace mesure comment cette consommation croît avec la taille des données."}, "problemes-np-complets-classiques-voyageur-de-commerce": {"title": "Problèmes NP-complets classiques (voyageur de commerce)", "description": "Le problème du voyageur de commerce (trouver le trajet le plus court visitant toutes les villes) est l'exemple emblématique de problème NP-complet, très difficile à résoudre exactement."}, "lois-de-de-morgan": {"title": "Lois de De Morgan", "description": "Ces lois relient négation, conjonction et disjonction : NON(A ET B) équivaut à (NON A) OU (NON B), un outil essentiel pour simplifier des expressions logiques."}, "formes-normales-conjonctive-disjonctive": {"title": "Formes normales (conjonctive, disjonctive)", "description": "Toute formule de logique booléenne peut se réécrire sous une forme normale standardisée (conjonctive ou disjonctive), utile pour la simplification et la résolution automatique."}, "simplification-de-circuits-tables-de-karnaugh": {"title": "Simplification de circuits (tables de Karnaugh)", "description": "Les tables de Karnaugh permettent de simplifier visuellement une expression logique complexe en un circuit équivalent utilisant un minimum de portes."}, "logique-et-algebre-de-boole": {"title": "Logique et algèbre de Boole", "description": "L'algèbre de Boole formalise mathématiquement les opérations logiques (ET, OU, NON), fondement théorique de toute l'électronique numérique et de la programmation."}, "additionneurs-binaires": {"title": "Additionneurs binaires", "description": "Un additionneur binaire est un circuit logique qui combine des portes ET, OU et XOR pour additionner deux nombres écrits en base 2, brique de base de tout processeur."}, "bascules-et-memoire-circuits-sequentiels": {"title": "Bascules et mémoire (circuits séquentiels)", "description": "Une bascule est un circuit capable de mémoriser un bit d'information dans le temps, brique de base de toute la mémoire numérique d'un ordinateur."}, "circuits-combinatoires-vs-sequentiels": {"title": "Circuits combinatoires vs séquentiels", "description": "Un circuit combinatoire calcule une sortie uniquement à partir des entrées actuelles ; un circuit séquentiel garde en mémoire un état interne qui influence aussi la sortie."}, "conception-de-circuits-integres-vlsi": {"title": "Conception de circuits intégrés (VLSI)", "description": "La conception VLSI (intégration à très grande échelle) permet de placer des milliards de transistors sur une seule puce de silicium, fondement de l'électronique moderne."}, "portes-logiques-et-cryptographie": {"title": "Portes logiques et cryptographie", "description": "L'opération XOR, réalisée par une simple porte logique, est à la base de nombreux algorithmes de chiffrement simples et de détection d'erreurs."}, "automates-deterministes-vs-non-deterministes": {"title": "Automates déterministes vs non déterministes", "description": "Un automate déterministe a toujours une seule transition possible par état et symbole ; un automate non déterministe peut en avoir plusieurs, bien que les deux reconnaissent les mêmes langages."}, "expressions-regulieres-et-theoreme-de-kleene": {"title": "Expressions régulières et théorème de Kleene", "description": "Le théorème de Kleene établit que les expressions régulières décrivent exactement les langages reconnus par un automate fini, fondant la recherche de motifs dans du texte."}, "automates-a-pile-langages-algebriques": {"title": "Automates à pile (langages algébriques)", "description": "Un automate à pile ajoute une mémoire (la pile) à un automate fini, ce qui lui permet de reconnaître des langages plus riches, comme les parenthésages équilibrés."}, "minimisation-d-automates": {"title": "Minimisation d'automates", "description": "Cette procédure réduit un automate fini au plus petit automate équivalent possible, en fusionnant les états qui se comportent de façon identique."}, "applications-aux-compilateurs": {"title": "Applications aux compilateurs", "description": "Les automates et grammaires formelles fondent la construction des compilateurs, qui doivent reconnaître et traduire un langage de programmation en code machine."}, "hierarchie-memoire-cache-ram-disque": {"title": "Hiérarchie mémoire (cache, RAM, disque)", "description": "Un ordinateur combine plusieurs niveaux de mémoire, du cache ultra-rapide mais minuscule au disque lent mais immense, pour optimiser à la fois vitesse et capacité."}, "pipeline-d-execution": {"title": "Pipeline d'exécution", "description": "Un pipeline découpe l'exécution d'une instruction en plusieurs étapes traitées simultanément pour des instructions différentes, augmentant considérablement le débit du processeur."}, "architecture-risc-vs-cisc": {"title": "Architecture RISC vs CISC", "description": "L'architecture RISC utilise des instructions simples et rapides ; l'architecture CISC utilise des instructions plus complexes mais moins nombreuses — deux philosophies de conception de processeur."}, "parallelisme-et-multi-c-urs": {"title": "Parallélisme et multi-cœurs", "description": "Un processeur multi-cœurs exécute plusieurs instructions simultanément sur des cœurs distincts, ce qui nécessite d'écrire des programmes capables d'exploiter ce parallélisme."}, "architecture-des-gpu-calcul-parallele": {"title": "Architecture des GPU (calcul parallèle)", "description": "Un GPU contient des milliers de cœurs simples optimisés pour exécuter la même opération sur beaucoup de données en parallèle, idéal pour le calcul graphique et l'IA."}, "hierarchie-de-chomsky": {"title": "Hiérarchie de Chomsky", "description": "Cette hiérarchie classe les langages formels en quatre niveaux (réguliers, hors contexte, contextuels, récursivement énumérables), chacun reconnu par une classe d'automates de plus en plus puissante."}, "grammaires-context-free-et-automates-a-pile": {"title": "Grammaires context-free et automates à pile", "description": "Les grammaires hors contexte, reconnues exactement par les automates à pile, décrivent la syntaxe de la plupart des langages de programmation."}, "analyse-syntaxique-parsing": {"title": "Analyse syntaxique (parsing)", "description": "L'analyse syntaxique vérifie qu'une suite de symboles respecte la grammaire d'un langage et construit un arbre représentant sa structure, étape clé de tout compilateur."}, "langages-recursivement-enumerables": {"title": "Langages récursivement énumérables", "description": "Un langage récursivement énumérable peut être reconnu par une machine de Turing qui s'arrête sur les mots du langage, mais pas nécessairement sur les autres."}, "applications-aux-compilateurs-et-au-nlp": {"title": "Applications aux compilateurs et au NLP", "description": "Les mêmes techniques de grammaire formelle qui structurent les compilateurs sont aussi utilisées, adaptées, pour analyser la structure grammaticale du langage naturel."}, "ordonnancement-des-processus": {"title": "Ordonnancement des processus", "description": "Le système d'exploitation décide, via un algorithme d'ordonnancement, quel processus obtient l'accès au processeur à chaque instant, pour donner l'illusion d'une exécution simultanée."}, "gestion-de-la-memoire-virtuelle": {"title": "Gestion de la mémoire virtuelle", "description": "La mémoire virtuelle donne à chaque programme l'illusion de disposer de toute la mémoire disponible, alors que le système d'exploitation gère en réalité son placement réel."}, "synchronisation-et-interblocage-deadlock": {"title": "Synchronisation et interblocage (deadlock)", "description": "Quand plusieurs processus se partagent des ressources, une mauvaise synchronisation peut mener à un interblocage où chacun attend indéfiniment une ressource détenue par un autre."}, "systemes-de-fichiers": {"title": "Systèmes de fichiers", "description": "Un système de fichiers organise et retrouve les données stockées sur un disque, gérant leur emplacement physique de façon transparente pour l'utilisateur."}, "virtualisation-et-conteneurs": {"title": "Virtualisation et conteneurs", "description": "La virtualisation crée des machines virtuelles isolées sur un même serveur physique ; les conteneurs, plus légers, isolent les applications sans dupliquer tout le système d'exploitation."}, "arbre-syntaxique-abstrait-ast": {"title": "Arbre syntaxique abstrait (AST)", "description": "L'AST représente la structure logique d'un programme sous forme d'arbre, éliminant les détails de syntaxe superflus pour faciliter les étapes suivantes de la compilation."}, "optimisation-de-code": {"title": "Optimisation de code", "description": "Un compilateur optimisant réorganise et simplifie automatiquement le code généré pour qu'il s'exécute plus rapidement ou consomme moins de mémoire, sans changer son comportement."}, "generation-de-code-intermediaire": {"title": "Génération de code intermédiaire", "description": "Un compilateur traduit souvent le code source vers une représentation intermédiaire indépendante du matériel, avant de la convertir en code machine spécifique au processeur cible."}, "compilation-vs-interpretation": {"title": "Compilation vs interprétation", "description": "Un langage compilé est traduit entièrement en code machine avant exécution (rapide mais moins flexible) ; un langage interprété est exécuté ligne par ligne (plus lent mais plus souple)."}, "compilateurs-just-in-time-jit": {"title": "Compilateurs Just-In-Time (JIT)", "description": "Un compilateur JIT traduit le code en langage machine au moment de l'exécution plutôt qu'à l'avance, combinant la flexibilité de l'interprétation et la rapidité de la compilation."}, "protocole-ip-et-routage": {"title": "Protocole IP et routage", "description": "Le protocole IP découpe les données en paquets et les achemine à travers le réseau internet en utilisant des adresses uniques et des tables de routage."}, "protocoles-applicatifs-http-dns": {"title": "Protocoles applicatifs (HTTP, DNS)", "description": "HTTP transporte les pages web, DNS traduit les noms de domaine en adresses IP — deux protocoles essentiels du fonctionnement quotidien d'internet."}, "securite-reseau-pare-feu-vpn": {"title": "Sécurité réseau (pare-feu, VPN)", "description": "Un VPN chiffre le trafic entre deux points pour le protéger sur un réseau non sûr, complétant la protection apportée par un pare-feu."}, "reseaux-sans-fil-wifi-reseaux-mobiles": {"title": "Réseaux sans fil (WiFi, réseaux mobiles)", "description": "Ces réseaux transmettent des données par ondes électromagnétiques plutôt que par câble, nécessitant des protocoles spécifiques pour gérer les interférences et la mobilité."}, "architecture-d-internet-et-data-centers": {"title": "Architecture d'internet et data centers", "description": "Internet repose sur une architecture décentralisée de routeurs et de centres de données interconnectés, conçue pour rester fonctionnelle même en cas de panne partielle."}, "chiffrement-asymetrique-rsa": {"title": "Chiffrement asymétrique (RSA)", "description": "RSA utilise une paire de clés, publique pour chiffrer et privée pour déchiffrer, résolvant le problème de l'échange sécurisé d'une clé secrète unique."}, "authentification-multi-facteurs": {"title": "Authentification multi-facteurs", "description": "Cette méthode de sécurité combine plusieurs preuves d'identité indépendantes (mot de passe, téléphone, empreinte) pour rendre un compte beaucoup plus difficile à compromettre."}, "attaques-par-force-brute-et-par-dictionnaire": {"title": "Attaques par force brute et par dictionnaire", "description": "Une attaque par force brute teste systématiquement tous les mots de passe possibles ; une attaque par dictionnaire se limite à des mots de passe probables."}, "securite-des-reseaux-pare-feu-detection-d-intrusion": {"title": "Sécurité des réseaux (pare-feu, détection d'intrusion)", "description": "Un pare-feu filtre le trafic réseau selon des règles de sécurité ; un système de détection d'intrusion surveille en plus les comportements suspects en temps réel."}, "signatures-numeriques": {"title": "Signatures numériques", "description": "Une signature numérique prouve mathématiquement qu'un message provient bien d'un émetteur donné et n'a pas été altéré, en utilisant la clé privée de cet émetteur."}, "infrastructure-a-cles-publiques-pki": {"title": "Infrastructure à clés publiques (PKI)", "description": "Cette infrastructure gère la création, la distribution et la vérification des certificats numériques, fondant la confiance dans les échanges chiffrés sur internet (HTTPS)."}, "protocoles-d-echange-de-cles-modernes": {"title": "Protocoles d'échange de clés modernes", "description": "Ces protocoles combinent souvent Diffie-Hellman avec des courbes elliptiques pour établir rapidement et sûrement une clé secrète partagée entre deux parties."}, "inegalite-de-rearrangement": {"title": "Inégalité de réarrangement", "description": "Cette inégalité dit que la somme des produits de deux suites est maximale quand elles sont triées dans le même ordre, minimale quand elles sont triées en ordre opposé."}, "inegalite-de-schur": {"title": "Inégalité de Schur", "description": "Cette inégalité classique, valable pour des réels positifs, complète souvent efficacement AM-GM et Cauchy-Schwarz dans les problèmes d'inégalités à trois variables."}, "inegalite-de-jensen-convexite": {"title": "Inégalité de Jensen (convexité)", "description": "Cette inégalité dit que l'image de la moyenne par une fonction convexe est toujours inférieure ou égale à la moyenne des images, un outil très général pour prouver des inégalités."}, "methode-sos-somme-de-carres": {"title": "Méthode SOS (somme de carrés)", "description": "Cette méthode prouve une inégalité en réécrivant la différence des deux membres comme une somme de carrés, manifestement positive ou nulle."}, "inegalites-a-plusieurs-variables-symetriques": {"title": "Inégalités à plusieurs variables symétriques", "description": "Les inégalités symétriques, invariantes par permutation des variables, atteignent souvent leur extremum quand toutes les variables sont égales — une intuition à toujours vérifier rigoureusement."}, "methode-des-multiplicateurs-de-lagrange-approche-avancee": {"title": "Méthode des multiplicateurs de Lagrange (approche avancée)", "description": "Même sans être exigée en olympiades, cette méthode d'optimisation universitaire aide souvent à deviner rapidement le cas d'égalité optimal d'une inégalité sous contrainte."}, "optimisation-par-substitution": {"title": "Optimisation par substitution", "description": "Remplacer intelligemment une ou plusieurs variables permet parfois de transformer un problème d'optimisation complexe en un problème beaucoup plus simple à traiter directement."}, "cas-d-egalite-et-leur-interpretation": {"title": "Cas d'égalité et leur interprétation", "description": "Dans une inégalité, identifier précisément quand l'égalité est atteinte révèle souvent la structure profonde du problème et guide vers une preuve plus naturelle."}, "optimisation-geometrique-aires-perimetres": {"title": "Optimisation géométrique (aires, périmètres)", "description": "Ces problèmes cherchent à maximiser ou minimiser une aire ou un périmètre sous contrainte géométrique, souvent résolus par des inégalités plutôt que par le calcul différentiel."}, "lien-avec-la-convexite": {"title": "Lien avec la convexité", "description": "De nombreuses inégalités classiques de compétition sont en réalité des cas particuliers de l'inégalité de Jensen appliquée à une fonction convexe bien choisie."}, "identites-remarquables-avancees": {"title": "Identités remarquables avancées", "description": "Au-delà des identités de base (carré d'une somme), des identités plus riches comme a³+b³+c³-3abc révèlent des factorisations utiles pour des problèmes de compétition avancés."}, "factorisation-par-substitution": {"title": "Factorisation par substitution", "description": "Remplacer une expression complexe par une nouvelle variable peut révéler une factorisation ou une identité remarquable cachée dans le problème original."}, "polynomes-symetriques": {"title": "Polynômes symétriques", "description": "Un polynôme symétrique élémentaire ne change pas quand on permute ses variables ; tout polynôme symétrique s'exprime en fonction de ces briques élémentaires."}, "factorisation-et-divisibilite": {"title": "Factorisation et divisibilité", "description": "Factoriser une expression révèle souvent immédiatement des propriétés de divisibilité qui seraient invisibles sous la forme développée initiale."}, "utilisation-des-racines-de-l-unite": {"title": "Utilisation des racines de l'unité", "description": "Les racines n-ièmes de l'unité, grâce à leurs propriétés de symétrie, simplifient élégamment de nombreux problèmes de sommes et de dénombrement en compétition."}, "substitutions-astucieuses-x-y-0-x-y": {"title": "Substitutions astucieuses (x=y=0, x=y)", "description": "Dans une équation fonctionnelle, essayer des substitutions simples (x=0, y=0, x=y) révèle souvent rapidement des informations essentielles sur la fonction cherchée."}, "points-fixes-de-fonctions": {"title": "Points fixes de fonctions", "description": "Un point fixe d'une fonction f vérifie f(x)=x ; en trouver un est souvent l'étape clé pour résoudre une équation fonctionnelle ou étudier une suite récurrente."}, "regularite-et-hypotheses-de-continuite": {"title": "Régularité et hypothèses de continuité", "description": "Sans hypothèse de régularité (comme la continuité), l'équation fonctionnelle de Cauchy admet des solutions extrêmement pathologiques en plus des simples fonctions linéaires."}, "monovariants-et-terminaison-de-processus": {"title": "Monovariants et terminaison de processus", "description": "Un monovariant, quantité qui évolue toujours dans le même sens, garantit qu'un processus itératif ne peut pas continuer indéfiniment et doit s'arrêter."}, "invariants-de-parite": {"title": "Invariants de parité", "description": "Un invariant de parité (le nombre d'éléments impairs, par exemple) reste souvent constant lors des transformations autorisées d'un problème, permettant de prouver des impossibilités."}, "invariants-modulo-n": {"title": "Invariants modulo n", "description": "Étudier une quantité modulo un entier n bien choisi révèle souvent une contrainte cachée qui prouve l'impossibilité d'atteindre un état final donné."}, "invariants-en-theorie-des-jeux": {"title": "Invariants en théorie des jeux", "description": "Dans un jeu combinatoire, un invariant identifie une quantité qui détermine qui, du premier ou du second joueur, dispose d'une stratégie gagnante."}, "symetries-comme-source-d-invariants": {"title": "Symétries comme source d'invariants", "description": "La symétrie d'un problème (par rapport à une transformation) produit presque toujours un invariant naturel, exploitable pour simplifier ou résoudre le problème."}, "suites-arithmetico-geometriques": {"title": "Suites arithmético-géométriques", "description": "Une suite arithmético-géométrique combine les règles d'une suite arithmétique et d'une suite géométrique ; elle se résout en la ramenant à une suite géométrique pure par un changement de variable."}, "points-fixes-et-convergence": {"title": "Points fixes et convergence", "description": "Une suite définie par récurrence converge, si elle converge, nécessairement vers un point fixe de la fonction qui la définit — un principe clé pour deviner sa limite."}, "descente-infinie-de-fermat": {"title": "Descente infinie de Fermat", "description": "Cette méthode prouve l'absence de solution entière en montrant qu'une solution supposée en engendrerait toujours une strictement plus petite, ce qui est impossible indéfiniment dans ℕ."}, "suites-recurrentes-lineaires-d-ordre-2": {"title": "Suites récurrentes linéaires d'ordre 2", "description": "Une suite comme celle de Fibonacci, définie par uₙ₊₂=auₙ₊₁+buₙ, se résout explicitement via les racines de son équation caractéristique associée."}, "suites-et-fractions-continues": {"title": "Suites et fractions continues", "description": "Une fraction continue représente un nombre réel par une suite imbriquée de fractions, offrant les meilleures approximations rationnelles possibles de ce nombre."}, "principe-des-tiroirs-generalise": {"title": "Principe des tiroirs généralisé", "description": "Ce principe garantit que si l'on range n objets dans k tiroirs avec n>k, au moins un tiroir contient plus d'un objet — simple mais extrêmement puissant."}, "inclusion-exclusion-avancee": {"title": "Inclusion-exclusion avancée", "description": "Pour plus de deux ensembles, le principe d'inclusion-exclusion nécessite d'alterner soigneusement les signes en fonction du nombre d'ensembles inclus dans chaque intersection."}, "double-comptage": {"title": "Double comptage", "description": "Cette technique évalue une même quantité de deux façons différentes pour en déduire une égalité non triviale entre deux expressions a priori sans rapport apparent."}, "bijections-combinatoires": {"title": "Bijections combinatoires", "description": "Une preuve bijective compte un ensemble en le mettant en correspondance exacte avec un autre ensemble dont la taille est déjà connue, une technique combinatoire particulièrement élégante."}, "combinatoire-et-theorie-des-graphes": {"title": "Combinatoire et théorie des graphes", "description": "De nombreux problèmes combinatoires se reformulent naturellement en langage de graphes, où sommets et arêtes rendent visibles des structures et symétries."}, "lemme-des-poignees-de-main": {"title": "Lemme des poignées de main", "description": "Ce lemme dit que la somme des degrés de tous les sommets d'un graphe est toujours paire, puisque chaque arête est comptée exactement deux fois."}, "theoreme-de-ramsey-cas-simples": {"title": "Théorème de Ramsey (cas simples)", "description": "Dans sa version la plus simple, ce théorème garantit que parmi six personnes, il y en a toujours trois qui se connaissent mutuellement ou trois qui sont mutuellement étrangères."}, "tournois-et-graphes-orientes": {"title": "Tournois et graphes orientés", "description": "Un tournoi est un graphe orienté complet représentant les résultats de matchs entre tous les participants, avec des propriétés combinatoires étonnamment riches."}, "graphes-bipartis": {"title": "Graphes bipartis", "description": "Un graphe biparti peut être divisé en deux groupes de sommets tels que toutes les arêtes relient un sommet de chaque groupe, structure fréquente en combinatoire et théorie des jeux."}, "coloration-de-graphes-en-competition": {"title": "Coloration de graphes en compétition", "description": "Les problèmes de coloration de graphes en olympiades demandent souvent de déterminer le nombre minimal de couleurs nécessaires pour une configuration donnée."}, "ordre-multiplicatif-modulo-n": {"title": "Ordre multiplicatif modulo n", "description": "L'ordre de a modulo n est le plus petit entier k tel que a^k≡1 (mod n) ; il divise toujours l'indicatrice d'Euler φ(n), un fait clé pour de nombreux problèmes."}, "lifting-the-exponent-lte": {"title": "Lifting the Exponent (LTE)", "description": "Cette technique calcule précisément la puissance d'un nombre premier qui divise une expression du type aⁿ-bⁿ, bien plus rapidement qu'une analyse directe cas par cas."}, "theoreme-chinois-des-restes-en-competition": {"title": "Théorème chinois des restes en compétition", "description": "Ce théorème permet de résoudre en compétition des systèmes de congruences simultanées, souvent la clé pour construire un nombre vérifiant plusieurs contraintes modulaires."}, "equation-de-pell-fermat": {"title": "Équation de Pell-Fermat", "description": "Cette équation x²-ny²=1 possède toujours une infinité de solutions entières (pour n non carré parfait), génératrices via les fractions continues du nombre √n."}, "triplets-pythagoriciens": {"title": "Triplets pythagoriciens", "description": "Un triplet pythagoricien (comme 3,4,5) vérifie a²+b²=c² ; tous les triplets primitifs se génèrent par une formule explicite utilisant deux entiers auxiliaires."}, "descente-infinie-de-fermat-approfondie": {"title": "Descente infinie de Fermat (approfondie)", "description": "Au-delà des cas simples, la descente infinie s'applique à des équations diophantiennes non linéaires plus subtiles, en construisant soigneusement une suite décroissante de solutions."}, "theoreme-des-deux-carres-de-fermat": {"title": "Théorème des deux carrés de Fermat", "description": "Ce théorème caractérise exactement quels nombres premiers s'écrivent comme somme de deux carrés parfaits, selon leur reste modulo 4."}, "puissance-d-un-point-et-axe-radical": {"title": "Puissance d'un point et axe radical", "description": "L'axe radical de deux cercles est l'ensemble des points qui ont la même puissance par rapport aux deux, une droite perpendiculaire à la ligne joignant leurs centres."}, "angles-inscrits-et-cocyclicite": {"title": "Angles inscrits et cocyclicité", "description": "Quatre points sont cocycliques (sur un même cercle) si et seulement si les angles inscrits qu'ils forment vérifient des relations précises, un critère très utilisé en géométrie de compétition."}, "theoreme-de-ptolemee": {"title": "Théorème de Ptolémée", "description": "Ce théorème relie, pour un quadrilatère inscrit dans un cercle, le produit des diagonales à la somme des produits des côtés opposés."}, "inversion-geometrique": {"title": "Inversion géométrique", "description": "L'inversion de centre O et de rapport k transforme un point M en un point M' aligné avec O tel que OM×OM'=k, échangeant cercles et droites selon des règles précises."}, "configurations-classiques-orthocentre-cercle-d-euler": {"title": "Configurations classiques (orthocentre, cercle d'Euler)", "description": "Certaines configurations géométriques (orthocentre, cercle des neuf points, droite d'Euler) reviennent si souvent en compétition qu'il est essentiel de les reconnaître immédiatement."}, "theoreme-de-ceva-et-menelaus-via-les-barycentres": {"title": "Théorème de Ceva et Ménélaüs via les barycentres", "description": "Les coordonnées barycentriques offrent souvent la démonstration la plus rapide et la plus naturelle des théorèmes de Ceva et Ménélaüs sur les concours de droites."}, "coordonnees-barycentriques": {"title": "Coordonnées barycentriques", "description": "Ces coordonnées repèrent un point par ses poids relatifs par rapport aux sommets d'un triangle de référence, simplifiant considérablement certaines preuves de géométrie."}, "barycentres-et-concours-de-cevianes": {"title": "Barycentres et concours de cévianes", "description": "Les coordonnées barycentriques offrent souvent la preuve la plus rapide qu'un ensemble de cévianes (segments reliant un sommet au côté opposé) sont concourantes."}, "centre-de-gravite-en-physique": {"title": "Centre de gravité en physique", "description": "Le centre de gravité d'un objet est le barycentre de sa masse ; c'est le point autour duquel l'objet est parfaitement équilibré sous l'effet de la gravité."}, "barycentres-en-dimension-superieure": {"title": "Barycentres en dimension supérieure", "description": "La notion de barycentre s'étend sans difficulté à l'espace et au-delà, permettant de généraliser de nombreux résultats de géométrie plane à des dimensions supérieures."}, "coloration-d-echiquiers-argument-classique": {"title": "Coloration d'échiquiers (argument classique)", "description": "Colorier un échiquier en damier révèle des contraintes cachées : par exemple, deux cases opposées en diagonale sont toujours de la même couleur, ce qui prouve l'impossibilité de certains pavages."}, "coloration-de-graphes": {"title": "Coloration de graphes", "description": "Colorier les sommets d'un graphe sans que deux voisins partagent la même couleur permet de résoudre des problèmes d'attribution (fréquences, emplois du temps) sans conflit."}, "nombre-chromatique": {"title": "Nombre chromatique", "description": "Le nombre chromatique d'un graphe est le plus petit nombre de couleurs nécessaires pour le colorier valablement, une quantité souvent difficile à calculer exactement."}, "colorations-et-parite": {"title": "Colorations et parité", "description": "De nombreux arguments de coloriage exploitent simplement la parité (pair/impair) du nombre de cases de chaque couleur recouvertes par une configuration donnée."}, "theoreme-des-quatre-couleurs": {"title": "Théorème des quatre couleurs", "description": "Ce théorème, prouvé avec l'aide d'un ordinateur, garantit que quatre couleurs suffisent toujours pour colorier n'importe quelle carte plane sans que deux régions voisines partagent la même couleur."}, "pavages-par-dominos-argument-de-coloriage": {"title": "Pavages par dominos (argument de coloriage)", "description": "Colorier un échiquier en damier révèle immédiatement qu'un domino recouvre toujours une case de chaque couleur, un argument classique pour prouver l'impossibilité de certains pavages."}, "polyominos-et-pavages-du-plan": {"title": "Polyominos et pavages du plan", "description": "Un polyomino est une forme construite en assemblant des carrés unité ; déterminer s'il peut paver le plan ou une figure donnée est un problème combinatoire classique."}, "pavages-periodiques-et-aperiodiques": {"title": "Pavages périodiques et apériodiques", "description": "Un pavage périodique se répète régulièrement ; un pavage apériodique (comme les pavages de Penrose) ne se répète jamais, bien que restant parfaitement ordonné."}, "theoreme-de-wang-indecidabilite-du-pavage": {"title": "Théorème de Wang (indécidabilité du pavage)", "description": "Ce résultat surprenant montre qu'il n'existe aucun algorithme général pour décider si un ensemble de tuiles peut paver tout le plan, un problème indécidable."}, "pavages-en-cristallographie": {"title": "Pavages en cristallographie", "description": "Les pavages périodiques du plan et de l'espace, classifiés par leurs groupes de symétrie, correspondent exactement aux structures observées dans les cristaux naturels."}, "lien-avec-l-inegalite-am-gm": {"title": "Lien avec l'inégalité AM-GM", "description": "De nombreuses inégalités avancées (Muirhead, Schur) se ramènent, dans leurs cas particuliers les plus simples, à la célèbre inégalité entre moyennes arithmétique et géométrique."}, "symetrisation-en-geometrie": {"title": "Symétrisation en géométrie", "description": "Exploiter la symétrie d'une configuration géométrique permet souvent de réduire un problème général à un cas particulier plus simple à traiter directement."}, "preuve-rigoureuse-de-l-egalite-des-cas-optimaux": {"title": "Preuve rigoureuse de l'égalité des cas optimaux", "description": "Deviner le cas d'égalité d'une inégalité ne suffit pas : il faut ensuite prouver rigoureusement que c'est bien l'unique cas où l'égalité est atteinte."}, "fonctions-symetriques-et-polynomes-symetriques": {"title": "Fonctions symétriques et polynômes symétriques", "description": "Une fonction symétrique ne change pas de valeur si on permute ses variables ; tout polynôme symétrique s'exprime comme combinaison des polynômes symétriques élémentaires."}, "symetrisation-de-steiner-geometrie-avancee": {"title": "Symétrisation de Steiner (géométrie avancée)", "description": "Cette technique transforme une figure en une figure symétrique de même aire mais de périmètre plus petit, un outil clé pour prouver des inégalités isopérimétriques."}, "choix-judicieux-d-un-invariant": {"title": "Choix judicieux d'un invariant", "description": "Trouver le bon invariant pour un problème donné est souvent la partie la plus créative et la plus difficile d'une démonstration par invariance en compétition."}, "monovariants-et-preuves-de-terminaison-d-algorithmes": {"title": "Monovariants et preuves de terminaison d'algorithmes", "description": "Un monovariant qui décroît strictement à chaque étape d'un algorithme, tout en restant positif, prouve rigoureusement que cet algorithme se termine en un temps fini."}, "invariants-en-theorie-des-jeux-combinatoires": {"title": "Invariants en théorie des jeux combinatoires", "description": "Ces invariants (souvent liés au XOR des positions dans un jeu de Nim) permettent de déterminer instantanément l'issue optimale d'un jeu combinatoire complexe."}, "invariants-topologiques": {"title": "Invariants topologiques", "description": "Un invariant topologique reste constant même quand une figure est déformée continûment, un outil puissant pour prouver que deux configurations ne sont pas équivalentes."}, "applications-a-la-verification-de-programmes": {"title": "Applications à la vérification de programmes", "description": "Les invariants de boucle, analogues aux invariants mathématiques utilisés en compétition, sont l'outil central pour prouver formellement qu'un programme informatique est correct."}, "equivalence-des-normes-en-dimension-finie": {"title": "Équivalence des normes en dimension finie", "description": "En dimension finie, toutes les normes sont équivalentes (elles définissent la même notion de convergence), un résultat qui simplifie grandement de nombreuses démonstrations de prépa."}, "normes-matricielles": {"title": "Normes matricielles", "description": "Une norme matricielle mesure la « taille » d'une matrice, souvent définie comme le facteur d'amplification maximal qu'elle peut appliquer à un vecteur — un outil clé pour l'analyse numérique."}, "applications-aux-methodes-numeriques": {"title": "Applications aux méthodes numériques", "description": "Les méthodes numériques (Newton, Euler, résolution de systèmes) apparaissent régulièrement aux concours, souvent couplées à un exercice de programmation en Python."}, "boules-ouvertes-et-fermees": {"title": "Boules ouvertes et fermées", "description": "Une boule ouverte exclut son bord, une boule fermée l'inclut ; cette distinction, subtile en apparence, est essentielle pour définir rigoureusement ouverts et fermés en topologie."}, "distance-et-topologie-induite": {"title": "Distance et topologie induite", "description": "Restreindre une distance à un sous-ensemble d'un espace métrique induit naturellement une topologie sur ce sous-ensemble, cohérente avec la topologie de l'espace de départ."}, "compacite-et-connexite": {"title": "Compacité et connexité", "description": "Ces deux propriétés topologiques fondamentales (l'une liée à la finitude, l'autre à l'absence de séparation) reviennent constamment dans les exercices de topologie de prépa."}, "topologie-produit-et-quotient": {"title": "Topologie produit et quotient", "description": "Ces constructions topologiques permettent de munir un produit d'espaces, ou un ensemble de classes d'équivalence, d'une topologie naturelle héritée des espaces de départ."}, "espaces-topologiques-non-metrisables": {"title": "Espaces topologiques non métrisables", "description": "Certains espaces topologiques ne peuvent être décrits par aucune distance, illustrant que la topologie est un cadre strictement plus général que celui des espaces métriques."}, "homeomorphismes": {"title": "Homéomorphismes", "description": "Un homéomorphisme est une bijection continue dont la réciproque est aussi continue ; deux espaces homéomorphes sont topologiquement indiscernables, malgré des apparences parfois très différentes."}, "convergence-normale-critere-de-weierstrass": {"title": "Convergence normale (critère de Weierstrass)", "description": "Ce critère pratique garantit la convergence uniforme d'une série de fonctions en majorant chaque terme par une constante dont la série numérique associée converge."}, "continuite-de-la-limite-uniforme": {"title": "Continuité de la limite uniforme", "description": "Si une suite de fonctions continues converge uniformément, sa limite est automatiquement continue — un résultat qui échoue souvent avec la simple convergence point par point."}, "derivation-et-integration-terme-a-terme": {"title": "Dérivation et intégration terme à terme", "description": "Sous convergence uniforme (ou normale), on peut dériver ou intégrer une série de fonctions terme à terme, un résultat très utilisé pour manipuler des séries entières."}, "series-de-fonctions-holomorphes": {"title": "Séries de fonctions holomorphes", "description": "Une série de fonctions holomorphes qui converge uniformément sur tout compact a pour limite une fonction elle-même holomorphe, un résultat remarquable propre à l'analyse complexe."}, "theoreme-de-dirichlet-convergence-ponctuelle": {"title": "Théorème de Dirichlet (convergence ponctuelle)", "description": "Ce théorème donne des conditions suffisantes pour que la série de Fourier d'une fonction converge, en chaque point, vers la valeur de la fonction elle-même."}, "egalite-de-parseval": {"title": "Égalité de Parseval", "description": "Cette égalité relie l'énergie totale d'une fonction périodique à la somme des carrés de ses coefficients de Fourier, un résultat central du programme de séries de Fourier."}, "applications-aux-edp-au-programme-de-prepa": {"title": "Applications aux EDP au programme de prépa", "description": "Les séries de Fourier permettent de résoudre explicitement l'équation de la chaleur sur un segment, un grand classique des sujets de concours en analyse."}, "conditions-de-cauchy-riemann": {"title": "Conditions de Cauchy-Riemann", "description": "Ces deux équations aux dérivées partielles caractérisent exactement les fonctions holomorphes, faisant le lien entre dérivabilité complexe et propriétés analytiques réelles."}, "theoreme-des-residus-application-aux-concours": {"title": "Théorème des résidus (application aux concours)", "description": "Le théorème des résidus est un outil redoutablement efficace pour calculer, en quelques lignes, des intégrales réelles qui résisteraient à toute méthode élémentaire."}, "fonctions-meromorphes": {"title": "Fonctions méromorphes", "description": "Une fonction méromorphe est holomorphe partout sauf en des points isolés où elle admet des pôles, une classe de fonctions centrale du programme d'analyse complexe de prépa."}, "applications-aux-integrales-reelles-technique-de-concours": {"title": "Applications aux intégrales réelles (technique de concours)", "description": "Passer par le plan complexe et le théorème des résidus permet de calculer élégamment des intégrales réelles autrement très difficiles, une technique appréciée des concepteurs de sujets."}, "automorphismes-du-disque-unite": {"title": "Automorphismes du disque unité", "description": "Les automorphismes holomorphes du disque unité sont exactement les transformations de Möbius qui préservent le disque, un résultat classique d'analyse complexe."}, "transformations-de-mobius-homographies": {"title": "Transformations de Möbius (homographies)", "description": "Ces transformations du plan complexe (z↦(az+b)/(cz+d)) sont exactement les automorphismes conformes de la sphère de Riemann, avec des propriétés géométriques remarquables."}, "representation-conforme-de-riemann": {"title": "Représentation conforme de Riemann", "description": "Ce théorème garantit que tout domaine simplement connexe du plan (autre que le plan entier) peut être transformé conformément en le disque unité, un résultat profond d'analyse complexe."}, "applications-a-la-cartographie": {"title": "Applications à la cartographie", "description": "Les transformations conformes préservent localement les angles, ce qui explique pourquoi certaines projections cartographiques (Mercator) les utilisent pour préserver les directions de navigation."}, "applications-a-l-electrostatique-et-la-mecanique-des-fluides": {"title": "Applications à l'électrostatique et la mécanique des fluides", "description": "Les transformations conformes permettent de résoudre certains problèmes bidimensionnels d'électrostatique ou d'écoulement de fluide en les ramenant à des configurations plus simples."}, "systemes-differentiels-lineaires-niveau-concours": {"title": "Systèmes différentiels linéaires (niveau concours)", "description": "Résoudre un système différentiel linéaire en prépa passe presque toujours par la diagonalisation de la matrice associée, technique à maîtriser parfaitement."}, "resolution-par-changement-de-variable": {"title": "Résolution par changement de variable", "description": "Un changement de variable bien choisi peut transformer une équation différentielle compliquée en une équation beaucoup plus simple à résoudre directement."}, "stabilite-des-solutions": {"title": "Stabilité des solutions", "description": "Étudier la stabilité des solutions d'une équation différentielle (est-ce qu'une petite perturbation reste petite ?) est une question récurrente des sujets de concours en mathématiques et en physique."}, "applications-a-la-physique-du-programme-de-prepa": {"title": "Applications à la physique du programme de prépa", "description": "Les équations différentielles étudiées en mathématiques trouvent une application directe dans les circuits électriques et les oscillateurs mécaniques du programme de physique."}, "projection-orthogonale-sur-un-sous-espace": {"title": "Projection orthogonale sur un sous-espace", "description": "La projection orthogonale d'un vecteur sur un sous-espace en donne l'élément le plus proche, un concept central pour les problèmes de moindres carrés en prépa."}, "theoreme-de-representation-de-riesz": {"title": "Théorème de représentation de Riesz", "description": "Ce théorème identifie toute forme linéaire continue sur un espace de Hilbert à un simple produit scalaire avec un vecteur bien choisi de cet espace."}, "theoreme-du-point-fixe-de-banach": {"title": "Théorème du point fixe de Banach", "description": "Ce théorème garantit qu'une application contractante sur un espace complet possède un unique point fixe, atteint par itération depuis n'importe quel point de départ."}, "theoreme-de-hahn-banach": {"title": "Théorème de Hahn-Banach", "description": "Ce théorème fondamental de l'analyse fonctionnelle garantit qu'on peut toujours prolonger une forme linéaire continue définie sur un sous-espace à l'espace tout entier, sans augmenter sa norme."}, "espaces-de-banach-de-fonctions-l-c": {"title": "Espaces de Banach de fonctions (Lᵖ, C⁰)", "description": "Ces espaces de fonctions, complets pour une norme bien choisie, fournissent le cadre rigoureux pour de nombreux résultats d'analyse fonctionnelle abordés en fin de prépa."}, "developpement-en-serie-entiere-des-fonctions-usuelles": {"title": "Développement en série entière des fonctions usuelles", "description": "Connaître par cœur les développements en série entière de exp, sin, cos, ln(1+x) et (1+x)^α est indispensable pour de nombreux calculs et démonstrations de concours."}, "series-entieres-et-fonctions-generatrices": {"title": "Séries entières et fonctions génératrices", "description": "Les séries entières servent aussi de fonctions génératrices pour résoudre des relations de récurrence, un pont classique entre analyse et combinatoire en prépa."}, "endomorphismes-symetriques-et-theoreme-spectral": {"title": "Endomorphismes symétriques et théorème spectral", "description": "Le théorème spectral, qui diagonalise tout endomorphisme symétrique dans une base orthonormée, est l'un des résultats les plus centraux et les plus réutilisés du programme d'algèbre de prépa."}, "applications-aux-systemes-differentiels": {"title": "Applications aux systèmes différentiels", "description": "La diagonalisation de matrices permet de résoudre explicitement des systèmes différentiels linéaires couplés, un exercice classique combinant algèbre et analyse."}, "espaces-euclidiens-et-orthogonalite": {"title": "Espaces euclidiens et orthogonalité", "description": "L'orthogonalité, le procédé de Gram-Schmidt et les projections orthogonales forment un socle incontournable du programme d'algèbre linéaire de deuxième année."}, "exercices-classiques-de-concours-algebre-lineaire": {"title": "Exercices classiques de concours (algèbre linéaire)", "description": "Certains exercices d'algèbre linéaire (diagonalisation, réduction) reviennent presque chaque année sous des formes variées, et méritent d'être parfaitement maîtrisés."}, "vecteurs-gaussiens-niveau-concours": {"title": "Vecteurs gaussiens (niveau concours)", "description": "Les vecteurs gaussiens, dont toute combinaison linéaire des composantes reste normale, apparaissent régulièrement dans les exercices de probabilités des concours les plus exigeants."}, "exercices-classiques-de-concours-probabilites": {"title": "Exercices classiques de concours (probabilités)", "description": "Les exercices classiques de probabilités en concours combinent souvent variables aléatoires discrètes, espérance conditionnelle et un peu de combinatoire."}, "applications-a-la-statistique-inferentielle": {"title": "Applications à la statistique inférentielle", "description": "Estimateurs, intervalles de confiance et tests d'hypothèses, vus en prépa, sont les outils de base de toute inférence statistique rigoureuse en recherche et en industrie."}, "estimateurs-sans-biais-et-convergents": {"title": "Estimateurs sans biais et convergents", "description": "Un bon estimateur statistique doit être à la fois sans biais (juste en moyenne) et convergent (de plus en plus précis avec la taille de l'échantillon) — deux critères étudiés en prépa."}, "intervalles-de-confiance-cas-gaussien": {"title": "Intervalles de confiance (cas gaussien)", "description": "Quand les données suivent une loi normale, la construction d'un intervalle de confiance pour la moyenne utilise la loi de Student, un résultat classique du programme de prépa."}, "applications-a-la-science-des-donnees": {"title": "Applications à la science des données", "description": "Les probabilités et la statistique du programme de prépa fondent directement les méthodes utilisées en science des données (régression, estimation, tests)."}, "equations-de-hamilton-formulation-alternative": {"title": "Équations de Hamilton (formulation alternative)", "description": "Cette formulation de la mécanique classique, équivalente à celle de Newton, s'avère souvent plus puissante pour analyser des systèmes complexes ou pour la transition vers la mécanique quantique."}, "coordonnees-generalisees-et-contraintes": {"title": "Coordonnées généralisées et contraintes", "description": "En mécanique analytique, choisir des coordonnées généralisées adaptées aux contraintes du système simplifie considérablement l'écriture des équations du mouvement."}, "symetries-et-lois-de-conservation-noether": {"title": "Symétries et lois de conservation (Noether)", "description": "Le théorème de Noether relie chaque symétrie continue d'un système physique à une quantité conservée, un résultat profond du programme de physique de prépa."}, "applications-a-la-mecanique-celeste": {"title": "Applications à la mécanique céleste", "description": "La géométrie symplectique et les systèmes hamiltoniens permettent d'étudier avec une grande précision la stabilité à long terme des orbites planétaires."}, "complexite-des-algorithmes-classiques": {"title": "Complexité des algorithmes classiques", "description": "Connaître la complexité des algorithmes de tri, de recherche et de graphes est indispensable pour les exercices d'informatique et pour écrire du code efficace aux concours."}, "automates-finis-et-expressions-regulieres": {"title": "Automates finis et expressions régulières", "description": "Ce sujet classique de l'option informatique relie la théorie des automates à la reconnaissance de motifs dans du texte, avec des exercices de programmation associés."}, "problemes-np-complets-classiques": {"title": "Problèmes NP-complets classiques", "description": "Connaître quelques problèmes NP-complets emblématiques (voyageur de commerce, SAT) aide à reconnaître rapidement la difficulté intrinsèque d'un problème algorithmique."}, "applications-aux-exercices-de-concours-informatique": {"title": "Applications aux exercices de concours (informatique)", "description": "Les concepts de complexité algorithmique et de structures de données sont directement mobilisés dans les exercices de l'option informatique des concours."}, "critere-de-d-alembert-et-de-cauchy": {"title": "Critère de d'Alembert et de Cauchy", "description": "Deux tests classiques pour déterminer la convergence d'une série : le critère de d'Alembert examine le rapport de deux termes consécutifs, celui de Cauchy examine la racine n-ième du terme général."}, "series-alternees-et-critere-de-leibniz": {"title": "Séries alternées et critère de Leibniz", "description": "Une série alternée change de signe à chaque terme ; le critère de Leibniz garantit sa convergence dès que les termes décroissent vers zéro en valeur absolue."}, "convergence-absolue-vs-semi-convergence": {"title": "Convergence absolue vs semi-convergence", "description": "Une série absolument convergente (Σ|uₙ| converge) peut être réarrangée sans changer sa somme ; une série semi-convergente (convergente mais pas absolument) peut voir sa somme changer selon l'ordre des termes."}, "series-de-fonctions-et-convergence-uniforme": {"title": "Séries de fonctions et convergence uniforme", "description": "Une série de fonctions converge uniformément si le contrôle de l'erreur ne dépend pas du point considéré, propriété nécessaire pour intégrer ou dériver terme à terme."}, "theoreme-de-bolzano-weierstrass": {"title": "Théorème de Bolzano-Weierstrass", "description": "Toute suite bornée de nombres réels possède une sous-suite convergente — un résultat fondamental qui garantit l'existence de limites partielles même sans convergence globale."}, "formule-de-taylor-lagrange": {"title": "Formule de Taylor-Lagrange", "description": "Cette version de la formule de Taylor exprime le reste (l'erreur d'approximation) à l'aide de la dérivée d'ordre supérieur évaluée en un point intermédiaire inconnu."}, "theoreme-de-darboux": {"title": "Théorème de Darboux", "description": "Même quand une dérivée n'est pas continue, elle vérifie toujours le théorème des valeurs intermédiaires — une propriété de continuité « cachée » propre aux fonctions dérivées."}, "inegalite-des-accroissements-finis": {"title": "Inégalité des accroissements finis", "description": "Cette inégalité borne la variation d'une fonction par le produit de la borne de sa dérivée et de la longueur de l'intervalle parcouru."}, "convexite-et-derivee-seconde": {"title": "Convexité et dérivée seconde", "description": "Une fonction est convexe sur un intervalle si et seulement si sa dérivée seconde y est positive ou nulle — un critère très pratique pour identifier des minima globaux."}, "theoreme-de-la-bijection": {"title": "Théorème de la bijection", "description": "Une fonction continue et strictement monotone sur un intervalle réalise une bijection vers son image, garantissant l'existence et l'unicité d'une solution à f(x)=k."}, "integrales-generalisees-et-convergence": {"title": "Intégrales généralisées et convergence", "description": "Une intégrale généralisée peut converger (avoir une valeur finie) ou diverger, selon la vitesse à laquelle la fonction décroît près de la borne problématique."}, "integration-des-fractions-rationnelles": {"title": "Intégration des fractions rationnelles", "description": "Toute fraction rationnelle s'intègre en la décomposant en éléments simples (fractions élémentaires), chacune ayant une primitive connue (logarithme, arctangente, puissance)."}, "calcul-de-volumes-de-revolution": {"title": "Calcul de volumes de révolution", "description": "La méthode des disques calcule le volume engendré par la rotation d'une courbe autour d'un axe, en intégrant l'aire des disques successifs."}, "integrales-a-parametre": {"title": "Intégrales à paramètre", "description": "Une intégrale à paramètre dépend d'une variable extérieure à la variable d'intégration ; on peut souvent dériver sous le signe intégrale pour l'étudier."}, "theoreme-des-fonctions-implicites": {"title": "Théorème des fonctions implicites", "description": "Ce théorème garantit que, sous certaines conditions, une relation F(x,y)=0 définit localement y comme fonction de x, même sans pouvoir l'expliciter algébriquement."}, "matrice-hessienne-et-extrema": {"title": "Matrice hessienne et extrema", "description": "La matrice hessienne regroupe les dérivées secondes d'une fonction à plusieurs variables ; son signe en un point critique détermine s'il s'agit d'un minimum, maximum ou point-selle."}, "theoreme-d-inversion-locale": {"title": "Théorème d'inversion locale", "description": "Si la différentielle d'une fonction est inversible en un point, la fonction elle-même est localement inversible autour de ce point — un résultat clé de l'analyse en plusieurs variables."}, "multiplicateurs-de-lagrange-et-kkt": {"title": "Multiplicateurs de Lagrange et KKT", "description": "Les conditions de Karush-Kuhn-Tucker généralisent les multiplicateurs de Lagrange aux contraintes d'inégalité, fondement de toute l'optimisation sous contraintes moderne."}, "champs-de-vecteurs-gradient-divergence-rotationnel": {"title": "Champs de vecteurs (gradient, divergence, rotationnel)", "description": "Le gradient indique la direction de plus forte variation, la divergence mesure l'expansion d'un flux, le rotationnel mesure sa tendance à tourner — trois opérateurs clés de l'analyse vectorielle."}, "theoreme-de-cauchy-lipschitz": {"title": "Théorème de Cauchy-Lipschitz", "description": "Sous une condition de régularité (lipschitzienne), ce théorème garantit l'existence et l'unicité de la solution d'une équation différentielle pour une condition initiale donnée."}, "systemes-differentiels-et-exponentielle-de-matrice": {"title": "Systèmes différentiels et exponentielle de matrice", "description": "Un système X'=AX se résout explicitement grâce à l'exponentielle de matrice, qui généralise la solution scalaire eᵃᵗ au cas vectoriel."}, "stabilite-et-portraits-de-phase": {"title": "Stabilité et portraits de phase", "description": "Un portrait de phase représente graphiquement les trajectoires d'un système différentiel, révélant visuellement la stabilité de ses points d'équilibre (nœuds, foyers, cols)."}, "equations-non-lineaires-bernoulli-riccati": {"title": "Équations non linéaires (Bernoulli, Riccati)", "description": "Certaines équations différentielles non linéaires (Bernoulli, Riccati) se ramènent à des équations linéaires par un changement de variable astucieux."}, "formule-d-inversion-de-bromwich": {"title": "Formule d'inversion de Bromwich", "description": "Cette formule reconstruit une fonction à partir de sa transformée de Laplace via une intégrale de contour dans le plan complexe, quand l'inversion directe par table n'est pas possible."}, "fonction-de-transfert-en-automatique": {"title": "Fonction de transfert en automatique", "description": "En automatique, la fonction de transfert relie la transformée de Laplace de la sortie d'un système à celle de son entrée, résumant tout son comportement dynamique."}, "transformee-de-fourier-discrete-dft-fft": {"title": "Transformée de Fourier discrète (DFT/FFT)", "description": "La version discrète de la transformée de Fourier s'applique à des signaux échantillonnés numériquement, et se calcule efficacement grâce à l'algorithme FFT."}, "distributions-et-transformee-de-dirac": {"title": "Distributions et transformée de Dirac", "description": "La distribution de Dirac δ modélise une impulsion infiniment concentrée ; sa transformée de Fourier est constante, ce qui traduit qu'elle contient toutes les fréquences également."}, "applications-aux-edp-chaleur-ondes": {"title": "Applications aux EDP (chaleur, ondes)", "description": "Les séries de Fourier permettent de résoudre explicitement l'équation de la chaleur et l'équation des ondes sur un intervalle, en décomposant la condition initiale en modes propres."}, "compacite-et-theoreme-de-heine-borel": {"title": "Compacité et théorème de Heine-Borel", "description": "Dans ℝⁿ, un ensemble est compact si et seulement s'il est fermé et borné — un résultat qui simplifie énormément la vérification de la compacité en pratique."}, "connexite-et-connexite-par-arcs": {"title": "Connexité et connexité par arcs", "description": "Un espace est connexe s'il ne peut pas être séparé en deux morceaux disjoints ouverts ; la connexité par arcs, plus forte, exige de pouvoir relier deux points par un chemin continu."}, "theoreme-de-baire": {"title": "Théorème de Baire", "description": "Dans un espace métrique complet, une intersection dénombrable d'ouverts denses reste dense — un résultat abstrait aux conséquences profondes en analyse fonctionnelle."}, "topologie-produit-et-topologie-quotient": {"title": "Topologie produit et topologie quotient", "description": "La topologie produit munit un produit d'espaces d'une structure naturelle ; la topologie quotient définit une topologie sur un ensemble obtenu en « recollant » des points d'un espace initial."}, "espaces-complets-et-theoreme-du-point-fixe": {"title": "Espaces complets et théorème du point fixe", "description": "Un espace complet ne possède aucun « trou » : toute suite de Cauchy y converge, condition essentielle pour garantir l'existence d'un point fixe unique à une contraction."}, "espaces-l-et-inegalite-de-holder": {"title": "Espaces Lᵖ et inégalité de Hölder", "description": "Les espaces Lᵖ regroupent les fonctions dont la puissance p-ième est intégrable ; l'inégalité de Hölder généralise Cauchy-Schwarz pour borner l'intégrale d'un produit de deux fonctions."}, "theoreme-de-radon-nikodym": {"title": "Théorème de Radon-Nikodym", "description": "Ce théorème garantit qu'une mesure « absolument continue » par rapport à une autre peut s'écrire comme une intégrale d'une fonction densité, généralisant la notion de densité de probabilité."}, "mesures-de-probabilite": {"title": "Mesures de probabilité", "description": "Une mesure de probabilité est une mesure au sens de Lebesgue dont la masse totale vaut 1, fondant rigoureusement toute la théorie des probabilités modernes."}, "convergence-presque-partout-vs-en-mesure": {"title": "Convergence presque partout vs en mesure", "description": "Deux notions de convergence de fonctions en théorie de la mesure : l'une exige la convergence en tout point sauf sur un ensemble négligeable, l'autre est plus faible et porte sur la mesure des écarts."}, "integration-sur-des-varietes": {"title": "Intégration sur des variétés", "description": "Intégrer une forme différentielle sur une variété courbe généralise l'intégrale usuelle et permet d'énoncer le théorème de Stokes dans un cadre géométrique très général."}, "operateurs-bornes-et-compacts": {"title": "Opérateurs bornés et compacts", "description": "Un opérateur borné ne peut pas amplifier indéfiniment un vecteur ; un opérateur compact, plus contraint encore, transforme les ensembles bornés en ensembles quasi-finis (précompacts)."}, "theoreme-spectral-pour-operateurs-auto-adjoints": {"title": "Théorème spectral pour opérateurs auto-adjoints", "description": "Un opérateur auto-adjoint sur un espace de Hilbert se diagonalise dans une base orthonormée de vecteurs propres, généralisant le théorème spectral matriciel à la dimension infinie."}, "espaces-de-sobolev": {"title": "Espaces de Sobolev", "description": "Ces espaces mesurent la régularité d'une fonction en contrôlant à la fois sa valeur et ses dérivées, au sens des distributions, un outil clé pour les EDP."}, "classification-des-singularites-poles-essentielles": {"title": "Classification des singularités (pôles, essentielles)", "description": "Une fonction holomorphe peut avoir des points où elle explose (pôles) ou se comporte de façon totalement imprévisible (singularités essentielles) ; cette classification guide le calcul des résidus."}, "theoreme-de-rouche": {"title": "Théorème de Rouché", "description": "Ce théorème compare le nombre de zéros de deux fonctions holomorphes proches l'une de l'autre sur un contour, un outil puissant pour localiser des racines."}, "injections-de-sobolev": {"title": "Injections de Sobolev", "description": "Ces théorèmes garantissent qu'une fonction suffisamment régulière au sens de Sobolev (dérivées contrôlées) l'est aussi au sens classique, un pont essentiel entre les deux notions de régularité."}, "formulation-faible-des-edp": {"title": "Formulation faible des EDP", "description": "Réécrire une équation aux dérivées partielles sous forme « faible » (intégrale, testée contre des fonctions quelconques) permet de définir des solutions même quand la solution classique n'existe pas."}, "convolution-de-distributions": {"title": "Convolution de distributions", "description": "La convolution combine deux distributions pour en produire une nouvelle, généralisant le filtrage de signaux et la résolution d'équations différentielles par fonction de Green."}, "transformee-de-fourier-des-distributions": {"title": "Transformée de Fourier des distributions", "description": "La transformée de Fourier s'étend aux distributions tempérées, ce qui permet de transformer des objets comme le Dirac ou des fonctions non intégrables."}, "applications-aux-elements-finis": {"title": "Applications aux éléments finis", "description": "La formulation faible d'une EDP, écrite via des distributions, est la base théorique de la méthode des éléments finis utilisée en simulation numérique (structures, fluides)."}, "separation-des-variables": {"title": "Séparation des variables", "description": "Cette technique de résolution des EDP cherche une solution sous forme de produit de fonctions d'une seule variable chacune, transformant l'EDP en plusieurs équations différentielles ordinaires."}, "fonction-de-green": {"title": "Fonction de Green", "description": "La fonction de Green d'une équation différentielle ou aux dérivées partielles donne la réponse du système à une impulsion ponctuelle, permettant de reconstruire la solution générale par superposition."}, "formulation-variationnelle-et-elements-finis": {"title": "Formulation variationnelle et éléments finis", "description": "La formulation variationnelle transforme une EDP en un problème d'optimisation, base théorique de la méthode des éléments finis utilisée en simulation d'ingénierie."}, "equations-de-navier-stokes": {"title": "Équations de Navier-Stokes", "description": "Ces équations, généralisant la loi de Newton à un fluide continu et visqueux, régissent tous les écoulements de fluides ; leur résolution générale reste un problème ouvert majeur."}, "methode-des-caracteristiques": {"title": "Méthode des caractéristiques", "description": "Cette méthode résout certaines EDP du premier ordre en suivant des courbes (les caractéristiques) le long desquelles l'équation se ramène à une simple équation différentielle ordinaire."}, "principe-de-moindre-action-en-physique": {"title": "Principe de moindre action en physique", "description": "Ce principe variationnel postule que la trajectoire réellement suivie par un système physique est celle qui minimise (ou rend stationnaire) une quantité appelée action."}, "multiplicateurs-de-lagrange": {"title": "Multiplicateurs de Lagrange", "description": "Cette méthode trouve les extrema d'une fonction sous une contrainte d'égalité en cherchant les points où le gradient de la fonction est proportionnel à celui de la contrainte."}, "dualite-de-fenchel-rockafellar": {"title": "Dualité de Fenchel-Rockafellar", "description": "Cette dualité associe à un problème d'optimisation convexe un problème « dual » souvent plus facile à résoudre, via la transformée de Legendre-Fenchel."}, "methode-directe-du-calcul-des-variations": {"title": "Méthode directe du calcul des variations", "description": "Cette méthode prouve l'existence d'un minimiseur d'une fonctionnelle en exploitant la compacité et la semi-continuité, sans avoir besoin de le calculer explicitement."}, "formule-des-complements-et-prolongement-de": {"title": "Formule des compléments et prolongement de Γ", "description": "La formule des compléments Γ(s)Γ(1-s)=π/sin(πs) relie la fonction Gamma en des points symétriques et permet de la prolonger au-delà de son domaine de définition initial."}, "equation-fonctionnelle-de": {"title": "Équation fonctionnelle de ζ", "description": "La fonction zêta de Riemann vérifie une équation qui relie ses valeurs en s et en 1-s, révélant une symétrie cachée essentielle à l'étude de ses zéros."}, "hypothese-de-riemann": {"title": "Hypothèse de Riemann", "description": "Cette conjecture non résolue affirme que tous les zéros non triviaux de la fonction zêta ont une partie réelle égale à 1/2 ; elle encoderait une information très précise sur la répartition des nombres premiers."}, "fonction-beta-et-lois-de-probabilite": {"title": "Fonction Bêta et lois de probabilité", "description": "La fonction Bêta, liée à la fonction Gamma, sert à définir la loi Bêta utilisée en statistique bayésienne pour modéliser des proportions entre 0 et 1."}, "nombres-de-bernoulli": {"title": "Nombres de Bernoulli", "description": "Ces nombres apparaissent dans le développement en série de nombreuses fonctions (dont la fonction zêta) et dans les formules de sommation de puissances d'entiers."}, "algorithme-d-euclide-etendu": {"title": "Algorithme d'Euclide étendu", "description": "Cette version de l'algorithme d'Euclide calcule non seulement le PGCD de deux nombres, mais aussi les coefficients de Bézout qui l'expriment comme combinaison des deux nombres."}, "theoreme-d-euler-et-indicatrice": {"title": "Théorème d'Euler et indicatrice φ", "description": "Le théorème d'Euler généralise le petit théorème de Fermat : a^φ(n)≡1 (mod n) si a est premier avec n, où φ(n) compte les entiers premiers avec n."}, "tests-de-primalite": {"title": "Tests de primalité", "description": "Ces algorithmes déterminent si un grand nombre est premier, souvent sans le factoriser explicitement, un ingrédient essentiel pour générer les clés utilisées en cryptographie RSA."}, "morphismes-et-isomorphismes": {"title": "Morphismes et isomorphismes", "description": "Un morphisme est une application qui respecte la structure algébrique (groupe, anneau...) ; un isomorphisme est un morphisme bijectif, signifiant que deux structures sont « identiques » à un renommage près."}, "groupes-quotients-et-theoremes-d-isomorphisme": {"title": "Groupes quotients et théorèmes d'isomorphisme", "description": "Un groupe quotient G/H « efface » les différences internes à un sous-groupe distingué H ; les théorèmes d'isomorphisme relient systématiquement quotients et morphismes."}, "extensions-de-corps": {"title": "Extensions de corps", "description": "Une extension de corps L/K est un corps L qui contient un plus petit corps K, permettant par exemple d'ajouter les racines d'un polynôme sans solution dans K."}, "classification-des-structures-finies": {"title": "Classification des structures finies", "description": "L'algèbre abstraite cherche à classifier entièrement certaines structures finies (groupes abéliens, corps finis), révélant qu'elles sont toutes construites à partir de briques élémentaires connues."}, "lemme-des-noyaux": {"title": "Lemme des noyaux", "description": "Ce lemme décompose l'espace vectoriel en somme directe de sous-espaces stables, à partir d'une factorisation du polynôme annulateur d'un endomorphisme — une étape clé vers la réduction de Jordan."}, "trigonalisation": {"title": "Trigonalisation", "description": "Quand une matrice n'est pas diagonalisable, on peut souvent la trigonaliser (la rendre triangulaire) dans une base bien choisie, ce qui simplifie déjà beaucoup les calculs."}, "reduction-de-jordan-pour-matrices-non-diagonalisables": {"title": "Réduction de Jordan pour matrices non diagonalisables", "description": "Les blocs de Jordan capturent précisément le défaut de diagonalisabilité d'une matrice, lié à la différence entre multiplicités algébrique et géométrique de ses valeurs propres."}, "polynome-minimal": {"title": "Polynôme minimal", "description": "Le polynôme minimal d'une matrice est le polynôme unitaire de plus petit degré qui l'annule ; il divise toujours le polynôme caractéristique et détermine sa diagonalisabilité."}, "espaces-hermitiens-cas-complexe": {"title": "Espaces hermitiens (cas complexe)", "description": "Un espace hermitien généralise l'espace euclidien aux nombres complexes, avec un produit scalaire qui vérifie une symétrie « conjuguée » plutôt qu'une symétrie simple."}, "decomposition-qr": {"title": "Décomposition QR", "description": "Toute matrice se décompose en un produit d'une matrice orthogonale Q et d'une matrice triangulaire R, technique numérique stable très utilisée pour résoudre des systèmes linéaires."}, "correspondance-de-galois": {"title": "Correspondance de Galois", "description": "Ce théorème central établit une bijection exacte entre les sous-groupes du groupe de Galois d'une extension et les corps intermédiaires de cette extension."}, "groupes-resolubles": {"title": "Groupes résolubles", "description": "Un groupe résoluble peut être décomposé en une suite de groupes abéliens ; le théorème d'Abel-Ruffini montre qu'une équation est résoluble par radicaux exactement quand son groupe de Galois est résoluble."}, "constructions-a-la-regle-et-au-compas": {"title": "Constructions à la règle et au compas", "description": "La théorie de Galois prouve que certaines constructions géométriques classiques (trisection de l'angle, duplication du cube) sont impossibles à la règle et au compas."}, "extensions-separables-et-normales": {"title": "Extensions séparables et normales", "description": "Une extension séparable n'a pas de racines multiples problématiques ; une extension normale contient toutes les racines de ses polynômes minimaux — deux conditions requises pour une extension galoisienne."}, "applications-a-la-theorie-des-codes": {"title": "Applications à la théorie des codes", "description": "Les corps finis et la théorie de Galois fournissent le cadre mathématique des codes correcteurs d'erreurs modernes (Reed-Solomon, codes BCH)."}, "modules-libres-et-de-type-fini": {"title": "Modules libres et de type fini", "description": "Un module libre possède une base comme un espace vectoriel ; un module de type fini est engendré par un nombre fini d'éléments, sans nécessairement avoir de base."}, "foncteurs-ext-et-tor": {"title": "Foncteurs Ext et Tor", "description": "Ces outils de l'algèbre homologique mesurent le défaut d'exactitude de certaines opérations sur les modules, révélant une information algébrique invisible autrement."}, "suites-exactes-courtes-et-longues": {"title": "Suites exactes courtes et longues", "description": "Une suite exacte encode précisément comment des modules ou groupes s'emboîtent les uns dans les autres, un langage central de l'algèbre homologique."}, "modules-projectifs-et-injectifs": {"title": "Modules projectifs et injectifs", "description": "Ces modules ont des propriétés qui facilitent le prolongement ou la factorisation de morphismes, jouant un rôle clé en algèbre homologique."}, "applications-a-la-reduction-de-jordan": {"title": "Applications à la réduction de Jordan", "description": "Le théorème de structure des modules explique pourquoi toute matrice, même non diagonalisable, admet une forme de Jordan canonique presque diagonale."}, "lemme-de-schur": {"title": "Lemme de Schur", "description": "Ce lemme dit qu'un morphisme entre deux représentations irréductibles d'un groupe est soit nul, soit un isomorphisme — un résultat simple mais extrêmement structurant en théorie des représentations."}, "table-de-caracteres": {"title": "Table de caractères", "description": "Une table de caractères résume toute l'information sur les représentations irréductibles d'un groupe fini en un tableau de nombres, outil central de la théorie des représentations."}, "relations-d-orthogonalite-des-caracteres": {"title": "Relations d'orthogonalité des caractères", "description": "Les caractères des représentations irréductibles d'un groupe fini vérifient des relations d'orthogonalité précises, un outil puissant pour décomposer n'importe quelle représentation."}, "representations-induites": {"title": "Représentations induites", "description": "Une représentation induite construit une représentation d'un groupe entier à partir d'une représentation connue d'un de ses sous-groupes, une technique centrale de la théorie des représentations."}, "applications-a-la-physique-des-particules": {"title": "Applications à la physique des particules", "description": "Les représentations de groupes classifient les particules élémentaires selon leurs symétries, fondement théorique du Modèle Standard de la physique des particules."}, "reduction-simultanee-de-deux-formes": {"title": "Réduction simultanée de deux formes", "description": "Sous certaines conditions, deux formes quadratiques peuvent être diagonalisées dans une même base, une technique utilisée en mécanique (modes propres couplés) et en statistique."}, "formes-definies-positives-et-convexite": {"title": "Formes définies positives et convexité", "description": "Une forme quadratique définie positive ne s'annule qu'en zéro et reste toujours positive ailleurs ; c'est exactement la condition qui caractérise un minimum local strict."}, "theoreme-de-witt": {"title": "Théorème de Witt", "description": "Ce théorème garantit que deux plongements isométriques d'un même espace quadratique dans un plus grand espace peuvent toujours être reliés par une isométrie de l'espace entier."}, "applications-aux-statistiques-multivariees": {"title": "Applications aux statistiques multivariées", "description": "Les formes quadratiques et les matrices de covariance sont l'outil algébrique central de la statistique multivariée, notamment pour l'analyse en composantes principales."}, "groupes-orthogonaux-et-symplectiques": {"title": "Groupes orthogonaux et symplectiques", "description": "Le groupe orthogonal préserve un produit scalaire (rotations, réflexions) ; le groupe symplectique préserve une structure symplectique, essentielle en mécanique hamiltonienne."}, "algebre-exterieure-et-formes-differentielles": {"title": "Algèbre extérieure et formes différentielles", "description": "L'algèbre extérieure construit des objets antisymétriques (formes différentielles) essentiels pour généraliser l'intégration et énoncer le théorème de Stokes sur des variétés."}, "algebre-symetrique": {"title": "Algèbre symétrique", "description": "L'algèbre symétrique construit, à partir d'un espace vectoriel, l'espace de tous les polynômes possibles sur cet espace, complémentaire de l'algèbre extérieure (antisymétrique)."}, "tenseurs-en-physique-contraintes-courbure": {"title": "Tenseurs en physique (contraintes, courbure)", "description": "Les tenseurs décrivent des grandeurs physiques qui dépendent de plusieurs directions à la fois, comme les contraintes en mécanique des matériaux ou la courbure en relativité générale."}, "produit-tensoriel-en-informatique-quantique": {"title": "Produit tensoriel en informatique quantique", "description": "Le produit tensoriel combine les espaces d'états de plusieurs qubits en un seul espace, permettant de décrire mathématiquement l'intrication quantique."}, "tenseurs-et-apprentissage-profond": {"title": "Tenseurs et apprentissage profond", "description": "Les réseaux de neurones manipulent des données organisées en tenseurs (généralisations multidimensionnelles des matrices), d'où le nom des bibliothèques comme TensorFlow."}, "polynomes-cyclotomiques": {"title": "Polynômes cyclotomiques", "description": "Le n-ième polynôme cyclotomique a pour racines exactement les racines primitives n-ièmes de l'unité ; ces polynômes structurent l'étude des extensions cyclotomiques."}, "codes-correcteurs-reed-solomon": {"title": "Codes correcteurs (Reed-Solomon)", "description": "Ces codes, construits à partir de polynômes sur un corps fini, corrigent efficacement les erreurs de transmission et sont utilisés dans les CD, QR codes et sondes spatiales."}, "courbes-elliptiques-sur-corps-finis": {"title": "Courbes elliptiques sur corps finis", "description": "Restreindre une courbe elliptique à un corps fini produit un groupe abélien fini, exploité en cryptographie pour offrir une sécurité élevée avec des clés courtes."}, "theorie-de-galois-des-corps-finis": {"title": "Théorie de Galois des corps finis", "description": "La théorie de Galois appliquée aux corps finis explique complètement leurs extensions, toutes cycliques, une structure remarquablement simple comparée au cas général."}, "applications-a-la-cryptographie-moderne": {"title": "Applications à la cryptographie moderne", "description": "La théorie des nombres (nombres premiers, arithmétique modulaire) fournit les fondations mathématiques de tous les protocoles cryptographiques utilisés aujourd'hui."}, "ideaux-premiers-et-maximaux": {"title": "Idéaux premiers et maximaux", "description": "Un idéal premier généralise la notion de nombre premier aux anneaux ; un idéal maximal produit, par quotient, un corps — la structure la plus riche possible."}, "bases-de-grobner": {"title": "Bases de Gröbner", "description": "Une base de Gröbner transforme un système d'équations polynomiales en une forme équivalente mais beaucoup plus facile à résoudre algorithmiquement, un outil clé du calcul formel."}, "varietes-affines-et-projectives": {"title": "Variétés affines et projectives", "description": "Une variété affine est définie par des équations polynomiales dans l'espace usuel ; une variété projective l'étend en ajoutant des points à l'infini, simplifiant certains théorèmes."}, "applications-a-la-cryptographie-sur-courbes": {"title": "Applications à la cryptographie sur courbes", "description": "Les courbes elliptiques offrent une sécurité cryptographique équivalente à RSA avec des clés beaucoup plus courtes, ce qui les rend très utilisées (Bitcoin, TLS moderne)."}, "classification-de-cartan-killing": {"title": "Classification de Cartan-Killing", "description": "Cette classification répertorie complètement toutes les algèbres de Lie simples possibles en quelques familles infinies et cinq cas exceptionnels — un résultat d'une grande élégance."}, "representations-des-algebres-de-lie": {"title": "Représentations des algèbres de Lie", "description": "Représenter une algèbre de Lie par des matrices permet d'étudier concrètement les symétries continues qu'elle décrit, essentiel en physique des particules."}, "groupes-de-lie-compacts": {"title": "Groupes de Lie compacts", "description": "Un groupe de Lie compact (comme les rotations SO(n)) a une structure topologique « bornée » qui simplifie considérablement sa théorie des représentations."}, "groupes-de-jauge-et-interactions-fondamentales": {"title": "Groupes de jauge et interactions fondamentales", "description": "Les interactions fondamentales de la physique (électromagnétique, faible, forte) sont décrites par des groupes de jauge spécifiques, dont la structure détermine les particules et forces observées."}, "fonctions-arithmetiques-mobius": {"title": "Fonctions arithmétiques (φ, Möbius)", "description": "Ces fonctions définies sur les entiers (indicatrice d'Euler, fonction de Möbius) encodent des propriétés de divisibilité et interviennent dans de nombreuses formules de théorie des nombres."}, "series-de-dirichlet": {"title": "Séries de Dirichlet", "description": "Une série de Dirichlet Σaₙ/nˢ généralise la fonction zêta et encode des informations arithmétiques profondes sur la fonction aₙ qui la définit."}, "theoreme-des-nombres-premiers": {"title": "Théorème des nombres premiers", "description": "Ce théorème donne l'estimation asymptotique π(x)~x/ln(x) du nombre de nombres premiers inférieurs à x, montrant qu'ils se raréfient progressivement mais restent infinis."}, "applications-a-la-cryptographie": {"title": "Applications à la cryptographie", "description": "Les structures algébriques (groupes, corps finis) fournissent les problèmes difficiles (factorisation, logarithme discret) sur lesquels repose la sécurité de la cryptographie moderne."}, "cryptographie-sur-courbes-elliptiques-ecc": {"title": "Cryptographie sur courbes elliptiques (ECC)", "description": "ECC est aujourd'hui privilégiée à RSA dans de nombreux protocoles (TLS, Bitcoin) car elle offre une sécurité équivalente avec des clés bien plus courtes, donc plus rapides."}, "protocole-de-diffie-hellman": {"title": "Protocole de Diffie-Hellman", "description": "Ce protocole permet à deux personnes de créer une clé secrète commune en échangeant seulement des informations publiques, exploitant la difficulté du logarithme discret."}, "fonctions-a-sens-unique-et-preuves-de-connaissance": {"title": "Fonctions à sens unique et preuves de connaissance", "description": "Une fonction à sens unique est facile à calculer mais très difficile à inverser ; elle fonde à la fois le chiffrement et les preuves à divulgation nulle de connaissance."}, "attaques-par-factorisation-et-algorithme-de-shor": {"title": "Attaques par factorisation et algorithme de Shor", "description": "L'algorithme quantique de Shor factoriserait efficacement de grands nombres, ce qui casserait RSA — une menace majeure motivant le développement de la cryptographie post-quantique."}, "torsion-et-courbes-gauches": {"title": "Torsion et courbes gauches", "description": "La torsion mesure à quel point une courbe de l'espace s'écarte d'être plane, complétant la courbure pour décrire complètement une courbe gauche (non plane)."}, "longueur-d-arc-et-parametrisation-naturelle": {"title": "Longueur d'arc et paramétrisation naturelle", "description": "Paramétrer une courbe par sa longueur d'arc (plutôt que par le temps) simplifie considérablement le calcul de sa courbure et de son repère de Frenet."}, "courbure-et-rayon-osculateur": {"title": "Courbure et rayon osculateur", "description": "Le rayon osculateur est le rayon du cercle qui épouse le mieux la courbe en un point ; il vaut l'inverse de la courbure en ce point."}, "courbes-de-bezier-cao": {"title": "Courbes de Bézier (CAO)", "description": "Ces courbes, définies par des points de contrôle, sont l'outil standard du dessin vectoriel et de la CAO pour créer des formes lisses et modifiables."}, "geodesiques-sur-une-surface": {"title": "Géodésiques sur une surface", "description": "Sur une surface quelconque, les géodésiques généralisent les droites du plan et jouent un rôle clé en relativité générale (trajectoires des objets en chute libre)."}, "courbures-principales-et-courbure-moyenne": {"title": "Courbures principales et courbure moyenne", "description": "En chaque point d'une surface, deux courbures extrêmes (principales) résument sa forme locale ; leur moyenne donne la courbure moyenne, liée aux surfaces minimales."}, "geodesiques-plus-courts-chemins-sur-une-surface": {"title": "Géodésiques (plus courts chemins sur une surface)", "description": "Une géodésique est le chemin le plus court entre deux points sur une surface courbe, généralisant la ligne droite du plan à un cadre courbe."}, "formule-de-gauss-bonnet": {"title": "Formule de Gauss-Bonnet", "description": "Cette formule relie de façon spectaculaire la courbure totale d'une surface à sa topologie (son genre), reliant géométrie locale et forme globale."}, "surfaces-minimales": {"title": "Surfaces minimales", "description": "Une surface minimale (comme un film de savon tendu sur un contour) minimise localement son aire, avec une courbure moyenne nulle en tout point."}, "espace-tangent-et-fibre-tangent": {"title": "Espace tangent et fibré tangent", "description": "L'espace tangent en un point d'une variété regroupe toutes les directions de déplacement possibles ; le fibré tangent les recolle en une seule structure sur toute la variété."}, "formes-differentielles": {"title": "Formes différentielles", "description": "Une forme différentielle généralise la notion de fonction à intégrer sur des courbes, surfaces ou volumes, unifiant tous les théorèmes classiques d'analyse vectorielle."}, "theoreme-de-stokes-generalise": {"title": "Théorème de Stokes généralisé", "description": "Ce théorème unifie tous les grands théorèmes de l'analyse vectorielle (Green, divergence, rotationnel) en une seule formule reliant une forme différentielle à son intégrale sur le bord."}, "varietes-riemanniennes": {"title": "Variétés riemanniennes", "description": "Une variété riemannienne est un espace courbe muni d'une métrique qui permet d'y mesurer distances et angles, le cadre mathématique de la relativité générale."}, "homologie-et-cohomologie": {"title": "Homologie et cohomologie", "description": "Ces théories associent à un espace topologique des groupes algébriques qui détectent ses « trous » de différentes dimensions, un des outils les plus puissants de la topologie."}, "theoreme-de-van-kampen": {"title": "Théorème de van Kampen", "description": "Ce théorème calcule le groupe fondamental d'un espace complexe en le décomposant en morceaux plus simples dont on connaît déjà les groupes fondamentaux."}, "classification-des-surfaces": {"title": "Classification des surfaces", "description": "Toute surface compacte se classe entièrement selon son genre (nombre de « trous ») et son orientabilité, un résultat fondamental de la topologie des surfaces."}, "theorie-des-n-uds": {"title": "Théorie des nœuds", "description": "Cette branche de la topologie étudie comment une boucle peut être enchevêtrée dans l'espace, avec des applications en biologie moléculaire (structure de l'ADN)."}, "applications-a-l-analyse-topologique-des-donnees": {"title": "Applications à l'analyse topologique des données", "description": "La topologie algébrique permet de détecter automatiquement des « trous » ou des structures cachées dans des jeux de données complexes à haute dimension."}, "courbure-de-ricci-et-courbure-scalaire": {"title": "Courbure de Ricci et courbure scalaire", "description": "La courbure de Ricci moyenne la courbure de Riemann dans toutes les directions ; la courbure scalaire la résume encore en un seul nombre par point."}, "geodesiques-et-equation-de-la-geodesique": {"title": "Géodésiques et équation de la géodésique", "description": "L'équation de la géodésique décrit précisément comment un chemin doit se courber pour rester localement le plus court possible sur une variété donnée."}, "theoreme-de-gauss-bonnet-generalise": {"title": "Théorème de Gauss-Bonnet généralisé", "description": "Cette version étendue relie la courbure totale d'une variété de dimension quelconque à sa caractéristique d'Euler, généralisant le résultat classique des surfaces."}, "flot-de-ricci-et-theoreme-de-perelman": {"title": "Flot de Ricci et théorème de Perelman", "description": "Le flot de Ricci fait évoluer une métrique pour lisser progressivement la courbure ; Perelman l'a utilisé pour démontrer la célèbre conjecture de Poincaré."}, "equations-de-hamilton": {"title": "Équations de Hamilton", "description": "Ces équations décrivent l'évolution d'un système physique dans l'espace des phases (position et impulsion), formulation équivalente mais souvent plus puissante que celle de Newton."}, "systemes-integrables-arnold-liouville": {"title": "Systèmes intégrables (Arnold-Liouville)", "description": "Un système hamiltonien intégrable possède suffisamment de quantités conservées pour être résolu explicitement, un cas particulièrement structuré de la mécanique classique."}, "quantification-geometrique": {"title": "Quantification géométrique", "description": "Cette approche construit la mécanique quantique à partir de la géométrie symplectique de la mécanique classique, en « quantifiant » l'espace des phases."}, "diviseurs-et-fonctions-rationnelles-sur-une-courbe": {"title": "Diviseurs et fonctions rationnelles sur une courbe", "description": "Un diviseur encode formellement les zéros et pôles d'une fonction sur une courbe algébrique, un outil central de la géométrie algébrique."}, "genre-d-une-courbe-algebrique": {"title": "Genre d'une courbe algébrique", "description": "Le genre d'une courbe algébrique compte, intuitivement, son nombre de « trous » (comme un tore) ; il détermine profondément ses propriétés arithmétiques et géométriques."}, "surfaces-de-riemann": {"title": "Surfaces de Riemann", "description": "Une surface de Riemann est une variété complexe de dimension 1, le cadre naturel pour étendre l'analyse complexe à des fonctions multiformes (comme le logarithme complexe)."}, "courbes-elliptiques-et-cryptographie": {"title": "Courbes elliptiques et cryptographie", "description": "Les points d'une courbe elliptique forment un groupe dont l'arithmétique fonde une cryptographie très sûre avec des clés bien plus courtes que RSA."}, "varietes-projectives": {"title": "Variétés projectives", "description": "Une variété projective généralise la variété affine en travaillant dans l'espace projectif (avec points à l'infini), ce qui simplifie souvent l'énoncé des théorèmes de géométrie algébrique."}, "theoremes-de-pascal-et-desargues": {"title": "Théorèmes de Pascal et Desargues", "description": "Ces théorèmes classiques de géométrie projective énoncent des propriétés d'alignement remarquables pour des configurations de coniques et de triangles."}, "dualite-projective": {"title": "Dualité projective", "description": "En géométrie projective, points et droites jouent des rôles parfaitement symétriques : tout théorème sur les points a un analogue obtenu en échangeant points et droites."}, "birapport-invariant-projectif": {"title": "Birapport (invariant projectif)", "description": "Le birapport de quatre points alignés est une quantité qui reste invariante sous toute transformation projective, un outil clé de la géométrie projective."}, "coniques-projectives": {"title": "Coniques projectives", "description": "En géométrie projective, toutes les coniques (cercle, ellipse, parabole, hyperbole) deviennent équivalentes, la distinction usuelle disparaissant dans ce cadre plus général."}, "applications-a-la-vision-par-ordinateur": {"title": "Applications à la vision par ordinateur", "description": "La géométrie projective modélise mathématiquement la perspective d'une photo, fondement de la reconstruction 3D à partir d'images en vision par ordinateur."}, "cohomologie-de-de-rham": {"title": "Cohomologie de de Rham", "description": "Cette théorie mesure, via les formes différentielles, les « trous » topologiques d'une variété par des méthodes purement analytiques, reliant analyse et topologie."}, "formes-harmoniques": {"title": "Formes harmoniques", "description": "Une forme harmonique minimise une énergie associée et représente, dans la décomposition de Hodge, la partie topologiquement essentielle d'une forme différentielle."}, "structures-kahleriennes": {"title": "Structures kählériennes", "description": "Une structure kählérienne combine harmonieusement géométrie complexe, riemannienne et symplectique sur une même variété, un cadre très riche utilisé en théorie des cordes."}, "varietes-de-calabi-yau": {"title": "Variétés de Calabi-Yau", "description": "Ces variétés complexes très particulières, à courbure de Ricci nulle, jouent un rôle central en théorie des cordes pour décrire les dimensions cachées de l'espace-temps."}, "applications-a-la-theorie-des-cordes": {"title": "Applications à la théorie des cordes", "description": "La théorie de Hodge et les variétés de Calabi-Yau interviennent dans la théorie des cordes pour décrire les dimensions supplémentaires compactifiées de l'espace-temps."}, "modeles-de-la-geometrie-hyperbolique": {"title": "Modèles de la géométrie hyperbolique", "description": "Plusieurs modèles équivalents (disque de Poincaré, demi-plan de Poincaré, hyperboloïde) représentent la même géométrie hyperbolique sous des formes visuelles différentes."}, "groupes-hyperboliques": {"title": "Groupes hyperboliques", "description": "Un groupe hyperbolique, au sens de la géométrie des groupes, a une croissance et des propriétés géométriques analogues à celles de l'espace hyperbolique."}, "bord-a-l-infini": {"title": "Bord à l'infini", "description": "Un espace hyperbolique possède un « bord à l'infini » qui encode son comportement asymptotique, un concept essentiel en théorie géométrique des groupes."}, "applications-aux-reseaux-hierarchiques-ia": {"title": "Applications aux réseaux hiérarchiques (IA)", "description": "La géométrie hyperbolique représente naturellement des données arborescentes ou hiérarchiques (réseaux sociaux, taxonomies) avec beaucoup moins de distorsion que la géométrie euclidienne."}, "pavages-hyperboliques-escher": {"title": "Pavages hyperboliques (Escher)", "description": "Dans le plan hyperbolique, on peut paver l'espace avec des polygones réguliers selon des combinaisons impossibles en géométrie euclidienne, popularisées par les œuvres d'Escher."}, "fibres-principaux": {"title": "Fibrés principaux", "description": "Un fibré principal généralise le fibré vectoriel en attachant un groupe (plutôt qu'un espace vectoriel) à chaque point, le cadre géométrique des théories de jauge."}, "theorie-de-jauge-en-physique": {"title": "Théorie de jauge en physique", "description": "Les théories de jauge décrivent les interactions fondamentales comme des connexions sur des fibrés, un cadre géométrique unifiant électromagnétisme et forces nucléaires."}, "classes-caracteristiques-chern-stiefel-whitney": {"title": "Classes caractéristiques (Chern, Stiefel-Whitney)", "description": "Ces invariants topologiques résument la « torsion » globale d'un fibré vectoriel, révélant des propriétés géométriques invisibles localement."}, "k-theorie-topologique": {"title": "K-théorie topologique", "description": "Cette théorie classifie les fibrés vectoriels sur un espace via des groupes algébriques, avec des applications profondes en topologie et en physique théorique."}, "applications-aux-interactions-fondamentales": {"title": "Applications aux interactions fondamentales", "description": "Les fibrés et leurs connexions fournissent le langage géométrique des théories de jauge qui décrivent les interactions fondamentales de la physique des particules."}, "dualite-de-kantorovich": {"title": "Dualité de Kantorovich", "description": "Cette dualité réécrit le problème de transport optimal (déplacer une masse au coût minimal) sous une forme équivalente souvent plus facile à résoudre."}, "theoreme-de-brenier": {"title": "Théorème de Brenier", "description": "Ce théorème garantit l'existence et l'unicité d'une solution optimale au problème de transport quadratique, sous la forme du gradient d'une fonction convexe."}, "inegalite-de-brunn-minkowski": {"title": "Inégalité de Brunn-Minkowski", "description": "Cette inégalité géométrique compare le volume de la somme de deux ensembles à leurs volumes individuels, avec de profondes conséquences en optimisation et probabilité."}, "geometrie-de-l-information": {"title": "Géométrie de l'information", "description": "Cette discipline applique les outils de la géométrie riemannienne à l'espace des distributions de probabilité, pour mesurer des « distances » entre modèles statistiques."}, "lois-usuelles-continues-uniforme-exponentielle-normale": {"title": "Lois usuelles continues (uniforme, exponentielle, normale)", "description": "Ces lois continues modélisent respectivement un tirage sans préférence, un temps d'attente sans mémoire, et des mesures dispersées symétriquement autour d'une moyenne."}, "changement-de-variable-et-theoreme-de-transfert": {"title": "Changement de variable et théorème de transfert", "description": "Le théorème de transfert calcule l'espérance d'une fonction d'une variable aléatoire sans devoir déterminer explicitement sa nouvelle loi de probabilité."}, "densites-conjointes": {"title": "Densités conjointes", "description": "La densité conjointe de plusieurs variables aléatoires continues décrit leur comportement simultané, dont on peut extraire les lois marginales et conditionnelles par intégration."}, "lien-avec-l-integrale-de-lebesgue": {"title": "Lien avec l'intégrale de Lebesgue", "description": "Les probabilités modernes se fondent rigoureusement sur la théorie de la mesure de Lebesgue, ce qui permet de traiter uniformément variables discrètes et continues."}, "vitesse-de-convergence-theoreme-de-berry-esseen": {"title": "Vitesse de convergence (théorème de Berry-Esseen)", "description": "Ce théorème précise à quelle vitesse la convergence du théorème central limite se produit, en fonction de la taille de l'échantillon."}, "applications-aux-sondages-et-intervalles-de-confiance": {"title": "Applications aux sondages et intervalles de confiance", "description": "Le théorème central limite justifie qu'un sondage sur un échantillon limité permette d'estimer une opinion nationale avec une marge d'erreur calculable."}, "grandes-deviations-au-dela-du-tcl": {"title": "Grandes déviations (au-delà du TCL)", "description": "Alors que le théorème central limite décrit les fluctuations typiques, la théorie des grandes déviations quantifie la rareté des écarts exceptionnels à la moyenne."}, "tcl-pour-variables-dependantes": {"title": "TCL pour variables dépendantes", "description": "Le théorème central limite s'étend, sous certaines conditions de dépendance faible, à des variables aléatoires qui ne sont pas totalement indépendantes."}, "etats-recurrents-et-transitoires": {"title": "États récurrents et transitoires", "description": "Dans une chaîne de Markov, un état récurrent est visité une infinité de fois presque sûrement ; un état transitoire n'est visité qu'un nombre fini de fois."}, "applications-au-pagerank-et-a-la-generation-de-texte": {"title": "Applications au PageRank et à la génération de texte", "description": "L'algorithme PageRank de Google modélise le web comme une chaîne de Markov géante, où l'importance d'une page est sa probabilité stationnaire d'être visitée."}, "theoreme-de-convergence-des-martingales": {"title": "Théorème de convergence des martingales", "description": "Sous des conditions raisonnables, une martingale bornée converge presque sûrement vers une limite, un résultat puissant aux nombreuses applications théoriques."}, "temps-d-arret-et-strategies-optimales": {"title": "Temps d'arrêt et stratégies optimales", "description": "Un temps d'arrêt décide d'interrompre un processus aléatoire en se basant uniquement sur l'information disponible jusqu'à cet instant, sans connaître le futur."}, "decomposition-de-doob": {"title": "Décomposition de Doob", "description": "Cette décomposition sépare un processus stochastique en une martingale (partie imprévisible) et un processus prévisible, isolant la tendance de l'aléa pur."}, "martingales-en-finance-absence-d-arbitrage": {"title": "Martingales en finance (absence d'arbitrage)", "description": "Sous la mesure risque-neutre, le prix actualisé d'un actif financier est une martingale, ce qui traduit mathématiquement l'absence d'opportunité d'arbitrage sur le marché."}, "inegalite-de-doob": {"title": "Inégalité de Doob", "description": "Cette inégalité borne la probabilité qu'une martingale atteigne un niveau élevé à un moment quelconque, un outil clé pour prouver des théorèmes de convergence."}, "calcul-stochastique-integrale-d-ito": {"title": "Calcul stochastique (intégrale d'Itô)", "description": "L'intégrale d'Itô définit rigoureusement l'intégration par rapport au mouvement brownien, malgré la non-dérivabilité de ses trajectoires, fondant tout le calcul stochastique moderne."}, "propriete-de-markov-du-mouvement-brownien": {"title": "Propriété de Markov du mouvement brownien", "description": "Le futur du mouvement brownien ne dépend que de sa position actuelle, pas de tout son passé — une propriété de « mémoire courte » caractéristique des processus de Markov."}, "applications-a-la-finance-black-scholes": {"title": "Applications à la finance (Black-Scholes)", "description": "Le mouvement brownien et le calcul stochastique sont à la base du modèle de Black-Scholes, qui donne un prix théorique aux options financières."}, "processus-d-ornstein-uhlenbeck": {"title": "Processus d'Ornstein-Uhlenbeck", "description": "Ce processus stochastique modélise un phénomène aléatoire qui tend à revenir vers une valeur moyenne, utilisé en finance (taux d'intérêt) et en physique (vitesse d'une particule)."}, "formule-d-ito-multidimensionnelle": {"title": "Formule d'Itô multidimensionnelle", "description": "Cette version généralise la formule d'Itô à plusieurs processus stochastiques couplés, indispensable pour modéliser des systèmes financiers ou physiques à plusieurs facteurs aléatoires."}, "schema-numerique-d-euler-maruyama": {"title": "Schéma numérique d'Euler-Maruyama", "description": "Ce schéma discrétise une équation différentielle stochastique pour la simuler numériquement pas à pas, généralisant la méthode d'Euler classique au cas aléatoire."}, "applications-a-la-finance-quantitative": {"title": "Applications à la finance quantitative", "description": "Les équations différentielles stochastiques modélisent l'évolution incertaine des prix d'actifs financiers, fondement de l'évaluation moderne des produits dérivés."}, "biais-et-convergence-d-un-estimateur": {"title": "Biais et convergence d'un estimateur", "description": "Un estimateur sans biais donne, en moyenne, la vraie valeur du paramètre ; sa convergence garantit que l'estimation s'améliore avec la taille de l'échantillon."}, "statistique-exhaustive": {"title": "Statistique exhaustive", "description": "Une statistique exhaustive résume toute l'information utile d'un échantillon pour estimer un paramètre, sans aucune perte d'information par rapport aux données complètes."}, "intervalles-de-confiance": {"title": "Intervalles de confiance", "description": "Un intervalle de confiance donne une fourchette de valeurs plausibles pour un paramètre inconnu, avec un niveau de certitude choisi (souvent 95%)."}, "estimation-bayesienne": {"title": "Estimation bayésienne", "description": "L'estimation bayésienne combine une connaissance a priori avec les données observées pour produire une estimation actualisée d'un paramètre inconnu, via la formule de Bayes."}, "puissance-d-un-test-et-erreur-de-seconde-espece": {"title": "Puissance d'un test et erreur de seconde espèce", "description": "La puissance d'un test mesure sa capacité à détecter un effet réel quand il existe ; l'erreur de seconde espèce est le risque complémentaire de ne pas le détecter."}, "p-valeur-et-interpretation": {"title": "p-valeur et interprétation", "description": "La p-valeur mesure la probabilité d'observer un résultat au moins aussi extrême que celui obtenu, en supposant l'hypothèse nulle vraie — une notion souvent mal interprétée."}, "tests-parametriques-vs-non-parametriques": {"title": "Tests paramétriques vs non paramétriques", "description": "Un test paramétrique suppose une forme connue pour la loi des données (souvent normale) ; un test non paramétrique s'en affranchit, au prix d'une puissance parfois moindre."}, "tests-multiples-et-correction-bonferroni": {"title": "Tests multiples et correction (Bonferroni)", "description": "Réaliser plusieurs tests statistiques simultanément augmente le risque de faux positifs ; la correction de Bonferroni ajuste le seuil de signification pour compenser ce risque accru."}, "tests-bayesiens": {"title": "Tests bayésiens", "description": "Contrairement aux tests classiques, les tests bayésiens comparent directement les probabilités a posteriori de deux hypothèses concurrentes, sans notion arbitraire de seuil de rejet."}, "fonction-de-taux-et-principe-de-grandes-deviations": {"title": "Fonction de taux et principe de grandes déviations", "description": "La fonction de taux quantifie précisément, de façon exponentielle, la probabilité décroissante d'un écart important à la moyenne, au cœur de la théorie des grandes déviations."}, "inegalites-de-concentration-modernes": {"title": "Inégalités de concentration modernes", "description": "Ces inégalités (Hoeffding, Bernstein) bornent finement la probabilité qu'une somme de variables aléatoires s'écarte de sa moyenne, essentielles en apprentissage automatique statistique."}, "applications-a-la-gestion-du-risque": {"title": "Applications à la gestion du risque", "description": "Les grandes déviations et les mesures de risque quantifient la probabilité et l'ampleur des pertes extrêmes, essentielles en assurance et en régulation bancaire."}, "grandes-deviations-en-physique-statistique": {"title": "Grandes déviations en physique statistique", "description": "Les grandes déviations expliquent pourquoi les fluctuations macroscopiques sont extrêmement rares dans les systèmes physiques comportant un très grand nombre de particules."}, "files-d-attente-modele-m-m-1": {"title": "Files d'attente (modèle M/M/1)", "description": "Ce modèle classique décrit une file d'attente à un seul serveur avec arrivées et services aléatoires, permettant de calculer le temps d'attente moyen d'un client."}, "processus-de-naissance-et-de-mort": {"title": "Processus de naissance et de mort", "description": "Ce modèle décrit l'évolution d'une population dont la taille augmente ou diminue aléatoirement d'une unité à la fois, utilisé en démographie et en files d'attente."}, "theorie-du-renouvellement": {"title": "Théorie du renouvellement", "description": "Cette théorie étudie des processus où un événement se répète à des intervalles aléatoires indépendants, généralisant le processus de Poisson à des lois d'attente quelconques."}, "processus-de-poisson-compose": {"title": "Processus de Poisson composé", "description": "Ce processus additionne des sauts aléatoires (de taille elle-même aléatoire) à des instants suivant un processus de Poisson, modélisant par exemple les sinistres cumulés en assurance."}, "applications-a-la-fiabilite-des-systemes": {"title": "Applications à la fiabilité des systèmes", "description": "La loi exponentielle et les processus de Poisson modélisent les temps de panne d'équipements, permettant de dimensionner la maintenance préventive et les stocks de pièces."}, "modele-binomial-de-cox-ross-rubinstein": {"title": "Modèle binomial de Cox-Ross-Rubinstein", "description": "Ce modèle discret, plus simple que Black-Scholes, évalue le prix d'une option en simulant l'évolution du sous-jacent par une succession de hausses et de baisses."}, "gestion-de-portefeuille-markowitz": {"title": "Gestion de portefeuille (Markowitz)", "description": "Le modèle de Markowitz optimise la répartition d'un portefeuille entre plusieurs actifs pour maximiser le rendement attendu à un niveau de risque donné."}, "mesures-de-risque-var-cvar": {"title": "Mesures de risque (VaR, CVaR)", "description": "La Value at Risk (VaR) estime la perte maximale probable sur un horizon donné ; la CVaR, plus prudente, moyenne les pertes au-delà de ce seuil."}, "options-americaines-et-arret-optimal": {"title": "Options américaines et arrêt optimal", "description": "Contrairement aux options européennes, une option américaine peut être exercée à tout moment, ce qui transforme son évaluation en un problème d'arrêt optimal."}, "modeles-de-taux-d-interet": {"title": "Modèles de taux d'intérêt", "description": "Ces modèles stochastiques (Vasicek, CIR) décrivent l'évolution aléatoire des taux d'intérêt dans le temps, essentiels pour évaluer les obligations et produits de taux."}, "stationnarite-et-differenciation": {"title": "Stationnarité et différenciation", "description": "Une série temporelle stationnaire a des propriétés statistiques stables dans le temps ; la différenciation (soustraire une valeur à la précédente) permet souvent de rendre stationnaire une série qui ne l'est pas."}, "autocorrelation-et-autocorrelation-partielle": {"title": "Autocorrélation et autocorrélation partielle", "description": "L'autocorrélation mesure la dépendance d'une série temporelle avec ses valeurs passées, un outil clé pour identifier la structure d'un modèle ARMA."}, "modeles-garch-volatilite-variable": {"title": "Modèles GARCH (volatilité variable)", "description": "Ces modèles capturent le fait que la volatilité des marchés financiers n'est pas constante mais évolue elle-même dans le temps, avec des périodes calmes et agitées."}, "cointegration-series-liees-a-long-terme": {"title": "Cointégration (séries liées à long terme)", "description": "Deux séries temporelles non stationnaires peuvent néanmoins être cointégrées si une combinaison linéaire d'entre elles est stationnaire, révélant une relation d'équilibre à long terme."}, "prevision-et-intervalles-de-confiance": {"title": "Prévision et intervalles de confiance", "description": "Prévoir une série temporelle nécessite non seulement une valeur centrale, mais aussi un intervalle de confiance qui quantifie l'incertitude croissante à mesure qu'on prévoit plus loin."}, "hamiltonien-et-equations-canoniques": {"title": "Hamiltonien et équations canoniques", "description": "L'hamiltonien, qui représente l'énergie totale d'un système, génère ses équations du mouvement via les équations canoniques de Hamilton, une formulation équivalente à celle de Newton."}, "principe-de-moindre-action": {"title": "Principe de moindre action", "description": "Ce principe fondamental postule que la trajectoire réellement suivie par un système physique est celle qui rend stationnaire une quantité globale appelée action."}, "coordonnees-generalisees": {"title": "Coordonnées généralisées", "description": "En mécanique analytique, les coordonnées généralisées décrivent la configuration d'un système par le plus petit nombre de variables indépendantes possible, adaptées aux contraintes du problème."}, "mecanique-celeste-orbites": {"title": "Mécanique céleste (orbites)", "description": "La mécanique céleste applique les lois de la gravitation pour décrire précisément les orbites des planètes, satellites et sondes spatiales, souvent via la formulation hamiltonienne."}, "fonction-d-onde-et-probabilites": {"title": "Fonction d'onde et probabilités", "description": "En mécanique quantique, le carré du module de la fonction d'onde donne la probabilité de trouver la particule en un endroit donné, non sa position exacte."}, "effet-tunnel": {"title": "Effet tunnel", "description": "En mécanique quantique, une particule peut traverser une barrière d'énergie qu'elle ne pourrait franchir classiquement, un phénomène exploité dans certains composants électroniques."}, "spin-et-particules-identiques": {"title": "Spin et particules identiques", "description": "Le spin est une propriété quantique intrinsèque sans équivalent classique ; il détermine si des particules identiques se comportent comme des fermions ou des bosons."}, "intrication-quantique": {"title": "Intrication quantique", "description": "Deux particules intriquées restent corrélées quelle que soit la distance qui les sépare, un phénomène quantique sans équivalent classique, exploité en cryptographie et informatique quantiques."}, "applications-a-l-informatique-quantique": {"title": "Applications à l'informatique quantique", "description": "L'intrication et la superposition quantiques permettent en principe de résoudre certains problèmes bien plus rapidement qu'un ordinateur classique, fondement de l'informatique quantique."}, "dilatation-du-temps-et-contraction-des-longueurs": {"title": "Dilatation du temps et contraction des longueurs", "description": "En relativité restreinte, le temps s'écoule plus lentement et les longueurs se contractent pour un objet en mouvement rapide, vu depuis un observateur au repos."}, "quadrivecteurs": {"title": "Quadrivecteurs", "description": "En relativité restreinte, un quadrivecteur combine trois composantes spatiales et une temporelle en un seul objet qui se transforme de façon cohérente entre référentiels."}, "equivalence-masse-energie": {"title": "Équivalence masse-énergie", "description": "La relativité restreinte établit que la masse d'un objet est une forme d'énergie « au repos », convertible en d'autres formes d'énergie selon E=mc²."}, "effet-doppler-relativiste": {"title": "Effet Doppler relativiste", "description": "Aux vitesses proches de celle de la lumière, l'effet Doppler doit intégrer la dilatation relativiste du temps en plus du décalage classique de fréquence."}, "geodesiques-et-trajectoires-en-espace-temps-courbe": {"title": "Géodésiques et trajectoires en espace-temps courbe", "description": "En relativité générale, les objets en chute libre suivent des géodésiques de l'espace-temps courbe — la gravité n'est plus une force mais un effet de la géométrie."}, "trous-noirs-et-horizon-des-evenements": {"title": "Trous noirs et horizon des événements", "description": "Un trou noir est une région où la gravité est si intense que rien, pas même la lumière, ne peut s'en échapper au-delà de son horizon des événements."}, "ondes-gravitationnelles": {"title": "Ondes gravitationnelles", "description": "Ces ondulations de l'espace-temps, prédites par Einstein et détectées en 2015, sont produites par des événements cosmiques violents comme la fusion de deux trous noirs."}, "cosmologie-relativiste": {"title": "Cosmologie relativiste", "description": "La cosmologie relativiste applique les équations d'Einstein à l'univers entier, expliquant son expansion, sa géométrie globale et son évolution depuis le Big Bang."}, "potentiels-electromagnetiques-et-jauge-de-lorenz": {"title": "Potentiels électromagnétiques et jauge de Lorenz", "description": "Les potentiels scalaire et vecteur permettent de reformuler les équations de Maxwell plus simplement ; la jauge de Lorenz fixe une contrainte qui les rend manifestement relativistes."}, "rayonnement-d-une-antenne": {"title": "Rayonnement d'une antenne", "description": "Une antenne rayonne de l'énergie électromagnétique selon un motif directionnel précis, déterminé par sa forme et calculé à partir des équations de Maxwell."}, "electromagnetisme-dans-les-milieux-dielectriques-conducteurs": {"title": "Électromagnétisme dans les milieux (diélectriques, conducteurs)", "description": "Les champs électromagnétiques se comportent différemment selon qu'ils traversent un isolant (diélectrique) ou un conducteur, ce qui doit être pris en compte dans les équations de Maxwell."}, "formulation-covariante-relativiste": {"title": "Formulation covariante (relativiste)", "description": "Écrire les lois de l'électromagnétisme sous une forme covariante les rend manifestement compatibles avec la relativité restreinte, indépendamment du référentiel choisi."}, "metamateriaux-et-applications": {"title": "Métamatériaux et applications", "description": "Ces matériaux artificiels, structurés à une échelle inférieure à la longueur d'onde, possèdent des propriétés électromagnétiques impossibles dans la nature (indice de réfraction négatif)."}, "turbulence-et-theorie-du-chaos": {"title": "Turbulence et théorie du chaos", "description": "L'écoulement turbulent d'un fluide, imprévisible dans le détail, partage des caractéristiques profondes avec les systèmes chaotiques étudiés en théorie du chaos."}, "couche-limite": {"title": "Couche limite", "description": "La couche limite est la fine région près d'une paroi où les effets visqueux d'un fluide en mouvement dominent, un concept clé pour comprendre la traînée aérodynamique."}, "ecoulements-compressibles-aerodynamique-supersonique": {"title": "Écoulements compressibles (aérodynamique supersonique)", "description": "À grande vitesse, un fluide ne peut plus être considéré comme incompressible, ce qui change radicalement son comportement (ondes de choc) en aérodynamique supersonique."}, "probleme-d-existence-et-regularite-prix-du-millenaire": {"title": "Problème d'existence et régularité (prix du millénaire)", "description": "Prouver l'existence et la régularité des solutions des équations de Navier-Stokes en trois dimensions est l'un des sept problèmes du prix du millénaire, toujours non résolu."}, "simulation-numerique-cfd": {"title": "Simulation numérique (CFD)", "description": "La dynamique des fluides numérique (CFD) résout par ordinateur les équations de Navier-Stokes discrétisées, permettant de simuler des écoulements trop complexes pour un calcul analytique."}, "distribution-de-boltzmann": {"title": "Distribution de Boltzmann", "description": "Cette distribution donne la probabilité qu'un système à l'équilibre thermique occupe un état d'énergie donnée, décroissant exponentiellement avec l'énergie."}, "ensembles-statistiques-microcanonique-canonique": {"title": "Ensembles statistiques (microcanonique, canonique)", "description": "Ces cadres formels de la physique statistique décrivent un système isolé (microcanonique) ou en contact avec un thermostat (canonique), chacun adapté à des conditions physiques différentes."}, "transitions-de-phase-et-point-critique": {"title": "Transitions de phase et point critique", "description": "Au point critique, les distinctions entre phases (liquide et gaz, par exemple) disparaissent, et le système présente des fluctuations à toutes les échelles."}, "lien-entropie-information-shannon": {"title": "Lien entropie-information (Shannon)", "description": "L'entropie de Shannon en théorie de l'information a la même forme mathématique que l'entropie de Boltzmann en physique statistique, révélant un lien profond entre information et désordre."}, "applications-a-la-physique-des-materiaux": {"title": "Applications à la physique des matériaux", "description": "La physique statistique explique les propriétés macroscopiques des matériaux (conductivité, magnétisme) à partir du comportement collectif de leurs atomes."}, "modele-standard-de-la-physique-des-particules": {"title": "Modèle Standard de la physique des particules", "description": "Confirmé avec une précision extrême par les expériences, ce modèle décrit toutes les particules élémentaires connues, bien qu'il n'explique pas la gravité ni la matière noire."}, "brisure-spontanee-de-symetrie": {"title": "Brisure spontanée de symétrie", "description": "Un système peut posséder une symétrie parfaite dans ses équations tout en adoptant un état final qui la brise, un mécanisme central pour expliquer l'origine de la masse des particules."}, "boson-de-higgs": {"title": "Boson de Higgs", "description": "Cette particule, découverte en 2012, est associée au mécanisme qui donne leur masse aux particules élémentaires du Modèle Standard."}, "interaction-forte-et-chromodynamique-quantique": {"title": "Interaction forte et chromodynamique quantique", "description": "L'interaction forte, décrite par la chromodynamique quantique, lie les quarks entre eux à l'intérieur des protons et neutrons via l'échange de gluons."}, "unification-des-forces-fondamentales": {"title": "Unification des forces fondamentales", "description": "Un objectif majeur de la physique théorique est d'unifier les quatre forces fondamentales (gravité, électromagnétisme, forces faible et forte) en une seule théorie cohérente."}, "attracteurs-etranges-lorenz": {"title": "Attracteurs étranges (Lorenz)", "description": "L'attracteur de Lorenz est une figure géométrique complexe vers laquelle convergent les trajectoires d'un système chaotique, sans jamais se répéter exactement."}, "bifurcations-et-diagrammes-de-bifurcation": {"title": "Bifurcations et diagrammes de bifurcation", "description": "Un diagramme de bifurcation représente comment le comportement à long terme d'un système change brutalement lorsqu'un paramètre de contrôle varie continûment."}, "theorie-kam-stabilite-des-systemes-integrables": {"title": "Théorie KAM (stabilité des systèmes intégrables)", "description": "La théorie KAM montre que la plupart des trajectoires d'un système hamiltonien légèrement perturbé restent stables, malgré la perte d'intégrabilité exacte du système."}, "chaos-en-meteorologie": {"title": "Chaos en météorologie", "description": "La météorologie est l'exemple historique du chaos déterministe : de minuscules différences dans les conditions initiales produisent des prévisions radicalement différentes après quelques jours."}, "applications-a-la-biologie-des-populations": {"title": "Applications à la biologie des populations", "description": "Les outils des systèmes dynamiques (points d'équilibre, stabilité) modélisent l'évolution de populations en interaction (proies-prédateurs, épidémies)."}, "modele-d-ising-et-champ-moyen": {"title": "Modèle d'Ising et champ moyen", "description": "Ce modèle simplifié de spins en interaction permet d'étudier analytiquement les transitions de phase magnétiques, l'approximation de champ moyen simplifiant encore les calculs."}, "groupe-de-renormalisation": {"title": "Groupe de renormalisation", "description": "Cette technique étudie comment le comportement d'un système physique change selon l'échelle d'observation, expliquant l'universalité des exposants critiques près d'une transition de phase."}, "universalite-des-exposants-critiques": {"title": "Universalité des exposants critiques", "description": "Près d'un point critique, des systèmes physiques très différents (aimant, fluide) partagent les mêmes exposants critiques, ne dépendant que de propriétés générales comme la dimension."}, "transitions-de-phase-du-second-ordre": {"title": "Transitions de phase du second ordre", "description": "Contrairement aux transitions du premier ordre (fusion, ébullition), les transitions du second ordre sont continues mais présentent des divergences caractéristiques au point critique."}, "applications-hors-de-la-physique-reseaux-epidemies": {"title": "Applications hors de la physique (réseaux, épidémies)", "description": "Les concepts de transition de phase et d'universalité s'appliquent au-delà de la physique, décrivant par exemple la propagation d'une épidémie ou la connectivité d'un réseau."}, "diagrammes-de-feynman": {"title": "Diagrammes de Feynman", "description": "Ces diagrammes représentent visuellement les interactions entre particules en théorie quantique des champs, chaque élément graphique correspondant à un terme mathématique précis du calcul."}, "renormalisation": {"title": "Renormalisation", "description": "Cette technique mathématique retire des infinis qui apparaissent naturellement dans les calculs de théorie quantique des champs, pour obtenir des prédictions physiques finies et vérifiables."}, "quantification-des-champs": {"title": "Quantification des champs", "description": "Quantifier un champ classique (comme le champ électromagnétique) consiste à en faire un objet quantique, dont les excitations élémentaires sont les particules (comme les photons)."}, "modele-standard": {"title": "Modèle Standard", "description": "Ce modèle théorique unifie toutes les particules élémentaires connues et trois des quatre interactions fondamentales (électromagnétique, faible, forte) en un cadre cohérent."}, "big-bang-et-rayonnement-fossile": {"title": "Big Bang et rayonnement fossile", "description": "Le rayonnement fossile, découvert en 1965, est la lumière la plus ancienne observable, émise 380 000 ans après le Big Bang, et confirme le modèle cosmologique standard."}, "energie-noire-et-constante-cosmologique": {"title": "Énergie noire et constante cosmologique", "description": "L'énergie noire, dont la nature reste mystérieuse, serait responsable de l'accélération observée de l'expansion de l'univers, modélisée par la constante cosmologique d'Einstein."}, "inflation-cosmique": {"title": "Inflation cosmique", "description": "Cette théorie postule une expansion extrêmement rapide de l'univers juste après le Big Bang, expliquant pourquoi l'univers observable est si homogène et plat."}, "matiere-noire": {"title": "Matière noire", "description": "La matière noire, invisible mais détectée par ses effets gravitationnels, constituerait la majorité de la matière de l'univers, sans que sa nature exacte soit encore identifiée."}, "structure-a-grande-echelle-de-l-univers": {"title": "Structure à grande échelle de l'univers", "description": "L'univers observable présente une structure filamenteuse à grande échelle (amas et vides de galaxies), issue de l'amplification gravitationnelle de fluctuations primordiales de densité."}, "these-de-church-turing": {"title": "Thèse de Church-Turing", "description": "Cette thèse (non un théorème prouvable) postule que tout ce qui est intuitivement « calculable » peut être calculé par une machine de Turing, unifiant toutes les notions de calcul."}, "probleme-de-l-arret-et-indecidabilite": {"title": "Problème de l'arrêt et indécidabilité", "description": "Ce problème, prouvé indécidable par Turing, montre qu'aucun algorithme ne peut déterminer, pour tout programme, s'il va s'arrêter ou tourner indéfiniment."}, "fonctions-recursives": {"title": "Fonctions récursives", "description": "En théorie de la calculabilité, les fonctions récursives forment une classe précise de fonctions calculables, équivalente en puissance aux machines de Turing."}, "theoreme-de-rice": {"title": "Théorème de Rice", "description": "Ce théorème dit qu'aucune propriété non triviale du comportement d'un programme ne peut être décidée algorithmiquement pour tous les programmes possibles."}, "machines-de-turing-universelles": {"title": "Machines de Turing universelles", "description": "Une machine de Turing universelle peut simuler n'importe quelle autre machine de Turing, capturant l'idée fondamentale d'un ordinateur programmable à usage général."}, "probleme-p-np-un-million-de-dollars-a-la-cle": {"title": "Problème P=NP (un million de dollars à la clé)", "description": "Ce problème, doté d'un prix d'un million de dollars, demande si tout problème dont la solution se vérifie rapidement peut aussi être résolu rapidement — toujours sans réponse."}, "approximation-de-problemes-np-difficiles": {"title": "Approximation de problèmes NP-difficiles", "description": "Face à un problème NP-difficile, un algorithme d'approximation garantit une solution proche de l'optimale (dans un facteur connu) en temps raisonnable."}, "axiome-du-choix-et-ses-consequences": {"title": "Axiome du choix et ses conséquences", "description": "Cet axiome, qui garantit qu'on peut toujours choisir un élément dans chaque ensemble d'une collection, a des conséquences parfois contre-intuitives (paradoxe de Banach-Tarski)."}, "hypothese-du-continu": {"title": "Hypothèse du continu", "description": "Cette hypothèse, indécidable dans le système d'axiomes standard des mathématiques (ZFC), affirme qu'il n'existe pas d'ensemble de taille strictement intermédiaire entre ℕ et ℝ."}, "theoremes-d-incompletude-de-godel-approfondi": {"title": "Théorèmes d'incomplétude de Gödel (approfondi)", "description": "Ces théorèmes montrent qu'aucun système formel assez puissant pour décrire l'arithmétique ne peut être à la fois complet et prouver sa propre cohérence."}, "theorie-des-modeles": {"title": "Théorie des modèles", "description": "Cette branche de la logique étudie les structures mathématiques qui satisfont un ensemble donné d'axiomes, reliant syntaxe formelle et interprétation concrète."}, "calculabilite-et-logique": {"title": "Calculabilité et logique", "description": "La calculabilité et la logique formelle sont intimement liées : les limites de ce qui est démontrable rejoignent les limites de ce qui est calculable (théorèmes de Gödel et de Turing)."}, "codage-de-source-compression-optimale": {"title": "Codage de source (compression optimale)", "description": "Le codage de source vise à représenter l'information avec le moins de bits possible, la limite théorique étant donnée par l'entropie de Shannon de la source."}, "codage-de-canal-et-codes-correcteurs": {"title": "Codage de canal et codes correcteurs", "description": "Le codage de canal ajoute une redondance calculée à un message pour permettre de détecter et corriger automatiquement les erreurs introduites par un canal de transmission bruité."}, "theoreme-de-shannon-codage-sans-bruit": {"title": "Théorème de Shannon (codage sans bruit)", "description": "Ce théorème donne la limite théorique de compression d'une source d'information, exactement égale à son entropie, en dessous de laquelle aucune compression sans perte n'est possible."}, "stabilite-et-convergence-des-methodes-numeriques": {"title": "Stabilité et convergence des méthodes numériques", "description": "Une méthode numérique stable ne voit pas ses erreurs s'amplifier au fil des calculs ; sa convergence garantit qu'elle se rapproche bien de la solution exacte recherchée."}, "methodes-iteratives-pour-systemes-lineaires": {"title": "Méthodes itératives pour systèmes linéaires", "description": "Pour de très grands systèmes linéaires, les méthodes itératives (Jacobi, Gauss-Seidel) approchent la solution progressivement, plus efficacement qu'une résolution directe."}, "analyse-d-erreur-numerique": {"title": "Analyse d'erreur numérique", "description": "Toute méthode numérique approchée accumule des erreurs d'arrondi et de troncature ; les analyser permet de garantir la fiabilité des résultats calculés."}, "applications-a-la-simulation-scientifique": {"title": "Applications à la simulation scientifique", "description": "Les méthodes numériques permettent de simuler des phénomènes physiques trop complexes pour une résolution analytique (météo, aérodynamique, structures)."}, "echantillonnage-et-theoreme-de-nyquist": {"title": "Échantillonnage et théorème de Nyquist", "description": "Ce théorème détermine la fréquence minimale d'échantillonnage nécessaire pour reconstruire fidèlement un signal continu à partir de mesures discrètes, sans perte d'information."}, "convolution-rapide-via-la-fft": {"title": "Convolution rapide via la FFT", "description": "Calculer une convolution directement coûte O(n²) opérations ; passer par la FFT permet de la calculer en O(n log n), une accélération considérable pour de grands signaux."}, "filtrage-numerique": {"title": "Filtrage numérique", "description": "Un filtre numérique modifie sélectivement certaines fréquences d'un signal (par exemple, atténuer les basses fréquences), essentiel en traitement audio et en télécommunications."}, "transformee-en-ondelettes": {"title": "Transformée en ondelettes", "description": "Contrairement à Fourier, la transformée en ondelettes localise l'analyse à la fois en temps et en fréquence, idéale pour la compression d'image (JPEG 2000)."}, "applications-au-traitement-d-image-et-audio": {"title": "Applications au traitement d'image et audio", "description": "La FFT et les ondelettes permettent de compresser, filtrer et analyser efficacement des images et des sons en exploitant leur contenu fréquentiel."}, "fonctions-a-sens-unique": {"title": "Fonctions à sens unique", "description": "Une fonction à sens unique est facile à calculer mais très difficile à inverser sans information supplémentaire, principe central de toute la cryptographie moderne."}, "protocoles-d-authentification-avances": {"title": "Protocoles d'authentification avancés", "description": "Ces protocoles (OAuth, certificats numériques) permettent de vérifier de façon sûre l'identité d'un utilisateur ou d'un service sans transmettre de mot de passe en clair."}, "cryptographie-et-blockchain": {"title": "Cryptographie et blockchain", "description": "Une blockchain utilise des fonctions de hachage et des signatures numériques pour garantir l'intégrité et l'authenticité d'un registre de transactions distribué et infalsifiable."}, "attaques-cryptanalytiques": {"title": "Attaques cryptanalytiques", "description": "Une attaque cryptanalytique cherche à casser un système de chiffrement sans connaître la clé, en exploitant des faiblesses mathématiques ou d'implémentation."}, "theorie-spectrale-des-graphes": {"title": "Théorie spectrale des graphes", "description": "Les valeurs propres de la matrice d'adjacence ou laplacienne d'un graphe révèlent des propriétés structurelles profondes, comme sa connectivité ou son nombre de composantes."}, "graphes-expanseurs": {"title": "Graphes expanseurs", "description": "Un graphe expanseur est à la fois peu dense et très bien connecté, une propriété paradoxale exploitée en informatique théorique (codes correcteurs, dérandomisation)."}, "theoreme-de-kuratowski-planarite": {"title": "Théorème de Kuratowski (planarité)", "description": "Ce théorème caractérise exactement les graphes qu'on peut dessiner sans croisement d'arêtes dans le plan, via l'absence de deux configurations interdites précises."}, "coloration-de-graphes-et-applications": {"title": "Coloration de graphes et applications", "description": "Colorier un graphe consiste à attribuer des couleurs aux sommets sans que deux sommets voisins partagent la même couleur, utile pour l'attribution de fréquences ou d'emplois du temps."}, "detection-de-communautes-dans-les-reseaux": {"title": "Détection de communautés dans les réseaux", "description": "Ces algorithmes identifient automatiquement des groupes de sommets fortement connectés entre eux dans un grand réseau (réseaux sociaux, biologie)."}, "grammaires-hors-contexte-et-automates-a-pile": {"title": "Grammaires hors contexte et automates à pile", "description": "Une grammaire hors contexte génère des langages structurés (comme les parenthésages imbriqués), naturellement reconnus par un automate muni d'une pile mémoire."}, "hierarchie-de-chomsky-complete": {"title": "Hiérarchie de Chomsky complète", "description": "Chaque niveau de la hiérarchie de Chomsky correspond exactement à une classe d'automates : automates finis, automates à pile, automates linéairement bornés, machines de Turing."}, "theoreme-de-chomsky-schutzenberger": {"title": "Théorème de Chomsky-Schützenberger", "description": "Ce théorème caractérise précisément les langages hors contexte comme provenant d'un langage de parenthésages bien équilibrés, transformé par un morphisme et une intersection."}, "applications-a-la-verification-formelle": {"title": "Applications à la vérification formelle", "description": "Les automates et la logique formelle permettent de prouver mathématiquement qu'un programme ou un protocole se comporte correctement dans tous les cas possibles."}, "reseaux-de-neurones-et-retropropagation": {"title": "Réseaux de neurones et rétropropagation", "description": "La rétropropagation calcule efficacement le gradient de l'erreur d'un réseau de neurones par rapport à tous ses paramètres, permettant de l'entraîner par descente de gradient."}, "sur-apprentissage-et-validation-croisee": {"title": "Sur-apprentissage et validation croisée", "description": "Un modèle en sur-apprentissage mémorise les données d'entraînement sans généraliser ; la validation croisée teste sa performance sur des données jamais vues pour détecter ce problème."}, "apprentissage-supervise-vs-non-supervise": {"title": "Apprentissage supervisé vs non supervisé", "description": "L'apprentissage supervisé entraîne un modèle sur des données déjà étiquetées ; l'apprentissage non supervisé cherche des structures cachées dans des données sans étiquette."}, "optimisation-convexe-en-apprentissage-automatique": {"title": "Optimisation convexe en apprentissage automatique", "description": "De nombreux algorithmes d'apprentissage automatique reposent sur la minimisation d'une fonction convexe, ce qui garantit qu'un minimum trouvé localement est aussi global."}, "reseaux-de-neurones-profonds-deep-learning": {"title": "Réseaux de neurones profonds (deep learning)", "description": "Un réseau de neurones profond empile de nombreuses couches de calcul, capable d'apprendre des représentations très abstraites à partir de données brutes (images, texte, son)."}, "methode-sos-somme-de-carres-avancee": {"title": "Méthode SOS (somme de carrés) avancée", "description": "Pour des inégalités à trois variables ou plus, la méthode SOS nécessite souvent une décomposition ingénieuse en plusieurs carrés pondérés par des coefficients bien choisis."}, "inegalites-avec-contraintes-lagrange-en-competition": {"title": "Inégalités avec contraintes (Lagrange en compétition)", "description": "Bien que non enseignés directement en compétition, les multiplicateurs de Lagrange peuvent aider à deviner le cas d'égalité optimal d'une inégalité sous contrainte."}, "inegalite-de-muirhead": {"title": "Inégalité de Muirhead", "description": "Cette inégalité compare des sommes symétriques de puissances selon un critère de « majoration » des exposants, généralisant AM-GM à un cadre beaucoup plus large."}, "inegalites-integrales-niveau-avance": {"title": "Inégalités intégrales (niveau avancé)", "description": "Certaines inégalités olympiques avancées s'expriment ou se prouvent à l'aide d'intégrales, faisant le pont entre combinatoire discrète et analyse continue."}, "lifting-the-exponent-lte-en-detail": {"title": "Lifting the Exponent (LTE) en détail", "description": "La formule LTE nécessite de vérifier des conditions précises (souvent p|a-b) avant de s'appliquer, mais accélère radicalement certains problèmes de divisibilité par un nombre premier."}, "residus-quadratiques-et-loi-de-reciprocite": {"title": "Résidus quadratiques et loi de réciprocité", "description": "La loi de réciprocité quadratique relie de façon surprenante la résolubilité de x²≡p (mod q) à celle de x²≡q (mod p), pour deux nombres premiers p et q."}, "ordre-multiplicatif-et-groupes-cycliques": {"title": "Ordre multiplicatif et groupes cycliques", "description": "L'ordre d'un élément dans l'arithmétique modulaire correspond exactement à l'ordre de cet élément dans le groupe cyclique multiplicatif associé, reliant théorie des nombres et théorie des groupes."}, "theoreme-de-zsygmondy": {"title": "Théorème de Zsygmondy", "description": "Ce théorème garantit l'existence d'un facteur premier « primitif » (n'apparaissant à aucune étape précédente) dans la suite aⁿ-bⁿ, sauf un nombre fini d'exceptions connues."}, "double-comptage-avance-identites-combinatoires": {"title": "Double comptage avancé (identités combinatoires)", "description": "Le double comptage permet de prouver élégamment des identités combinatoires complexes sans aucun calcul algébrique, juste en comptant intelligemment un même ensemble de deux manières."}, "principe-des-tiroirs-generalise-version-forte": {"title": "Principe des tiroirs généralisé (version forte)", "description": "La version forte du principe des tiroirs garantit qu'un tiroir contient au moins ⌈n/k⌉ objets, une précision souvent nécessaire pour des problèmes plus fins."}, "combinatoire-extremale": {"title": "Combinatoire extrémale", "description": "Cette branche cherche la taille maximale ou minimale d'une structure combinatoire satisfaisant certaines contraintes, un domaine riche à la frontière de la combinatoire et de la théorie des graphes."}, "theoreme-de-ramsey-cas-generaux": {"title": "Théorème de Ramsey (cas généraux)", "description": "Ce théorème garantit que, dans un graphe suffisamment grand, on trouve toujours une structure régulière (clique ou ensemble indépendant), quelle que soit la coloration choisie."}, "applications-a-la-theorie-des-graphes": {"title": "Applications à la théorie des graphes", "description": "De nombreux problèmes de compétition se traduisent élégamment en langage de graphes (sommets, arêtes), révélant des structures et symétries cachées."}, "inversion-geometrique-avancee": {"title": "Inversion géométrique avancée", "description": "Une inversion bien choisie peut transformer un problème de géométrie complexe en une configuration triviale, une technique redoutablement efficace aux olympiades internationales."}, "theoreme-de-ptolemee-et-ses-generalisations": {"title": "Théorème de Ptolémée et ses généralisations", "description": "L'inégalité de Ptolémée généralise le théorème aux quadrilatères non cocycliques, l'égalité n'étant atteinte que dans le cas inscriptible."}, "axe-radical-et-faisceaux-de-cercles": {"title": "Axe radical et faisceaux de cercles", "description": "L'axe radical de deux cercles est la droite des points de même puissance par rapport aux deux ; un faisceau de cercles partage tous le même axe radical."}, "geometrie-inversive-et-cercles-orthogonaux": {"title": "Géométrie inversive et cercles orthogonaux", "description": "L'inversion transforme cercles et droites les uns dans les autres selon des règles précises ; deux cercles orthogonaux restent orthogonaux après toute inversion."}, "polynomes-a-coefficients-entiers-et-congruences": {"title": "Polynômes à coefficients entiers et congruences", "description": "Étudier un polynôme à coefficients entiers modulo un nombre premier révèle souvent des contraintes fortes sur ses racines entières possibles."}, "polynomes-irreductibles-en-competition": {"title": "Polynômes irréductibles en compétition", "description": "Prouver qu'un polynôme est irréductible (le critère d'Eisenstein, notamment) est une technique récurrente pour résoudre certains problèmes olympiques avancés."}, "points-fixes-et-iteration-de-fonctions": {"title": "Points fixes et itération de fonctions", "description": "Itérer une fonction plusieurs fois révèle souvent des cycles ou des points fixes qui structurent complètement son comportement à long terme."}, "theoreme-de-ramsey-cas-generaux-et-nombres-de-ramsey": {"title": "Théorème de Ramsey (cas généraux et nombres de Ramsey)", "description": "Les nombres de Ramsey R(m,n) restent extrêmement difficiles à calculer exactement au-delà de très petites valeurs, malgré des décennies de recherche."}, "graphes-extremaux": {"title": "Graphes extrémaux", "description": "La théorie des graphes extrémaux cherche le nombre maximal d'arêtes qu'un graphe peut avoir sans contenir une certaine sous-structure interdite (comme un triangle)."}, "tournois-et-proprietes-structurelles": {"title": "Tournois et propriétés structurelles", "description": "Tout tournoi, aussi grand soit-il, contient toujours un chemin hamiltonien qui visite chaque participant exactement une fois, un résultat remarquable et non intuitif."}, "theorie-de-ramsey-en-combinatoire-additive": {"title": "Théorie de Ramsey en combinatoire additive", "description": "La théorie de Ramsey s'étend à la combinatoire additive, garantissant l'existence de structures arithmétiques régulières (comme des progressions) dans tout grand ensemble de nombres."}, "principe-extremal-choisir-l-element-extremal": {"title": "Principe extrémal (choisir l'élément extrémal)", "description": "Cette stratégie consiste à choisir l'élément le plus grand, le plus petit ou le plus particulier d'une configuration pour en tirer une contradiction ou une conclusion générale."}, "preuve-par-contradiction-avancee": {"title": "Preuve par contradiction avancée", "description": "Au-delà de la contradiction simple, certaines preuves construisent une contradiction subtile en combinant plusieurs hypothèses intermédiaires successives."}, "induction-structurelle": {"title": "Induction structurelle", "description": "Cette forme de récurrence prouve une propriété sur une structure définie récursivement (arbre, expression) en la supposant vraie sur ses sous-structures constitutives."}, "strategies-de-bijection": {"title": "Stratégies de bijection", "description": "Construire une bijection explicite entre deux ensembles est souvent la preuve la plus élégante possible qu'ils ont le même nombre d'éléments."}, "heuristiques-de-resolution-de-problemes-polya": {"title": "Heuristiques de résolution de problèmes (Pólya)", "description": "Georges Pólya a formalisé une méthode générale de résolution de problèmes (comprendre, planifier, exécuter, vérifier) toujours enseignée en préparation aux olympiades."}, "pavages-par-polyominos-complexes": {"title": "Pavages par polyominos complexes", "description": "Au-delà des simples dominos, paver une figure avec des polyominos plus complexes (tétrominos, pentominos) nécessite souvent des arguments de coloriage plus sophistiqués."}, "colorations-a-plusieurs-couleurs-arguments-modulo-n": {"title": "Colorations à plusieurs couleurs (arguments modulo n)", "description": "Certains problèmes de pavage nécessitent des coloriages plus riches, utilisant n couleurs distinctes et un raisonnement modulo n pour révéler une contrainte cachée."}, "invariants-topologiques-en-pavage": {"title": "Invariants topologiques en pavage", "description": "Certains arguments de pavage exploitent des invariants de nature topologique plutôt que simplement combinatoire, révélant une contrainte plus profonde et souvent élégante."}, "theoreme-de-wang-et-indecidabilite": {"title": "Théorème de Wang et indécidabilité", "description": "La question de pavabilité du plan par un jeu de tuiles donné est indécidable en général, un résultat qui relie combinatoire du pavage et théorie de la calculabilité."}, "applications-aux-fractales-et-a-l-auto-similarite": {"title": "Applications aux fractales et à l'auto-similarité", "description": "L'invariance d'échelle observée dans certains problèmes combinatoires rappelle la structure auto-similaire des fractales, où un motif se répète à toutes les échelles."}, "redaction-d-une-demonstration-par-recurrence": {"title": "Rédaction d'une démonstration par récurrence", "description": "Une récurrence bien rédigée exige une initialisation claire, une hérédité rigoureusement justifiée, et une conclusion précise — des attentes strictement évaluées en concours."}, "justification-des-theoremes-cites-hypotheses-verifiees": {"title": "Justification des théorèmes cités (hypothèses vérifiées)", "description": "Citer un théorème sans vérifier explicitement ses hypothèses est une des erreurs de rigueur les plus sanctionnées en copie de concours."}, "presentation-claire-des-calculs-intermediaires": {"title": "Présentation claire des calculs intermédiaires", "description": "Montrer clairement chaque étape d'un calcul, même simple, permet au correcteur de suivre le raisonnement et d'attribuer des points même en cas d'erreur finale."}, "eviter-les-erreurs-de-rigueur-classiques": {"title": "Éviter les erreurs de rigueur classiques", "description": "Oublier de vérifier une hypothèse, confondre une condition nécessaire et suffisante, ou mal justifier un passage à la limite sont des erreurs de rigueur très fréquemment sanctionnées."}, "redaction-sous-contrainte-de-temps-epreuve-de-4h": {"title": "Rédaction sous contrainte de temps (épreuve de 4h)", "description": "Rédiger vite tout en restant rigoureux est une compétence spécifique qui se travaille par un entraînement régulier en conditions chronométrées."}, "techniques-de-memorisation-des-demonstrations-de-cours": {"title": "Techniques de mémorisation des démonstrations de cours", "description": "Comprendre l'idée directrice d'une démonstration, plutôt que de l'apprendre mot pour mot, permet de la reconstruire fiablement même sous le stress d'une colle ou d'un oral."}, "gestion-du-stress-a-l-oral": {"title": "Gestion du stress à l'oral", "description": "Respirer, prendre le temps de réfléchir avant de répondre, et accepter de ne pas tout savoir font partie des techniques essentielles pour bien gérer un oral de concours."}, "reactivite-face-aux-questions-du-colleur-jury": {"title": "Réactivité face aux questions du colleur/jury", "description": "Savoir réagir avec souplesse à une question inattendue, sans paniquer, est une compétence qui se développe progressivement au fil des colles et oraux blancs."}, "utilisation-efficace-du-tableau": {"title": "Utilisation efficace du tableau", "description": "Structurer clairement son tableau lors d'une colle ou d'un oral (garder une trace visible du raisonnement) aide à communiquer efficacement avec l'examinateur."}, "differences-entre-colles-et-oraux-de-concours": {"title": "Différences entre colles et oraux de concours", "description": "Une colle évalue régulièrement la progression sur le programme récent ; un oral de concours, plus ponctuel et décisif, teste la maîtrise globale et la réactivité sous pression."}, "differences-de-style-entre-concours-analyse-comparative": {"title": "Différences de style entre concours (analyse comparative)", "description": "X-ENS privilégie des sujets théoriques et exigeants en rigueur, Mines-Ponts des sujets plus calculatoires, Centrale-Supélec un équilibre entre les deux approches."}, "strategie-de-priorisation-des-questions": {"title": "Stratégie de priorisation des questions", "description": "Repérer rapidement les questions accessibles et les traiter en premier, avant de s'attaquer aux plus difficiles, maximise le score global sur une épreuve chronométrée."}, "annales-et-exercices-types-par-concours": {"title": "Annales et exercices types par concours", "description": "S'entraîner sur les annales des années précédentes permet de se familiariser avec le style et le niveau de difficulté propres à chaque concours visé."}, "gestion-du-stress-en-epreuve-ecrite": {"title": "Gestion du stress en épreuve écrite", "description": "Prioriser les questions accessibles, respirer, et ne pas rester bloqué trop longtemps sur une difficulté sont des réflexes essentiels pour bien gérer le stress d'une épreuve de 4 heures."}, "analyse-des-rapports-de-jury": {"title": "Analyse des rapports de jury", "description": "Les rapports de jury, publiés après chaque concours, détaillent les erreurs fréquentes des candidats et les attentes précises en termes de rigueur — une lecture précieuse pour la préparation."}, "programme-detaille-de-premiere-annee-mpsi": {"title": "Programme détaillé de première année (MPSI)", "description": "La première année MPSI pose les bases : algèbre linéaire, analyse réelle, nombres complexes, et une introduction aux structures algébriques (groupes, anneaux)."}, "programme-detaille-de-deuxieme-annee-mp": {"title": "Programme détaillé de deuxième année (MP)", "description": "La deuxième année de MP approfondit l'algèbre linéaire (réduction), l'analyse (séries, intégrales généralisées) et introduit les probabilités et la topologie."}, "repartition-des-coefficients-selon-les-concours": {"title": "Répartition des coefficients selon les concours", "description": "Chaque concours pondère différemment les épreuves (maths, physique, langues), ce qui doit orienter la répartition du temps de révision selon les concours visés en priorité."}, "options-mp-informatique-renforcee-physique": {"title": "Options MP (informatique renforcée, physique)", "description": "La filière MP propose des options qui renforcent soit l'informatique, soit la physique, permettant d'orienter légèrement son profil selon ses affinités."}, "poursuite-d-etudes-apres-mp": {"title": "Poursuite d'études après MP", "description": "Après une prépa MP, les élèves intègrent généralement une école d'ingénieurs généraliste ou une ENS, avec de nombreux débouchés en recherche, finance ou industrie technologique."}, "programme-detaille-de-premiere-annee-pcsi": {"title": "Programme détaillé de première année (PCSI)", "description": "La première année PCSI couvre un tronc commun de mathématiques similaire à MPSI, mais avec un volume horaire réduit au profit de la physique-chimie."}, "programme-detaille-de-deuxieme-annee-pc": {"title": "Programme détaillé de deuxième année (PC)", "description": "La deuxième année de PC approfondit les mathématiques du tronc commun tout en les articulant étroitement avec un programme de physique-chimie plus poussé."}, "lien-mathematiques-physique-dans-le-programme-pc": {"title": "Lien mathématiques-physique dans le programme PC", "description": "En filière PC, de nombreux outils mathématiques (équations différentielles, séries de Fourier) sont introduits directement à travers leurs applications en physique."}, "comparaison-avec-la-filiere-mp": {"title": "Comparaison avec la filière MP", "description": "La filière PC accorde plus de place à la physique-chimie appliquée, tandis que MP privilégie une approche plus abstraite et théorique des mathématiques."}, "poursuite-d-etudes-apres-pc": {"title": "Poursuite d'études après PC", "description": "Après une prépa PC, les élèves s'orientent souvent vers des écoles d'ingénieurs à forte composante physique-chimie, ou vers des filières de recherche en sciences physiques."}, "preparation-ciblee-par-matiere-maths-physique-si": {"title": "Préparation ciblée par matière (maths, physique, SI)", "description": "Adapter son temps de révision selon ses points faibles dans chaque matière (maths, physique, sciences de l'ingénieur) optimise l'efficacité globale de la préparation."}, "gestion-du-stress-face-a-un-examinateur": {"title": "Gestion du stress face à un examinateur", "description": "Rester calme et méthodique face à un examinateur, même en cas de blocage, est une compétence qui se travaille autant que le contenu mathématique lui-même."}, "utilisation-efficace-du-temps-de-preparation": {"title": "Utilisation efficace du temps de préparation", "description": "Bien utiliser le temps de préparation avant un oral (identifier la stratégie, faire les calculs clés) conditionne largement la qualité de la présentation qui suit."}, "differences-entre-colleurs-styles-varies": {"title": "Différences entre colleurs (styles variés)", "description": "Chaque colleur a son propre style d'interrogation (plus ou moins directif, plus ou moins exigeant sur la rigueur), une diversité qui prépare bien à la variété des examinateurs de concours."}, "progression-mesurable-au-fil-de-l-annee": {"title": "Progression mesurable au fil de l'année", "description": "Les colles hebdomadaires permettent de suivre une progression continue et objective tout au long de l'année, bien plus fine que les seuls résultats aux devoirs surveillés."}, "decomposition-d-un-probleme-long-en-sous-questions": {"title": "Décomposition d'un problème long en sous-questions", "description": "Un problème de concours est presque toujours découpé en sous-questions progressives, chacune servant souvent d'indice ou d'outil pour la suivante."}, "utilisation-des-questions-precedentes-indices-du-sujet": {"title": "Utilisation des questions précédentes (indices du sujet)", "description": "Les questions d'un problème de concours s'enchaînent presque toujours logiquement : le résultat d'une question sert souvent d'outil pour la suivante."}, "conjecture-et-verification-sur-des-cas-particuliers": {"title": "Conjecture et vérification sur des cas particuliers", "description": "Tester un problème sur de petits cas particuliers permet souvent de deviner la formule générale avant de la démontrer rigoureusement, une stratégie efficace en épreuve de concours."}, "gestion-du-temps-sur-un-probleme-long": {"title": "Gestion du temps sur un problème long", "description": "Répartir son temps entre les différentes parties d'un problème long, sans s'attarder excessivement sur une question bloquante, est une compétence clé pour maximiser son score."}, "techniques-de-blocage-et-deblocage": {"title": "Techniques de blocage et déblocage", "description": "Face à un blocage sur un exercice, changer d'angle d'attaque, tester un cas particulier, ou relire l'énoncé attentivement permettent souvent de débloquer la situation."}, "fonctionnement-des-banques-d-epreuves-communes": {"title": "Fonctionnement des banques d'épreuves communes", "description": "Une banque d'épreuves mutualise les résultats d'un même concours écrit entre plusieurs écoles, simplifiant les candidatures multiples pour les élèves de prépa."}, "strategie-de-choix-des-concours-selon-le-profil": {"title": "Stratégie de choix des concours selon le profil", "description": "Le choix des concours à préparer en priorité dépend du profil de l'élève (plutôt théorique ou appliqué) et des écoles visées en priorité."}, "oraux-d-admission-format-et-preparation": {"title": "Oraux d'admission (format et préparation)", "description": "Les oraux de concours, en fin de processus d'admission, évaluent la réactivité et la solidité des connaissances face à des questions imprévues, dans un format différent des écrits."}, "comparaison-des-debouches-selon-les-ecoles": {"title": "Comparaison des débouchés selon les écoles", "description": "Les débouchés professionnels varient significativement selon l'école intégrée (ingénierie généraliste, recherche, finance), un critère important dans le choix des vœux."}, "alternatives-admissions-paralleles-doubles-diplomes": {"title": "Alternatives (admissions parallèles, doubles diplômes)", "description": "Au-delà des concours classiques post-prépa, il existe des admissions parallèles (après une licence) et des doubles diplômes qui élargissent les parcours possibles vers les grandes écoles."}, "principe-d-inclusion-exclusion": {"title": "Principe d'inclusion-exclusion", "description": "Ce principe calcule la taille d'une union d'ensembles en additionnant leurs tailles individuelles puis en corrigeant systématiquement les intersections comptées plusieurs fois."}, "partitions-d-un-ensemble-ou-d-un-entier": {"title": "Partitions d'un ensemble ou d'un entier", "description": "Une partition découpe un ensemble en sous-groupes disjoints qui le recouvrent entièrement, ou décompose un entier en somme d'entiers plus petits — deux notions combinatoires classiques."}, "combinatoire-des-graphes": {"title": "Combinatoire des graphes", "description": "Compter le nombre de chemins, cycles ou arbres couvrants dans un graphe combine des techniques de combinatoire et d'algèbre linéaire (matrices d'adjacence)."}, "combinatoire-et-probabilites-denombrement-de-cas": {"title": "Combinatoire et probabilités (dénombrement de cas)", "description": "Dans un univers équiprobable, calculer une probabilité revient à compter le nombre de cas favorables et de cas possibles, mobilisant directement les outils combinatoires."}, "combinatoire-et-intelligence-artificielle-espace-de-recherch": {"title": "Combinatoire et intelligence artificielle (espace de recherche)", "description": "L'espace des solutions possibles d'un problème d'IA (échecs, planification) croît de façon combinatoire, ce qui motive des heuristiques pour éviter une recherche exhaustive."}};
